window.SEARCH = [{"u": "ch01.html", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "开头", "x": "本讲结论 shell 是电脑最底层的文本接口。一行命令就是程序名加参数。程序之间用管道和重定向拼起来。命令写进文件，第一行加上 #! ，就成了脚本。"}, {"u": "ch01.html#s1", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "工具没人教，但天天要用", "x": "这门课教的是干活的工具。别的课默认你会，却没人专门教。 bash · 最小例子（示意） # 测试一百次才挂一次？别手动按一百遍 ↑ 加回车 while ./run_tests.sh; do # 测试通过，退出码是 0，就接着跑 echo \"又过了一次\" done # 第一次失败时跳出循环 打个比方 专业课教你做菜，没人教你磨刀。刀钝了，做哪道菜都慢。 三位讲师是 Anish、Jon 和 Jose，都是 MIT 的前博士生。他们 2019 年和 2020 年开过这门课。到了 2026 年，AI 工具变化太大，于是重开一轮。 课名说的就是这件事。MIT 的课默认你会用 Git、编辑器和终端。可是没有哪门课专门教这些。这就是“缺失的一学期”。 为什么要学工具 电脑最会做重复的活。可我们常忘了，用电脑这件事本身也能自动化。比如反复跑测试，不必手动按一百次 ↑ 加回车。 “未知的未知” 你遇到的麻烦，前人多半早就解决了。只是编译原理和算法课不讲。这门课先让你知道这些工具存在，要用时能想起来。 “暴露疗法” 一共 9 讲，每讲 1 小时。覆盖面大，细节少。课上只展示能做到什么。具体用法，靠课后读讲义和做练习。 练习最重要 每讲都配练习，讲师说这是收获最大的环节。官方不给答案。卡住了可以去 OSSU Discord 问，也可以拿题目和 LLM 聊。 2026 版：AI 拆进了每一讲 讲义首页说得很清楚。AI 是通用技术，所以 不单开一讲 。每一讲都会带上相关的 AI 工具。第 7 讲另外专讲智能体编程。"}, {"u": "ch01.html#s2", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "终端只是窗口，干活的是 shell", "x": "终端只负责显示文字和接收按键。读懂命令、启动程序的，是窗口里跑着的 shell。 bash · 本机实测（Git Bash） $ echo $BASH_VERSION # 窗口里跑的是 bash，这是它的版本号 5.3.15(1)-release $ which ls # ls 不是 shell 本身，是磁盘上的一个程序 /usr/bin/ls $ type cd # cd 是 shell 自带的，没有对应的文件 cd is a shell builtin 打个比方 终端是餐厅的点菜窗口，shell 是后厨的接单员。你在窗口报菜名，接单员去叫对应的厨师。厨师就是 ls、date 这些程序。 图形界面只能做作者设计好的事。不存在的按钮你按不了。两家厂商的软件也很难拼在一起。shell 往下降了一层，它是电脑的 文本接口 。命令随便写，也随便组合。它比所有图形界面都早。 终端只是外壳窗口。真正干活的是窗口里的 shell（视频 8:59） 系统 怎么打开终端 默认 shell Linux Ctrl + Alt + T ，或在菜单里搜 Terminal 通常是 bash，有的发行版换成 zsh macOS Cmd + Space 打开 Spotlight，搜 Terminal 以前是 bash，现在是 zsh。zsh 和 bash 兼容 Windows Win + R ，输入 cmd 或 powershell cmd 或 PowerShell， 不是 本课用的 shell。请装 WSL 或 Linux 虚拟机 shell 有好几种。bash 最普及，但多年没加大功能。zsh 兼容 bash，用起来更顺手。fish 主打让人敲着舒服。三位讲师各用各的，课上统一讲 bash 。 为什么会在这里踩坑 Windows 自带的 cmd 和 PowerShell 也是 shell，只是语法完全不同。课上的命令拿过去跑，很多直接报错。比如 ls -l ，cmd 根本不认识 ls。所以先确认窗口里跑的是 bash。 本笔记的实测环境 标着“本机实测”的输出，来自 Windows 11 上的 Git Bash 。版本是 GNU bash 5.3.15。本讲大部分命令它都能跑。但它不是真的 Linux，比如 NTFS 不记执行权限（见 第 15 节 ）。讲义推荐 Windows 用户用 WSL。"}, {"u": "ch01.html#s3", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "学 shell 图的是快、能自动化、能组合", "x": "图形界面一次只能点一下。shell 一行命令能处理一百个文件，还能接着往下加工。 bash · 最小例子（示意） # 图形界面：打开 100 个日志，一个个搜 ERROR # shell：一行搞定，结果还能接着往下传 grep -l ERROR logs/*.log | wc -l # 出过错的日志一共几个 打个比方 图形界面像自动售货机，只能按面板上那几个钮。shell 像自家厨房，原料怎么配都行。 快 ：熟练以后，敲几个键就顶得上很多次点击。任务越复杂，差距越大。 能自动化 ：提示符就是一个 bash 程序的开头。你敲的每一行，都是一段被执行的代码。 能组合 ：一个程序的输出喂给下一个，再喂给第三个。shell 天生就是为这种组合设计的。 通用语 ：开源工具的安装说明，几乎都是 shell 命令。看懂它们，就不用从 Stack Overflow 盲目复制。 CI 也用它 ：第 9 讲的持续集成，步骤大多是 shell 命令。"}, {"u": "ch01.html#s4", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "shell 先按空白切词，第一个词是程序名", "x": "shell 拿到一行命令，先按空白切成一串词。第一个词是要运行的程序，后面的都是参数。 bash · 本机实测 $ echo hello world # 切成 3 个词，中间几个空格都一样 hello world $ echo \"hello world\" # 引号里不切，4 个空格原样保留 hello world $ echo My\\ Photos # \\ 让紧跟的空格变成普通字符 My Photos $ cd My Photos # 没加引号，cd 收到了两个参数 bash: cd: too many arguments 打个比方 切词就像拿剪刀沿着空格剪纸条。引号是贴在纸条上的胶带，胶带盖住的空格不剪。反斜杠是只盖一个字的小胶带。 打开终端看到的那一小段叫 提示符 （prompt）。它表示 shell 在等你输入。 讲义里的提示符 missing:~$ 含义 missing 主机名。讲师的提示符还带用户名，比如 jon@xos ~ 当前所在的目录。 ~ 是家目录的简写 $ 表示你不是 root 管理员 想让一个参数里带空格，有两种写法 。 引号 ： 'My Photos' 或 \"My Photos\" 。引号里的空格不切。 转义 ： My\\ Photos 。反斜杠告诉 shell，下一个字符别当特殊字符。 切出来的这些词，最后就是程序拿到的参数。Python 里叫 sys.argv ，Java 里是 main 的 args （ 学生提问）。 路径里同时有空格、单引号和双引号时最难写。得把几种引号拼着用。很头疼，但总能写对。 为什么会在这里踩坑 文件名带空格最容易出事。 cd My Photos 被切成两个参数，bash 直接报 too many arguments。脚本里更隐蔽。 rm $file 没加引号，带空格的文件名会被拆成两个去删。所以变量一律写成 \"$file\" 。 引号没闭合怎么办 敲 echo 'hello 回车，shell 会显示 > 等你接着输（ ）。补上引号就行。不想要这行了，就按 Ctrl + C 。 下面的演示一步步切词。看扫描指针怎么走，词怎么进 argv。再看引号和反斜杠怎么改规则。"}, {"u": "ch01.html#s5", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "不会用就先 man", "x": "man 程序名 会打开这个程序的说明书。所有选项都在里面，很多还附了例子。 bash $ man echo # 打开 echo 的手册，按 q 退出 $ man bash # 很厚的一本，按 / 再输关键词搜索 $ date --help # 只想看简短版，多数程序支持 --help 打个比方 man 是家电附带的说明书，什么都写，就是厚。tldr 是别人贴在冰箱上的便利贴，只写最常用的几招。 为什么会在这里踩坑 Git Bash 没有带 man。本机实测敲 type man ，结果是 not found。在 Git Bash 里只能用 --help ，或者上网查手册页。一般的 Linux 都自带 man。 讲义推荐 · tldr tldr 直接给出常见用法的例子。另外，LLM 很会解释命令，也能帮你拼出想要的写法。"}, {"u": "ch01.html#s6", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "相对路径从当前目录算，cd 就是改当前目录", "x": "shell 一直记着一个当前目录。相对路径都从它算起， cd 改的就是它。 bash · 本机实测（Git Bash 的家目录是 /c/Users/lrhto） $ cd /; pwd # 以 / 开头是绝对路径，从根走起 / $ cd usr/../usr/./bin/..; pwd # .. 退一层，. 原地不动 /usr $ cd ~/..; pwd # ~ 是家目录，它的上一层是 /c/Users /c/Users 打个比方 当前目录就像你在商场里站的位置。相对路径是“往前走两家店”。绝对路径是“从正门进来第三家”。你一挪地方，“往前两家”就指向别处了。 很多命令不说位置时，就作用在当前目录上。所以提示符里一直显示它。不确定自己在哪，就敲 pwd 或 echo $PWD 。 绝对路径从根 / 找起。相对路径从当前目录找起（视频 22:58 的例子） 写法 含义 例子 /a/b 绝对路径，从根 / 逐段走 cd /bin a/b 相对路径，从当前目录开始 在 / 时 cd bin 到 /bin 。在 /bin 里再 cd bin 就报错 . 当前目录本身 cd . 原地不动 .. 上一层目录。在 / 时还是 / cd ../6858 退一层再进隔壁 ~ 家目录 cd ~/.. 到 /home 为什么会在这里踩坑 脚本里写了 cat data.txt 。在脚本所在的目录跑没问题，换个目录跑就找不到文件。因为相对路径看的是你当时站在哪，不看脚本放在哪。 Tab 补全 ：敲几个字母按 Tab 会自动补全。候选不止一个时，按两下 Tab 全部列出。讲师演示 cd /b 时，候选有 /bin 和 /boot 。 下面的演示走一遍讲义里那条绕圈命令 cd bin/../bin/././../bin/.. 。每走一段，当前目录跟着变。 讲义推荐 · zoxide zoxide 会记住你常去的目录。以后敲 z 关键字 就能跳过去，少打很多字。"}, {"u": "ch01.html#s7", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "shell 按 $PATH 的顺序找程序，只用第一个", "x": "敲 date 时，shell 按 PATH 里的目录挨个找同名文件。找到第一个就运行，后面的不看。 bash · 本机实测（Git Bash） $ which -a python # 三个都叫 python，敲 python 只跑第一个 /d/py/python /d/anaconda/python /c/Users/lrhto/AppData/Local/Microsoft/WindowsApps/python $ type cd # cd 是内建命令，根本不查 PATH cd is a shell builtin 打个比方 PATH 像一排抽屉，从左往右挨个翻。翻到第一个就停手。后面的抽屉里有同名的，也不会去管。 PATH 是一个 环境变量 。里面是一串目录，用冒号隔开。讲义里的样子是这样的： 讲义原文 missing:~$ echo $PATH /usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin missing:~$ which echo /bin/echo missing:~$ /bin/echo $PATH /usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin shell 查找命令的顺序。“内建优先”这一步是补充，不在视频里。出处是 man bash 的 COMMAND EXECUTION 一节 which 程序名 把同样的查找走一遍，打印第一个命中的路径。 which 自己也只是一个程序。 which -a sh 列出 PATH 里 所有 同名文件（ ）。 直接写完整路径，比如 /bin/echo ，就会 跳过 查找。 想知道能运行哪些程序？把 PATH 里每个目录 ls 一遍，比如 ls /bin 。 为什么会在这里踩坑 装了新版 Python，敲 python 跑的还是旧版。多半是旧版所在的目录在 PATH 里更靠前。先敲 which -a python 看看排序，再去调 PATH。上面本机实测就有三个 python。 bash · 本机实测 $ which -a sh # Git Bash 里同一个 sh 被列了三次 /usr/bin/sh /bin/sh /usr/bin/sh 补充（非视频内容）：为什么 sh 列了三行 Git Bash 的 PATH 里， /usr/bin 出现了不止一次。 which -a 每命中一次就列一行。 /bin 在 Git Bash 里也映射到同一个目录。规则不变，shell 只用第一个。 下面的演示让搜索指针一个目录一个目录地走。先找到 /bin/echo 。再看 lecture.sh 为什么找不到。最后看 ./lecture.sh 和 cd 为什么根本不查 PATH。"}, {"u": "ch01.html#s8", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "sort 默认按字典序，uniq 只合并挨着的行", "x": "这几个小工具各管一件事。最容易错的有两点。 sort 默认按字典序排， uniq 只看相邻的行。 bash · 本机实测 $ printf 'a\\n3\\n31\\nb\\nx\\n1\\n4\\n' > data # 造 7 行测试数据 $ sort data | tr '\\n' ' ' # 字典序逐个字符比，31 排在 4 前面 1 3 31 4 a b x $ sort -n data | tr '\\n' ' ' # -n 才按数值，字母行被当成 0 a b x 1 3 4 31 $ printf 'bob\\nann\\nbob\\n' | uniq -c # 两个 bob 不挨着，各数一次 1 bob 1 ann 1 bob $ printf 'bob\\nann\\nbob\\n' | sort | uniq -c # 先排序，同名才挨在一起 1 ann 2 bob 打个比方 uniq 像排队点名，只和前一个人比。前后两人同名才算重复。中间隔了一个人，它就认不出来。所以先用 sort 让大家按名字站好。 命令 作用 要点 cat file 打印文件内容 讲义推荐带语法高亮的 bat sort file 按行排序 默认字典序 。加 -n 才按数值 uniq file 去掉 相邻 的重复行 4 4 4 3 4 变成 4 3 4。 sort -u 一步到位 head / tail 打印开头或结尾几行 默认 10 行， -n 数字 指定 为什么会在这里踩坑 统计次数时忘了先 sort，同一个名字会被数成好几段。上面两个 bob 就是这样。正确写法是 sort | uniq -c 。按次数排序时也要加 -n ，不然 10 会排在 9 前面。 补充（非视频内容） tr '\\n' ' ' 只是把多行压成一行，方便展示。"}, {"u": "ch01.html#s9", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "grep 挑出匹配的行，sed 改写每一行", "x": "grep 只把匹配模式的行打印出来。 sed 按规则改写每一行。两者的模式都是正则表达式。 bash · 写法示意 $ grep -r TODO src/ # 搜的是文件内容，不是文件名 $ sed 's/grep/john/' notes.md # 不加 -i，只打印结果，文件不变 $ sed -i 's/grep/john/g' */*.md # -i 直接改文件，g 表示一行里全换 打个比方 grep 像拿荧光笔扫一遍，只抄下带关键词的行。sed 像编辑器里的“查找替换”，但能一口气改一堆文件。 grep 加 -r 会钻进子目录，把整棵目录树都搜一遍。正则表达式在第 9 讲细讲。 sed 是一个能编程的行编辑器。它有自己的小语言，最常用的就是查找替换： 讲义原文 $ sed -i 's/pattern/replacement/g' file 片段 含义 -i 直接改文件。不加的话文件不变，只打印结果 s/…/…/ sed 里的替换命令。 / 隔开模式和替换内容 g 一行里所有 匹配都换。不加只换每行第一个 讲师在课程仓库里跑了 sed -i 's/grep/john/g' */*.md 。再用 git diff 一看，所有 grep 都成了 john（ ）。 为什么会在这里踩坑 第一，忘了 g ，每行只换掉第一个。第二， -i 改完没法撤销。稳妥的做法是先不加 -i 看输出，确认没错再加。第三，macOS 自带的 sed， -i 后面必须跟一个参数，比如 -i '' 。这一条是补充，不在视频里。 glob 归 shell 展开，正则归程序解释 *.md 这种通配符，shell 会先展开成文件名。正则表达式原样交给程序，由程序自己解释。 bash · 本机实测（目录里有 a/x.md 和 b/y.md） $ echo */*.md # shell 先展开成文件列表，echo 只管打印 a/x.md b/y.md $ echo '*/*.md' # 加了引号，shell 不展开，原样交给 echo */*.md 打个比方 glob 像门卫，先按名单把人领进来。程序只看得到名单上的人。正则像一张规则纸条，原样递给屋里的程序自己判断。 glob（通配符） 正则表达式 谁来解释 shell 在运行程序前展开成路径列表。前提是没加引号 程序自己 ，比如 grep 和 sed 语法 很小： * ? {a,b} ，还有 [...] 复杂得多 用途 写路径， / 有特殊含义 匹配任意文本，不懂目录 例子 */*.md ：任意子目录里的 .md 文件 [^a].*-[0-9] 为什么会在这里踩坑 给 grep 的正则不加引号，里面的 * 会先被 shell 当成 glob。如果正好匹配到文件名，grep 收到的就不是你写的模式。所以正则一律用单引号包起来。 讲义推荐 · ripgrep ripgrep（rg） 比 grep 快，也更友好。它默认递归搜当前目录，只是可移植性差一点。"}, {"u": "ch01.html#s10", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "find 逐层检查每个文件，-exec 对结果跑命令", "x": "find 从一个目录往下逐层走。每个文件都拿条件过一遍，全满足的才输出。 讲义例子（注释是笔记加的） $ find ~/Downloads -type f -name \"*.zip\" -mtime +30 # 30 天前的 zip 文件 $ find ~ -type f -size +100M -exec ls -lh {} \\; # 大于 100M 的逐个列出 $ find . -name \"*.py\" -exec grep -l \"TODO\" {} \\; # 哪些 py 文件里有 TODO 打个比方 find 像仓库管理员拿着清单逐层巡查。条件就是清单上的要求。 -exec 是让他每找到一件，就顺手贴个标签。 片段 含义 -type f 只要普通文件。 d 表示目录 -name \"*.zip\" 文件名匹配这个 glob。要 加引号 ，交给 find 自己匹配 -mtime +30 修改时间在 30 天以前 -size +100M 大于 100M -exec 命令 {} \\; 对每个结果跑一次命令， {} 换成文件路径。 ; 表示命令结束。它要写成 \\; ，否则 shell 会当成分隔符 -maxdepth N 最多往下走 N 层，默认不限。讲师现场踩了坑：它要写在 -name 这类条件 前面 grep -l 打印匹配的 文件名 ，不打印匹配的行。 为什么会在这里踩坑 -name 后面的 *.zip 不加引号，就会被 shell 先展开。当前目录正好有 zip 文件时，find 收到的就成了具体文件名。另外，把 ls -lh 换成 rm ，一行就能批量删文件。讲师也没真跑。你也先用 ls 看清楚再删。 讲师建议 find 的语法很怪，看几个例子学不会。网上的 find 例子极多。所以 让 LLM 帮你写 find 命令 ，效果通常很好（ ）。更现代的替代品是 fd 。"}, {"u": "ch01.html#s11", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "awk 按列取数据", "x": "awk 把每一行按空白切成几列。 $1 是第一列， $2 是第二列。 bash · 本机实测 $ printf 'a b c\\nd e f\\ng h i\\n' > m # 3 行 3 列 $ awk '{print $2}' m # 单引号：$2 原样交给 awk b e h $ awk \"{print $2}\" m # 双引号：$2 先被 shell 换成空串 a b c d e f g h i 打个比方 awk 像拿着一张 Excel 表，只抄你要的那一列。sed 擅长改文件，awk 擅长拆文件。 { … } 里的代码对每一行执行一次。前面可以加一个条件，只处理满足条件的行。练习 17 会用到。 加 -F, 改用逗号分列，awk 马上就能解析 CSV。讲师现场拿没逗号的文件试了一下。没有第 2 列，打印出来全是空行。 为什么会在这里踩坑 awk 程序要用单引号包起来。用了双引号， $2 会先被 shell 当成自己的变量。它通常是空的，awk 收到的就成了 {print } ，于是整行原样打印。上面第二条命令就是这样。"}, {"u": "ch01.html#s12", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "流水线的每一级只做一件小事", "x": "前一级的输出就是后一级的输入。几个小工具一连，就能从日志里数出谁被乱试得最多。 讲义原文（讲师的服务器现场没连上，讲义给出了结果） $ ssh myserver 'journalctl -u sshd -b-1 | grep \"Disconnected from\"' \\ | sed -E 's/.*Disconnected from .* user (.*) [^ ]+ port.*/\\1/' \\ | sort | uniq -c \\ | sort -nk1,1 | tail -n10 \\ | awk '{print $2}' | paste -sd, postgres,mysql,oracle,dell,ubuntu,inspur,test,admin,user,root 打个比方 像工厂流水线。每个工位只拧一颗螺丝，整条线连起来就能出成品。 每一级只做一件小事。前一级的 stdout 就是后一级的 stdin 片段 作用（视频 54:00 到 56:21） ssh myserver '…' 在远程服务器上执行引号里的命令。第 2 讲细讲 ssh journalctl -u sshd -b-1 打印 sshd 服务的日志。 -b-1 只要上一次开机期间的 grep \"Disconnected from\" 有人登录失败或断开时，日志里会出现这句 sed -E 's/…(.*)…/\\1/' 正则替换。 \\1 是 反向引用 ，指第一个括号抓到的用户名 sort | uniq -c 先排序再计数。 john 出现 3 次就输出 3 john sort -nk1,1 | tail -n10 按第 1 列的数值排，次数多的在后面。取最后 10 行就是前 10 名 awk '{print $2}' | paste -sd, 只留用户名，再用逗号连成一行 为什么会在这里踩坑 整条流水线一次写对很难。出错时别盯着整行看。从左往右一级级加，每加一级就看一眼输出。哪一级的输出不对，问题就在哪。 讲义结果里全是 postgres、oracle、admin、root 这类名字。它们来自网上的扫描器，在乱试密码。讲师说，“没有一个是我的名字”。 我们连不上讲师的服务器。所以笔记造了 12 行 示意日志 。在本机把每一级都真跑了一遍。下面的演示逐级播放。右侧代码高亮当前这一级，控制台是这一级的真实输出。"}, {"u": "ch01.html#s13", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "管道把程序接到程序，重定向把流接到文件", "x": "| 把左边程序的标准输出，接到右边程序的标准输入。 > 和 < 把流改接到文件上。 bash · 本机实测 $ ls /nonexistent /tmp > out.txt 2> err.txt; echo \"exit=$?\" # 练习 5：正常输出和报错分开存 exit=2 $ cat err.txt # 报错走的是 2 号流 stderr ls: cannot access '/nonexistent': No such file or directory $ printf '3\\n1\\n2\\n' > f; sort f > f; wc -c < f # > 先把 f 清空，sort 读到的是空文件 0 打个比方 每个程序都接着三根水管。0 号进水，1 号出水，2 号排污。管道把一根出水管接到下一个程序的进水口。重定向把水管接进水桶。 大多数命令行程序没拿到文件参数，就去读 stdin。管道正是靠这一点才能用。 写法 效果 cmd > file stdout 写进文件，会 覆盖 cmd >> file stdout 追加 到文件末尾 cmd < file stdin 从文件读，不从键盘读 cmd 2> file stderr 也就是报错，写进文件 练习 5 cmd > file 2>&1 stdout 和 stderr 进同一个文件。讲义的 flaky 脚本就这么用 a | tee log | b tee 把输入原样往下传， 同时 存一份到文件 讲义里的 tee 用法 verbose cmd | tee verbose.log | grep CRITICAL 。完整日志留在文件里，终端只显示关键行。 bash · 本机实测 $ printf 'INFO a\\nCRITICAL disk\\nINFO b\\n' | tee verbose.log | grep CRITICAL CRITICAL disk $ wc -l verbose.log # 终端只看到一行，文件里三行都在 3 verbose.log 为什么会在这里踩坑 第一， sort f > f 会把 f 清空。shell 先打开并清空输出文件，sort 才开始读。上面本机实测，结果是 0 字节。第二， 2>&1 要写在 > file 后面。写反了，报错还是跑到终端上： bash · 本机实测 $ ls /nonexistent > o 2>&1; cat o # 先把 1 接到 o，再让 2 跟着 1 走 ls: cannot access '/nonexistent': No such file or directory $ ls /nonexistent 2>&1 > o; wc -c < o # 2 先跟了终端，1 后来才改到 o ls: cannot access '/nonexistent': No such file or directory 0 管道和重定向是一件事的两面，都是把流接到哪里。所以下面的演示分两幕。第一幕看管道接 stdin。第二幕看重定向把 0、1、2 改接到文件。"}, {"u": "ch01.html#s14", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "if 看的是退出码，不是真假值", "x": "bash 的 if 后面跟的是一条命令。命令退出码是 0 就算真，非 0 就算假。 bash · 本机实测 $ grep -q zzz data; echo $? # 没找到 zzz，退出码是 1 1 $ if grep -q 31 data; then echo found; else echo missing; fi # if 直接看 grep 的退出码 found $ a=x; [ \"$a\"=\"y\" ] && echo same # = 两边没空格，成了一个非空字符串，永远为真 same $ a=x; [\"$a\" = \"y\"] # [ 后面没空格，shell 去找叫 [x 的程序 bash: [x: command not found 打个比方 if 不问“这句话对不对”，只问“这件事办成没有”。办成了返回 0，就走 then。这和 C 语言里 0 为假正好相反。 bash 有变量、条件、循环和函数。你在提示符里敲的，就是一小段被解释执行的代码。 bash · 语法骨架（讲义，注释是笔记加的） if command1; then command2; command3; fi # command1 退出码为 0 才走 then while command1; do command2; command3; done # command1 一直成功，就一直循环 for varname in a b c d; do command; done # 依次把 a b c d 放进 varname for i in $(seq 1 10); do …; done # $( ) 是命令替换，把输出塞进来 概念 说明 退出码 程序结束时返回的一个数。 $? 存着上一条命令的退出码。grep 找到返回 0，没找到返回 1，出错返回 2 $(cmd) 命令替换。先运行 cmd，用它的输出换掉整个 $( ) ，再按空白切词。旧代码里的反引号作用一样。 $( ) 能嵌套，优先用它 test / [ 专门做比较的程序，条件成立就返回 0。 [ -f file ] 判断文件存在。 [ \"$var\" = \"string\" ] 判断字符串相等 [[ ]] bash 内建的加强版，引号相关的怪问题更少 sleep 10 视频里放进 while 循环，每 10 秒检查一次 为什么会在这里踩坑 [ 其实是一个命令， ] 是它的最后一个参数。所以 [ 、 ] 和 = 两边都要有空格。少了空格不一定报错，可能悄悄地永远为真。上面第三条就是。 下面的演示把“条件就是退出码”画出来。先看 grep 的退出码怎么决定分支。再看 $( ) 的输出怎么变成 for 的元素。最后看 test 不成立时怎么走 else。 学生提问：if 是程序吗（视频 1:07:31） 不是。 if 、 while 和 | 都是 bash 自己的语法， cd 也内建在 shell 里。 test 和 [ 在讲师的机器上是真实存在的程序， which [ 能找到。cd 为什么必须内建？这是练习 7。 讲师建议 bash 的语法很古老。结束 if 要写 fi ，讲师的解释是“因为为什么不呢”。这类命令 LLM 写得很好。人除非写过很多次，否则总得查。"}, {"u": "ch01.html#s15", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "脚本要过两关：执行权限和第一行的 #!", "x": "运行 ./lecture.sh 时，系统先查有没有执行权限。再读第一行的 #! ，决定把文件交给哪个解释器。 bash · 本机实测 $ printf '#!/bin/sh\\necho hi\\n' > lecture.sh # 第一行 #! 指定用 /bin/sh 来跑 $ chmod +x lecture.sh # 加执行权限，Linux 下不加会 Permission denied $ ./lecture.sh # 带 ./，明说文件就在当前目录 hi $ lecture.sh # 不带 /，只查 PATH，当前目录不在里面 bash: lecture.sh: command not found 打个比方 #! 像快递单上的收件人。系统看一眼第一行，就知道这个包裹该交给谁拆。执行权限是门禁卡，没卡连门都进不去。 命令长到三行，在提示符里就很难改了。把它们写进文件，bash 会从上到下逐行执行。效果和你一行行敲一样。 “内核读 #! 再启动解释器”这个分工是补充，不在视频里。视频里的说法是：shell 运行 #! 指定的程序，把文件交给它 shebang #!/path ：写在文件第一行，指定用哪个程序运行它。 ./lecture.sh 就相当于 /bin/sh lecture.sh 。换成 #!/usr/bin/python 就能直接跑 Python。R、Julia、Ruby 都行。Java 不行，它得先编译。 执行权限 ： ls -l 左边的 rwx 分别是读、写、执行。新建的文件没有 x，执行会报 Permission denied 。 chmod +x 加上执行位后，ls 还会把它换个颜色显示。 为什么要写 ./ ：名字里没有 / 时，shell 只查 PATH。当前目录故意不放进 PATH。不然有人在目录里放个 ls 文件，你敲的 ls 就被顶替了。 本机实测差异：Git Bash 不认 chmod 在 Windows 的 Git Bash 里，以 #! 开头的文件， ls -l 直接显示 -rwxr-xr-x 。不用 chmod 也能运行。不带 ./ 运行一样会报错： bash · 本机实测 $ ls -l lecture.sh -rwxr-xr-x 1 lrhto 197610 30 Oct 29 15:29 lecture.sh $ lecture.sh bash: lecture.sh: command not found 想亲眼看到 Permission denied，请在 WSL 或 Linux 里做练习 9。 补充（非视频内容）：Windows 换行符的坑 在 Windows 上写的脚本，行尾常常是 CRLF。到了 Linux，第一行就成了 #!/bin/sh 后面多一个回车符。系统找不到这个解释器，会报 bad interpreter。本机 Git Bash 能容忍 CRLF，实测照样输出 hi。所以这个坑只在 Linux 上踩到。 下面的演示把两道关画出来。先查执行权限，再读 #! 启动解释器。最后一步对照 Git Bash 的实测差异。"}, {"u": "ch01.html#s16", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "讲义的完整脚本：一直跑，跑到失败为止", "x": "这个脚本循环跑测试，直到某一次失败才停。日志文件里留下的，正好是失败那一轮。 打个比方 像设个闹钟让机器一直试。你去喝咖啡，它摔倒的那一刻就停下。现场原样留着，等你回来看。 讲师在 6.824 分布式系统课上碰到一个测试。它跑一百次才挂一次。于是写了这个脚本。后台先把 CPU 压满，再循环跑测试，人去喝咖啡。 flaky.sh（讲义脚本，注释译成中文并补了考点） #!/bin/bash set -euo pipefail # 三个安全开关，下面的表格逐个讲 # 在后台启动 CPU 压力 stress --cpu 8 & # & 放到后台，shell 不等它 STRESS_PID=$! # $! 是刚才那个后台进程的 PID # 准备日志文件 LOGFILE=\"test_runs_$(date +%s).log\" # 用时间戳起名，每次都不重名 echo \"Logging to $LOGFILE\" # 一直跑测试，直到失败 RUN=1 # 从 1 开始，正好避开 ((RUN++)) 的坑 while cargo test my_test > \"$LOGFILE\" 2>&1; do # 每轮覆盖写，最后留下失败那轮 echo \"Run $RUN passed\" ((RUN++)) done # 收尾并报告 kill $STRESS_PID # 别忘了关掉后台的压力进程 echo \"Test failed on run $RUN\" echo \"Last 20 lines of output:\" tail -n 20 \"$LOGFILE\" echo \"Full log: $LOGFILE\" 新东西 含义 & 放到后台运行，shell 不等它结束。 $! 是这个后台进程的 PID $(date +%s) 当前的 Unix 时间戳，本机实测的一个例子是 1793288178 。每次日志名都不一样 > \"$LOGFILE\" 2>&1 每一轮的全部输出都覆盖写进日志。循环结束时，文件里正好是失败那一轮 ((RUN++)) 算术展开，RUN 加 1 set -e 任何命令失败，脚本立刻退出 set -u 用到没定义的变量就报错，不当成空串 set -o pipefail 管道里任一程序失败，整条管道就算失败 下面的演示逐行执行这个脚本。右侧同步显示变量、日志文件和输出。失败轮次和 PID 都是示意。 bash · 本机实测：三个开关的效果 $ bash -c 'set -u; echo \"$NOPE\"' # -u：变量没定义，直接报错 bash: line 1: NOPE: unbound variable $ bash -c 'set -e; false; echo never'; echo \"exit=$?\" # -e：false 一失败就退出 exit=1 $ bash -c 'false | true; echo $?' # 默认只看管道里最后一个程序 0 $ bash -c 'set -o pipefail; false | true; echo $?' # pipefail：任一失败就算失败 1 为什么会在这里踩坑（补充，非视频内容） 算术命令 ((表达式)) 的值为 0 时，退出码是 1。讲义脚本里 RUN 从 1 开始，所以没事。要是从 0 开始，第一次 ((RUN++)) 的值就是 0。退出码成了 1， set -e 会让脚本 一声不吭地退出 。本机实测： bash · 本机实测 $ bash -c 'set -e; RUN=0; ((RUN++)); echo \"after RUN=$RUN\"'; echo \"exit=$?\" # echo 那句根本没跑到 exit=1 改成 RUN=$((RUN + 1)) 就没这个问题。 讲义建议 bash 的坑多到有人专门建站收集，叫 BashPitfalls 。写脚本时多用 shellcheck 检查。LLM 很会写、也很会调 shell 脚本。脚本超过 100 行，就让它帮你改写成 Python 这类正经语言。"}, {"u": "ch01.html#s17", "c": "第 1 讲 · 课程概览 + Shell 入门", "t": "一页带走：本讲结论都在这几行里", "x": "把本讲浓缩成几行命令。每行的注释就是结论和考点。 bash · 本讲速查（注释即考点） echo hello world # 切成 3 个词，echo 用一个空格拼起来输出 echo \"hello world\" # 引号里不切，argv[1] 带着 4 个空格 which -a python # 同名程序全列出来，shell 只跑第一个 sort data | uniq # uniq 只合并相邻行，所以先 sort find . -name \"*.zip\" # 加引号，模式交给 find，别让 shell 先展开 sed -i 's/a/b/g' */*.md # 不加引号，就是要 shell 展开成文件列表 cmd > out.txt 2>&1 # 2>&1 写在后面，报错才会跟着进文件 if grep -q x f; then … # if 看退出码，0 才是真 ./lecture.sh # 当前目录不在 PATH 里，要写 ./ 终端是窗口，shell 是读命令的程序。本课用 bash。 一行命令按空白切成参数，第一个词是程序名。引号和 \\ 能改变切法。 程序名里没有 / 时，按 $PATH 的顺序找。 cd 和 if 是 shell 内建的。 cat、sort、uniq、grep、sed、find、awk 各管一件事。用 | 接起来，威力就大了。 > 、 >> 和 < 把流接到文件， tee 负责分流。 if 和 while 看命令的退出码。 [ 做比较， $( ) 做命令替换。 脚本就是文件加 shebang 加执行权限。 set -euo pipefail 让脚本更安全。 下一步 这一讲是全课的地基，后面每一讲的工具都在 shell 里用。下一讲是命令行环境。会深入讲参数、glob、三条流和环境变量。还有信号、作业控制、SSH 和 tmux。现在先去做 本讲练习的可视化笔记 。"}, {"u": "ch02.html", "c": "第 2 讲 · 命令行环境", "t": "开头", "x": "本讲结论 命令行程序靠一组约定和外界打交道。输入有参数、stdin 和环境变量。输出有 stdout、stderr 和退出码。跑到一半，它还可能收到信号。看懂这几样，再学会 SSH、tmux 和 dotfiles。换到哪台机器上，你都能舒服地干活。"}, {"u": "ch02.html#s1", "c": "第 2 讲 · 命令行环境", "t": "CLI 程序没有函数签名，进出口全靠约定", "x": "命令行程序没有类型签名可看。它从哪拿输入、往哪交结果，全靠大家默认遵守的约定。 bash · 本机实测 $ { echo \"data\"; echo \"oops\" >&2; } | wc -l # 一句走 stdout，一句走 stderr。管道只接 stdout oops 1 打个比方 CLI 程序像一台标准接口的机器。进料口、出料口、报警灯的位置全都统一。所以几台机器能直接首尾相连。 上一讲说过，shell 是一门完整的编程语言。它和普通语言不一样。它的设计只围着两件事转。一是运行程序，二是让程序之间高效通信。这套设计高度依赖约定（conventions）。一个 CLI 程序想和别人配合好，就得守这些约定。 Python 函数 def add(x: int, y: int) -> int 一眼就能看出输入输出。shell 脚本没这么直白。讲义开头的例子，几乎用上了本讲所有概念。讲师说，现在看不懂没关系。 讲义例子（注释是笔记加的，先别急着看懂） #!/usr/bin/env bash if [[ -f $1 ]]; then # $1：第 1 个参数 echo \"Target file already exists\" exit 1 # 退出码，非 0 表示失败 else if $DEBUG; then # 环境变量 grep 'error' - | tee $1 # - 表示读 stdin，| 是管道 else grep 'error' - > $1 # 重定向 stdout fi exit 0 fi 本讲的骨架。左边 4 种输入，右边 4 种输出。文件副作用出自讲义“返回码”一节的开头 为什么会在这里踩坑 自己写脚本时，报错常被随手 echo 到 stdout。下游程序会把报错当成数据接着处理。报错要写进 stderr，写法是 echo \"出错了\" >&2 。上面的实测里，oops 就没进管道。失败时还要 exit 1 ，调用方才知道出了事。"}, {"u": "ch02.html#s2", "c": "第 2 讲 · 命令行环境", "t": "参数只是一串字符串，怎么解释归程序", "x": "shell 把命令行切成一串字符串，原样交给程序。哪个算选项、哪个算文件名，由程序自己说了算。 bash · 本机实测（args.py 只有一行 print(sys.argv)） $ python args.py -l project1 # -l 对 shell 来说只是个普通字符串 ['args.py', '-l', 'project1'] 打个比方 shell 像快递分拣员。它只按空格把包裹分好，一件件递进去。包裹里是衣服还是书，由收件的程序自己拆开看。 所以 ls -l folder/ 就是用参数 ['-l', 'folder/'] 运行 /bin/ls 。讲师写了个只打印 sys.argv 的 Python 脚本，验证了这一点。在 shell 脚本里，用特殊变量取参数： 写法 含义 $1 … $9 第 1 到第 9 个参数 $@ 全部参数。写成 \"$@\" 时，每个参数各自完整 $# 参数个数 $0 脚本自己的名字 bash · 本机实测（p.sh 打印上面几个变量） $ bash p.sh -l \"my folder\" x # 引号让 my folder 保持为一个参数 $0=p.sh $1=-l $2=my folder $#=3 arg: [-l] arg: [my folder] arg: [x] 为什么会在这里踩坑 脚本把参数往下传时，最常见的错是 $@ 没加引号。它会把 my folder 重新切成两个。写成 \"$@\" ，每个参数才原样保持： bash · 本机实测 $ set -- -l \"my folder\"; for a in $@; do echo \"[$a]\"; done # set -- 设定位置参数。没加引号 [-l] [my] [folder] $ set -- -l \"my folder\"; for a in \"$@\"; do echo \"[$a]\"; done # 加了引号，还是 2 个参数 [-l] [my folder] flag 是程序的约定，不是 shell 的语法 -a 、 --all 这些写法，shell 一概不管。是 ls 自己解析参数，才认得它们。 bash · 本机实测（目录里有隐藏文件 .a 和 main.py） $ ls # 默认不显示 . 开头的文件 main.py $ ls -a | tr '\\n' ' ' # -a：隐藏文件也列出来 . .. .a main.py $ diff <(ls -l -a) <(ls -la) && diff <(ls -la) <(ls -al) && diff <(ls -a) <(ls --all) && echo \"all same\" # 合并、换序、长短写法，结果全一样 all same 打个比方 flag 像点菜时说的“少辣、去葱”。服务员 shell 只管把话传进后厨。听不听得懂，看厨师自己。 以 - 或 -- 开头的参数叫 flag ，也就是选项。它通常可选，用来改程序的默认行为。 单横线后面一般跟一个字母，比如 -a 。双横线跟长名字，比如 --all 。同一个选项常常两种写法都有， ls -a 就等于 ls --all 。 单字母 flag 能合并，顺序也无所谓。 ls -l -a 、 ls -la 、 ls -al 是一回事。 几乎人人都支持 --help 、 --verbose 和 --version 。 -a 常表示 all， -h 常表示 help。 关键点（视频 5:09） 这些便利 不是 shell 给的 ，是 ls 自己解析参数实现的。shell 并不要求程序用 - 或 -- 。你完全可以写一个 myprogram +myoption myfile ，只是会让人困惑。真写程序时，用现成的解析库，比如 Python 的 argparse 。 还有一个常见约定。同类参数可以给任意多个，程序对每个都做同样的事。 mkdir src 加 mkdir docs ，等于 mkdir src docs 。这个语法糖单看不起眼。和 glob 一结合，就很强大。 为什么会在这里踩坑 以为 -la 这种合并写法是 shell 的功能，到哪都能用。其实每个程序各有各的规矩。比如 find 的 -name 是单横线加长名字。所以 flag 怎么写，以 man 或 --help 为准。"}, {"u": "ch02.html#s3", "c": "第 2 讲 · 命令行环境", "t": "glob 由 shell 先展开，程序只看到文件名", "x": "rm *.py 里的 rm 收不到 *.py 。shell 先把它换成匹配到的文件名，再去启动 rm。 bash · 本机实测（目录：args.py main.py utils.py notes.md run.sh） $ python args.py *.py # shell 先展开，args.py 收到 3 个文件名 ['args.py', 'args.py', 'main.py', 'utils.py'] $ python args.py \"*.py\" # 加了引号不展开，收到的是字面的 *.py ['args.py', '*.py'] 打个比方 glob 像出发前点名。shell 先按名单把人叫齐，再把整队交给程序。程序看不到名单规则，只看到来了谁。 想删掉当前目录里所有 .py 文件，不递归。用上一讲的东西，可以写个 for 循环： for file in $(ls | grep -P '\\.py$'); do rm \"$file\"; done 。其实只要 rm *.py 。 关键在于， rm 收到的不是 '*.py' 。shell 先在当前目录里找匹配的文件。找到后替换进命令行，再去调用程序。目录里有 main.py 和 utils.py，rm 收到的就是 ['main.py', 'utils.py'] 。讲师用打印 argv 的脚本验证了这一点（ ）。 glob 匹配 讲义例子 → 展开结果 * 零个或多个任意字符 rm *.py → rm main.py utils.py ? 恰好一个任意字符 见第 1 讲练习 3 {a,b} 把逗号隔开的几项，展开成多个参数 touch folder/{a,b,c}.py → touch folder/a.py folder/b.py folder/c.py convert image.{png,jpg} → convert image.png image.jpg 组合 先展开花括号，再匹配通配符 mv *{.py,.sh} folder ：移动所有 .py 和 .sh bash · 本机实测 $ echo folder/{a,b,c}.py # 花括号不看磁盘，直接生成 3 个词 folder/a.py folder/b.py folder/c.py $ echo *{.py,.sh} # 先变成 *.py *.sh，再各自去匹配 args.py main.py utils.py run.sh $ shopt -s globstar; echo **/*.py # ** 能跨任意层子目录 args.py main.py sub/deep/y.py sub/x.py utils.py 递归通配 ** 讲师用的 zsh 默认支持 ** 。它匹配任意层子目录（ ）。所以 rm **/*.py 会递归删除。bash 也支持，但要先 shopt -s globstar 。这一句是补充，非视频内容，上面已实测。 为什么会在这里踩坑 文件名以 - 开头时，glob 会展开出一个“选项”。下面的目录里有个文件就叫 -l 。 ls * 展开成了 ls -l a.txt ，输出成了长格式。换成 rm * ，碰上叫 -rf 的文件就危险了。写成 ls -- * 或 rm ./* 才稳。练习 1 有完整实测。 bash · 本机实测 $ touch -- -l a.txt # -- 之后不当选项，才建得出叫 -l 的文件 $ echo * # 先看 glob 展开成了什么 -l a.txt $ ls * # 等于 ls -l a.txt -rw-r--r-- 1 lrhto 197610 0 Nov 11 01:00 a.txt $ ls -- * # -- 之后全当文件名 -l a.txt 下面的演示画了 glob 展开、花括号展开和 -- 的作用。argv 都是本机真跑打印的。"}, {"u": "ch02.html#s4", "c": "第 2 讲 · 命令行环境", "t": "管道上的程序是同时启动的", "x": "shell 不会等 cat 跑完再启动 grep。管道上的程序一起启动。上游一产生数据，下游马上接着处理。 bash · 本机实测 $ yes | head -3 # yes 会无限输出 y。要是得等它跑完，这行永远不会结束 y y y 打个比方 管道像流水线上的传送带。上一个工位做好一件就放上去，下一个工位马上接手。没人等上游把一整天的活干完。 执行 cat myfile | grep -P '\\d+' | uniq -c 时， 三个程序是同时运行的 。shell 把它们一起启动。cat 的输出接到 grep 的输入。grep 的输出再接到 uniq 的输入（ ）。讲师写了个慢慢吐数字的 Python 脚本。接上 grep 一跑，两边并行干活。 讲义用 sleep 证明，所有进程立刻就启动了。注意 Git Bash 的 ps 只显示可执行文件的路径： bash · 本机实测（numbers.txt 每行一个：1 12 3 3 x 7） $ (sleep 2 && cat numbers.txt) | grep -P '^\\d$' | sort | uniq & $ sleep 0.5; ps | grep -E '(sleep|cat|grep|sort|uniq)' | grep -v -- '-E' # 0.5 秒后看看谁在跑 5508 5503 5503 29360 ? 197610 16:28:43 /usr/bin/sort 5506 5503 5503 40816 ? 197610 16:28:43 /usr/bin/grep 5509 5503 5503 37052 ? 197610 16:28:43 /usr/bin/uniq 5481 3788 3788 30080 ? 197610 16:28:38 /usr/bin/sleep 5507 5505 5503 22728 ? 197610 16:28:43 /usr/bin/sleep $ jobs -l [1]+ 5505 Running ( sleep 2 && cat numbers.txt ) 5506 | grep -P '^\\d$' 5508 | sort 5509 | uniq & $ wait # 2 秒后 cat 才启动，数据流过整条管道 1 3 7 第 4 行 PID 5481 的 sleep 和我们无关。它属于本机另一个进程组，PGID 是 3788。它的启动时间也早了 5 秒。我们的 4 个进程，PGID 都是 5503。 sleep、grep、sort、uniq 都在， 唯独没有 cat 。它要等 sleep 成功结束才启动，这是 && 的规矩。学生问，能不能让 cat 先跑？讲师答，拿掉 sleep 就会立刻执行。管道 | 只规定数据往哪流（ ）。 流 编号 约定 stdin 0 大多数程序从这里读输入，用管道时自动接好。很多程序把文件名 - 当成读 stdin。 echo \"hello\" | grep \"hello\" - 和不写 - 等价。这里的 - 不是 flag stdout 1 正常输出。 管道传的就是它 stderr 2 警告和错误。下一个程序不会把它当数据 bash · 本机实测 $ ls /nonexistent | grep \"pattern\" # 报错照样打在终端上 ls: cannot access '/nonexistent': No such file or directory $ ls /nonexistent 2>/dev/null # 没有任何输出：stderr 被扔进 /dev/null 第一条的报错照样出现在终端上，因为 stderr 根本没进管道。 /dev/null 是个特殊文件，写进去的东西直接消失（ ）。重定向的写法速查如下： 讲义例子（注释是笔记加的） echo \"hello\" > output.txt # stdout 覆盖写入文件 echo \"world\" >> output.txt # stdout 追加 ls foobar 2> errors.txt # stderr 写入文件 ls foobar &> all_output.txt # stdout 和 stderr 都写入同一个文件 grep \"pattern\" < input.txt # stdin 从文件读 cmd > /dev/null 2>&1 # 丢弃全部输出 讲义推荐 · fzf fzf 是个模糊查找器，很能体现 Unix 哲学。它从 stdin 读进很多行，给你一个交互界面来筛选，比如 ls | fzf 。后面“定制 shell”一节，会看到它接管 Ctrl + R 。本机没装，未实测。 为什么会在这里踩坑 想在报错里 grep 关键词，结果一行也搜不到。因为报错走 stderr，管道只接 stdout。先用 2>&1 把 stderr 并进 stdout，再进管道： bash · 本机实测 $ ls /nonexistent | grep -c \"No such\" # 报错没进管道，grep 数到 0 ls: cannot access '/nonexistent': No such file or directory 0 $ ls /nonexistent 2>&1 | grep -c \"No such\" # 并进 stdout 之后，数到 1 1 下面的演示画出三件事。进程同时启动，cat 迟到，stderr 绕过管道。"}, {"u": "ch02.html#s5", "c": "第 2 讲 · 命令行环境", "t": "等号两边不能有空格，变量全是字符串", "x": "foo=bar 是赋值。 foo = bar 却是运行一个叫 foo 的程序。shell 见空格就切参数，赋值也不例外。 bash · 本机实测 $ bash -c 'foo = bar' # 切成 3 个词，foo 被当成程序名 bash: line 1: foo: command not found $ foo=bar; echo \"$foo\" '$foo' # 双引号展开变量，单引号原样输出 bar $foo 打个比方 shell 读命令像念电报，见空格就断句。 foo = bar 在它眼里是三个词，和 ls -l x 没区别。第一个词当然就是程序名。 shell 变量 没有类型，全是字符串 。 单双引号不能互换。 '…' 是字面量。它不展开变量，不做命令替换，也不处理转义。 \"…\" 这些都会做。 命令替换 ： files=$(ls) 把 ls 的 stdout 存进变量，换行也一起存。所以 echo \"$files\" | grep README 照样逐行工作。 进程替换 （讲义）： <( CMD ) 先运行 CMD。它把输出放进一个临时文件。再把 <( ) 换成这个文件名。它适合只收文件参数、不读 stdin 的命令，比如 diff <(ls src) <(ls docs) 。 bash · 本机实测 $ files=$(ls); echo \"$files\" | grep \".py\" # 加了引号，换行还在，grep 能逐行挑 a.py b.py $ echo $files # 不加引号：换行被当作分隔符，压成一行 README.md a.py b.py numbers.txt $ diff <(ls src) <(ls docs) # 两个 <( ) 各变成一个文件名，交给 diff 2c2 < b --- > c 为什么会在这里踩坑 变量不加引号，是最常见的坑。上面 echo $files 就把多行压成了一行。文件名里有空格时，还会被拆成好几个参数。所以变量一律写成 \"$var\" 。 命令替换变成字符串，进程替换变成文件名。两者的区别看下面的演示： 只有 export 过的变量，才会传给子进程 shell 启动一个程序时，会把一组变量拷贝给它。这组变量就是 环境变量 。没 export 的变量只留在当前 shell，子进程看不到。 打个比方 export 像在便条上盖个“随入职包发放”的章。以后每来一个新员工，都复印一份当时的便条给他。没盖章的便条只贴在你自己桌上。 printenv 可以列出当前环境。讲师用 DEBUG 演示了三种情况（ 、 ）： bash · 本机实测 $ DEBUG=1 # 只是本地 shell 变量 $ bash -c 'echo \"child sees DEBUG=[$DEBUG]\"' # 子进程看不到 child sees DEBUG=[] $ DEBUG=2 bash -c 'echo \"prefix: child sees DEBUG=[$DEBUG]\"' # 写在命令前，只给这一条命令 prefix: child sees DEBUG=[2] $ echo \"parent DEBUG=[$DEBUG]\" # 父 shell 里还是 1 parent DEBUG=[1] $ export DEBUG; bash -c 'echo \"after export: child sees DEBUG=[$DEBUG]\"' after export: child sees DEBUG=[1] $ DEBUG=3; bash -c 'echo \"modified after export: child sees DEBUG=[$DEBUG]\"' # export 过再改值，新子进程看到新值 modified after export: child sees DEBUG=[3] $ unset DEBUG; bash -c 'echo \"after unset: child sees DEBUG=[$DEBUG]\"' after unset: child sees DEBUG=[] 写法 当前 shell 子进程 DEBUG=1 有 没有 。它只是本地 shell 变量 DEBUG=2 cmd 不变 只有这一次的 cmd 看到 2 export DEBUG=1 有 之后启动的子进程都有。之后再改值，子进程也看到新值。学生提问见 ，本机实测见上 unset DEBUG 删除 删除 bash -c '…' 是什么？它启动一个子 bash，执行右边这段字符串。这是创建子 shell 的一种办法（ ）。环境变量按惯例全大写，比如 HOME 、 PATH 、 DEBUG 。这样好和小写的本地变量区分，但这只是约定。 为什么要有环境变量 它让很多程序悄悄改变行为。系统给每个用户设好 $HOME 。程序想存配置，直接读它就行。不用每次都写 --home /home/alice 。 TZ 时区 TZ=Asia/Tokyo date 打印东京时间。之后 echo $TZ 是空的，因为 TZ 只给了那一条命令。很多程序都要知道时区，用环境变量最省事。 本机实测差异：Git Bash 没有时区数据库 bash · 本机实测（本机时区为 UTC） $ TZ=Asia/Tokyo date +'%H:%M %Z' # 查不到时区，悄悄退回 UTC 16:29 GMT $ TZ=JST-9 date +'%H:%M %Z' # POSIX 写法，不依赖时区数据库 01:29 JST Git Bash 没有 /usr/share/zoneinfo ，查不到 Asia/Tokyo 。于是 date 悄悄退回 UTC ，还不报错。改用 POSIX 写法 JST-9 ，就不依赖时区数据库。它是名字加上与 UTC 的偏移，东区写负号。在 Linux 和 macOS 上，讲义的写法正常工作。 为什么会在这里踩坑 在终端里写了 DEBUG=1 ，脚本里却读不到。因为脚本跑在子进程里，没 export 的变量不会拷过去。反过来也一样。脚本里 export 的变量，脚本一结束就没了，改不了你的终端。想改当前 shell，要用 source 。 下面的演示把父子进程的变量表画成两张卡片。看 export 前后，哪些会被拷贝过去："}, {"u": "ch02.html#s6", "c": "第 2 讲 · 命令行环境", "t": "成功是 0，&& 和 || 只看返回码", "x": "程序结束时会交回一个数，叫返回码。0 表示一切正常，非 0 表示出了问题。 && 、 || 、if、while 都只看它。 bash · 本机实测 $ ls > /dev/null; echo $? # 成功，返回 0 0 $ ls /nonexistent 2>/dev/null; echo $? # 失败，ls 返回 2 2 $ grep -q \"pattern\" file.txt && echo \"Pattern found\" # -q 不输出，只用返回码说话 Pattern found $ grep -q \"nope\" file.txt || echo \"Pattern not found\" # 没找到返回 1，|| 右边才跑 Pattern not found $ false || echo \"This will always print\" This will always print 打个比方 返回码像快递单上的签收栏。0 是“已签收”，别的数字是各种失败原因。后面的人只看签收栏，不拆包裹。 输入有参数、stdin 和环境变量。输出除了 stdout 和 stderr，还有这个 返回码 （return code 或 exit code）。脚本默认返回 0。想返回非 0，用内建命令 exit NUM 。读上一条命令的返回码，用 $? 。 && 和 || 是 短路 运算符，看的是返回码。 a && b 只在 a 成功时运行 b。 a || b 只在 a 失败时运行 b。 grep -q 是 quiet，只匹配不输出。你只关心找没找到时，就用它（ ）。 true 总是成功， false 总是失败。它们都是程序。 if 和 while 也只看返回码。 while read line; do echo \"$line\"; done < file.txt 里，read 读到文件末尾时返回非 0，循环就结束了。 为什么会在这里踩坑 $? 只记上一条命令的返回码。中间随手插一句 echo，它就被冲掉了。要么紧跟着读，要么先存进变量： bash · 本机实测 $ false; echo hi; echo $? # 读到的是 echo hi 的返回码 hi 0 $ false; rc=$?; echo \"rc=$rc\" # 先存起来，再慢慢用 rc=1 下面演示的最后 3 步，预告了下一节。进程被信号杀死时，返回码是 128 加信号编号 。本机实测是 130、137、143。右侧“手推过程”会逐行推导。"}, {"u": "ch02.html#s7", "c": "第 2 讲 · 命令行环境", "t": "Ctrl-C 不是直接杀进程，而是发一个信号", "x": "按下 Ctrl + C ，前台进程会收到 SIGINT 信号。程序没处理它，就按默认动作退出。程序处理了它，就可以不退。 bash · 本机实测 $ bash -c 'trap \"echo got INT, not stopping\" INT; kill -INT $$; echo still alive' # 给自己发 SIGINT，trap 接住后接着跑 got INT, not stopping still alive 打个比方 信号像有人拍你肩膀。你可以停下手里的活应付一下，再接着干。SIGKILL 不是拍肩膀，是直接把你拖走。 信号（signal）是一种特殊的进程间通信，也叫 软件中断 。进程收到信号，先暂停手头的事去处理它。处理完，执行路线可能就变了。 讲义列出的这 4 步。严格说，把 Ctrl-C 变成 SIGINT 的是终端驱动 tty。讲义简化成了“shell 发送”（补充） 程序可以 自己处理 信号。讲义的 Python 程序捕获 SIGINT 后，只打印一句话，并不退出。想停它，得用更凶的 SIGQUIT，按键是 Ctrl + \\ （ ）： sigint.py（讲义原文） #!/usr/bin/env python import signal, time def handler(signum, time): print(\"\\nI got a SIGINT, but I am not stopping\") signal.signal(signal.SIGINT, handler) i = 0 while True: time.sleep(.1) print(\"\\r{}\".format(i), end=\"\") i += 1 讲义原文（两次 Ctrl-C，然后 Ctrl-\\） $ python sigint.py 24^C I got a SIGINT, but I am not stopping 26^C I got a SIGINT, but I am not stopping 30^\\[1] 39913 quit python sigint.py 本机实测差异：Windows 原生 Python 收不到 Git Bash 的 kill -INT 在 Git Bash 里，对后台的 python sigint.py 执行 kill -INT 。处理器 没有被调用 ， kill -QUIT 也杀不掉它。原因是 Git Bash 的信号由 MSYS 运行时模拟，只对 MSYS 程序有效。Windows 原生的 python.exe 收不到。于是笔记用 bash 的 trap 把同样的逻辑重写成 sigint.sh，在本机真跑： sigint.sh（本笔记改写的 bash 版） #!/usr/bin/env bash trap 'echo; echo \"I got a SIGINT, but I am not stopping\"' INT i=0 while true; do sleep 0.1 printf '\\r%d' \"$i\" i=$((i + 1)) done 先用 set -m 打开作业控制，让脚本在后台跑。两次 kill -INT 之后，再发 kill -TERM ： bash · 本机实测（set -m 开作业控制） $ set -m; bash sigint.sh > sig.out 2>&1 & p=$! $ sleep 1.2; kill -INT $p; sleep 0.6; kill -INT $p; sleep 0.6; kill -TERM $p; wait $p; echo \"exit=$?\" exit=143 $ tr '\\r' '\\n' < sig.out | grep -c 'not stopping' # 两次 SIGINT 都被接住了 2 注意最后用的是 SIGTERM，不是 SIGQUIT。bash 手册写明，它在任何情况下都忽略 SIGQUIT。这条是补充，非视频内容。退出码 143 等于 128 加 15，15 是 SIGTERM 的编号。手推过程见 第 6 节 的演示。 信号 怎么发 含义（讲义） SIGINT (2) Ctrl + C 中断，可以被捕获 SIGQUIT (3) Ctrl + \\ 更强硬：“你真该退出了” SIGTERM (15) kill -TERM <PID> ，kill 默认发它 通用的“请体面地退出” SIGKILL (9) kill -KILL <PID> 不能被捕获 ，立即终止。可能留下孤儿子进程 SIGTSTP / SIGSTOP Ctrl + Z / kill -STOP 暂停。TSTP 是终端版的 STOP SIGCONT fg / bg / kill -CONT 继续运行 SIGHUP (1) 关闭终端、断开 SSH “挂断”，默认终止进程 完整列表看 kill -l 或 man signal 。讲师说，实际只会用到其中几个（ ）。 为什么会在这里踩坑 以为 Ctrl+C 一定能停下程序。程序可以捕获 SIGINT 不退出，上面的 sigint.py 就是。这时试试 Ctrl+\\ 发 SIGQUIT，或者另开终端用 kill。 kill -9 是最后手段，它不给程序任何清理的机会。 trap 兜得住 TERM，兜不住 KILL 内建命令 trap 给信号挂一个处理函数。脚本被 Ctrl+C 或 kill 打断时，也能先把临时文件删掉。但 SIGKILL 谁也接不住。 讲义脚本（注释译成中文） #!/usr/bin/env bash cleanup() { echo \"Cleaning up temporary files...\" rm -f /tmp/mytemp.* } trap cleanup EXIT # 脚本退出时运行 cleanup trap cleanup SIGINT SIGTERM # 按 Ctrl-C 或被 kill 时也运行 打个比方 trap 像在门口贴一张“离开前关灯”。正常下班、被人叫走，都会看到它。SIGKILL 是直接断电，提示贴了也没人看。 本机按同样结构写了 trapdemo.sh。临时文件放在当前目录，方便观察。然后分别用 TERM 和 KILL 打断它： trapdemo.sh（本笔记示例） #!/usr/bin/env bash cleanup() { echo \"Cleaning up temporary files...\" rm -f mytemp.* } trap cleanup EXIT trap 'echo \"got SIGTERM\"; exit 143' TERM touch mytemp.1 mytemp.2 echo \"created: $(echo mytemp.*)\" sleep 30 & wait $! bash · 本机实测 $ bash trapdemo.sh & P=$!; sleep 1; kill -TERM $P; wait $P; echo \"exit=$? left: $(ls mytemp.* 2>&1)\" # TERM：接住了，清理跑了 created: mytemp.1 mytemp.2 got SIGTERM Cleaning up temporary files... exit=143 left: ls: cannot access 'mytemp.*': No such file or directory $ bash trapdemo.sh & P=$!; sleep 1; kill -KILL $P; wait $P; echo \"exit=$? left: $(echo mytemp.*)\" # KILL：清理没跑，文件留下 created: mytemp.1 mytemp.2 bash: line 1: 9782 Killed bash trapdemo.sh exit=137 left: mytemp.1 mytemp.2 SIGKILL 无法被捕获。清理没跑，临时文件留下了。脚本里的 sleep 30 子进程成了孤儿。本机 /proc/PID/ppid 显示，它的父进程变成了 1，事后手动清掉了。这正是讲义说的“坏副作用”。 细看还会发现一件事。TERM 那次虽然删了文件， sleep 30 也成了孤儿。因为 cleanup 只删文件，没管子进程。更完整的写法，是在 cleanup 里加一句 kill $(jobs -p) 2>/dev/null （补充）。 学生问，被打断时程序会不会清理缓存？讲师答，取决于程序有没有处理信号。不处理的话，可能留下写了一半的文件（ ）。 为什么会在这里踩坑：后台任务收不到 SIGINT（补充） 本机第一次实验，用 kill -INT 去打断 bash trapdemo.sh & 。结果 trap 根本没触发，脚本照睡 30 秒，退出码是 0。原因是没开作业控制时，bash 让 异步命令忽略 SIGINT 和 SIGQUIT 。而进入 shell 时就被忽略的信号，没法再 trap。交互式终端里按 Ctrl+C 不受影响。在脚本里测试，就加 set -m 。上面的 sigint.sh 就是这么做的。"}, {"u": "ch02.html#s8", "c": "第 2 讲 · 命令行环境", "t": "Ctrl-Z 是暂停，不是退出", "x": "按 Ctrl + Z ，进程收到 SIGTSTP 被挂起，但还活着。之后用 fg 放回前台，或用 bg 放到后台接着跑。 bash · 最小例子（示意） sleep 1000 # 前台跑着，终端被占住 ^Z # 按 Ctrl+Z：进程挂起，不是结束 bg # 让它在后台接着跑，提示符回来了 jobs # 能看到它还在 Running kill %1 # 不想要了，按作业号结束它 打个比方 Ctrl+Z 像视频的暂停键，不是关掉播放器。fg 是回到大屏接着放。bg 是缩成小窗，在角落里接着放。 信号不只能杀进程。SIGTSTP 的意思是 Terminal Stop。讲师现场还用 kill 给挂起的进程发 SIGCONT。进程就恢复运行了（ ）。可见 kill 不只会“杀”，它能发任何信号。 工具 作用 cmd & 后台运行，立刻拿回提示符。但它照样往终端打字，嫌吵就重定向 jobs 列出当前终端会话里没结束的作业 %1 、 $! %1 指作业 1， $! 是最近一个后台作业的 PID。也可以直接用 PID，用 pgrep 查 Ctrl + Z 然后 bg 把正在前台跑的程序转到后台 nohup cmd & / disown 后台进程仍是终端的子进程。关终端时，它会收到 SIGHUP 而死。nohup 让命令忽略 SIGHUP。disown 用于已经启动的进程 本机在 bash -c 脚本里复现了讲义的示例会话。先用 set -m 打开作业控制。Ctrl+Z 用 kill -TSTP %1 代替。每步之间 sleep 0.5 等状态更新，下面省略了。 bash · 本机实测：复现讲义的示例会话 $ set -m; sleep 1000 & $ kill -TSTP %1; jobs -l # 代替 Ctrl+Z [1]+ 9670 Stopped sleep 1000 $ bg %1; jobs -l # 发 SIGCONT，在后台接着跑 [1]+ sleep 1000 & [1]+ 9670 Running sleep 1000 & $ nohup sleep 2000 > /dev/null 2>&1 & $ jobs [1]- Running sleep 1000 & [2]+ Running nohup sleep 2000 > /dev/null 2>&1 & $ kill -HUP %1 # 模拟关终端，sleep 1000 被挂断 $ kill -HUP %2; jobs # nohup 挡住了 SIGHUP /usr/bin/bash: line 7: 9670 Hangup sleep 1000 [2]+ Running nohup sleep 2000 > /dev/null 2>&1 & $ kill %2; jobs # kill 默认发 SIGTERM，nohup 挡不住它 [2]+ Terminated nohup sleep 2000 > /dev/null 2>&1 补充（非视频内容）：Git Bash 里 jobs 的状态有时“过时” 本机实测， kill -CONT 之后进程恢复运行。 ps 第一列的 S 标记也消失了。可 jobs 仍显示 Stopped。bash 在这里收不到“已继续”的通知。用 bg 或 fg 恢复，状态就是对的。练习 6 是 Ctrl+Z 加 bg 加 pkill，实测见练习页。 为什么会在这里踩坑 在终端或 SSH 里敲 long_job & ，以为放到后台就安全了。其实后台进程还是终端的子进程。终端一关，它收到 SIGHUP，跟着一起死。要么 nohup long_job & ，要么对已经启动的用 disown 。最省心的是放进 tmux 里跑。 下面的演示把讲义的会话画成一张状态机。作业在 4 种状态之间移动，每一步都是一个信号推着走。"}, {"u": "ch02.html#s9", "c": "第 2 讲 · 命令行环境", "t": "私钥等于密码，只有公钥能给别人", "x": "SSH 用一对密钥证明你是你。私钥留在自己电脑上，公钥放进服务器的 ~/.ssh/authorized_keys 。登录时只证明你有私钥，私钥本身不出门。 bash · 最小例子（示意） ssh-keygen -a 100 -t ed25519 -f ~/.ssh/id_ed25519 # 生成一对钥匙，记得设口令 ssh-copy-id -i .ssh/id_ed25519 alice@remote # 只是把公钥追加进对方的 authorized_keys ssh alice@remote # 之后改用密钥登录，不用再输服务器密码 打个比方 公钥像锁芯，可以随便装到别人家的门上。私钥是唯一那把钥匙，丢了谁都能开门。口令是给钥匙再套一个密码盒。 程序员越来越多地在远程服务器上干活。最常用的工具是 SSH ，全称 Secure Shell。它在远端给你一个熟悉的 shell： 讲义原文 $ ssh alice@server.mit.edu 这条命令以用户 alice 登录 server.mit.edu。讲师演示时写的是 IP 地址。 server.mit.edu 这种名字，最后也会被 DNS 翻译成一个 IP（ ）。默认每次都要输密码，很烦。所以要用 SSH 密钥 。 公钥密码学 ：一对私钥加公钥。客户端能向服务器证明“我有私钥”，却 不泄露私钥 。密钥认证更方便，也更安全，应该优先用。 私钥常见的是 ~/.ssh/id_rsa ，较新的是 ~/.ssh/id_ed25519 。它 等同于你的密码 。永远不要分享，也别复制粘贴到任何地方。讲师现场展示，是因为那是临时密钥。公钥是 .pub 文件，可以给别人。GitHub 就用它来验证你。 生成用 ssh-keygen -a 100 -t ed25519 -f ~/.ssh/id_ed25519 。想检查有没有口令、顺便验证私钥，用 ssh-keygen -y -f /path/to/key 。 服务器查 ~/.ssh/authorized_keys ，决定放谁进来。把公钥拷过去，用 ssh-copy-id -i .ssh/id_ed25519 alice@remote 。也可以手动写 cat .ssh/id_ed25519.pub | ssh alice@remote 'cat >> ~/.ssh/authorized_keys' 。讲师强调，ssh-copy-id 这个“魔法命令” 只做一件事 。它把一行字符串追加到 authorized_keys 里（ ）。 bash · 本机实测（在沙箱 HOME 里生成，指纹每次不同） $ ssh-keygen -a 100 -t ed25519 -f ~/.ssh/id_ed25519 -N 'correct horse battery' -C 'student@laptop' # -N 设口令，-C 写注释 Generating public/private ed25519 key pair. … The key fingerprint is: SHA256:knqwBVI1jDcw1+17wKXaciXSyfEU5Dr4egdpIGJHg54 student@laptop $ ssh-keygen -y -f ~/.ssh/id_ed25519 -P 'wrong pass' # 口令不对，连本机都解不开私钥 Load key \"…/.ssh/id_ed25519\": incorrect passphrase supplied to decrypt private key 学生提问：密钥要不要加口令？（视频 40:29） 讲师答：“一定要加。”不加口令，就等于把服务器密码明文放在文件系统里。任何能读你文件的程序都能拿走它。加了口令，私钥就被口令加密，每次用都要先解密。讲义推荐配合 ssh-agent ，免得反复输口令。 为什么会在这里踩坑 最要命的是把私钥当公钥发出去。要给别人、要贴到 GitHub 的，永远是带 .pub 的那个文件。另一个坑是私钥不加口令。笔记本一丢，所有服务器的门就都开了。"}, {"u": "ch02.html#s10", "c": "第 2 讲 · 命令行环境", "t": "引号决定管道在哪台机器上跑", "x": "ssh 后面跟命令，就在远端执行，再把输出传回本地。没加引号时， | 由本地 shell 切开。加了引号，整串交给远端的 shell 去解析。 讲义原文（注释译成中文） # 这里 ls 在远端跑，wc 在本地跑 ssh alice@server ls | wc -l # 这里 ls 和 wc 都在服务器上跑 ssh alice@server 'ls | wc -l' 打个比方 不加引号，像打电话让同事把文件名一个个念给你。你自己在这边数。加了引号，像让同事数完，只报一个数字给你。 ssh 有个常被忽略的功能。它能 非交互地 执行命令，还能正确处理 stdin 和 stdout。所以它能和别的命令组合。讲师说，SSH 不是魔法命令。它和几乎所有命令一样，接收输入，产生输出。 区别全在 引号 。没引号时，本地 shell 先把整行按 | 切开， wc -l 归本地。加了引号， 'ls | wc -l' 整体成为一个参数交给 ssh。到了远端，再由远端的 shell 去解析。本节末尾的演示画了这两条数据路径。 传文件工具 说明 scp 最传统： scp path/to/local_file remote_host:path/to/remote_file 。讲师演示了把 ignore.py 拷到服务器（ ） rsync 语法和 scp 类似。它会跳过两边相同的文件。对符号链接和权限控制得更细， --partial 可以续传 这些工具底层都走 SSH，所以配好的密钥直接能用。客户端配置文件 ~/.ssh/config 用来声明主机和默认设置。scp、rsync、mosh 也都会读它： ~/.ssh/config（讲义原文，注释译成中文） Host vm User alice HostName 172.16.174.141 Port 2222 IdentityFile ~/.ssh/id_ed25519 # 配置里也能用通配符 Host *.mit.edu User alice 之后 ssh vm 就等于 ssh -p 2222 -i ~/.ssh/id_ed25519 alice@172.16.174.141 。不连服务器，也能检查配置有没有生效。 ssh -G vm 会打印解析后的最终设置，练习 19 实测过。 讲义推荐 · Mosh Mosh 可以替代 SSH。它扛得住断线、睡眠唤醒、切换网络和高延迟链路。 为什么会在这里踩坑 ssh host ls *.txt 里的 glob，会先在本地展开。本地正好有 txt 文件时，发到远端的就成了本地的文件名。下面用 echo 代替 ssh，看它会收到什么参数： bash · 本机实测（当前目录有 a.txt 和 b.txt） $ echo ssh host ls *.txt # 本地的 a.txt b.txt 被塞了进去 ssh host ls a.txt b.txt $ echo ssh host 'ls *.txt' # 加了引号，*.txt 原样送到远端再展开 ssh host ls *.txt 下面的演示有两幕。第一幕看引号怎么决定管道在哪台机器上跑。第二幕是练习里会配的端口转发 LocalForward 9999 localhost:8888 。看数据怎么穿过 SSH 连接。"}, {"u": "ch02.html#s11", "c": "第 2 讲 · 命令行环境", "t": "tmux 让会话不再跟着网络连接一起死", "x": "tmux 在服务器上开一个常驻的会话。SSH 断了，会话照样在跑。重新连上， tmux attach 就能原样接回。 bash · 最小例子（示意，本机没有 tmux） tmux new -s work # 开一个叫 work 的会话 python train.py # 在里面跑个长任务 # 先按 Ctrl+b，松开，再按 d：分离会话，任务接着跑 tmux a -t work # 下次 SSH 上来，接回 work 打个比方 tmux 像在服务器上租了个带锁的房间。你断线离开，房间里的程序照常干活。回来开门，一切原样。 讲师在服务器上跑起一个程序。这时终端被占住，别的什么都干不了。开个新终端窗口能解决，但 终端复用器 更灵活。它在同一个终端里开多个 shell 会话。还能把当前会话 分离 （detach），以后再 接回 （attach）。最流行的是 tmux 。 tmux 的三层：会话 ⊃ 窗口 ⊃ 窗格（讲义） tmux 的快捷键是 前缀式 的。 <C-b> x 的意思是：先按 Ctrl + b ，松开，再按 x。 层级 命令或按键（讲义） 会话 tmux 开新会话， tmux new -s NAME 带名字。 tmux ls 列出全部。 <C-b> d 分离。 tmux a 接回最近的会话，加 -t 指定哪个 窗口 <C-b> c 新建，在 shell 里按 <C-d> 关闭。 <C-b> N 去第 N 个。 <C-b> p 和 n 是上一个和下一个。 <C-b> , 改名， <C-b> w 看列表 窗格 <C-b> \" 水平分割， <C-b> % 垂直分割。 <C-b> 方向键 移动。 <C-b> z 放大或还原。 <C-b> [ 进入回滚，空格开始选，回车复制。 <C-b> 空格 切换布局 tmux 为什么能“断线不死”（视频 39:06） 断开远程连接时，shell 察觉后会发出 挂断信号 SIGHUP 。还在跑的进程会被全部杀掉。tmux 拦下了这个信号，不往下传。所以重新 SSH 上去， tmux attach ，一切都还在跑。远程会话从此不和网络连接绑在一起。也就用不着 nohup 这类技巧了。 本机未实测 Git Bash 没有 tmux， command -v tmux 没有输出。要在 Linux、macOS 或 WSL 上练。练习 9 给出了配置文件和检验标准。本节末尾的演示画了三层结构和分离、接回。还画了它和 SIGHUP 的关系。 讲义推荐的教程： 快速入门 、 更详细的讲解 。 为什么会在这里踩坑 在 SSH 里直接跑长任务，然后合上笔记本。连接一断，任务就跟着没了。长任务一律先开 tmux 再跑。另一个坑在按键上。按完 Ctrl+b 要先松开，再按下一个键。"}, {"u": "ch02.html#s12", "c": "第 2 讲 · 命令行环境", "t": "缺工具先找包管理器，别急着 curl | bash", "x": "命令找不到，多半是没装。各系统都有包管理器，一条命令就能装好。 讲义原文（注释译成中文） # ripgrep：更快的 grep，默认设置也更好用 brew install ripgrep # fd：更快、更友好的 find brew install fd 打个比方 包管理器像手机的应用商店，装、更新、卸载都有人管。 curl | bash 像从陌生网站下个安装包，看都不看就双击。 照着讲师的步骤敲 tmux ，可能会提示找不到。有些发行版没预装它。各系统装法不同。macOS 用 Homebrew ，Ubuntu 和 Debian 用 apt ，Fedora 用 dnf ，Arch 用 pacman 。第 6 讲细讲包管理。 装完用 rg 代替 grep，用 fd 代替 find。讲师吐槽，包叫 ripgrep，命令却叫 rg。这种不一致有时很烦（ ）。 命令找不到时，去查 command-not-found.com 。输入命令名，它告诉你各系统怎么装。第一反应永远是先找包管理器。 tldr 是以例子为主的简版 man，比如 tldr fd 。 为什么会在这里踩坑：curl | bash（讲义警告） curl -fsSL https://example.com/install.sh | bash 下载完脚本就 立刻执行 。你跑的是一段没看过的代码。更安全的做法是先下载，读一遍，再执行： 讲义原文（注释译成中文） curl -fsSL https://example.com/install.sh -o install.sh less install.sh # 先读一遍脚本 bash install.sh 有的安装器用 /bin/bash -c \"$(curl -fsSL https://url)\" ，稍微安全一点。它至少保证由 bash 来解释，而不是你当前的 shell。"}, {"u": "ch02.html#s13", "c": "第 2 讲 · 命令行环境", "t": "export 只管这次会话，长期生效要写进 .bashrc", "x": "export PATH=… 只对当前会话和它的子进程有效，关掉终端就没了。写进 ~/.bashrc ，每个新开的交互式 bash 都会重新执行一遍。 bash · 最小例子（示意） export PATH=\"$PATH:path/to/append\" # 讲义原文：在末尾追加一个目录 echo 'export PATH=\"$PATH:$HOME/bin\"' >> ~/.bashrc # 写进配置，以后每个新终端都生效 source ~/.bashrc # 不想重开终端，就在当前 shell 里执行一遍 打个比方 export 像在白板上写字，散会就擦了。写进 .bashrc，像写进每次开会必念的开场白。 上一讲讲过， PATH 是一串放程序的目录。想加一个目录，就是普通的变量赋值。而且要 export ，不然子进程看不到。 学生问，当前所在的目录会被加进去吗？讲师答，不会。 cd 到哪里，PATH 都不变。shell 默认不在当前目录找程序。所以运行当前目录的脚本，要写 ./ （ ）。 问题是，export 只对这个会话和它的子进程有效。断开重连就没了（ ）。要长期生效，就写进 shell 的配置文件。下面在干净环境里实测： bash · 本机实测（~/bin/myscript.sh 只打印一行） $ myscript.sh bash: line 2: myscript.sh: command not found $ export PATH=\"$PATH:$HOME/bin\"; myscript.sh; bash -c \"myscript.sh\" # 子进程也找得到，因为 PATH 已 export hi from myscript hi from myscript # 另开一个全新的会话 $ myscript.sh bash: line 1: myscript.sh: command not found # 把 export 那一行写进 ~/.bashrc，再开新的交互式会话 $ myscript.sh hi from myscript 视频 52:40 的说法是：交互式会话读 bashrc，非交互式不读。登录 shell 还会读 ~/.bash_profile 等文件。规则相当复杂，讲义推荐看这篇 启动脚本详解 还有些变量会改 shell 的行为。比如 PS1 ，它决定左边的提示符长什么样（ ）。讲师把它设成一个单独的符号。新开的 shell，提示符就只剩那个符号。想要好看的提示符，得用 shell 认识的转义： bash · 本机实测（${PS1@P} 按提示符规则展开） $ PS1='\\w \\$ '; echo \"[${PS1@P}]\" # \\w 是当前目录，\\$ 是 $ 或 # [~/proj $ ] $ PS1='$ '; echo \"[${PS1@P}]\" [$ ] 补充（非视频内容） \\w 是当前目录，家目录显示成 ~ 。 \\W 只显示最后一级。 \\$ 对普通用户显示 $，对 root 显示 #。 \\A 是 24 小时制的时间。详见 man bash 的 PROMPTING 一节。 为什么会在这里踩坑 改完 .bashrc，当前终端没反应。它只在新开交互式 bash 时才读。要么开个新终端，要么 source ~/.bashrc 。另一个坑： bash script.sh 是非交互式的，根本不读 .bashrc。脚本能用 ~/bin 里的程序，是因为继承了父进程的 PATH。 Ctrl+R 在历史里搜，fzf 让它变成模糊搜索 大多数 shell 支持 Ctrl + R 反向搜索历史。按下之后，边打字边匹配以前的命令。 讲师加载了 fzf 的 shell 集成。之后 Ctrl+R 就成了交互式的模糊搜索，范围是全部历史。不想退出重开，就用 source 文件 。意思是在当前 shell 里，把这个文件逐行执行一遍。 别名只是文字替换，脚本里默认不展开 alias 是 shell 内建命令。它在命令求值之前，把短名字换成你写好的长命令。 讲义例子（节选，注释是笔记加的） alias ll=\"ls -lh\" # 常用 flag 的简写 alias gs=\"git status\" # 省打字 alias sl=ls # 防手误 alias mv=\"mv -i\" # 覆盖前先问 alias la=\"ls -A\" alias lla=\"la -l\" # 别名可以组合 \\ls # 前面加 \\ 绕过别名 unalias la # 删除别名 alias ll # 打印定义：ll='ls -lh' 打个比方 alias 像输入法里的自定义短语。打 gs，自动换成 git status。但这个替换只在你手敲的时候才发生。 = 两边没有空格。因为 alias 是只收 一个参数 的命令。 别名不能在命令中间接收参数。更复杂的就写 shell 函数。 为什么会在这里踩坑 脚本里的别名默认 不展开 ，因为非交互式 shell 关掉了 expand_aliases 。下面同样两行，放进脚本就报 command not found。打开这个选项才行。练习 10 有更多实测： bash · 本机实测 $ cat al.sh alias dc=cd dc / && pwd $ bash al.sh; echo \"exit=$?\" # 别名没展开，dc 被当成程序去找 al.sh: line 2: dc: command not found exit=127 $ bash al2.sh; echo \"exit=$?\" # al2.sh 第一行多了 shopt -s expand_aliases / exit=0"}, {"u": "ch02.html#s14", "c": "第 2 讲 · 命令行环境", "t": "配置放进 git 仓库，家目录只留软链接", "x": "~/.bashrc 这类配置文件叫 dotfiles。把它们集中放进一个 git 仓库。家目录里只留指向仓库的符号链接。 bash · 最小例子（示意） mkdir ~/.dotfiles && cd ~/.dotfiles && git init # 建一个专门放配置的仓库 mv ~/.bashrc ~/.dotfiles/bashrc # 真文件搬进仓库 ln -s ~/.dotfiles/bashrc ~/.bashrc # 老位置换成一个指过去的链接 ls -l ~/.bashrc # 开头是 l，箭头指向仓库里的文件 打个比方 符号链接像桌面上的快捷方式。程序照常去老地方找 .bashrc。快捷方式把它领到了仓库里那份。 很多命令行程序用纯文本配置文件。文件名以 . 开头， ls 默认不显示，所以叫 dotfiles 。讲师说，这又是一个约定。 工具 配置文件（讲义） bash ~/.bashrc 、 ~/.bash_profile git ~/.gitconfig vim ~/.vimrc 和 ~/.vim 目录 ssh ~/.ssh/config tmux ~/.tmux.conf 讲师用 ls -la 一看，他的 .bashrc 其实 不是文件 。它是一个 符号链接 （symlink）。意思是，谁要读 .bashrc，就去读 .dotfiles/bash/bashrc （ ）。这样所有配置都集中在一个目录里。放进 Git，推到 GitHub。换新电脑时，一个脚本建好所有链接就行。 讲义推荐的组织方式。独立目录，加版本控制，再用脚本建软链接 好处 ：新机器一分钟装好。各处行为一致，改动随处同步。还能追踪历史。你可能会维护 dotfiles 一整个职业生涯。 学什么配置 ：读工具文档和 man，搜别人的博客。看 GitHub 上的 dotfiles 仓库 ，最受欢迎的是 mathiasbynens/dotfiles 。还有 dotfiles.github.io 。三位讲师的也都公开： Anish 、 Jon 、 Jose 。 别盲目复制 ：讲师建议逐行理解。别整份拷贝别人的 bashrc（ ）。他举的例子是，有人在配置里让 glob 忽略大小写。 本机实测差异：Git Bash 的 ln -s 默认是复制 bash · 本机实测 $ ln -s \"$PWD/dotfiles/bashrc\" ~/.bashrc; [ -L ~/.bashrc ] && echo \"is symlink\" || echo \"NOT a symlink (copied)\" NOT a symlink (copied) $ rm ~/.bashrc; MSYS=winsymlinks:nativestrict ln -s \"$PWD/dotfiles/bashrc\" ~/.bashrc; ls -l ~/.bashrc # 设了 MSYS 才是真链接 lrwxrwxrwx 1 lrhto 197610 124 Oct 29 16:42 …/.bashrc -> …/dotfiles/bashrc Git Bash 默认把 ln -s 实现成 复制 。改了仓库里的文件，家目录那份不会跟着变。dotfiles 方案就失效了。设置 MSYS=winsymlinks:nativestrict ，才会创建真正的 Windows 符号链接。这需要开发者模式或管理员权限。练习 14 的安装脚本对此做了检测。 为什么会在这里踩坑 图省事，直接把配置文件 cp 到家目录，而不是建链接。以后改了仓库，家目录那份不跟着变。Git Bash 的 ln -s 默认就是复制，正好踩中这个坑。检查办法很简单， [ -L ~/.bashrc ] 为真才是链接。 下面的演示画了两件事。一是读 ~/.bashrc 时，怎么被链接引到仓库里的文件。二是新机器上怎么一键安装。输出来自本机实测的练习 14 和 15。"}, {"u": "ch02.html#s15", "c": "第 2 讲 · 命令行环境", "t": "插件一次只装一个，用不上就删", "x": "shell 没有的方便功能，有人做成了插件。装插件通常就两步： git clone 下来，再往配置文件里加一行 source 。 bash · 最小例子（示意） git clone https://github.com/zsh-users/zsh-autosuggestions ~/.zsh/zsh-autosuggestions # 插件就是一个仓库 echo 'source ~/.zsh/zsh-autosuggestions/zsh-autosuggestions.zsh' >> ~/.zshrc # 往配置里追加一行 [[ ! -f ~/.zshrc.local ]] || source ~/.zshrc.local # 讲师式写法：文件在才加载 打个比方 插件像手机 App，一次装一个，觉得没用就删。大框架像预装了几十个 App 的整机，开机自然就慢。 讲师的 zsh 会根据历史命令 自动建议补全 。命令存在时显示绿色，不存在时显示红色。不用运行就知道会失败。提示符里还显示当前 git 分支和未提交的改动数。上一条命令返回码非 0 时，光标会变红（ ）。 插件（讲义） 作用 zsh-syntax-highlighting 边打边给命令上色，合法和非法颜色不同 zsh-autosuggestions 根据历史，边打边给建议 zsh-completions 更多补全定义 zsh-history-substring-search fish 风格的历史搜索 powerlevel10k 又快又能定制的提示符主题 学生问，这些会影响所有 shell 吗？讲师现场敲了 bash ，提示符立刻变了样。zsh 和 bash 读的是 完全不同的配置文件 。一个是 .zshrc ，一个是 .bashrc 。所以可以分别配置。讲师故意不改 bash，留着出问题时当后备（ ）。在 WSL 里也一样。 插件怎么装？多数在 GitHub 上有安装说明。最简单的是 git clone 到某个路径，再往 .zshrc 追加一行 source … 。安装说明常给一条 echo '…' >> ~/.zshrc ，连编辑器都不用开（ ）。 讲师读了自己 .zshrc 里的一行： [[ ! -f 文件 ]] || source 文件 。文件不存在时， [[ ]] 成功，后面就短路了。文件存在时，才去 source。讲师说用 || 不用 && ，写法有点怪。但这正是返回码短路的用法。 讲师建议（视频 1:00:03） oh-my-zsh 、 prezto 这类大框架，会明显拖慢 shell 启动。更推荐一次只装一个插件，看自己是不是真在用。不用就删。细粒度地控制，能防止 shell 变臃肿。 fish 默认就带了很多这类功能。 为什么会在这里踩坑 整份照搬 oh-my-zsh 或别人的配置，shell 启动变慢。出了问题，也不知道是哪一行干的。另一个坑：在 zsh 里配好的别名，敲 bash 进去就没了。因为两者读的是不同的配置文件。"}, {"u": "ch02.html#s16", "c": "第 2 讲 · 命令行环境", "t": "LLM 也是 CLI：指令走参数，数据走 stdin", "x": "命令行里的 AI 工具，和别的程序守同一套约定。指令从参数进，数据从 stdin 进，结果从 stdout 出。所以它也能接进管道。 bash · 写法示意（命令出自讲义，本机没装 llm） llm cmd \"find all python files modified in the last week\" # 让模型生成命令，先给你看，再问要不要跑 INSTRUCTIONS=\"Extract just the username from each line, one per line, nothing else\" llm \"$INSTRUCTIONS\" < users.txt | sort # 指令加引号当一个参数，数据走 stdin，结果还能接 sort 打个比方 llm 像一个能读懂英文说明的 sed。说明书从参数递进去，要加工的料从 stdin 倒进去。 想问 AI，当然可以去网页上问 ChatGPT。但用命令行工具和模型打交道，往往更方便。讲义给了三个集成层次： 层次 例子（讲义原文） 生成命令 simonw/llm ： llm cmd \"find all python files modified in the last week\" 生成 find . -name \"*.py\" -mtime -7 。讲师演示时，它会先问你要不要运行。你快速检查，觉得大致合理再执行 接进管道 从格式五花八门的行里抽用户名，用正则会很痛苦。可以先写 INSTRUCTIONS=\"Extract just the username from each line, one per line, nothing else\" ，再跑 llm \"$INSTRUCTIONS\" < users.txt AI shell Claude Code 这类“元 shell”。它接收英文指令，翻译成 shell 操作、文件编辑和多步任务。讲义说它是“编程语言是英语的 shell” 讲义原文 $ cat users.txt Contact: john.doe@example.com User 'alice_smith' logged in at 3pm Posted by: @bob_jones on Twitter Author: Jane Doe (jdoe) Message from mike_wilson yesterday Submitted by user: sarah.connor $ INSTRUCTIONS=\"Extract just the username from each line, one per line, nothing else\" $ llm \"$INSTRUCTIONS\" < users.txt john.doe alice_smith bob_jones jdoe mike_wilson sarah.connor 本讲概念在 AI 工具里的体现 讲师特意指出， 指令通过参数 传进 llm。 \"$INSTRUCTIONS\" 必须加引号，因为里面有空格。 数据通过 stdin 进来，也就是 < users.txt 。这和任何 CLI 程序完全一样，所以后面还能接 | sort 。 讲师还用 Claude Code 演示了一个任务。任务是找出最近修改的 shell 脚本，把 shebang 改成 csh。它生成了一条看着很“外星”的 find 命令。拆开看，其实很合理。它自己把上一步的输出喂给下一步。最后提出修改 cleanup.sh 的 shebang，人确认后才执行（ ）。本机没装 llm，以上都没有实测。 为什么会在这里踩坑 AI 生成的命令别闭眼回车。讲师的做法是先看一眼，确认大致合理再跑。另一个坑是指令忘了加引号。指令里有空格，不加引号就会被切成好几个参数。llm 收到的就不是一句完整的话了。"}, {"u": "ch02.html#s17", "c": "第 2 讲 · 命令行环境", "t": "终端要待成百上千小时，值得调顺手", "x": "shell 跑在 终端模拟器 里，它是提供文本界面的图形程序。字体、配色、快捷键都值得花时间调一调。 toml · 写法示意（配置文件路径是补充，非视频内容） # ~/.config/alacritty/alacritty.toml [font] size = 32 # 讲师上课把字号从 16 调到 32，改完立刻生效 打个比方 终端像你的工位。椅子和显示器调舒服了，一天坐八小时才不累。 值得调的有字体、配色和快捷键。还有标签页、窗格、回滚缓冲和性能。 Alacritty 、 Ghostty 这类较新的终端有 GPU 加速。讲师用的就是 Alacritty。为了上课，他把字号从 16 改成 32。改完配置文件，立刻生效。 为什么会在这里踩坑 终端和 shell 不是一回事。换了 Ghostty 或 Alacritty，里面跑的还是原来那个 bash 或 zsh。配置也分两处。字体和配色归终端管，提示符和别名归 shell 管。"}, {"u": "ch02.html#s18", "c": "第 2 讲 · 命令行环境", "t": "一页带走：本讲的考点都在这几行里", "x": "把本讲浓缩成几行命令。每行的注释就是结论和考点。 bash · 本讲速查（注释即考点） python args.py *.py # 收到的是展开后的文件名，不是 *.py ls -- * # -- 之后都当文件名，叫 -l 的文件不会变成选项 cmd 2>&1 | grep error # 报错走 stderr，不并进来，管道就看不到 (sleep 2 && cat f) | grep x & # 0.5 秒后 ps：sleep 和 grep 都在，cat 还没启动 DEBUG=1; bash -c 'echo $DEBUG' # 打印空行：没 export，子进程看不到 DEBUG=1 bash -c 'echo $DEBUG' # 打印 1：只给这一条命令 false; echo hi; echo $? # 打印 0：$? 只记上一条命令 kill -TERM $pid # 能被 trap 接住，清理会跑，返回 143 kill -KILL $pid # 接不住，临时文件留下，返回 137 ssh host ls | wc -l # wc 在本地跑，数的是传回来的行 ssh host 'ls | wc -l' # 整串交给远端，ls 和 wc 都在服务器上 tmux attach # 断线时 tmux 挡住了 SIGHUP，会话还在 bash script.sh # 不读 .bashrc，PATH 是从父进程继承来的 ln -s ~/.dotfiles/bashrc ~/.bashrc # 配置放仓库，家目录只放链接 参数是一串字符串。 -a 和 --all 是程序自己解析的约定。 -- 表示后面不再有 flag。 glob 由 shell 在运行程序 之前 展开。加了引号就不展开。 管道里的程序同时运行。管道只传 stdout，stderr 默认直接打到终端。 变量没有类型。 VAR=x cmd 只给一条命令， export 给之后所有子进程。子进程改不了父进程。 返回码 0 是成功。 && 、 || 、if、while 都看它。被信号杀死时，返回码是 128 加信号编号。 信号是软件中断。INT、QUIT、TERM 能被 trap 捕获，KILL 不行。 Ctrl+Z 发 TSTP， bg 和 fg 让它继续。断线发 HUP，nohup 和 tmux 能挡住。 SSH 用密钥加口令登录。 ssh host 'cmd' 在远端执行， ~/.ssh/config 存主机设置，scp 和 rsync 传文件。 配置写进 dotfiles，放进 git，用 ln -s 装到家目录。 下一步 第 1 讲教你写命令。这一讲教你看懂命令运行的环境。比如程序之间靠什么约定通信，怎么控制它们。还有怎么在远程机器上干活，怎么把环境调成自己的。下一讲是“开发环境与工具”。它讲编辑器 Vim、语言服务器和 AI 编程工具。现在先去做 本讲练习的可视化笔记 。一共 24 道题，dotfiles 和 SSH 两组最实用。"}, {"u": "ch03.html", "c": "第 3 讲 · 开发环境与工具", "t": "开头", "x": "本讲结论 写代码时，大部分时间在跳转、阅读和小改。Vim 把编辑器界面做成一门能组合的 语言 。命令就是动词加计数加名词。IDE 靠 语言服务器 看懂代码的语义。AI 工具有三种形态： 补全、行内对话和编码智能体 。"}, {"u": "ch03.html#s1", "c": "第 3 讲 · 开发环境与工具", "t": "开发环境分两派：终端拼装和图形 IDE", "x": "开发环境就是写软件用的一套工具。核心是文本编辑。再配上高亮、类型检查、格式化和补全。 bash · 最小例子（示意） # 终端派：几个命令行工具拼成一套环境 tmux # 一个窗口分成几个窗格 vim fizz.py # 一个窗格写代码 ruff check fizz.py # 另一个窗格跑 linter，类型检查交给 mypy code . # IDE 派：VS Code 打开当前目录，这些全在一个窗口里 打个比方 终端派像自己攒电脑，每个零件都挑最顺手的。IDE 派像买品牌整机，插上电就能用。 讲师先展示了自己的两套环境。 终端工作流 讲师用 tmux 分出几个窗格。左边 Vim 打开讲义，右下角是 shell，右上角跑着 docker。这套环境由几样东西拼成。终端复用器用 tmux ，编辑器用 Vim ，shell 用 Zsh 。再加上各语言的命令行工具。比如 Python 的 linter 兼格式化器 Ruff ，还有类型检查器 Mypy 。它很轻量。有的机器没有图形界面，也装不了软件。SSH 上去以后，它可能是唯一选择。 集成开发环境 IDE IDE 是 Integrated Development Environment 的缩写，比如 VS Code 。编辑、lint、自动格式化，全在一个程序里。图形 IDE 更容易上手。AI 功能通常也集成得更好，比如 AI 自动补全开箱即用。课上不少人举手说听过 Cursor 。它是 VS Code 的一个分支（fork）。 学生问，终端里的编辑器算不算 IDE（ ）。讲师说，Emacs 和 Vim 本质上是文本编辑器。装上一堆插件，它们也能表现得像 IDE。不过一般人说 IDE，指的是图形 IDE。 讲义建议 两种都要基本熟悉， 至少精通一种 。还没有偏好的 IDE，就从 VS Code 开始。 本讲分四部分。先讲文本编辑与 Vim，再讲代码智能与语言服务器。然后是 AI 辅助开发，最后是扩展与其他 IDE 功能。讲师开场还预告了正则表达式和查找替换。实际没来得及讲，2026 版讲义把它放进了第 9 讲。 为什么会在这里踩坑 平时只用图形 IDE 的人，SSH 到服务器上常常傻眼。那里没有图形界面，往往也不让装软件。所以终端编辑器至少要会打开、修改、保存和退出。"}, {"u": "ch03.html#s2", "c": "第 3 讲 · 开发环境与工具", "t": "写代码是跳来跳去地小改，Vim 专为此设计", "x": "写代码很少从头写到尾。大多是跳到一处，读一小段，改一行。Vim 的按键就是为这种节奏设计的。 vim · 最小例子（示意） j # 下移一行 10j # 下移 10 行：数字加动作，这就是组合 f( # 在本行往右找 ( % # 跳到和它配对的括号 ci( # 删掉括号里的内容，直接开始输入 打个比方 Vim 的按键像乐高积木。学会几块基本的，就能拼出成百上千种动作。不用一个个死背。 比如用 Word 写文章，通常是从头写到尾，或者从头读到尾。写代码不一样。你在文件之间跳来跳去，读一小段。在这里加个函数，再跳到上面改一行 bug。讲师问，谁能从头到尾一口气写完一个程序？没有人举手（ ）。 Vim 就是为这种“导航加小改”优化的。 手不离键盘 ：在键盘和鼠标之间来回切换很慢。这是 Vim 和前身 vi 的作者观察到的。所以 Vim 避免用鼠标，连方向键都尽量不用。方向键离主键位太远了。 界面是编程语言 ：按键就是命令，名字都有助记含义。命令之间还能 组合 。讲师开场演示了几下（ ）。 j 下移一行， 10j 下移 10 行。 f 找字符， % 跳到配对的括号。 ci( 删掉括号里的内容，并开始输入。 效果 ：熟练以后，编辑速度能跟上思考速度。就像一个“脑机接口”。 不用 Vim 也能用 Vim 的思想 很多软件支持“Vim 模式”。VS Code 有 VSCodeVim 插件，Zsh 内建了 Vim 模拟 。bash 也支持，写法是 set -o vi ，练习 1 实测过。连 Claude Code 都有 Vim 编辑模式 。 所以 2026 版课程不再专讲 Vim 这个软件（ ）。怎么用 :wq 退出不再是重点，在 VS Code 里点 X 就行。重点是各处通用的 核心思想和按键 。 为什么会在这里踩坑 手在键盘和鼠标之间来回挪，每次都要重新找光标。一次只慢一点，可写代码时这个动作极其频繁。Vim 的设计，就是把这一步省掉。"}, {"u": "ch03.html#s3", "c": "第 3 讲 · 开发环境与工具", "t": "同一个键，在不同模式下干不同的事", "x": "Vim 是 模态编辑器 （modal editor）。按键先看当前在哪个模式，再决定干什么。 vim · 最小例子（示意，文本是 the quick fox） x # Normal 模式：删掉光标下的字符 ix<Esc> # i 进 Insert，这时 x 就是打一个字母 x vex # v 进 Visual，e 选到词尾，x 删掉整个选区 :q! # 有没保存的修改时 :q 会被拒，加 ! 强制退出 打个比方 模式像汽车的挡位。同样踩一脚油门，D 挡往前走，R 挡往后退。踩之前先看挂的是哪个挡。 模式 用途 从 Normal 怎么进 Normal 移动和修改。这是默认模式，大部分时间待在这里 任何模式按 Esc 回来 Insert 插入文字，和普通编辑器一样 i Replace 覆盖已有的文字 R Visual（普通 / 行 / 块） 选中一段文字 v / V / Ctrl + v Command-line 运行命令，比如 :q 退出 : 拿字母 x 举例。在 Insert 模式下，它插入一个字面的 x。在 Normal 模式下，它删掉光标下的字符。在 Visual 模式下，它删掉选中的部分。 Vim 默认在左下角显示当前模式。讲师的配置也是这样（ ）。讲师演示 :q 时，因为有没保存的修改，被拒绝了。于是改用 :q! 强制退出。 讲义建议：把 Caps Lock 改成 Esc Esc 要按很多次。可以考虑把 Caps Lock 映射成 Esc，讲义给了 macOS 的做法 。也可以给 Esc 设一个 简单的替代按键 。 下面的演示把模式画成一张状态机。看同一个 x ，在三种模式下做了三件不同的事。文本变化来自本机 Vim 9.2 的真实回放。 为什么会在这里踩坑 最常见的事故：以为自己在 Insert 模式，其实在 Normal 模式。想打一个 x，结果删掉了一个字符。接着打的一串字母，全被当成了命令。所以先看左下角的模式提示。拿不准就先按一下 Esc ，回到 Normal 再说。"}, {"u": "ch03.html#s4", "c": "第 3 讲 · 开发环境与工具", "t": "先把 Vim 当普通编辑器用，但别一直待在 Insert", "x": "刚上手时，按 i 进 Insert 模式，就能像普通编辑器一样打字。按 Esc 回到 Normal 模式。 vim · 最小例子（示意） i # Normal 模式下按 i，进入 Insert 模式 ABCD # 讲师敲的就是这几个字母 <Esc> # 回到 Normal 模式，这时按键又变回命令 打个比方 一直待在 Insert 模式，就像买了跑车却只挂一挡开。车能走，但它的本事全浪费了。 讲师就是这么演示的。按 i ，敲了 “ABCD”，再按 Esc 。移动用方向键，配置合适的话还能用鼠标。 这些就够你用 Vim 改文件了，只是不高效。一直待在 Insert 模式里，就没用上 Vim 的长处（ ）。 为什么会在这里踩坑 新手常在 Insert 模式里用方向键挪光标，再用退格一个个删。能用，但很慢。讲义说得直白：删改文字，该用比退格键更强的东西。那就是下面几节的移动和编辑命令。"}, {"u": "ch03.html#s5", "c": "第 3 讲 · 开发环境与工具", "t": "移动命令是名词，指代一段文字", "x": "移动命令也叫 名词 。它指代从光标到落点的那段文字。单独按是挪光标。前面加个动词，就是对这段文字动手。 vim · 最小例子（示意） w # 单独按：光标跳到下一个词首 dw # 前面加动词 d：删掉到下一个词首的这一段 $ # 单独按：光标跳到行尾 d$ # 加上 d：从光标删到行尾 打个比方 移动命令像指路的话，比如“下一个词”“行尾”。单独说，是让你走过去。前面加个“删”，就是把这一段路拆掉。 Normal 模式下的按键分五类（ ）。分别是 移动 、 选择 、 编辑 、 计数 和 修饰符 。它们可以互相组合。讲师特意讲得很快。他强调别背具体按键，要记住组合的思想。 类别 按键（讲义） 助记 基本 h j k l 左、下、上、右。手不离开主键位，方向键也能用 词 w b e 下一个词首、词首（back）、词尾（end） 行内 0 ^ $ 行首、第一个非空字符、行尾 屏幕 H M L ， Ctrl + u / Ctrl + d 屏幕顶、中、底。往上、往下翻半屏 文件 gg G ， :{行号}<CR> 或 {行号}G 文件开头、结尾。跳到指定行， <CR> 是回车 配对 % 跳到配对的圆括号或花括号 行内查找 f{c} t{c} F{c} T{c} ， ; , f 是 find，t 是 to，停在它前一格。大写往左找。 ; 和 , 在匹配之间前后跳 搜索 /{正则} ， n / N 讲师搜了 “phys”，光标跳到第一个匹配。n 下一个，N 上一个 vim · 本机实测（vim -Es 回放，记下每步的光标） 文本 L1: for i in range(limit): w → L1 C5 (for) w → L1 C9 (i) b → L1 C5 e → L1 C7 (for 的 r) 0 → L1 C1 ^ → L1 C5 $ → L1 C26 (:) F( → L1 C19 (() % → L1 C25 ()) j → L2 C22 G → L3 C13 gg → L1 C5 /fizz⏎ → L3 C20（\"fizz\" 的 f） 注意两点。 gg 和 G 落在 第一个非空字符 上，不是第 1 列。 j 会尽量保持原来的列。第 2 行只有 22 个字符，光标就停在行尾。下面的演示让光标一步步走一遍： 为什么会在这里踩坑 j 记着原来的列号。练习 2 里，光标在第 2 行第 31 列。按 4j 下去，落到第 6 行第 31 列。那里正好是 end=\"\" 的空引号，接下来的 ci\" 就改错了地方。想落在第一个非空字符上，用 6G 或 :6 加回车。"}, {"u": "ch03.html#s6", "c": "第 3 讲 · 开发环境与工具", "t": "先选中再动手：三种 Visual 模式", "x": "按 v 、 V 或 Ctrl + v 进 Visual 模式。再用移动键扩大选区，最后按 d 删或 c 改。 vim · 最小例子（示意） vw # 按字符选，w 把选区扩到下一个词的开头 Vj # 按行选，j 把下一行也选进来 <C-v>jl # Ctrl+v 按矩形块选：往下一行，往右一列 d # 对选区动手：d 删除，c 修改 打个比方 Visual 模式像先拿荧光笔，把要改的地方涂出来。涂好了，再决定是擦掉还是重写。 三种 Visual 模式，进去之后都用 移动键 扩大选区（ ）。 按键 模式 讲师演示 v Visual，按字符选 按 w 选到下一个词的开头 V Visual Line，按行选 按 j 把下一行也选进来 Ctrl + v Visual Block，按矩形块选 选出一个矩形区域。很多编辑器做不到 选好之后按 d 删除，按 c 修改。这就是“先选中再操作”。后面行内对话那一节，讲师在 VS Code 里开着 Vim 插件。他就是用 V 加 j 选中代码块，再唤起 AI 的（ ）。 为什么会在这里踩坑 在 Visual 模式里，移动键是在扩大选区，不是在挪光标。忘了还在 Visual 模式，顺手按个 d ，选中的一大片就没了。好在按 u 能撤销。"}, {"u": "ch03.html#s7", "c": "第 3 讲 · 开发环境与工具", "t": "编辑命令是动词，作用在名词上", "x": "以前用鼠标做的事，现在用键盘上的 编辑命令 做。它们叫 动词 ，后面跟一个移动，就作用在那段文字上。 vim · 最小例子（示意） dw # 删到下一个词首，连词后的空格一起删 cw # 改这个词：删掉它，再进 Insert 模式 d$ # 从光标删到行尾 x # 删一个字符，等于 dl u # 撤销，Ctrl+r 重做 打个比方 动词加名词，就像说“删掉这个词”“改到行尾”。句式是固定的。换个名词，就是一条新命令。 动词和名词能自由组合，这正是 Vim 像编程语言的地方。 命令（讲义） 作用 i 进入 Insert 模式。但删改文字，应该用比退格键更强的东西 o / O 在下方或上方开一个新行，并进入 Insert d{移动} 删除。 dw 删一个词， d$ 删到行尾， d0 删到行首。讲师还演示了 dj ，删掉本行和下一行 c{移动} 修改。 cw 改一个词。相当于 d{移动} 再按 i x / s x 删一个字符，等于 dl 。 s 替换一个字符，等于 cl Visual + d / c 选中后删除或修改 u / Ctrl + r 撤销、重做 y / p 复制（yank）、粘贴。 d 这类命令也会把删掉的内容存起来 ~ / J 翻转字符大小写。把下一行接到本行末尾 vim · 本机实测（\"\" 是无名寄存器，存着删掉的内容） 起始: message = \"hello \" + name j^ → 光标 C5（message 的 m） cwgreeting ⎋ → greeting = \"hello \" + name \"\" = message w dw → greeting \"hello \" + name \"\" = \"= \" u → greeting = \"hello \" + name （撤销） $ x → greeting = \"hello \" + nam \"\" = e u → greeting = \"hello \" + name （撤销） F+ d$ → greeting = \"hello \" \"\" = \"+ name\" 注意 dw 删掉的是 = ，因为“一个词”包括后面的空白。 d$ 从光标所在的字符删到行尾。下面的演示把每个动词的效果逐字画出来： 为什么会在这里踩坑 dw 和 cw 看着对称，其实不一样。 dw 会连词后面的空格一起删。光标在词上时， cw 像 ce ，只改到词尾，空格留着。上面实测里， cw 改完 message，后面的 = 和空格都还在。"}, {"u": "ch03.html#s8", "c": "第 3 讲 · 开发环境与工具", "t": "数字让动作重复，i 和 a 决定带不带外壳", "x": "动作前面加数字，就重复那么多次。名词前面加 i ，指括号里面。加 a ，连括号一起算。 vim · 最小例子（示意） 3w # 前进 3 个词 7dw # 删掉 7 个词，是一条命令，一次 u 就能撤销 ci( # change inside ()：只改括号里面 da' # delete around ''：连引号一起删 5u # 计数几乎哪都能加：撤销 5 次 打个比方 i 像只倒掉杯子里的水，杯子留着。 a 像连杯子一起扔掉。 计数 （count）让一个动作重复多次。 3w 前进 3 个词， 5j 下移 5 行， 7dw 删掉 7 个词。讲师补充，几乎任何命令都能带计数。比如 5u 撤销 5 次（ ）。 修饰符 （modifier）改变名词的含义。 i 表示 inner，也就是里面。 a 表示 around，也就是连同外壳。 组合（讲义） 读法 效果 ci( change · inside · ( ) 改当前这对圆括号里的内容。讲师用它替换 Markdown 链接里的网址。他说改函数参数时非常快 ci[ change · inside · [ ] 改方括号里的内容 da' delete · around · ' ' 删掉单引号字符串，连引号一起 vim · 本机实测 起始: print(compute(a, b), items[idx + 1], 'done') fa ci(x ⎋ → print(compute(x), items[idx + 1], 'done') \"\" = a, b fd ci[0 ⎋ → print(compute(x), items[0], 'done') \"\" = idx + 1 f' da' → print(compute(x), items[0],) \"\" = \" 'done'\" 0 ci( ⎋ → print() （光标在 p 上，不在任何括号里） da' 删掉的是 'done' 。around 还带走了一侧的空白。 看最后一行。光标在行首，并不在括号里。Vim 9.2 的 ci( 会往后找这一行里 最近的一对括号 。讲师开场演示时说的正是“改后面那对括号里的内容”。 ci\" 也一样。讲师修 FizzBuzz 时，就利用了它会往后找引号。较老的 Vim 版本里， ci( 不一定往后找。这一条是补充，没在老版本上实测。 vim · 本机实测：计数 起始: alpha beta gamma delta epsilon zeta eta theta iota kappa （下面还有 line 2 … line 7） 3w → C18（delta） 7dw → alpha beta gamma \"\" = delta epsilon zeta eta theta iota kappa u → 恢复 5j → L6 10j → L7（只剩 1 行可走，就停在最后一行） 补充（非视频内容）：本页的 Vim 结果怎么实测 用 vim -u NONE -i NONE -N -Es -S trace.vim 文件 在后台启动 Vim，不读任何配置。脚本用 :normal 执行每组按键。执行完记下光标行列、整个缓冲区和无名寄存器。练习 2 的回放器也是这样跑的。 脚本连续执行时，所有修改会并成一个撤销块。所以每步之后用 :let &undolevels = &undolevels 切一刀。这样 u 的效果就和你手敲时一样。 为什么会在这里踩坑 光标不在括号里时， ci( 也会动手。Vim 9.2 会往后找最近的一对括号。改的未必是你想的那对。上面实测里，光标在行首， print() 括号里的内容全没了。所以先把光标放进要改的括号里，再按 ci( 。"}, {"u": "ch03.html#s9", "c": "第 3 讲 · 开发环境与工具", "t": "学 Vim 的办法：处处开 Vim 模式，硬用一个月", "x": "讲师的办法很直接。把你用的所有软件都切成 Vim 模式，强迫自己用一个月。 bash · 最小例子（示意） vimtutor # 装了 Vim 就有的交互式教程，先过一遍 set -o vi # bash 的命令行也切成 Vim 键位（练习 1 实测） # 发现自己在重复按同一串键？停下来，查一查有没有更短的按法 打个比方 像学骑自行车。头几天比走路还慢，还老摔。熬过去以后，就再也不想走路了。 讲师说“你们得相信我”。三位讲师都用了很多年 Vim，都认为这笔投入非常值。这正是练习 1。 学生问（ ）：撤销和重做，别的编辑器也有。可有些操作别处没有，比如跳到配对括号。我怎么知道 Vim 能做？讲师给了两个办法。 做一遍教程 ：把按键练成肌肉记忆。装了 Vim 就有 vimtutor ，本机实测在 /usr/bin/vimtutor 。 边用边留意 ：发现自己在做重复又烦人的操作？那 一定有更好的办法 。去 Google，问 LLM，或者到课程 Discord 提问。讲师说：“最好的程序员里，有一些是很懒的人。” 讲义推荐的资源 说明 2020 版 Vim 讲座 上一期课程，Vim 讲得更深 vimtutor 随 Vim 一起装好的交互式教程 Vim Adventures 学 Vim 的游戏 Vim Tips Wiki 、 Vim Advent Calendar 各种技巧 VimGolf 代码高尔夫，只不过“编程语言”是 Vim 的界面。比谁的按键最少（练习 2） Vi/Vim Stack Exchange 、 Vimcasts 、 Practical Vim 问答社区、录屏、书 讲义建议 学完基础，就在所有软件里开启 Vim 模式，在实践中用。忍住别用鼠标和方向键。有些编辑器可以直接解绑方向键，逼自己养成好习惯。 为什么会在这里踩坑 最常见的半途而废：嫌慢，又偷偷用回鼠标和方向键。这样永远练不成肌肉记忆。所以讲义建议直接解绑方向键，断了退路。"}, {"u": "ch03.html#s10", "c": "第 3 讲 · 开发环境与工具", "t": "实战：用 Vim 修好有 3 个 bug 的 FizzBuzz", "x": "修 bug 的节奏是固定的。在 Normal 模式里跳到位置，进 Insert 改一点，马上回来。 练习 2 的 lecture.keys 拆成三行（注释是笔记加的） Goif __name__ == \"__main__\": main()<Esc> # bug 1：main 从没被调用 /range<CR>wwi1, <Esc>ea + 1<Esc> # bug 2：应该从 1 数到 limit :6<CR>ci\"buzz<Esc> # bug 3：5 的倍数也打印成了 fizz 打个比方 修 bug 像外科手术。先精准找到病灶，切一刀就收手。Normal 模式负责定位，Insert 模式只管那一刀。 FizzBuzz 是“确认你会写代码”的经典题。打印 1 到 n。3 的倍数打印 fizz，5 的倍数打印 buzz。同时是 3 和 5 的倍数，打印 fizzbuzz。讲义给了一个有 3 个 bug 的版本： 讲义原文：坏掉的 FizzBuzz def fizz_buzz(limit): for i in range(limit): if i % 3 == 0: print(\"fizz\", end=\"\") if i % 5 == 0: print(\"fizz\", end=\"\") if i % 3 and i % 5: print(i, end=\"\") print() def main(): fizz_buzz(20) bug 按键（讲义） 本机 Vim 回放后的光标 main 从没被调用。讲师先运行了一次，什么都没输出 G 到最后一行， o 开新行。输入 if __name__ == \"__main__\": main() ，再按 Esc L12 → L13 从 0 开始，不是从 1 /range<CR> 搜索。 ww 前进两个词。也可以写 2w ，小计数时人们常直接连按。 i 输入 1, ， Esc 。 e 跳到下个词尾。 a 追加 + 1 ， Esc L2 C14 → C20 → C22 → C27 → C31 5 的倍数打印了 fizz :6<CR> 到第 6 行。 ci\" 把引号里的内容改成 buzz ， Esc L6 C13 → C23 讲师指出， a 和 l 加 i 效果一样，但少按一个键。他说这“省了 50% 的输入”（ ）。这些重叠的专用按键，用一阵就成了肌肉记忆。 工作节奏： 平时待在 Normal 模式到处移动 。要改的时候进 Insert 改一点，马上回到 Normal。 讲师的 Vim 开了 Python 支持， o 之后自动缩进了，他按了退格。本机回放用的 Vim 不加载任何配置，没有自动缩进。最后 :w 保存。 bash · 本机实测（修好后运行，换行压成空格显示） $ python fizz.py | tr '\\n' ' ' 1 2 fizz 4 buzz fizz 7 8 fizz buzz 11 fizz 13 14 fizzbuzz 16 17 fizz 19 buzz 下面的演示逐键回放整个修复过程。光标位置全部来自本机 Vim 的真实记录。练习 2 把它改成了一道 VimGolf。讲义解法 70 键，还能压到 64 键。 为什么会在这里踩坑 第 2 个 bug 最容易只修一半。把 range(limit) 改成 range(1, limit) 还不够。range 不含右端点，最后一个数会丢。要写成 range(1, limit + 1) ，才会数到 limit 本身。 bash · 本机实测 $ python -c \"print(list(range(5)))\" # 从 0 开始，到 4 为止 [0, 1, 2, 3, 4] $ python -c \"print(list(range(1, 5)))\" # 只改起点，5 还是没有 [1, 2, 3, 4] $ python -c \"print(list(range(1, 5 + 1)))\" # 讲义的修法：右端点加 1 [1, 2, 3, 4, 5]"}, {"u": "ch03.html#s11", "c": "第 3 讲 · 开发环境与工具", "t": "IDE 靠语言服务器看懂代码，LSP 把 M×N 变成 M+N", "x": "IDE 不会为每种语言各写一套支持。它和各语言的 语言服务器 之间，说一种通用协议，叫 LSP。 LSP · 最小例子（示意，练习 3 有完整的真实会话） 编辑器 → 服务器：textDocument/completion # 在 r. 后面，能补全什么 服务器 → 编辑器：Area, H, W # 服务器推断出 r 是 Rect，列出它的成员 编辑器 → 服务器：textDocument/definition # Println 定义在哪 服务器 → 编辑器：publishDiagnostics # 发现错误时，服务器主动推送，不用你问 打个比方 LSP 像电源插座的国家标准。电器厂只管做标准插头，装修队只管装标准插座。M 种电器配 N 种房子，不用做 M×N 种转接头。 补全、跳转这些功能，都要对代码有语义层面的理解。这套协议叫 语言服务器协议 ，英文是 Language Server Protocol。IDE 实现协议的一端，语言服务器实现另一端。两边就能互通。讲师的说法是，把 M×N 问题变成 M+N 问题 （ ）。 比如 VS Code 的 Python 扩展依赖 Pylance ，Go 扩展依赖官方的 gopls 。 3 个编辑器配 3 种语言。没有协议要做 9 份集成。有了 LSP，各实现一次协议，一共 3 + 3 份。clangd 等例子是补充 语言服务器带来的功能（讲义） 讲师在 VS Code 里的演示 代码补全 ：输入 object. 后看到字段和方法 在一个对象后敲点号，列出所有字段和方法（ ） 行内文档 ：悬停或补全时显示文档 字段有 docstring 时会直接显示 跳转到定义 右键选 Go to Definition，跳到结构体定义。不然只能全局搜索，到处翻 查找引用 ：跳转定义反过来 “我定义的这个结构体，都在哪里用了？” 帮你管 import ：整理、删掉没用的、标出缺的 用了 fmt 却没导入，出现红色波浪线。保存时自动加上 import（ ） 代码质量 ：格式化、类型检查、lint，边写边查错 调用不存在的方法，立刻提示“该类型没有这个方法”。不用等编译或跑测试，第 9 讲细讲 本机装了 Go 和 gopls。于是练习 3 写了一个 最小的 LSP 客户端 ，大约 100 行 Python。它扮演编辑器一方，和 gopls 逐条交换消息。上面每一项都真跑验证过： bash · 本机实测（练习 3 · ex03-a 节选） $ python -u lsp_client.py shapes --> initialize #1 <-- 服务器能力: completionProvider, hoverProvider, definitionProvider, referencesProvider, codeActionProvider --> textDocument/didOpen <-- publishDiagnostics: 1 条 L18:16 r.Perimeter undefined (type Rect has no field or method Perimeter) --> textDocument/completion #2 <-- 补全: Area, H, W --> textDocument/definition #5 <-- 库函数定义: fmt/print.go L306:6 为什么会在这里踩坑 没有语言服务器，跳转定义只能按文本全局搜索。同名的函数、字段一多，就跳到别处去了。这时别急着怪 IDE。先看语言服务器装没装、配没配好。 配置语言服务器（讲义） 有的语言，装好扩展和语言服务器就能用。有的还要告诉 IDE 你的 环境 ，才能发挥全部作用。比如在 VS Code 里，要先 指定 Python 环境 。这样语言服务器才看得到你装的包。环境在第 6 讲细讲。 不同的语言服务器还有各自的设置。比如项目不用类型注解。那就可以在 VS Code 的 Python 支持里，关掉静态类型检查。讲师建议，用到哪种语言，就把它的支持配好。不会就搜 “how to set up Go support for VS Code”。 为什么会在这里踩坑 装了 Python 扩展， import numpy 还是一条红线。多半是 IDE 选错了 Python 环境。语言服务器看不到你装的包。先在 VS Code 里选对解释器，再看红线还在不在。"}, {"u": "ch03.html#s12", "c": "第 3 讲 · 开发环境与工具", "t": "AI 写代码有三种形态，能改的范围一个比一个大", "x": "补全只能往光标后面续写。行内对话能改选中的代码。编码智能体能跨文件、分多步干活。 最小例子（示意） def extract_links(md: str) -> list[str]: # 补全：写到这里，它接着往下写函数体 # 行内对话：选中几行，Ctrl+I，输入“不要用第三方库” # 编码智能体：在对话框里说需求，它自己翻文件、改多处 打个比方 补全像帮你接话的同桌，只能接你的下半句。行内对话像改作文的老师，只改你圈出来的那段。智能体像坐在旁边的搭档。它能自己翻整个项目，也能和你商量。 讲师说这是最难准备的一部分，因为不确定大家的背景。他现场问，谁用过专门写代码的 AI 工具？ChatGPT 这类独立聊天不算。只有约 20% 的人举手，于是重点讲基础。 2021 年中， GitHub Copilot 推出，用的是 OpenAI 的 Codex 模型。从那以后， 大语言模型 在软件工程里被广泛采用。目前主要有三种形态： 形态 你怎么用 能改哪里 自动补全 autocomplete 边打字边出现灰色建议，按 Tab 接受。可以用注释“引导”它 只能在 光标之后 续写 行内对话 inline chat 选中一行或一块，直接用自然语言下指令 能改已有的代码，通常限于选区 编码智能体 coding agents 对话式，像接入了你代码库的 ChatGPT 多文件、多步骤。第 7 讲专讲 为什么会在这里踩坑 拿补全去干需要改别处的活，它只会在光标后面硬写。下一节的 import re 被塞进函数中间，就是这么来的。动手前先想清楚改动范围，再挑形态。"}, {"u": "ch03.html#s13", "c": "第 3 讲 · 开发环境与工具", "t": "补全只看上下文，名字起清楚它才补得对", "x": "AI 补全只在光标处往后续写。它补的是最可能的写法。所以函数名和注释，决定了它补出什么。 python · 最小例子（示意，签名取自讲义） def extract(contents: str) -> list[str]: # 名字太含糊：模型只会把内容按行切开 # 加一行英文注释，说明要提取 Markdown 链接，它就补对了 def extract_links(contents: str) -> list[str]: # 更好：名字自己说清楚，用不着临时注释 打个比方 补全像一个听半句话就抢答的同学。你只说“提取”，他不知道提取什么。说成“提取链接”，他就答对了。 补全的形式和传统补全一样，在光标处给出续写建议。可以开着它被动地用。也可以用代码注释来 提示 （prompt）它。讲师用 VS Code 加 GitHub Copilot 演示。他强调不推荐具体产品，Cursor 里效果一样。演示任务是写一个脚本。它下载本讲讲义，再提取里面所有的链接。 讲义原文：只写了函数签名 import requests def download_contents(url: str) -> str: 模型补全了函数体。讲师还用快捷键在几个候选之间切换（ ）： 讲义原文：模型的补全 response = requests.get(url) return response.text 接着写一个名字含糊的函数 def extract(contents: str) -> list[str]: 。模型只能按最可能的方式补，结果是把内容按行切开。这对“提取链接”毫无用处。加一行注释 # extract all Markdown links from the content ，补全就对了。下面是讲义原文： 讲义原文：注释引导后的补全 import re pattern = r'\\[.*?\\]\\((.*?)\\)' return re.findall(pattern, content) 只能补光标之后 ： import re 被塞进了函数中间。按惯例，它应该在模块顶部。这是补全形态固有的局限（ ）。 更好的做法 ：函数名起得有描述性，比如 extract_links ，再写个 docstring。模型同样能一次补对，docstring 对以后读代码的人也有用。只为引导 AI 写的临时注释，事后删掉（ ）。 务必检查 ：模型只是在大量数据上训练出来的概率模型。它没有人那样的智能。接受补全前，要看它是否真做了你想要的。有时得改一改，或者自己重写（ ）。 讲义原文：把脚本补完 print(extract(download_contents(\"https://raw.githubusercontent.com/missing-semester/missing-semester/refs/heads/master/_2026/development-environment.md\"))) 补充（非视频内容）：引导后的正则在本机真跑 本机没接 Copilot，没法复现“补全”这个动作。但可以验证补出来的代码对不对。拿一小段示例 Markdown 跑一下： bash · 本机实测 $ python -c \"import re; print(re.findall(r'\\[.*?\\]\\((.*?)\\)', 'See [VS Code](https://code.visualstudio.com/) and [Vim](https://www.vim.org/).'))\" ['https://code.visualstudio.com/', 'https://www.vim.org/'] 下面的演示画出两件事。一是补全只能在光标后续写，二是注释怎么改变上下文。模型输出逐字取自讲义。 为什么会在这里踩坑 按 Tab 太顺手，最容易漏看。补出来的代码有时看着对，其实有问题。本节的 import re 被塞进了函数中间，就是一例。接受之前一定要读一遍。"}, {"u": "ch03.html#s14", "c": "第 3 讲 · 开发环境与工具", "t": "行内对话能改已有代码，但通常只改选区", "x": "选中一段代码，用自然语言下指令，模型就改这一段。编辑器用 diff 显示改动，你审完再决定留不留。 最小例子（示意） Vj # Vim 键位：按行选中，j 往下扩 Ctrl+I # 唤起行内对话，Mac 上是 Cmd+I use built-in libraries instead # 讲义里的指令：别用第三方库 # 红色是要删的行，绿色是新增的行，审完再接受 打个比方 行内对话像在文档上圈一段，旁边批注“改成这样”。批注只管圈里的字，圈外的一个不动。 行内对话（inline chat）也是用自然语言让模型写代码。和补全不同，它能 改已有的代码 。接着上面的例子，假设不想依赖第三方库 requests。讲师在 VS Code 里用 Vim 键位 V 加 j ，选中那三行。再按 Ctrl / Cmd + I 唤起行内对话，输入“不要用第三方库”。讲义里写的是 use built-in libraries instead 。 讲义原文：模型的提议 from urllib.request import urlopen def download_contents(url: str) -> str: with urlopen(url) as response: return response.read().decode('utf-8') 编辑器用 diff 显示改动。红色是删除，绿色是新增。你审完再选择保留（ ）。 学生提问：改动要用到选区外的代码呢？（视频 44:14） 要看具体实现。讲师现场试了一下。他把光标放在函数里，让它把 import 移到外面。在这个实现里，它只改选区内的内容，没做成有用的事。别的编辑器的行内对话，可能允许改其他地方。这个领域很新，变化很快。 为什么会在这里踩坑 想让它“把 import 移到文件顶部”，可能做不成。有些实现只改选区里的内容，文件顶部不在选区里。这种跨位置的改动，交给编码智能体。"}, {"u": "ch03.html#s15", "c": "第 3 讲 · 开发环境与工具", "t": "AI 工具基本都要联网，要真隐私只能本地跑", "x": "主流模型太大，只能跑在云端。你的代码和提示词都会发过去。想完全不上传，就得在本地跑模型。 三种选择（示意） # 云端模型：代码和提示词发到服务商的 GPU 上算，能力最强 # 打开隐私选项：服务商承诺不保留数据，但你只能选择信任 # 本地模型：数据不出电脑，代价是能力差一截、很耗电 打个比方 云端模型像去餐馆吃饭，菜好，但后厨你看不见。本地模型像在家做饭，放心，就是手艺差点。 要联网吗？ 基本都要。这些工具用的模型非常大，有的上万亿参数。要大量显存和高级 GPU 才跑得动。也有能在笔记本上跑的本地小模型。但能力差一截，而且很耗电（ ）。 能不让代码上传到云端吗？ 讲师说“可以，但有星号”。有些工具能在设置里打开额外的隐私选项。提供方承诺不保留你的代码和提示词。但你是在 信任 他们这么做，常见的技术保障手段还很少。真要隐私，只能在本地跑模型（ ）。 在 Python 以外、没那么灵活的语言里，效果差吗？ 讲师的经验是“还行”。有些补全模型还会预测 光标下一步要去哪 。比如它发现你需要 import re 。它会先建议光标跳到顶部写 import。写完再跳回来补函数体（ ）。 在合适的抽象层次上工作 ：简单的事让 AI 直接搞定。任务超出它的能力，它会写出看着对、其实有 bug 的代码。或者彻底糊涂（ ）。工具每隔几个月就进步一截。三个月前做不到的事，现在可能轻松完成。所以要一直用，不断试探它的边界。这样你对它擅长什么的直觉，才不会过时。 讲师的提醒（视频 50:52） 这些 LLM 不像人那样有智能。它们是“概率性的下一个 token 预测器”。有时说得合理也正确，有时乍看合理，却完全错误。所以用它们，和把任务交给一位员工不一样。讲师说，希望员工别像这些模型那样，试图对你 gaslight。 为什么会在这里踩坑 AI 写的代码有时看着合理，其实是错的。任务越超出它的能力，越容易这样。别像信任同事那样直接合并，每一行都要自己审。"}, {"u": "ch03.html#s16", "c": "第 3 讲 · 开发环境与工具", "t": "要 AI 解释、反问、说把握，得用编码智能体", "x": "补全和行内对话只管写代码。想让 AI 先问你问题、解释思路，得用编码智能体。它是对话式的。 对话示意 你：先别写代码。问我几个问题，弄清需求再动手。 # 补全和行内对话做不到这一步 智能体：链接要去重吗？相对路径要不要转成绝对路径？ # 对话式工具可以反过来问你 你：要去重，相对路径不用管。 # 答完它再动手，第 7 讲细讲 打个比方 补全和行内对话像自动铅笔，你写到哪它补到哪。智能体像一个能聊天的搭档，可以先商量，再动笔。 学生问：能不能让 AI 解释它为什么这么写？能不能先问我问题，再说说它有多确定？讲师说，补全和行内对话做不到， 编码智能体 可以。它们是对话式工具。讲师说，它“大致相当于接入了你代码库的 ChatGPT”。你可以让它先问你问题，也可以随时问它。 之前有学生问侧边栏的 “Build with agent” 聊天框（ ）。它和写注释有什么区别？答案也在这里。补全只在光标后补一小段。改文件别处的事，要交给对话或智能体。 编码智能体在 第 7 讲 深入展开。这次讲座超时了。讲师现场举手投票，不少人想深入了解（ ）。他表示会考虑调整课表。最终的课表里，第 7 讲就是《智能体编程》。 讲义推荐的软件 流行的 AI IDE 有两类。一是 VS Code 加 GitHub Copilot 扩展，二是 Cursor 。 GitHub Copilot 对学生、教师和热门开源项目的维护者 免费 。但要先通过 GitHub Education 认证身份。讲师记得，要交学生证之类的材料。别的很多工具每月约 20 美元。 讲师的看法是，这个领域变化很快。主流产品的功能大致相当（ ）。入门阶段尤其如此。 为什么会在这里踩坑 问补全“你为什么这么写”，它答不了。补全只会续写代码，行内对话也只会改选区。想要解释和追问，得换成对话式的智能体。"}, {"u": "ch03.html#s17", "c": "第 3 讲 · 开发环境与工具", "t": "IDE 的很多本事，来自扩展 讲义", "x": "视频没来得及讲这部分。IDE 因为 扩展 而更强大。比如在容器里开发、远程开发、多人同时编辑。 bash · 写法示意 code --install-extension vscodevim.vim # VS Code：命令行装扩展，参数是发布者.名字 git clone 仓库地址 ~/.vim/pack/plugins/start/名字 # Vim 8 起：放进这个目录就算装好 :scriptnames # 在 Vim 里列出已加载的脚本，确认插件在里面 打个比方 扩展像手机里的 App。手机出厂只会打电话、发短信。装上 App，才能导航、记账。 可以浏览扩展榜单。Vim 插件看 Vim Awesome ，VS Code 看 按安装量排序的扩展 。讲义点名了这几个： 功能 做什么 例子 开发容器 在容器里运行开发工具，方便移植或隔离。容器见第 6 讲 VS Code 支持 远程开发 通过 SSH 在远程机器上开发。比如在云上的强力 GPU 机器上写代码、跑代码 Remote - SSH 。用的就是第 2 讲的 SSH 和 ~/.ssh/config 协同编辑 像 Google Docs 一样，多人同时编辑一个文件 Live Share 补充（非视频内容）：扩展本质上是什么 以 Vim 为例，扩展就是一些脚本。它们放在约定的目录里，启动时会被执行。Vim 8 起自带包机制， ~/.vim/pack/*/start/*/plugin/*.vim 会自动加载。练习 4 在沙箱里写了一个 7 行的插件。实测加载前 :Hello 报错，返回 1。加载后正常工作。 VS Code 扩展是装在扩展目录里的 JavaScript 包。由扩展主机进程负责加载。 为什么会在这里踩坑（补充，非视频内容） 扩展能读你的代码，也能运行程序。来路不明的扩展，和第 2 讲的 curl | bash 一样危险。装之前看看发布者、安装量和更新时间。一次只装一个，确认真在用再留下。"}, {"u": "ch03.html#s18", "c": "第 3 讲 · 开发环境与工具", "t": "一页带走：本讲结论都在这几行里", "x": "把本讲浓缩成几行按键和命令。每行的注释就是结论和考点。 本讲速查（注释即考点） x / ix<Esc> / vex # 同一个 x：Normal 删字符，Insert 打字，Visual 删选区 7dw # 计数加动词加名词：删掉 7 个词，一次 u 全回来 cw # 等于 d 加移动再按 i。光标在词上时像 ce，不吃后面的空格 x = dl s = cl # 讲义给的等价写法 ci( da' # i 只动里面，a 连外壳一起 ci\" # 光标在行首：改 \"fizz\"。光标在 end= 后面：改的是 \"\" 6G :6<CR> 4j # 前两个落在第一个非空字符。4j 保持列号，练习 2 就错在这 # LSP：编辑器实现一次客户端（M），语言实现一次服务器（N），M×N 变 M+N # AI 补全只能续写光标之后，所以 import re 被塞进了函数中间 # 隐私：设置里的“不保留数据”靠信任，真隐私只能本地跑模型 写代码主要是跳转、阅读和小改。Vim 为此优化，核心思想在各种软件的 Vim 模式里通用。 模态编辑：Normal 是大本营。 i 、 R 、 v 、 V 、 Ctrl + v 、 : 进入其他模式， Esc 回来。 编辑语言： 动词 d c y ， 计数 3 5 7 ， 名词 w e $ % ， 修饰符 i a 。 7dw 、 ci( 、 da' 都是这么拼出来的。 语言服务器协议把 M×N 变成 M+N。功能有补全、悬停文档、跳转定义和查找引用。还能整理 import，边写边查错。 AI 有三种形态。补全只续写光标之后，行内对话改选区。编码智能体能对话、走多步，第 7 讲细讲。不管哪种，结果都要审。 主流模型在云端。要真正的隐私，只能在本地跑模型。 下一步 第 1、2 讲在 shell 里组合程序。这一讲转向 写代码本身的工具 。也就是编辑器、语言服务器和 AI。下一讲是调试与性能分析。讲代码写出来以后，怎么找 bug，怎么让它跑得快。AI 编程在第 7 讲深入。 现在先去做 本讲练习的可视化笔记 。开启 Vim 模式，打一局 VimGolf。再用 100 行的 LSP 客户端和 gopls 对话，最后装一个扩展。"}, {"u": "ch04.html", "c": "第 4 讲 · 调试与性能分析", "t": "开头", "x": "本讲结论 程序只做你 写 的事，不做你 以为 的事。调试就是找出两者在哪一步分岔。先用打印和日志看，再上调试器、系统调用追踪和 sanitizer。调试器能设断点、观察点，还能倒着执行。性能分析先 测量 ，再优化。测量靠 time、基准测试、profiler 和火焰图。"}, {"u": "ch04.html#s1", "c": "第 4 讲 · 调试与性能分析", "t": "代码只做你写的事，不做你想的事", "x": "计算机严格按字面执行，不猜你的心思。你想的和它做的，总会在某一步分岔。调试就是找到这一步。 bash · 本机实测（Python 3.13.5） $ python -c 'x = [3, 1, 2]; y = x.sort(); print(y, x)' # 以为 y 是排好的新列表 None [1, 2, 3] # sort 原地改了 x，返回值是 None 打个比方 计算机像一个死抠字面的跑腿。你说“把这摞单子排好给我”，他在原地排好了。递到你手里的，却是一张空收条。 这是讲义开头的“黄金法则”。代码不会做你 期望 的事，只会做你 告诉 它的事。计算机几乎什么都能做，但它只认字面。 调试（debugging）处理的是结果不对。性能分析（profiling）处理另一类问题。结果是对的，但太慢或太占内存。 本讲的工具都服务于中间两步。先把内部状态摆到眼前，再验证猜想 为什么会在这里踩坑 代码看着对，跑了一个例子也对，就以为没问题。练习页的归并排序就是这样。bug 只在下标 i 和 j 不相等时才出现。前两次合并时 i 和 j 都是 0，结果碰巧是对的。所以别只信一个例子，多造几组随机数据去对拍。"}, {"u": "ch04.html#s2", "c": "第 4 讲 · 调试与性能分析", "t": "print 调试每次从零开始，日志能一直留着", "x": "print 调试就是在怀疑的地方打印信息。修好 bug 以后，把这些 print 改成带级别的日志留下来。下次出事，信息已经在了。 bash · 本机实测（Python 3.13.5） $ python -c 'import logging; logging.info(\"hello\"); logging.warning(\"slow query\")' WARNING:root:slow query # info 那条没了：默认阈值是 WARNING 打个比方 日志级别像小区门禁。阈值设成 WARNING，就只放警告以上的人进门。DEBUG 和 INFO 在门口就被拦下，连个记录都不留。 讲师引用了 C 语言作者之一 Brian Kernighan 的话。最有效的调试工具，仍然是 仔细思考 。再加上 放对位置的打印语句 。讲师说，他自己的调试大多也还是 print 调试。 print 调试最大的问题是 每次都从零开始 （ ）。程序跑完，你得重新去缩小范围。于是有了 日志 （logging）。它是更讲究的 print，会一直留在代码里： 日志框架提供的 说明（讲义，视频 2:30–3:41） 级别（level） TRACE、DEBUG、INFO、WARN、ERROR、CRITICAL。可以设阈值，只输出够重要的记录。生产环境常关掉 TRACE 和 DEBUG，调试时再打开 按模块设置 比如“这一块要 trace 级别，其余只要 warning”。只深挖你关心的部分 输出去向 全部或部分日志，可以导到不同的地方。比如文件、终端、日志服务 结构化日志 不是一句话，而是带字段的记录，比如指标或 JSON。事后程序能直接提取 logdemo.py（笔记作者编写，用来演示级别过滤） import logging, sys logging.basicConfig(stream=sys.stdout, level=logging.INFO, format=\"%(levelname)-7s %(name)s: %(message)s\") db, web = logging.getLogger(\"app.db\"), logging.getLogger(\"app.web\") def handle_request(): web.debug(\"parsing headers\") web.info(\"GET /index.html\") db.debug(\"SELECT * FROM users WHERE id = 42\") db.warning(\"slow query took 1200 ms\") web.error(\"template not found: index.html\") # 跑三次：先用 INFO，再把 root 调成 WARNING。最后 root 回到 INFO，单独把 app.db 调成 DEBUG python · 本机实测（Python 3.13） == root level = INFO INFO app.web: GET /index.html WARNING app.db: slow query took 1200 ms ERROR app.web: template not found: index.html == root level = WARNING WARNING app.db: slow query took 1200 ms ERROR app.web: template not found: index.html == root INFO, but app.db = DEBUG INFO app.web: GET /index.html DEBUG app.db: SELECT * FROM users WHERE id = 42 WARNING app.db: slow query took 1200 ms ERROR app.web: template not found: index.html == structured (JSON) logging {\"ts\": 1793293095, \"level\": \"WARNING\", \"logger\": \"app.db\", \"msg\": \"slow query\", \"ms\": 1200, \"table\": \"users\"} 把 print 变成日志（视频 4:17） 调试时加了一堆 print。问题修好以后，别急着删。把它们改成合适级别的日志，留在代码里。下次出类似问题，需要的信息早就打在日志里了。不用再改代码、重编译、重跑。日志要是半结构化的，还能直接用第 1 讲的 grep 和 awk 提取。 第三方程序：先加 -v，再翻系统日志 别人写的程序，你改不了代码。但它们大多自带日志开关。 很多命令行工具支持 -v 或 --verbose ，打印更多信息。常常还能叠加，写成 -v -v 或 -vv 。 系统服务也有日志。比如数据库、Web 服务器、SSH 守护进程。Linux 上常在 /var/log/ 下。systemd 管的服务用 journalctl -u <服务名> 查看。第 1 讲的 SSH 日志就是这么来的。 第三方库也可以查查（讲义）。看它能不能用环境变量或配置打开调试日志。 下面的演示用本机实测的输出，画出两件事。每条记录都带级别，过滤器按阈值放行： 为什么会在这里踩坑（补充，非视频内容） Python 的 logging 默认阈值是 WARNING。没配置就写 logging.info ，什么都不会打印。上面的实测就是这样。更隐蔽的是下面这条： bash · 本机实测 $ python -c 'import logging; logging.warning(\"a\"); logging.basicConfig(level=logging.DEBUG); logging.debug(\"b\")' WARNING:root:a # debug 那条没出来：basicConfig 被悄悄忽略了 模块级的 logging.warning 会顺手做一次默认配置。之后再调 basicConfig ，就不生效了。所以配置日志的代码，要放在程序最开头。真要重新配置，就加 force=True 。"}, {"u": "ch04.html#s3", "c": "第 4 讲 · 调试与性能分析", "t": "调试器让程序停在现场，你随时翻看变量", "x": "print 要你提前猜好打印什么。调试器让程序停下来，你想看哪个变量就看哪个。 bash · 本机实测（Python 3.13.5，节选。pdb 不回显命令，这里补在提示符后。路径前缀已省略） # avg.py 里 avg([]) 会算 total / len(xs)，除以 0 $ printf 'p xs, total\\nq\\n' | python -m pdb -c c avg.py # -c c：直接跑，崩了就停在现场 …（Traceback 省略） ZeroDivisionError: division by zero Uncaught exception. Entering post mortem debugging … > avg.py(3)avg() -> return total / len(xs) (Pdb) p xs, total # 现场还在：xs 是空列表 ([], 0) 打个比方 print 调试像在路口装几个摄像头，只看得到装了的地方。调试器像让车直接停在路边。你走过去，车里什么都能翻。 print 调试适合这种情况：你知道该打印什么。改代码重跑也方便。下面几种情况，就该上 调试器 （debugger）了。你不确定需要什么信息。bug 只在难以复现的条件下出现。重启程序代价很大，比如启动慢、状态难重建。调试器让你在程序运行中和它交互。 能做什么（讲义） 执行到某一行时暂停。一次执行一步。崩溃后查看变量。满足条件时才停。还有很多高级功能。 两类调试器 通用的 gdb （GNU）和 lldb （LLVM）能调任何本地二进制。C、C++、Rust 都行。语言专用的有 Python 的 pdb 、Java 的 jdb。它们和运行时结合得更紧。 gdb 命令（讲义） 作用 pdb 里对应 run 启动程序 run / restart b 函数 、 b 文件:行 设断点，可以加条件 b 行号, 条件 c 继续运行到下一个断点 c step / next / finish 单步进入、单步越过、运行到当前函数返回 s / n / r p 表达式 打印变量或表达式的值 p bt backtrace，打印调用栈 w （where） watch 表达式 观察点：值一变就停 pdb 没有，要用条件断点模拟 讲义提示：gdb 的 TUI 模式 gdb -tui ，或者在 gdb 里按 Ctrl - x a 。屏幕分成上下两半。上面是源代码，下面是命令行。 讲义调试练习 1 的归并排序有 bug。用 pdb 的 条件断点 ，停在两边各 2 个元素的那次合并。单步几下就能看到问题： bash · 本机实测（Python 3.13 pdb，节选。pdb 不回显命令，这里把 step.pdb 里的命令补在提示符后。路径前缀已省略） $ python -m pdb msort.py < step.pdb (Pdb) b merge, len(left) == 2 and len(right) == 2 Breakpoint 1 at msort.py:11 (Pdb) c > msort.py(11)merge() (Pdb) p left, right ([1, 3], [1, 4]) …（n 单步若干次） > msort.py(18)merge() -> result.append(right[i]) (Pdb) p i, j, right[i], right[j] (1, 0, 4, 1) 应该取 right[j] ，也就是 1。代码却用了左边的下标 i ，取到了 4。完整过程见练习页 调试 1 。 下面的演示分两幕。第 1 幕画出这次单步。第 2 幕是 gdb 的 观察点 （watchpoint）。它盯住讲义调试练习 2 里的 students[1].id ，值一被改写程序就停。练习页 调试 2 有本机真跑的结果。 为什么会在这里踩坑 两个坑最常见。第一，编译 C 程序时没加 -g 。调试器只看得到地址，看不到变量名和源码行。第二，把 gdb 的条件写法搬进 pdb。gdb 写 b 18 if i != j ，pdb 要写 b 18, i != j 。写错了，断点根本没设上，程序直接跑完。练习页调试 1 实测过这个坑。"}, {"u": "ch04.html#s4", "c": "第 4 讲 · 调试与性能分析", "t": "跑过头才发现出错？rr 能倒着执行", "x": "rr 先把一次运行完整录下来。回放时既能往前走，也能倒着走。发现值已经坏了，就从这里往回倒。一直倒到它刚被改坏的那一刻。 rr · 写法示意（本机没有 Linux，未实测） rr record ./corruption # 录一次完整运行 rr replay # 回放，界面就是 gdb (rr) watch accounts[0].id # 盯住那个被改坏的字段 (rr) reverse-continue # 倒着跑，停在最后一次改它的地方 打个比方 rr 像行车记录仪。普通调试器只能从现在往前开。rr 能把录像往回拖，拖到撞车前一秒。看清是谁先变的道。 普通调试器只能让程序 往前 跑：停下，再继续。麻烦在于，你常常跑过了头才发现出错。这时真正的 bug 早就执行过去了。你真正想问的是：“这个数怎么变成 4 而不是 5 的？”（ ） 记录-回放调试 （record-replay debugging）解决的就是这个问题。Linux 上的 rr 把一次运行里所有不确定的东西都录下来。之后可以 确定性地 重放任意多次，还能 倒着执行 。它的界面就是 gdb，命令完全一样。 bash · 讲义原文（注释译成中文） rr record ./my_program # 录制一次执行 rr replay # 回放（打开 gdb 界面） 反向命令（讲义） 作用 reverse-continue （ rc ） 倒着运行，直到碰到断点或观察点 reverse-step （ rs ） 倒退一行 reverse-next （ rn ） 倒退一行，跳过函数调用 reverse-finish 倒着运行到进入当前函数的地方 视频演示：倒放一次就抓到越界的 strcpy 账户 0 改名后，id 变成了怪数。rr 倒着执行，直接停在写坏它的 strcpy 上。 gcc -g corruption.c -o corruption 。 -g 让编译器保留变量名和函数名。还会记下每段机器码对应哪行源码。没有它，调试器只看得到地址（ ）。 程序跑完，账户 0 的名字正确改成了 “Alexandria”。id 却变成了一个怪数。 先 rr record ./corruption ，再 rr replay 。然后 break 52 、 continue ，停在检测异常的 if 上。此时 p accounts[0].id 已经坏了（ ）。 普通 gdb 到这里只能把断点往前挪，再从头重跑。一次次地二分。rr 可以先 watch accounts[0].id ，再 reverse-continue 。程序倒着执行，直到这个值发生变化（ ）。 命中硬件观察点。注意倒放时 Old 和 New 是反的，New value 是更早的值（ ）。 bt 显示改写它的是 C 库的 strcpy，调用者是 update_name（ ）。 原因是 name 字段只有 8 字节。“Alexandria” 加上结尾的 \\0 有 11 字节。多出的部分写进了紧挨着的 id（ ）。 rr 的限制（讲义，视频 21:37–22:48） 只支持 Linux。它需要 CPU 的硬件性能计数器。很多虚拟机不提供，比如多数 AWS EC2 实例。也不支持 GPU。macOS 可以看看 Warpspeed。 改了代码就得重新录。旧录像对应的是旧的二进制文件。 用法技巧：第 1 讲有个“跑到失败为止”的循环。把里面的命令换成 rr record 。偶发失败一出现，你就有了一份录像。它能反复前进后退。 Heisenbug （ ）的名字来自测不准原理。你一观察，它就消失。最常见于 print 调试。打印让程序变慢。并发程序里，线程的先后顺序跟着变了。bug 也就不出现了。 调试器同样会改变执行方式。rr 尤其如此，它用 确定性调度 按固定顺序跑所有线程。某些竞态在它下面可能根本不发生。讲义说，可能要录好几次才能抓到。所以选工具时，不光要看它能做什么。还要看问题在它下面还能不能复现。 学生提问：gdb 能不能方便地重来？（视频 23:33） 可以。gdb 里再敲一次 run ，会从头运行程序， 所有断点都保留 。再配合 watch ，就能直接停在第一次改那个字段的地方。然后 continue 到下一次修改。没有 rr 时，这就是“二分”的做法。本机是 Windows，没有 rr。练习页 调试 2 用 gdb 观察点真跑出了结果： bash · 本机实测（gdb 14.1 MinGW，节选） $ gdb -q -batch -x watch.gdb ./corruption Hardware watchpoint 2: students[1].id Thread 1 hit Hardware watchpoint 2: students[1].id Old value = 1002 New value = 1007 #0 curve_scores (student_idx=0, curve=5) at corruption.c:23 #1 0x00007ff7631617fc in main () at corruption.c:34 $1 = 3 $2 = (int *) 0x7ff7631690b0 <students+16> $3 = (int *) 0x7ff7631690b0 <students+16> 下面的演示复述视频里的 rr 演示。先录制，再回放，和手工二分对比。最后倒着执行，找到写坏 id 的 strcpy。 为什么会在这里踩坑 加一行 print，bug 就不见了。删掉 print，bug 又回来了。这多半是 Heisenbug，打印改变了线程的先后顺序。这时别再往里加 print 了。把 rr record 放进“跑到失败为止”的循环，录住出错的那一次。"}, {"u": "ch04.html#s5", "c": "第 4 讲 · 调试与性能分析", "t": "strace 把程序找内核办的每件事都列出来", "x": "程序开文件、分内存、建进程、上网，都要找内核。这些请求叫 系统调用 （system call）。strace 把每一次调用和参数都打印出来。 bash · 写法示意（Linux，本机未实测） strace -e trace=%file ls -l # 只看和文件有关的调用 strace -f ./build.sh # 跟进子进程，不加就漏掉 strace ls 2>&1 | grep openat # strace 写的是 stderr，先 2>&1 才能 grep 打个比方 strace 像银行柜台的流水单。客户在家怎么盘算，你看不见。但他每次来柜台存钱、取钱、查账，都记得清清楚楚。 有时 bug 不在你的代码里。或者你只想知道，一个程序在做什么、卡在哪。它可能还是别人写的。追踪系统调用，就能看到程序在“边界”上做的每件事。 ls -l 和内核之间的大致过程。按视频 27:22–33:43 的讲解画成示意，不是真实输出 bash · 讲义原文（注释译成中文） strace ./my_program # 追踪全部系统调用 strace -e trace=file ./my_program # 只看与文件相关的 strace -f ./my_program # 跟随子进程（程序再启动别的程序时很重要） strace -p <PID> # 附着到正在运行的进程 strace -T ./my_program # 显示每次调用的耗时 输出太多 ：开头一大段是在启动进程、加载共享库。这些通常不是你关心的（ ）。用 -e 过滤。 %file 表示所有和文件系统有关的调用。也可以只写一个调用名，比如 statx 。man 页的 filtering 一节还有更多类别（ ）。比如进程、网络和信号。讲师用 2>&1 | less 把全部输出送进分页器慢慢翻。 -f 跟随子进程 。讲师那台机器上，ls 其实是 Nix 的包装程序。真正干活的 ls 是它启动的子进程。不加 -f ，就什么都看不到（ ）。 参数决定行为 ：加了 -l ，ls 要对每个文件做 statx 和 listxattr。还要去读时区文件。追踪里一眼就能看出，ls -l 比 ls 干的活多（ ）。 -p 附着上去却什么都不打印 ？说明那个进程卡在纯 CPU 计算里（ ）。它根本没找内核。 macOS 和 BSD 上用 dtruss ，它基于 dtrace。想深入学，可以看 Julia Evans 的 strace zine （讲义）。 本机实测：Git Bash 自带的 strace 不是 Linux strace Windows 没有 Linux 的 ptrace，讲义的 strace 命令本机跑不了。Git Bash 的 /usr/bin/strace 是 Cygwin/MSYS 版。它记录的是 MSYS 运行时里的 POSIX 层调用。用 -m syscall 只看这一层。再用一个小 awk 脚本，把几百行原始输出压成时间线。同样能看出 ls -l 多做了什么： bash · 本机实测（Git Bash 的 MSYS strace，TZ=UTC。目录 d 里只有 a.txt 和 b.txt） $ strace -o plain.trace -m syscall ls d > /dev/null $ awk -f d4/calls.awk plain.trace …（逐条调用的时间线，见练习页） -- total: lstat=0 stat=2 opendir=1 readdir=5 closedir=1 open=0 write=1 $ strace -o long.trace -m syscall ls -l d > /dev/null $ awk -f d4/calls.awk long.trace … -- total: lstat=3 stat=1 opendir=1 readdir=5 closedir=1 open=7 write=1 多出的 3 次 lstat，是目录本身加两个文件。7 次 open 里有 1 次是时区文件 /usr/share/zoneinfo/UTC 。这和视频里 Linux 上的现象一致。完整时间线见练习页 调试 4 。 下面的演示是 ls -l 的调用时序，按视频讲解画成示意。再分别看 -e 、 -f 、 -p 的作用： 为什么会在这里踩坑 想用 grep 筛 strace 的输出，屏幕上却照样刷满。因为 strace 把追踪写到 stderr，管道只接 stdout。要先写 2>&1 ，讲师就是这样接给 less 的。另一个坑是忘了 -f 。程序一启动子进程，真正干活的那部分就全漏掉了。"}, {"u": "ch04.html#s6", "c": "第 4 讲 · 调试与性能分析", "t": "要统计不要流水账，就把小程序装进内核", "x": "strace 只会逐条打印。eBPF 把一段小程序装进内核，在事件发生处就地计数。bpftrace 是它的高层写法，语法像 awk。 bash · 写法示意（本机没有 Linux，未实测） # 每次有进程进入 openat 就触发，按进程名计数 sudo bpftrace -e 'tracepoint:syscalls:sys_enter_openat { @[comm] = count(); }' # 不会逐条刷屏。按 Ctrl-C 时，才打印每个进程打开了几次文件 打个比方 strace 像在收银台逐张抄小票。bpftrace 像在收银机里装个计数器。它只记每种商品卖了几件，打烊时报个总数。 想要 统计 怎么办？比如 read 调用的耗时分布。那就得把一段小程序 装进内核 。这就是 eBPF （extended Berkeley Packet Filter）。它是跑在 Linux 内核里的沙箱程序。它有内核的视野，表达能力很强。 bpftrace 提供了类似 awk 的高层语法（ ）。 bash · 讲义原文（注释译成中文） # 打印全系统每一次打开文件（立即输出） sudo bpftrace -e 'tracepoint:syscalls:sys_enter_openat { printf(\"%s %s\\n\", comm, str(args->filename)); }' # 按名字统计系统调用次数（Ctrl-C 时打印汇总） sudo bpftrace -e 'tracepoint:syscalls:sys_enter_* { @[probe] = count(); }' # 只看名叫 bash 的进程 sudo bpftrace -e 'tracepoint:syscalls:sys_enter_* /comm == \"bash\"/ { @[probe] = count(); }' # 用 -c 启动一条命令，cpid 就是它的 PID sudo bpftrace -e 'tracepoint:syscalls:sys_enter_* /pid == cpid/ { @[probe] = count(); }' -c 'ls -la' 片段 含义（视频 37:17–41:29） tracepoint:syscalls:sys_enter_* 探针：进入任何系统调用时触发。 * 是模式，也可以写具体名字，比如 sys_enter_statx /条件/ 过滤。 comm 是进程名， pid 是进程号 @[probe] = count() @ 是一个 map。 probe 是当前探针名。 count() 每调用一次加 1 -c 'ls -la' 由 bpftrace 启动这条命令，把它的 PID 放进特殊变量 cpid 。命令结束时自动打印结果 strace 胜在拿来就能用。想要 更低开销 ，就用 bpftrace。追踪内核函数、做 聚合 ，也用它（讲义）。代价是必须 root。而且它默认监视整个内核，不只是某个进程。视频 39:03 讲师因此碰到一大堆输出。 现成工具： bcc 用 C 写 eBPF 程序，附带很多工具（ ）。比如 biolatency ，它画磁盘请求耗时的直方图。视频里 2 次落在 4–8 μs，1 次落在 2–4 μs。还有 opensnoop ，看谁打开了哪个文件。 下面的演示是示意，本机没有 Linux。系统调用在内核里被就地计数，Ctrl-C 时才打印。再看过滤条件和 -c 、 cpid 怎样缩小范围。 为什么会在这里踩坑 第一次跑 bpftrace，满屏都是别的进程。它默认看的是整个系统，不是你那个程序。要加 /comm == \"bash\"/ 或 /pid == cpid/ 这类过滤。另外它必须 root，忘了 sudo 就跑不起来。"}, {"u": "ch04.html#s7", "c": "第 4 讲 · 调试与性能分析", "t": "网络问题看包：tcpdump 抓，Wireshark 拆", "x": "tcpdump 把经过网卡的每个包都打印出来。Wireshark 能看懂 IP 之上的协议。HTTPS 加了密，要靠 mitmproxy 或浏览器开发者工具。 bash · 讲义原文（注释译成中文） sudo tcpdump -i any port 80 # 抓 80 端口的包 sudo tcpdump -i any -w capture.pcap # 存成文件，交给 Wireshark 分析 打个比方 tcpdump 像邮局门口的监控。每个信封的寄件人、收件人和厚度，它都看得到。信要是 HTTPS 封死的，它就只能看信封。mitmproxy 相当于先拆开抄一份，再封好寄出去。 tcpdump 打印经过网卡的每个包。内容有源和目的 IP、端口、TCP 标志、窗口和长度。需要时连包的内容也能打。 视频里讲师用 curl http://neverssl.com 制造流量（ ）。一个简短的 HTTP 请求和响应，就产生了好几个包。 -i 选网卡，讲师的 Wi-Fi 叫 wlp2s0。 any 表示所有网卡。 Wireshark 能理解 IP 之上的协议（ ）。比如有插件专门解析 MySQL 流量。还能录下来，离线重放和测试。 HTTPS 是加密的，tcpdump 只能看到密文。 mitmproxy 冒充服务器做中间人，解密后再记录。 调网页的 HTTPS 请求，往往用浏览器开发者工具最方便。看它的 Network 面板。解密后的请求、响应、头部和耗时都能看到（讲义）。 为什么会在这里踩坑 抓了半天，只看到一堆乱码。因为请求走的是 HTTPS，tcpdump 只能看到密文。调网页请求，先开浏览器开发者工具的 Network 面板。另外 tcpdump 要 sudo。 -i 选错了网卡，就什么也抓不到。"}, {"u": "ch04.html#s8", "c": "第 4 讲 · 调试与性能分析", "t": "内存 bug 不一定崩溃，要靠 sanitizer 揪出来", "x": "越界写、释放后再用这类 bug，往往不会马上崩溃。它们悄悄写坏别处的内存，很久以后才出事。sanitizer 让编译器在每次内存访问前插一道检查。 c · 最小例子（示意） char *p = malloc(32); free(p); p[0] = 'J'; // 写已释放的内存。不开检查，程序通常照常运行 // gcc -fsanitize=address -g uaf.c 重新编译，这一行当场报错 打个比方 ASan 像给每块内存配了个门卫。门卫手里有张名单，写着哪些格子能进。free 之后，这块就从名单上划掉。谁再来碰，当场拦下。 缓冲区溢出、use-after-free 和内存泄漏，是最难查的一类 bug。视频里有个 heap overflow 的例子。程序往缓冲区里塞了超长数据，却照常结束（ ）。看上去什么都没发生。那只是因为被覆盖的那块内存，恰好没人再用。 Sanitizer 是编译器的扩展。它让编译器在程序里插入额外的检查指令。最常用的是 AddressSanitizer（ASan） 。它能查出栈、堆和全局缓冲区的溢出。还能查 use-after-free、use-after-return 和内存泄漏。 bash · 讲义原文 gcc -fsanitize=address -g program.c -o program ./program 加上 -fsanitize=address 后，同一个 heap overflow 程序直接崩溃（ ）。ASan 还给出一份报告。报告里有错误类型和地址，还有出错时的调用链。视频里那条链上是 memcpy。另外还写明这块内存在哪分配，哪些字节被覆盖了。 其他 sanitizer（讲义） 检测什么 ThreadSanitizer（TSan， -fsanitize=thread ） 多线程的数据竞争 MemorySanitizer（MSan， -fsanitize=memory ） 读未初始化的内存 UndefinedBehaviorSanitizer（UBSan， -fsanitize=undefined ） 未定义行为，比如整数溢出 sanitizer 要重新编译，但跑得足够快。可以放进 CI 和日常开发（ ）。Java、Python 这类有运行时的语言，很多检查由运行时完成。这些检查有时默认关着，因为太贵。ASan 在这些语言里用不上。但它们的 unsafe 操作，同样可能出这类问题。 本机实测：MinGW 没有 ASan 运行时，但编译器能提前警告 讲义调试练习 3 的 uaf.c，本机不加检查直接运行。结果确实“看起来正常”。加 -fsanitize=address 就链接失败，因为 MinGW-w64 的 gcc 缺 libasan。不过 gcc 的 -Wall 在 编译期 就发现了问题： bash · 本机实测（gcc 13.2 MinGW-w64） $ gcc uaf.c -o uaf && ./uaf Hello, world! Jello, world! $ gcc -fsanitize=address -g uaf.c -o uaf_asan <mingw64>/…/ld.exe: cannot find -lasan: No such file or directory $ gcc -Wall -g uaf.c -o uaf uaf.c:12:17: warning: pointer 'greeting' used after 'free' [-Wuse-after-free] 编译期警告只能抓住编译器“看得出”的情况。ASan 在运行期检查每一次访问，能抓住复杂得多的场景。完整对照见练习页 调试 3 。 ASan 为什么能在运行时抓住这种 bug？下面的演示画出它的“影子内存”： 为什么会在这里踩坑 程序没崩，输出也对，就以为没有内存 bug。use-after-free 那一下写入，通常会“成功”。上面实测就打印出了 Jello。可它也许已经悄悄改坏了别处的数据。写 C 和 C++，平时就开着 -Wall ，测试时再开 ASan。 不能重编译就用 Valgrind，代价是慢 Valgrind 不改你的程序。它自己假装成 CPU，一条条解释执行。所以能检查每一次内存访问，但慢得多。 Valgrind 是一个可扩展的 程序解释器 。它逐条执行你程序的指令，在每条指令前后做额外检查。不用重新编译，就能查每一次内存访问。它能指出哪条指令写了不该写的内存。还能指出这块内存是哪条指令分配的。 bash · 讲义原文 valgrind --leak-check=full ./my_program 适用场景有这几种（讲义）。没有源码，或者没法重新编译，比如第三方库。或者你需要 sanitizer 没有的检查。Valgrind 也是强大的 profiler，见 第 13 节 。"}, {"u": "ch04.html#s9", "c": "第 4 讲 · 调试与性能分析", "t": "LLM 擅长解释报错和定位，不擅长修", "x": "看不懂的报错和几十层的调用栈，可以交给 LLM 翻成人话。它给的修法，一定要自己用调试工具验证。 borrow.rs 的核心三行（注释是笔记加的。完整实测见练习页调试 5） let first = &scores[0]; // 不可变借用，一直活到最后一行 scores.push(100); // 要可变借用，和上一行冲突，报 E0502 println!(\"first = {}\", first); // 问 LLM 时，整段代码和完整报错一起贴 打个比方 LLM 像见过无数病例的老护士。你一说症状，她马上能猜出几种可能。但开不开刀，还得拍片子确认。 讲师与讲义的建议 解释难懂的报错 （ ）。C++ 模板错误和 Rust 借用检查器的报错，往往很晦涩。别人多半遇到过几乎一样的报错。可地址、程序名略有不同，很难搜到。LLM 很擅长把它翻成人话，还能给出绕过办法。 跨语言、跨抽象层 （ ）。比如 Python 程序链接了 Rust 库，Rust 又调用了 C 库。讲师的经验是，LLM 会自己写小的复现程序。它从 Python 一路追到 Rust，再追到 C。最后指出“C 代码这里看起来不对”。它不太擅长 修 这种 bug，但很擅长 找 。 由症状猜原因 ：比如“程序能跑，但内存多用了 10 倍”。LLM 能列出可能的原因，以及该查什么（讲义）。 读长长的调用栈 （ ）。崩溃栈动不动几十上百层。在陌生代码库里，重点尤其难找。 局限 （讲义）：它可能编出听着合理、实际错误的解释。也可能给出掩盖 bug 而不是修复 bug 的改法。一定要用真正的调试工具验证。它是理解代码的补充，不是替代。 讲义提示：调试符号 想得到有意义的调用栈，就要带调试符号。二进制文件和它链接的库都要带。也就是加 -g ，通常是 DWARF 格式。编译时再加 -fno-omit-frame-pointer 保留帧指针，profiler 的调用栈会更可靠。否则调用栈里可能只有内存地址，或者残缺不全。C++、Rust 这类原生程序尤其要注意。 练习页 调试 5 在本机生成了两条真实的难懂报错。一条是 Rust E0502，一条是 26 行的 C++ 模板错误。页面还给了向 LLM 提问的模板和核对方法。 为什么会在这里踩坑 LLM 给的改法，常常只是让报错消失。比如 Rust 里到处加 clone() ，C++ 里强制类型转换。编译是过了，程序的意思却变了。所以改完要重新编译、重新跑测试。再对照编译器自己的说明，比如 rustc --explain E0502 。"}, {"u": "ch04.html#s10", "c": "第 4 讲 · 调试与性能分析", "t": "优化之前先测量，别凭感觉找热点", "x": "算法课教大 O，却不教怎么找程序里的热点。凭感觉优化，很容易改错地方。先用工具测出时间花在哪，再动手。 bash · 写法示意 time ./slow # 第一步：总共花了多久，CPU 忙还是在等 python -m cProfile -s tottime slow.py | head # 第二步：时间花在哪个函数上 # 最后才改代码。改完再测一遍，确认真的变快了 打个比方 看病先拍片，再开刀。不拍片就动刀，切掉的多半不是病灶。 代码功能对了还不够，吃光 CPU 或内存也不行。“过早优化是万恶之源”（讲义）。先用 profiler 和监控工具，弄清时间和资源花在哪。再集中优化那一部分。讲师说，性能分析和调试密切相关。弄明白代码在做什么，通常也就明白它表现如何。 real 远大于 user 加 sys，说明程序在等 time 报三个数。real 是墙上的钟走了多久。user 和 sys 是 CPU 真正干活的时间。差出来的那部分，程序在等网络、磁盘或别的东西。 最简单的办法就是计时。 time 几乎每个 shell 都有，放在任何命令前面就行： bash · 讲义原文 $ time curl https://missing.csail.mit.edu &> /dev/null real 0m0.272s user 0m0.079s sys 0m0.028s 含义 上例 real 墙钟时间：从开始到结束，包括等待 0.272 s user CPU 执行用户代码的时间 0.079 s sys CPU 在内核里替这个程序干活的时间 0.028 s CPU 一共只用了 107 ms，剩下 165 ms 在等网络。反过来， 多核程序的 user 可以大于 real （ ）。10 个 CPU 各忙 1 秒，real 是 1 秒，CPU 时间却是 10 秒。另外，同一条命令多跑几次，耗时会变（ ）。视频里是 124 ms、138 ms 这样跳。所以只跑一次 time 来比较两个程序，并不可靠。 bash · 本机实测（Git Bash） $ time bash -c 'i=0; while [ $i -lt 200000 ]; do i=$((i+1)); done' real 0m3.130s user 0m2.406s sys 0m0.296s $ time sleep 1 real 0m1.248s user 0m0.015s sys 0m0.046s 为什么会在这里踩坑：time 看不到原生程序的 CPU 对 MSYS 自己的程序，比如 bash 和 sleep，Git Bash 的 time 是准的。原生 Windows 程序就不行了，比如 python 和 gcc 编出的 exe。它们的 user 和 sys 几乎总是 0.015 s： bash · 本机实测 $ time python -c 'sum(range(3 * 10**7))' real 0m0.735s user 0m0.015s sys 0m0.031s $ python -c 'import time; t = time.process_time(); sum(range(3 * 10**7)); print(\"cpu seen by python itself:\", round(time.process_time() - t, 2), \"s\")' cpu seen by python itself: 0.47 s 在这台机器上只信 real。CPU 时间请在程序内部测，或者换 Linux。"}, {"u": "ch04.html#s11", "c": "第 4 讲 · 调试与性能分析", "t": "只跑一次不算数：多跑、预热、看波动", "x": "同一条命令每次耗时都不一样。基准测试要预热，要跑很多次，再看均值和标准差。比较两个程序时，倍数也要带上误差。 bash · 本机实测（Git Bash，TIMEFORMAT=%R 只打印 real） $ TIMEFORMAT=%R; for k in 1 2 3; do time ls -R /usr/share > /dev/null; done 1.483 # 第一次最慢，多半是文件还没进磁盘缓存 0.261 0.181 # 同一条命令，后两次快了好几倍 打个比方 量体重别只称一次。刚吃完饭和早上空腹，差一两斤很正常。多称几次取平均，再看看上下浮动多大。 hyperfine 把每条命令跑很多次。它统计均值和标准差。最后给出“快几倍、误差多少”的结论： bash · 讲义原文 $ hyperfine --warmup 3 'fd -e jpg' 'find . -iname \"*.jpg\"' Benchmark #1: fd -e jpg Time (mean ± σ): 51.4 ms ± 2.9 ms [User: 121.0 ms, System: 160.5 ms] Range (min … max): 44.2 ms … 60.1 ms 56 runs Benchmark #2: find . -iname \"*.jpg\" Time (mean ± σ): 1.126 s ± 0.101 s [User: 141.1 ms, System: 956.1 ms] Range (min … max): 0.975 s … 1.287 s 10 runs Summary 'fd -e jpg' ran 21.89 ± 2.33 times faster than 'find . -iname \"*.jpg\"' --warmup 3 ：先跑 3 次不计时。让文件进入磁盘缓存，避免第一次冷启动拉高结果。 视频里的现场结果正好相反（ ）。find 比 fd 快了约 40 倍。讲师是在一个几乎空的目录里测的。那不是 fd 优化的场景。可见基准测试的结论，和 测试条件 绑在一起。 网页开发：浏览器开发者工具自带很好的 profiler。见 Firefox Profiler 和 Chrome DevTools 的文档（讲义）。 本机没有 hyperfine。练习页 性能 3 写了个不到 50 行的 Python 脚本。它按同样的方法，比较了 grep -r 和 git grep。还手推了“± 0.60”是怎么来的： 为什么会在这里踩坑 改完代码跑一次 time，快了 20%，就宣布优化成功。可同一条命令连跑三次，上面实测就差了好几倍。至少多跑几次，看均值和波动。两组数据的波动范围要是重叠，这 20% 可能只是噪声。"}, {"u": "ch04.html#s12", "c": "第 4 讲 · 调试与性能分析", "t": "程序慢，先看是哪种资源被吃满了", "x": "先看大盘，再看细节。CPU 是全满，还是只满一个核？内存够不够？磁盘和网络在不在排队？ bash · 写法示意（Linux） htop # 每个核一根条，别只看总数 free -h # 总内存和已用内存 ss -tlnp | grep :8080 # 谁占着 8080 端口 lsof /var/log/app.log # 谁开着这个文件 打个比方 程序慢像高速堵车。先看是堵在收费站，还是堵在匝道。收费站是 CPU，匝道是磁盘和网络。找对地方，才知道该修哪儿。 程序慢，先看它是不是 资源受限 。是用满了所有核，还是只用了一个核？还是磁盘太慢？ 工具 看什么（讲义，视频 58:33–1:01:21） htop 每个核的利用率、内存、负载和进程列表。 F6 排序， t 树状显示， H 显示或隐藏线程。小写 h 是帮助，这条按 htop 手册写（补充）。还有 I/O 等标签页 btop 比 htop 监控的东西多得多，可以配置 iotop 实时 I/O 使用 free 总内存和已用内存 lsof 进程打开了哪些文件。可以查谁占着某个文件 ss 网络连接。常用 ss -tlnp | grep :8080 找出谁占着端口 nethogs 、 iftop 每个进程的网络用量 负载（load average）是什么（视频 59:06） htop 右上角有三个数。它们是过去一段时间里，平均“需要多少个 CPU 核”。三个数对应越来越长的时间窗口。讲师建议你自己查一下确切含义。补充：Linux 上通常是 1、5、15 分钟的指数平均。等待磁盘 I/O 的进程也算在内，见 man proc 的 loadavg 一节。 练习页 性能 4 在本机用 Windows 的 start /affinity 复现了 taskset 题。 性能 5 用 netstat 找出并结束了占端口的进程。 为什么会在这里踩坑 看到某个进程 CPU 占用 100%，就以为它用满了机器。其实它可能只占满了一个核，其余的核都闲着。htop 里要看每个核的条，不能只看总数。反过来，CPU 很闲程序却很慢，就该去看磁盘和网络。"}, {"u": "ch04.html#s13", "c": "第 4 讲 · 调试与性能分析", "t": "perf 采样找热点，火焰图一眼看出时间去哪", "x": "采样型 profiler 每隔约 1 毫秒拍一下调用栈。被拍到次数多的函数，就是热点。火焰图把这些栈画出来，越宽越热。 bash · 写法示意（Linux，本机未实测） gcc -g -O2 slow.c -o slow -lm # -g 留下函数名，不然报告里全是地址 perf record -g ./slow # 采样，-g 连调用栈一起记 perf report # Self 只算函数自身，Children 连带它调用的 打个比方 采样像老师隔几分钟抬头扫一眼教室。扫一百次，有八十次看到小明在玩手机。那他大部分时间都在玩。追踪型 profiler 像给每个人都装了计时器。数字准，但人人都被拖慢。 真要让程序变快，就得知道程序 内部 哪里最热。CPU profiler 有两类（讲义）： 追踪型（tracing） 记录程序的每一次函数调用。数字精确，但开销大。例子有 Valgrind 的 callgrind、Python 的 cProfile。 采样型（sampling） 定期暂停程序，记下调用栈，常见是每毫秒一次。开销小，结果是统计近似。生产环境一般用它。例子有 perf、py-spy。 perf 是 Linux 的标准 profiler。不用重新编译，就能分析任何程序。 perf stat 给出总览： bash · 讲义原文 $ perf stat ./slow_program Performance counter stats for './slow_program': 3,210.45 msec task-clock # 0.998 CPUs utilized 12 context-switches # 3.738 /sec 0 cpu-migrations # 0.000 /sec 156 page-faults # 48.587 /sec 12,345,678,901 cycles # 3.845 GHz 9,876,543,210 instructions # 0.80 insn per cycle 1,234,567,890 branches # 384.532 M/sec 12,345,678 branch-misses # 1.00% of all branches 视频里，讲师对讲义的 slow.c 采样（ ）。命令是 perf record -g ./slow ，再 perf report 。 Children 列算的是这个函数，加上它调用的所有函数。所以 _start 是 100%。 Self 列只算函数自身，cos 43.6%，sin 43.2%。在 report 里按 h 看帮助。还能把热点标到汇编和源码行上（ ）。 火焰图：越宽越耗时，横轴不是时间顺序 火焰图的纵轴是调用层级。底部是程序入口，越往上调用越深。横轴宽度正比于花在那里的时间。 一大堆数字，人很难读。 火焰图 （flame graph）把它变成了图。讲师用的是 flamegraph 的 Rust 移植版 inferno。在浏览器里打开 SVG，还能点击放大（ ）。 bash · 讲义原文 perf record -g ./my_program perf script | stackcollapse-perf.pl | flamegraph.pl > flamegraph.svg 讲义推荐 交互式查看用 Speedscope 。系统级分析用 Perfetto 。各语言也有专用工具。Python 有 cProfile 和 py-spy ，Go 有 go tool pprof 。Rust 有 cargo-flamegraph ，其实对任何编译型程序都能用。 采样会漏，要精确计数就用 callgrind 采样只看得到被拍到的瞬间。频率调高更准，但暂停越多，程序被拖得越慢。要精确数据，就用 Valgrind 的 callgrind（讲师）。 它解释执行每一条指令，所以能精确计数，但很慢。 bash · 讲义原文（注释译成中文） valgrind --tool=callgrind ./my_program callgrind_annotate callgrind.out.<pid> # 文本报告 kcachegrind callgrind.out.<pid> # 图形界面 callgrind 给出精确的调用次数，还有谁调用了谁。加 --cache-sim=yes 还能模拟缓存行为（讲义）。 本机实测：没有 perf，用 Python 版对照两类 profiler slow.c 在本机编译运行，用了约 11–18 秒。几次运行差异较大。perf 跑不了，于是把它翻成 Python 版 slow.py。再分别用追踪型的 cProfile 和自己写的 40 行采样器分析： bash · 本机实测（节选） $ python -m cProfile -s tottime slow.py | head -12 2000095 function calls in 0.736 seconds ncalls tottime percall cumtime percall filename:lineno(function) 10 0.399 0.040 0.735 0.073 slow.py:4(slow_computation) 1000000 0.170 0.000 0.170 0.000 {built-in method math.sin} 1000000 0.165 0.000 0.165 0.000 {built-in method math.cos} $ python sampler.py slow.py --- 130 samples, folded stacks (stack count share) --- <module>;main;slow_computation:8 129 99.2% <module>;main;slow_computation:7 1 0.8% cProfile 让程序慢了 2.6 倍，从 0.40 s 变成 1.05 s。换来的是精确的调用次数。采样器几乎不拖慢程序。但它只看得到 Python 帧，分不出 sin 和 cos。详见练习页 性能 2 。 下面的演示分两幕。第 1 幕画出采样、合并计数、画火焰图的过程。数字按视频里的 perf report 折算。第 2 幕是上面这组本机实测的对照。 为什么会在这里踩坑 火焰图里某个块很宽，就以为它被调用了很多次。宽度只说明它占的时间多。可能是调用多，也可能是单次就很慢。要精确的次数，得用 callgrind 或 cProfile 这类追踪型工具。另外，没带 -g 或省掉了帧指针，调用栈就会残缺。火焰图上只剩一堆地址。"}, {"u": "ch04.html#s14", "c": "第 4 讲 · 调试与性能分析", "t": "内存只涨不跌，就用内存 profiler 看谁在涨", "x": "内存 profiler 记录堆内存随时间的变化。泄漏和过度分配，都能从曲线里看出来。 mem.py · 本机实测（补充，非视频内容。注释是后加的） import tracemalloc tracemalloc.start() # 从这里开始给内存记账 a = [0] * 1_000_000 # 一百万个元素的列表 cur, peak = tracemalloc.get_traced_memory() # 当前用量和峰值，单位是字节 print(cur // 1024, \"KiB\") # 本机输出 7812 KiB，每个元素存一个 8 字节指针 打个比方 内存 profiler 像记账本。每笔开销都记下是哪一行花的。月底一对比，就知道钱从哪儿漏出去了。 视频只顺带提了一句（ ）。Valgrind 有多种“工具模式”。比如检查内存用得对不对，或者统计指令次数。讲义补充了专门的内存 profiler： bash · 讲义原文 valgrind --tool=massif ./my_program ms_print massif.out.<pid> Massif 记录堆内存随时间的使用情况。它能帮你发现内存泄漏和过度分配。Python 可以用 memory-profiler 逐行查看内存用量。 补充（非视频内容）：Python 标准库的 tracemalloc 不装第三方包也行。 tracemalloc.start() 之后，用 tracemalloc.take_snapshot().statistics('lineno') 按源码行统计当前分配的内存。两次快照相减，还能看出哪一行在涨。见 官方文档 。上面的最小例子用的就是它。 为什么会在这里踩坑（补充，非视频内容） 内存涨了，不一定是泄漏。缓存、预分配、列表扩容，都会让内存先涨一截。要看的是曲线。跑得越久涨得越多，而且从不回落，才像泄漏。只看某一刻的总量，很容易冤枉好代码。"}, {"u": "ch04.html#s15", "c": "第 4 讲 · 调试与性能分析", "t": "性能数据要画成图，表格看不出规律", "x": "性能分析不只是找哪里慢。还要看耗时怎样随输入变化。几千行的数字表看不出规律，一张图就看出来了。 bash · 写法示意 echo \"$(date +%s),$ms\" >> latency.csv # 打日志时就写成“时间戳,数值” gnuplot -e \"set datafile separator ','; plot 'latency.csv' using 1:2 with lines\" # 一行出图 打个比方 体检报告上一排数字，很难看出趋势。把十年的体重画成一条线，哪年突然胖了，一眼就看到。 讲师举了个例子。比如一个像 grep 的搜索程序。你想知道它的耗时怎样随输入变化。变量有输入大小、模式长度和模式复杂度。一张大表格记满了输入多大、模式多长、用了多少微秒。这种表没什么用，要 画出来 （ ）。 bash · 讲义原文（注释译成中文） # 画一个 “时间戳,数值” 的 CSV gnuplot -e \"set datafile separator ','; plot 'latency.csv' using 1:2 with lines\" 让数据好画 （讲义）。打印或记日志时，就用 CSV 或 JSON 这种整洁格式。比如 1705012345,42.5 。这比一句话好处理得多。 gnuplot 为 shell 而生。它和 bpftrace 一样，用 -e 传一段小程序。适合快速出图（ ）。 matplotlib 和 ggplot2 适合反复切分、变换数据，验证猜想。讲师最喜欢 ggplot2 的 facet ，也就是分面（ ）。它按某一列把数据拆成一组并排的小图。再用颜色、行列编码更多维度，一次看清五维数据。 讲义里的例子 画出请求延迟随时间的曲线。百分位数看不出的周期性变慢，曲线上一目了然。比如垃圾回收、定时任务、流量模式。 往一个不断增长的数据结构里插元素，画出耗时。底层数组 容量翻倍 时，会出现特征尖峰。 按维度分面，比如请求类型、用户群、服务器。常常发现“全系统问题”其实只出在某一类上。 为什么会在这里踩坑 只看平均延迟，一切正常。可每隔一分钟就有一次尖峰，平均值把它抹平了。用户偏偏就撞上了那一下。所以别只盯一个汇总数，把原始数据按时间画出来看看。"}, {"u": "ch04.html#s16", "c": "第 4 讲 · 调试与性能分析", "t": "以后要分析的数，现在就记进日志", "x": "讲师的结束语把首尾连了起来。以后想分析的数据，现在就用结构化的形式记进日志。真需要时，直接解析、画图。 python · 写法示意 log.info(json.dumps({\"event\": \"search\", \"input_bytes\": n, # 输入多大 \"pattern_len\": len(p), # 模式多长 \"us\": elapsed})) # 用了多少微秒。以后直接拿去画图 打个比方 像搬家前就给每个箱子贴好标签。现在多花一分钟，以后找东西就不用把箱子全拆开。 讲师说，你要是知道以后会做性能分析，就别等。早点把相关的数 记进日志 。比如输入多大、函数用了多久、内部的图有多大。尽量用结构化的形式。等到真需要时，信息已经在日志里了。直接解析、画图，就能看出潜在问题。比如“扩展性悬崖”。 为什么会在这里踩坑 日志只写一句话，比如 “search took a while”。出了性能问题想回头分析。这才发现没记输入大小，也没记耗时。只能补上日志，再等问题重现一次。"}, {"u": "ch04.html#s17", "c": "第 4 讲 · 调试与性能分析", "t": "一页带走：本讲结论都在这几行里", "x": "把本讲浓缩成几行命令。每行的注释就是结论和考点。 bash · 本讲速查（注释即考点） logging.basicConfig(level=logging.INFO) # 日志按级别过滤。配置放在最前面，不然会被忽略 b merge, len(left) == 2 # pdb 条件断点用逗号，gdb 用 if # 为什么要条件断点：前两次合并 i 等于 j，bug 不显现 watch students[1].id # 观察点：值一变就停，回答“谁改了它” rr record ./prog; rr replay # 录一次，随便倒着放。只支持 Linux (rr) reverse-continue # 倒放命中观察点时，New value 才是更早的值 strace -f ./prog 2>&1 | less # -f 跟子进程。追踪写在 stderr，要先 2>&1 gcc -fsanitize=address -g prog.c # ASan：运行时抓越界和 use-after-free time ./prog # real 2.0 s，user 0.1 s：在等，加 CPU 没用 strace -T ./prog # 接着查它在等什么：看哪个系统调用耗时长 hyperfine --warmup 3 'a' 'b' # 快 1.8 ± 0.6 倍：误差太大，别急着下结论 perf record -g ./prog; perf report # 采样找热点。Self 算自身，Children 连带子调用 # 火焰图的宽度是时间占比，不是调用次数。要次数就用 callgrind 或 cProfile print 调试仍然最常用。修好 bug 后，把 print 改成带级别的日志留下。结构化日志方便事后提取和画图。 调试器能设断点，断点可以带条件。还能单步、看变量、看调用栈、设观察点。gdb 和 lldb 通用，pdb 这类是语言专用。 rr 录一次就能确定性回放，还能 倒着执行 。配合观察点，直接找到谁改了它。它只支持 Linux，还要小心 Heisenbug。 strace 看程序和内核的边界。要统计用 bpftrace，查网络用 tcpdump、Wireshark 和 mitmproxy。 内存 bug 用 sanitizer，要重新编译但够快。Valgrind 不用重新编译，但很慢。 性能先测量。time 分清 real、user、sys。基准测试多跑几次，看均值和 σ。perf 加火焰图找热点，callgrind 求精确。最后把数据画出来。 在整门课里的位置 · 下一步 前三讲给了你 shell、命令行环境和编辑器。这一讲教你在程序不听话或太慢时，怎么看清它。下一讲是版本控制与 Git，会讲到 git bisect 。它在历史里二分查找引入 bug 的那次提交。这又是一种调试手段。现在去做 本讲练习的可视化笔记 。"}, {"u": "ch05.html", "c": "第 5 讲 · 版本控制与 Git", "t": "开头", "x": "本讲结论 Git 仓库里只有两样东西。一是 对象 ：blob、tree 和 commit。它们按内容的 SHA-1 命名，写进去就不再改。二是 引用 ：分支和 HEAD 这些能移动的名字。每条 git 命令，都只是在添加对象、移动引用。想清楚它对提交图做了什么，命令就不再是咒语。"}, {"u": "ch05.html#s1", "c": "第 5 讲 · 版本控制与 Git", "t": "Git 存的是快照，还能自动帮你找 bug", "x": "版本控制系统把目录在每个时刻的样子存成快照。每个快照都是整个目录，外加谁做的、为什么做。 bash · 写法示意 git log --oneline -3 # 最近 3 个快照，一行一个 git blame main.py # 每一行最后是谁、哪次提交改的 git bisect start HEAD v1.0 # 先说好坏：HEAD 是坏的，v1.0 是好的 git bisect run ./test.sh # 自动二分：脚本失败就算坏，几步就揪出元凶 打个比方 版本控制像游戏存档。每次存档存的是整个世界，不是比上次多走几步。想回到哪一档，直接读档。 一个人用 能看旧版本，能记下为什么这么改。还能在并行的分支上开发。比如功能 1 写到一半，先切去修 bug。两边的改动互不干扰（ ）。 多人协作 能看别人改了什么，能解决并行开发的冲突。没有版本控制，就只能来回发 zip 包。很快就乱成一团（ ）。 讲义还列了几个问题，现代 VCS 都能轻松回答。这个模块是谁写的？这一行是谁、什么时候、为什么改的？过去 1000 个版本里，某个单元测试是从哪次开始挂的？ 最后一个问题，Git 能 自动二分查找 来回答（ ）。你写一个测试，有 bug 就失败。Git 会帮你定位引入 bug 的那次提交。演示见 第 19 节 。Git 是当今事实上的标准。 为什么会在这里踩坑 很多人把 Git 当成网盘，只会 add、commit、push 三板斧。出了问题不知道 Git 存了什么，就只能删库重来。其实每个快照都完整存着。提交过的东西，多半找得回来。"}, {"u": "ch05.html#s2", "c": "第 5 讲 · 版本控制与 Git", "t": "命令只能死记，数据模型可以理解", "x": "Git 的命令行界面很乱，硬背只能当咒语。但底层数据模型很简单。理解了它，命令自然就通了。 bash · 写法示意 # 自顶向下：背咒语，出错了只能删库重来 git pull; git add .; git commit -m \"fix\"; git push # 自底向上：每条命令都问一句，它对提交图做了什么 git commit # 新增一个 commit 对象，再把当前分支挪过去 git branch x # 不新增任何对象，只是多了一个名字 打个比方 背命令像背地铁换乘口诀，线路一改就懵。看懂线路图，怎么换乘自己就能推出来。 讲义引了 xkcd 1597 。漫画里说，Git 用优美的分布式图论树模型跟踪协作。怎么用？没人知道，背下几条命令就行。出了错，就把工作存到别处，删掉项目，重新下一份。讲师问现场谁这么干过，不少人举手，包括他自己。 原因是 Git 的命令行是一个 有漏洞的抽象 （leaky abstraction）。从命令学起，就只能把命令当咒语背。可 Git 底层的设计很漂亮。 丑陋的界面只能死记，漂亮的设计可以理解。 所以这一讲先讲数据模型，再讲命令。每条命令都对应回数据模型（ ）。 为什么会在这里踩坑 平时用 Git 出错，多半是不知道命令改了哪里。比如以为 git branch -d 删了提交，其实只删了名字。先想数据模型，这类误会就少了。"}, {"u": "ch05.html#s3", "c": "第 5 讲 · 版本控制与 Git", "t": "文件是 blob，目录是 tree，快照是顶层 tree", "x": "Git 只用两种东西描述目录。文件叫 blob，就是一串字节。目录叫 tree，把名字映射到 blob 或别的 tree。 bash · 本机实测（练习页 ex01-b 与 ex01-a，节选） $ git cat-file -p HEAD:foo # 子目录 foo 也是一个 tree，里面记着 bar.txt 100644 blob 3b18e512dba79e4c8300dd08aeb37f8e728b8dad bar.txt $ git cat-file -t 4448adbf # baz.txt 的内容是一个 blob blob 打个比方 tree 像一本书的目录页，只写“哪个标题在哪一页”。blob 是那一页的正文。目录页本身不装正文，只记页码。 快照就是被跟踪的那个顶层 tree。目录可以一层套一层，所以 tree 也能嵌套。 讲义里的例子。视频 6:57 讲师在黑板上画的是同一棵树 为什么会在这里踩坑（补充，非视频内容） blob 里只有内容， 没有文件名 。名字记在上一层的 tree 里。所以 Git 并不记录“改名”这个动作。改名之后，对新名字 git log ，历史会停在改名那次。加上 --follow ，Git 才会按内容相似度往前追。"}, {"u": "ch05.html#s4", "c": "第 5 讲 · 版本控制与 Git", "t": "历史是一张图：每个提交记着自己的 parent", "x": "Git 的历史不是一条线，而是一张有向无环图。每个提交记着一组 parent。合并出来的提交有两个 parent。 bash · 本机实测（练习页 ex01-e，节选） $ git cat-file -p HEAD | head -4 # HEAD 是一次合并提交，所以有两行 parent tree b6fe6fe890c2f61255f8c330c28aa2dfd93c302e parent 352b132d8e0501612e1848b6836d29f15d3b341f parent c560925a653e009456e6427c402986e7ef0b1998 author Ada Example <ada@example.com> 1768557600 +0000 打个比方 提交图像家谱。每个人只记自己的父母是谁。合并提交就是有两个父母的孩子。往上一直追，就是整条血统。 快照之间怎么连？最简单的是一条线：版本 1、2、3 排成一列。Git 不这么做。每个快照记着它的一组 parent ，也就是之前的快照。说“一组”，是因为合并时会有两条线汇到一起。Git 把这种快照叫做 commit （提交）。 讲义原文（箭头指向 parent，意思是“在它之前”） o <-- o <-- o <-- o <---- o ^ / \\ v --- o <-- o 第三个提交之后，历史分成了两支。比如两个功能在并行开发。最后两支被 合并 成一个新提交，就是加粗的那个。它同时包含两边的改动，有两个 parent（ ）。上面实测里那两行 parent，说的就是这件事。 提交是不可变的（视频 10:27） 现实中没法回到过去改历史，Git 也一样。历史只能 追加 ，不能修改。错误照样能纠正。所谓“修改历史”，其实是新建一批提交。再把引用（见 第 7 节 ）指到新的那批上。 为什么会在这里踩坑 git log 默认把这张图拉平成一列显示。分叉和合并都看不出来，容易以为历史是一条线。想看图的形状，加上 --graph 。"}, {"u": "ch05.html#s5", "c": "第 5 讲 · 版本控制与 Git", "t": "commit 就是 parent、作者、说明加一个 tree", "x": "整个数据模型几行类型定义就能写完。blob 是字节数组，tree 是名字到对象的映射。commit 是一个结构体。 bash · 本机实测（练习页 ex01-c） $ git cat-file -p HEAD # 一个真实的 commit 对象，对照下面的伪代码看 tree 12330f8cfe317d61bbf9690538896975910e22f2 parent a9254971ec6ef8d6423964549097af7233cda0ac author Ada Example <ada@example.com> 1768557600 +0000 committer Ada Example <ada@example.com> 1768557600 +0000 exclaim 打个比方 commit 像一张快递单。单上写着寄件人、备注和上一单的单号。箱子里装着整个目录，也就是 tree。 讲义原文（注释译成中文） // 文件就是一堆字节 type blob = array<byte> // 目录：名字 → 文件或目录 type tree = map<string, tree | blob> // 提交：父提交、元数据、顶层 tree type commit = struct { parents: array<commit> author: string message: string snapshot: tree } 对照实测看。第一行 tree 就是伪代码里的 snapshot。parent 对应 parents，最后一行是 message。真实的 commit 比伪代码多一行 committer。第一个提交没有 parent 行，见练习页 ex01-b。 讲师强调了几个词（ ）。blob 和 tree 是这个递归结构里的元素。“快照”不完全是 Git 的标准术语。它指被跟踪目录对应的顶层 tree。commit 是历史图里的节点。它也是递归的，因为它会引用别的 commit。 为什么会在这里踩坑 伪代码里 parents 是 commit 本身，好像提交里装着父提交。真实存储里只放父提交的哈希，见下一节。所以父提交一变，子提交的哈希就得跟着重算。"}, {"u": "ch05.html#s6", "c": "第 5 讲 · 版本控制与 Git", "t": "对象按内容的 SHA-1 命名，引用别人只记哈希", "x": "blob、tree、commit 统称对象。Git 用对象内容的 SHA-1 当键，存进对象库。这叫内容寻址：内容一样，ID 就一样。 bash · 本机实测（Git 2.55，哈希和讲义原文相同） $ git cat-file -p HEAD^{tree} # tree 里不装子对象，只记它们的哈希 100644 blob 4448adbf7ecd394f42ae135bbeed9676e894af85 baz.txt 040000 tree c68d233a33c5c06e0340e4c224f0afca87c8ce87 foo $ git cat-file -p 4448adbf # 拿哈希前缀就能取回内容 git is wonderful $ printf 'blob 17\\0git is wonderful\\n' | sha1sum # 手算一遍，结果一样 4448adbf7ecd394f42ae135bbeed9676e894af85 *- 打个比方 内容寻址像按指纹建档。同一个人永远是同一个指纹。档案柜按指纹编号，不按名字。别的档案提到他，只写指纹号。 讲义用几行伪代码写出了对象库： 讲义原文 type object = blob | tree | commit objects = map<string, object> def store(object): id = sha1(object) objects[id] = object def load(id): return objects[id] 关键细节是，对象引用别的对象时， 并不装着 它们。它只记下它们的哈希。可以把哈希当成指针（ ）。讲义那个目录的顶层 tree，打开就是上面那样。本机按同样内容造了一个仓库，哈希和讲义一字不差。 最后一条命令说明了哈希到底算的是什么。先是类型和长度，再是一个 \\0 ，最后才是内容。 学生提问：SHA-1 是什么？（视频 21:52） 哈希函数把任意长的字节， 确定地 变成固定长度的输出。SHA-1 输出 160 位，写成 40 个十六进制字符。结果看着像随机数。两个不同的输入，几乎不可能撞出同一个结果。 讲师用“随机预言机”打比方。想象全世界共用一本登记簿。有人第一次查某个输入，就给它分配一个随机值。以后谁再查，都得到同一个值。 另一个提问是，哈希为什么写成字符串。其实在磁盘上它是字节数组。写成十六进制，只是为了讲解方便（ ）。 补充（非视频内容）：SHA-1 已经不安全了吗 2017 年已经有人造出了 SHA-1 碰撞。Git 从 2.13 起，换用能检测已知碰撞攻击的 SHA-1 实现。从 2.29 起，又实验性地支持 SHA-256 仓库，命令是 git init --object-format=sha256 。内容寻址的思想不变。详见 Git 文档 hash-function-transition 。 为什么会在这里踩坑 两个人在不同电脑上提交同一份文件。blob 哈希一样，commit 哈希却不一样。因为 commit 里还有作者、时间和 parent。任何一项不同，哈希就变。练习页把身份和时间都固定了，哈希才能复现。 下面的演示分两幕。第 1 幕从字节开始，算出一个 blob 的 ID。第 2 幕看 tree 和 commit 怎么用哈希互相指。再看改一个字节时，哪些对象会变，哪些被共享。"}, {"u": "ch05.html#s7", "c": "第 5 讲 · 版本控制与 Git", "t": "引用是给哈希起的名字，而且可以改", "x": "40 位的哈希记不住，所以 Git 给它起名字，叫引用。对象写进去就不变。引用却随时能改成指向别的提交。 bash · 本机实测（练习页 ex01-b，节选） $ cat .git/HEAD .git/refs/heads/master # 引用就是小文本文件 ref: refs/heads/master a9254971ec6ef8d6423964549097af7233cda0ac # HEAD 里写着“我跟着 master”，master 里写着一个提交哈希 打个比方 对象像图书馆里的书，上架后再也不改。引用像书架上的“新书推荐”标签。标签随时能挪到另一本书上。 比如 master 通常指向主开发线上最新的提交。讲义把引用也写成了伪代码： 讲义原文 references = map<string, string> def update_reference(name, id): references[name] = id def read_reference(name): return references[name] def load_reference(name_or_id): if name_or_id in references: return load(references[name_or_id]) else: return load(name_or_id) 历史为什么必须不可变？讲师是这么解释的（ ）。后面的提交靠 内容的哈希 指向前面的提交。改了中间某个提交，它的哈希就变了。后面所有指向它的东西都对不上。所以对象库只能追加，可变的部分全放在引用里。开发新功能时，你新建提交指向旧提交。再把 master 挪到新提交上。 为什么会在这里踩坑 rebase 或 amend 之后，提交哈希全变了。如果已经 push 过，同事手里还是旧哈希。两边的历史就分叉了。所以已经分享出去的历史，别改写。 提交了密钥先作废它，撤销提交用 revert “改写历史”并不是真的改。Git 是照着你要的改动，重建那个提交。它之后的提交也全部重建。 bash · 本机实测（补充，身份和时间按练习页固定） $ git revert --no-edit HEAD # 不碰旧提交，追加一个反向改动 [anish 5fe8159] Revert \"add hotel\" Date: Fri Jan 16 10:00:00 2026 +0000 1 file changed, 1 deletion(-) $ git log --oneline # 旧提交还在，只是多了一个 5fe8159 Revert \"add hotel\" 856e17c add hotel 13341bc initial commit 打个比方 revert 像在账本末尾记一笔冲账。前面记错的那笔不涂改，只是后面再记一笔抵消它。 已经分享出去了 ：先去对应服务作废这个 key。再生成一个新的。作废之后，它留在历史里也没关系（ ）。 还没分享 ：可以用 git rebase 这类命令改写历史（ ）。它不是真的修改，而是重建那个提交和之后所有提交。练习 3 练的就是这个。 只想撤销某次提交的效果 ：用 git revert 。它算出那次的改动，在最新处追加一个反向的新提交。历史一点不改（ ）。 合并时 Git 怎么知道怎么合 ：靠一套启发式规则。两边改的是不同文件，就自动合并。同一文件里离得远的两处，也能自动合并。改的是同一处，比如同一个函数，Git 就放弃。它报 合并冲突 （merge conflict），在文件里留下冲突标记。由你来判断怎么改（ 、 ）。 git mergetool 能帮忙，详见 第 12 节 。 为什么会在这里踩坑 密钥推上去以后，很多人第一反应是改写历史。可别人的克隆和 fork 里可能早有了。所以第一步永远是作废密钥，改写历史只是第二步。撤销已分享的提交，用 revert 最安全。 下面的演示看“改写历史”在提交图上是什么样。rebase 把一串提交的改动，重放到新的基础上。得到的是全新的提交，然后再挪动分支名。"}, {"u": "ch05.html#s8", "c": "第 5 讲 · 版本控制与 Git", "t": "HEAD 记着你在哪，仓库就是对象加引用", "x": "新建提交时，Git 得知道 parent 是谁。所以它用一个特殊引用 HEAD，记着“你现在在哪”。 讲义例子（注释是笔记加的） git checkout master; git reset --hard 5d83f9e # 前一半：HEAD 附着到 master 上 # 后一半：master 挪到 5d83f9e，工作区也跟着变过去 # 合起来：丢掉未提交的修改，让 master 指向 5d83f9e 打个比方 仓库像一本只能往后续写的书。对象是写好的页，引用是贴在页边的便利贴。HEAD 是你手里的书签，标着你正在读哪一页。 HEAD 可以粗略理解成“你现在正在看的那个东西”。于是可以给 Git 仓库下定义了：仓库就是 对象 加 引用 。磁盘上 Git 存的就这两样。 所有 git 命令，都是在提交图上做两件事。一是添加对象，二是添加或移动引用（讲义）。反过来，你想对提交图做某种改动。多半有一条命令能做到。比如“丢掉未提交的修改，让 master 指向 5d83f9e”。这就是上面那两条命令。 学生提问：GitHub 是什么？（视频 32:59） Git 是免费开源的分布式版本控制工具。GitHub 是托管 Git 仓库的商业服务，现在属于微软。开源项目常把仓库放在那里协作。 比如教授把实验放在 Git 仓库里，你克隆下来做。教授更新了实验，你用 Git 就能干净地合进来。哪怕你已经改过自己的副本。不用再下 zip、手工搬改动。GitHub 也不是唯一的托管服务，讲义还提到了 GitLab 和 Bitbucket。 为什么会在这里踩坑 很多人以为 HEAD 就是“最新的提交”。其实它只是“你现在在哪”。切到旧提交时，HEAD 就指着旧提交，见 第 15 节 。"}, {"u": "ch05.html#s9", "c": "第 5 讲 · 版本控制与 Git", "t": "git add 拷的是此刻的内容，之后再改不算", "x": "暂存区决定下一次提交里有什么。 git add 把文件此刻的内容放进暂存区。 git commit 再把暂存区做成提交。 bash · 本机实测（练习页 ex01-d，节选） $ echo hotel >> nato.txt; git status --short # 右列 M：工作区改了，还没暂存 M nato.txt $ git add nato.txt; git status --short # 左列 M：改动进了暂存区 M nato.txt $ echo india >> nato.txt; git status --short # 暂存后又改：两列都是 M MM nato.txt 打个比方 git add 像把作业复印一份交到讲台上。之后你在原稿上接着改，讲台上那份不会变。commit 收走的是讲台上那份。 有的 VCS 只有一个“拍快照”命令。它把目录当前的样子整个存下来。Git 不这样，因为我们想要 干净 的快照。暂存区不属于数据模型。它是“怎么做出一个提交”的操作界面。 你写了两个独立的功能，想拆成两次提交。每次只含一个功能。 你修了一个 bug，又到处加了调试用的 print。你只想提交修复，丢掉 print（讲义）。 Git 的办法是 暂存区 （staging area，也叫 index）。你用它挑出下一次提交要包含的修改。 status 输出有两列字母。左列比较暂存区和 HEAD，右列比较工作区和暂存区。下面的演示把这三个位置画了出来： 为什么会在这里踩坑 status 显示 MM 时直接 commit，只会提交左边那个 M。暂存之后的新改动不会进去。很多人提交完发现少了东西，就是这个原因。想全带上，先再 add 一次，或者用 git commit -a 。"}, {"u": "ch05.html#s10", "c": "第 5 讲 · 版本控制与 Git", "t": "所有功能都是 git 的子命令，不会就 git help", "x": "git init 建出一个 .git 目录，里面就是对象库和引用。之后的 add、commit、log，都是在读写它。 bash · 本机实测（补充，Git 2.55） $ git init -q nato && cd nato $ git status # 在 master 上，但一个提交都没有 On branch master No commits yet nothing to commit (create/copy files and use \"git add\" to track) $ cat .git/HEAD # HEAD 已经说好要跟着 master ref: refs/heads/master $ ls .git/refs/heads | wc -l # 可 master 这个文件还不存在 0 打个比方 git init 像开了一个空账本。户头名 master 写好了，但一笔账都还没记。 讲师现场问大家想听哪部分。基础、远程和高级功能，举手的人差不多。于是尽量都讲。所有功能都是 git 的子命令。 git help 子命令 会打开对应的 man 页，比上网搜快（ ）。第 1 讲讲过 man。 命令（讲义） 作用 git init 新建仓库，数据存在 .git 目录里。里面的 objects 和 refs 就是对象库和引用 git status 告诉你现在的状况。在哪个分支，有没有提交。哪些修改已暂存、未暂存或未跟踪 git add <文件> 把文件放进暂存区 git commit 新建一个提交，会打开编辑器写说明。 -m 直接给说明。 -a 把已跟踪文件的修改一起暂存 git log 把历史拉平成一列显示。 git log --all --graph --decorate 画成 DAG git diff <文件> 看相对暂存区的改动。 git diff <版本> <文件> 比较两个快照里的这个文件 git checkout <版本> 移动 HEAD。检出的是分支时，也切换当前分支 git cat-file -t / -p 看对象的类型或内容。日常很少用，但能直接看到数据模型（ ） 讲师的演示从 到 。在空目录里 git init ， ls .git 能看到 objects 和 refs。 git status 显示 On branch master 和 No commits yet。这时 master 只是一个名字，还不指向任何提交。上面的本机实测也能看出来。 接着写一个 nato.txt，内容是北约音标字母 bravo、charlie 等。status 显示它是 untracked。 git add 之后，它变成 Changes to be committed。 git commit 时写下说明 initial commit。 最后用 git cat-file -t master 看出它是 commit。再用 -p 依次打开 commit、tree、blob。最后看到的内容，和工作区里的 nato.txt 一样。 写好提交说明 为了省时间，讲师故意把提交说明写得越来越敷衍。但他强调，好的提交说明非常重要。讲义推荐了两篇文章。一篇是 A Note About Git Commit Messages ，另一篇是 How to Write a Git Commit Message 。第 8 讲还会讲。 学生提问：一个目录只能有一个仓库吗？（视频 39:47） 基本是这样，因为目录名 .git 是固定的。想要多个仓库，就用多个目录。很多人有一个 src 目录，下面每个子目录各是一个仓库。Git 还有子模块这类更花哨的机制，这里不展开。 为什么会在这里踩坑 git commit -a 只暂存 已跟踪 文件的修改。新建的文件不会被带上，得先 git add 。很多人以为 -a 是“全部”。提交完才发现，新文件没进去。"}, {"u": "ch05.html#s11", "c": "第 5 讲 · 版本控制与 Git", "t": "分支只是一个指向提交的指针", "x": "分支是一种特殊的引用。HEAD 附着在它上面时，每次提交它都跟着往前挪。别的分支原地不动。 bash · 本机实测（补充，身份和时间按练习页固定） $ git branch anish # 建分支不新增任何对象 $ cat .git/refs/heads/anish # 分支就是一个文件，里面只有一个哈希 13341bc1a326fe29015968de880508bce2fa2b8b $ wc -c < .git/refs/heads/anish # 40 个十六进制字符，加一个换行 41 $ git switch -q anish; echo hotel >> nato.txt; git commit -q -am \"add hotel\" $ git log --all --oneline --decorate # 只有 anish 前进了，master 留在原地 856e17c (HEAD -> anish) add hotel 13341bc (master) initial commit 打个比方 分支像一枚书签。你拿着哪枚书签往后写，它就跟着挪到新的一页。别的书签留在原处。 git status 说 On branch master，意思是 HEAD 附着在 master 上（ ）。 git commit 一条命令做了两件事。先在图里加一个节点，再把 master 挪过去。 分支不是“一串提交” ：直觉上分支像一整条血统。但在 Git 里，它 只是一个指向提交的指针 。想挪到哪就挪到哪。血统由提交里的 parent 记着（ ）。 master 不会自动指向最新提交 。只有你所在的分支，才会随提交前进。 git branch anish 在当前位置建新分支， git switch anish 切过去。再提交，前进的是 anish，master 留在原地（ ）。 switch 也改工作区 ：切回 master 后，nato.txt 变回 master 那个快照的内容。刚加的 hotel 不见了（ ）。 git log 默认只显示从当前分支走得到的历史。加 --all ，才显示从所有分支走得到的（ ）。 bash · 本机实测（练习页 ex01-e，复刻视频的操作） $ git log --all --graph --oneline # 两个分支各走了一步，图分叉了 * c560925 add hotel | * 352b132 add alpha |/ * 6f7b00b initial commit 分支命令（讲义） 作用 git branch 列出分支，当前分支前面有 * git branch <名字> 在当前位置新建分支。也可以写 git branch <名字> <提交> 指定位置 git switch <名字> 切换到这个分支 git checkout -b <名字> 新建并切换。等于 git branch 加 git switch 为什么会在这里踩坑 在 anish 上提交了 hotel，切回 master 一看，hotel 不见了。别慌，它好好地待在 anish 的提交里。switch 只是把工作区换成了 master 的快照。 下面的演示一步步建分支、切分支、提交。看清每一步是哪个名字在动。"}, {"u": "ch05.html#s12", "c": "第 5 讲 · 版本控制与 Git", "t": "合并生成有两个 parent 的提交，改了同一处才冲突", "x": "两个提交谁也不是谁的祖先，历史就分叉了。git merge 新建一个合并提交，把两边的改动合在一起。 bash · 本机实测（练习页 ex01-e） $ git merge --no-edit anish # 两边改的地方离得远，自动合并 Auto-merging nato.txt Merge made by the 'ort' strategy. nato.txt | 1 + 1 file changed, 1 insertion(+) $ git log --graph --oneline # 合并提交把两条线收拢 * 30baa2b Merge branch 'anish' |\\ | * c560925 add hotel * | 352b132 add alpha |/ * 6f7b00b initial commit $ git branch -d anish # 只删名字，图一点没变 Deleted branch anish (was c560925). 打个比方 合并像两个人各改了同一份文档的不同段落。一个改开头，一个改结尾，拼起来就行。两人改了同一句话，就得有人拍板。 切回 master，运行 git merge anish 。Git 新建一个合并提交，会打开编辑器让你写说明。它提示 Auto-merging nato.txt。一边在开头加了 alpha，一边在末尾加了 hotel，中间相同。差异合并算法自动合在一起，没有冲突（ ）。 合并之后，anish 的提交都能从 master 走到。这个名字就用不着了，可以 git branch -d anish 。图一点没变，删的只是名字。 分支和血统记录是两回事 （ ）。 反过来，把 master 合进 anish 也完全可以。master 并不特殊（ ）。 当前检出的分支不能删。可以先 git branch main; git switch main ，再 git branch -d master （ ）。 git mergetool 能用更顺手的工具解决冲突（讲义）。 合并相关（讲义） 作用 git merge <版本> 合并到当前分支 git mergetool 用图形或终端工具帮你解决冲突 git rebase 把一组补丁变基到新的基础上。演示见 第 7 节 为什么会在这里踩坑 删已合并的分支，提交不会丢，它们还能从 master 走到。删没合并的分支， -d 会拒绝。本机实测报的是 error: the branch 'anish' is not fully merged 。换成 -D 强删后，就没有引用指着那些提交了。只能去 reflog 里找，见下一节。 下面的演示分两幕。第 1 幕是这次自动合并。第 2 幕是讲义练习 8 的冲突。两边改了同一行，Git 停下来等你解决。全部是本机实测。"}, {"u": "ch05.html#s13", "c": "第 5 讲 · 版本控制与 Git", "t": "删错分支别慌，reflog 记着引用去过哪", "x": "引用是会变的，所以 Git 记下了每个引用的历史，叫 reflog。分支挪错了、删错了，都能从这里找回原来的位置。 bash · 本机实测（补充，身份和时间按练习页固定） $ git branch -D anish # 没合并的分支，用 -D 强删 Deleted branch anish (was 856e17c). $ git reflog -3 # HEAD@{1} 就是被删分支最后指的提交 13341bc HEAD@{0}: checkout: moving from anish to master 856e17c HEAD@{1}: commit: add hotel 13341bc HEAD@{2}: checkout: moving from master to anish $ git branch anish 856e17c # 照着哈希重建，分支回来了 $ git log --all --oneline --decorate 856e17c (anish) add hotel 13341bc (HEAD -> master) initial commit 打个比方 reflog 像浏览器的历史记录。书签删了，历史记录里还有你去过的网址。照着网址再建一个书签就行。不过历史记录也会定期清理。 学生问，删了分支还能找回来吗？讲师说这是相当高级的内容。操作得当，就永远用不上。Git 还维护了一些额外状态。其中就有 引用的历史 ，命令是 git reflog 。引用是可变的，所以记下它曾经指向哪里很有用。 Git 怎么决定留哪些对象？从任何引用出发能走到的提交，都算“活着”。哪个引用都走不到的，就成了孤儿对象。Git 会自动对它们做 垃圾回收 。所以刚删的分支，提交还在对象库里，reflog 也找得到。一年后才后悔，可能就没了（ ）。 学生提问：新建分支时怎么指定它指向哪里？（视频 55:50） 不带参数时，它指向当前位置，也就是 HEAD。也可以给一个引用或哈希。 git branch old <哈希> 就在那个提交上，建了一个叫 old 的分支。上面找回 anish 用的就是这招。 为什么会在这里踩坑（补充，非视频内容） reflog 只存在你本地的仓库里，push 不会带上它。换台电脑，就没有这份记录了。reflog 条目也会过期。过期后再 gc，孤儿对象就真的没了。所以别把它当备份。"}, {"u": "ch05.html#s14", "c": "第 5 讲 · 版本控制与 Git", "t": "main 放稳定代码，每个功能开一个分支", "x": "常见做法是让 main 放最新的稳定代码。开发功能时开一个功能分支，改完再合回 main。 bash · 写法示意 git switch -c fix-login # 从 main 开一个功能分支 git commit -am \"fix login\" # 在分支上随便提交，main 不受影响 git switch main # 改完回到 main git merge fix-login # 合回来，再删掉分支名 打个比方 main 像正式出版的书。功能分支像你的草稿本。草稿写好了，再誊进正式版。 这个分支以前默认叫 master。现在 GitHub 默认叫 main。更复杂的工作流也有。比如网站的生产版本在 main，预发布的测试版在 staging。功能和修复分支先合进 staging 测试。没问题了，再合进 main（ ）。 名字只是约定，叫 anish 也行。讲义列了几种流行的工作流，比如 git-flow ，也有对它的 批评 。 补充：本机 Git 的默认分支名（本机实测） 本机是 Git 2.55。没配 init.defaultBranch 时，它仍用 master。但 git init 会打印一句提示： This default branch name will change to \"main\" in Git 3.0 。提示里还教你用 git config --global init.defaultBranch <name> 来设定。练习页的实验都显式设成了 master，和讲义一致。 为什么会在这里踩坑 一直在 main 上直接改。改到一半来了紧急 bug，半成品就和修复混在一起了。养成习惯，一件事开一个分支。"}, {"u": "ch05.html#s15", "c": "第 5 讲 · 版本控制与 Git", "t": "切到旧提交会游离 HEAD，这时的提交没人跟", "x": "git checkout 一个提交哈希，HEAD 就直接指着提交。它不附着在任何分支上。这时提交，没有分支跟着前进。 bash · 本机实测（练习页 ex01-f，节选） $ git checkout -q HEAD~1; git status | head -1 # 切到上一个提交 HEAD detached at 6f7b00b $ echo zulu >> nato.txt && git commit -q -am \"orphan\"; git switch master Warning: you are leaving 1 commit behind, not connected to any of your branches: d6fefb2 orphan $ git branch rescue HEAD@{1} # 趁 reflog 还在，给它起个名字 打个比方 游离 HEAD 像在旧版本上写散页。写的东西没装订进任何一本册子。你一走开，散页就没人管，迟早被清理。 想把工作区变回某个旧状态，有两种办法。一是 git switch old ，切到指向旧提交的分支。二是直接 git checkout <提交哈希> ，哈希写出足够唯一的前缀就行。 第二种情况下， git log 里那个全大写的 HEAD 直接指着提交。 git status 会说你处于 detached HEAD （游离 HEAD）状态。这时没有活动分支（ ）。 游离状态下也能提交，但没有分支跟着前进。切回 main 时，Git 会警告你。说你留下了 1 个提交，没连到任何分支上。这个提交暂时还在对象库里。可没有分支指向它，也没有分支指向它的后代。它最终会被回收（ ）。补救办法见 的问答：用它的哈希建一个分支。 为什么会在这里踩坑 为了看旧代码，checkout 了一个哈希。顺手改了几行，还提交了。切回 main 时 Git 警告了，很多人没看就关了。那几个提交就成了孤儿。补救是趁 reflog 还在，用 git branch 给它起个名字。上面实测的 rescue 就是这么救的。"}, {"u": "ch05.html#s16", "c": "第 5 讲 · 版本控制与 Git", "t": "remote 只是另一个仓库，fetch 取数据不动本地分支", "x": "Git 是分布式的。你手里就是一份完整的仓库。它可以连任意多个别的仓库，叫 remote。push 送出对象和引用，fetch 取回来但不改你的本地分支。 bash · 本机实测（练习页 ex01-h：用本地裸仓库代替 GitHub） $ git status -sb | head -1 # bob 刚 push 过，alice 这边却显示一致 ## master...origin/master $ git fetch -q && git status -sb | head -1 # fetch 之后，才知道落后 1 个 ## master...origin/master [behind 1] $ git pull -q --ff-only && git log --oneline # pull 才真正挪动本地 master fdf7920 bob: second 4d59c41 alice: first 打个比方 origin/master 像你上次看天气预报时记下的数。天变了，你不重新看预报，记下的数就不会变。fetch 是重新看一眼。pull 是看完再照着换衣服。 GitHub 上的仓库并不特殊。在上面建一个空仓库。这相当于别人做了一次 git init （ ）。 命令（讲义） 作用 git remote 列出 remote git remote add <名字> <url> 添加 remote，惯例叫 origin git push <remote> <本地分支>:<远程分支> 把对象送到远程，再更新远程的引用 git branch --set-upstream-to=<remote>/<远程分支> 让本地分支对应一个远程分支。 git push -u 也会设置 git fetch 从远程取回对象和引用， 不改 你的本地分支 git pull 等于 git fetch 再 git merge git clone 把远程仓库整个下载下来 视频里的流程在 到 ： 在 GitHub 上建一个空仓库。 git remote add origin … 。认证细节见 GitHub 文档。 git push -u origin main 。远程没有 main，就新建它。 -u 让本地 main 跟踪 origin/main。以后直接 git push 就行。 扮演“另一个人”，在桌面上 git clone ，提交，再 push。 回到原来的目录， git status 看不到变化。因为还没从远程拉。 git fetch 只取数据。 git pull 才更新本地引用，这里是一次 fast-forward。 学生提问：push 只发送那一个提交吗？（视频 1:05:46） 不是。它会发送通往那个提交的 整段历史 。只发对方没有的部分。也有只取一部分历史的高级命令。比如讲义里的 git clone --depth=1 ，叫浅克隆。但一般用不上，很多 git 命令都要用完整历史。 GitHub 网页也能把提交历史画出来。课程网站本身就是 GitHub 上的开源仓库（ ）。 为什么会在这里踩坑 git status 说 up to date with origin/master，同事却刚 push 过。这不矛盾。origin/master 只是上次联网时远程的样子，Git 不会自己联网。先 git fetch ，它才会更新。"}, {"u": "ch05.html#s17", "c": "第 5 讲 · 版本控制与 Git", "t": "Git 存的是快照，diff 是现算出来的", "x": "每个提交对应一个完整的快照。它不记“这次改了什么”。Git 不存增量。要看改动，就用 git diff 拿两个快照现算。 bash · 本机实测（补充，接第 7 节 revert 的例子） $ git diff HEAD~1 --stat # 和上一个快照比：少了 hotel 这一行 nato.txt | 1 - 1 file changed, 1 deletion(-) $ git diff HEAD~2 --stat # 和两步前比：什么都不输出 $ git rev-parse HEAD^{tree} HEAD~2^{tree} # 原因：两个快照的 tree 哈希一样 b32d974f6ffb790006046a5147487d17bc41ba1d b32d974f6ffb790006046a5147487d17bc41ba1d 打个比方 Git 像每天给房间拍一张全景照。想知道今天比昨天多了什么，就把两张照片摆在一起比。照片上从来不写“今天多了一把椅子”。 git diff HEAD~ 和上一个提交比。也可以比两个名字，或只看一个文件（ ）。 git log -p 给每个提交附上改动。可以一路往下翻（ ）。 Git 面向用户的高层命令叫 porcelain ，意思是“瓷器”。它们都建在这一讲的数据模型之上。两小时讲不完它们。但基础懂了，进阶内容很好学（ ）。 补充（非视频内容）：那磁盘不会爆吗 逻辑上存快照，不等于物理上每次复制整个目录。没变的文件是同一个 blob，直接共享。 第 6 节 演示第 2 幕里，改一个文件只新增 4 个对象。 另外， git gc 会把对象打包成 packfile。包里会对相似的对象做增量压缩。但这只是存储优化，数据模型仍然是快照。 为什么会在这里踩坑 有人以为 revert 会把那次提交从历史里删掉。其实它追加了一个新提交。新快照恰好和两步前一样。上面 git diff HEAD~2 为空，就是这个原因。"}, {"u": "ch05.html#s18", "c": "第 5 讲 · 版本控制与 Git", "t": "撤销有四招，分享过的历史只用 revert", "x": "每种撤销都能对应回数据模型。要么新建提交再挪引用。要么拿一处的内容，覆盖另一处。 bash · 本机实测（补充，身份和时间按练习页固定，节选） $ git log --oneline -1 # amend 之前 13341bc initial commit $ git commit -q --amend -m \"first commit\" # 新建一个提交顶替它 $ git log --oneline -1 # 哈希变了，旧的还在 reflog 里 5ad3af1 first commit $ echo india >> nato.txt; git add nato.txt; git status --short M nato.txt $ git reset -q nato.txt; git status --short # 移出暂存区，工作区的改动还在 M nato.txt 打个比方 amend 像重新打印最后一页，把旧的那页换掉。revert 像在本子末尾写一行“作废上一条”。前者换掉了一页，后者只往后加。 撤销（讲义） 作用 对数据模型做了什么（补充） git commit --amend 修改上一个提交的内容或说明 新建一个提交替换它，分支指向新提交。旧提交仍在 reflog 里 git reset <文件> 把文件移出暂存区 用 HEAD 的版本覆盖暂存区里这一项 git restore 丢弃工作区的修改 用暂存区或指定来源覆盖工作区文件 git revert <提交> 新增一个提交，抵消某个旧提交 只追加，不改写。适合已经分享的历史 git config ：Git 高度可配置 。全局配置在 ~/.gitconfig ，练习 5 建别名，练习 6 设全局 gitignore。 .gitignore ： 指定 故意不跟踪的文件。比如构建产物和编辑器临时文件。 本机实测提示 本笔记放在 U 盘上，文件系统是 FAT32。直接在上面操作仓库，Git 会报 detected dubious ownership。因为这种文件系统不记录文件属主。所以练习页的实验都放在系统临时目录里做。你在类似的盘上用 Git，可以按提示把目录加进 safe.directory 。这条是补充，是本机遇到的情况。 为什么会在这里踩坑（补充，非视频内容） git restore 和 git reset --hard 都会丢掉工作区的修改。没 add 过的修改，从没进过对象库。reflog 也救不回来。动手前先 git stash ，或者先提交一次。"}, {"u": "ch05.html#s19", "c": "第 5 讲 · 版本控制与 Git", "t": "bisect 二分查找历史，几步就揪出坏提交", "x": "进阶命令很多，最值得先学的是 git bisect 。它在历史里二分查找，每一步跑一次测试。很快就能定位到引入 bug 的提交。 bash · 本机实测（练习页 ex01-i，节选） $ git bisect start HEAD HEAD~15 # 先说好坏：HEAD 坏，HEAD~15 好 Bisecting: 7 revisions left to test after this (roughly 3 steps) [6b417f4f142162f71857d8ac44f1a9729ca015e4] v8: feature 8 $ git bisect run bash test_add.sh # 自动跑测试：退出码 0 算好，1 算坏 running 'bash' 'test_add.sh' # ……中间又测了 3 次，这里省略 78824cac241795729e846fa53e1abbb36f5eef32 is the first 'bad' commit 打个比方 bisect 像猜数字游戏。1 到 16 之间猜一个数，每次只问“大了还是小了”。4 次就能猜中。 命令（讲义） 作用 git clone --depth=1 浅克隆，不下载完整历史 git add -p 交互式暂存，一块一块挑要提交的修改。这才是暂存区真正的威力 git rebase -i 交互式变基。合并、改写、重排还没分享的提交 git blame 每一行最后是谁、在哪次提交改的。见练习 2 git stash 把工作区的修改临时收起来。见练习 4 git bisect 在历史里二分查找，比如找回归 bug git worktree 同时把多个分支检出到不同目录 讲义：杂项 图形界面 ：有很多 GUI 客户端 。讲师们自己都用命令行。 shell 集成 ：在提示符里显示 Git 状态非常方便。有 zsh 版和 bash 版。Oh My Zsh 这类框架通常自带。 编辑器集成 ：Vim 的标准插件是 fugitive.vim 。 Git 不是 GitHub ：GitHub 用 pull request 给别的项目贡献代码。见练习 7。 讲义推荐资源 Pro Git 强烈推荐，读完 1 到 5 章就够熟练了。 Oh Shit, Git!?! 讲常见错误怎么救。还有 Git for Computer Scientists 和 Git from the Bottom Up 。 Learn Git Branching 是浏览器里的闯关游戏。 为什么会在这里踩坑 测试脚本的退出码要守规矩。0 表示好，125 表示跳过。1 到 127 里的其他值都算坏。脚本因为缺环境而失败，bisect 也会当成坏。结果就指错了提交。 开头提到的“自动二分查找”，就是 git bisect 。下面的演示在 16 个提交的历史上，真跑了 git bisect run ："}, {"u": "ch05.html#s20", "c": "第 5 讲 · 版本控制与 Git", "t": "一页带走：仓库就是对象加引用", "x": "把本讲浓缩成几行命令。每行的注释就是结论和考点。 bash · 本讲速查（注释即考点） git cat-file -p HEAD # commit 里只有 tree、parent、作者和说明，不存 diff git hash-object f.txt # 内容一样，blob 哈希就一样，和文件名无关 git commit # 两台电脑提交同一份文件：blob 相同，commit 不同（时间和作者不同） git status --short # MM：只有左边那个 M 会进这次提交 git branch -d anish # 只删名字，已合并的提交还能从 master 走到 git merge sweet # 两边改了同一行才冲突，合并提交有两个 parent git rebase master # 重放出新提交：parent 变了，后面每个哈希都跟着变 git checkout 6f7b00b # 游离 HEAD：这时的提交没有分支跟着 git reflog # 引用去过哪都记着，删错分支从这里找回 git fetch # 只更新 origin/master，本地分支不动 git revert HEAD # 已分享的历史别改写，追加一个反向提交 blob 是文件，tree 是目录，commit 是快照加 parent 加元数据。 三者都是对象，按内容的 SHA-1 寻址，互相用哈希指向。 对象不可变，只能追加。引用是可变的名字，比如分支和 HEAD。仓库就是对象加引用。 暂存区决定下一次提交里有什么。 提交时，只有 HEAD 附着的分支前进。merge 生成有两个 parent 的提交。 游离 HEAD 下的提交没有分支跟着。reflog 记着引用的历史，走不到的对象最终被回收。 remote 就是另一个仓库。push 送出，fetch 取回不动本地，pull 等于 fetch 加 merge。 改写历史就是新建提交再挪引用。已分享的历史别改写，用 revert。 下一步 从现在起，你写的每个练习都可以放进 Git 仓库。第 6 讲是打包与交付代码，会用到版本号和发布。第 8 讲讲提交说明、代码评审和开源贡献。第 9 讲的 CI 也是由 git push 触发的。现在去做 本讲练习的可视化笔记 。"}, {"u": "ch06.html", "c": "第 6 讲 · 打包与交付代码", "t": "开头", "x": "本讲结论 代码要在 别人的机器 上跑起来，得说清两件事。一是交出去的东西是什么，叫 构件 （artifact）。二是它对周围环境做了哪些假设。依赖、环境、版本和锁文件，都在回答这两个问题。容器、配置、编排和发布也一样。"}, {"u": "ch06.html#s1", "c": "第 6 讲 · 打包与交付代码", "t": "在我电脑上能跑，不等于在你电脑上能跑", "x": "代码悄悄依赖着一整套环境。换一台机器，少一样就跑不起来。 bash · 最小例子（示意） # 你的电脑：半年前全局装过 requests，早忘了 python fetch.py # 正常，打印 200 # 同学的电脑：只拿到了 fetch.py 这一个文件 python fetch.py # ModuleNotFoundError: No module named 'requests' 打个比方 交付代码像把菜谱寄给朋友。你家灶台、调料、锅都齐。朋友家缺一样，菜就做不出来。所以菜谱上得写清要哪些东西。 你的代码隐含地依赖着一整套东西。有语言运行时、第三方库和操作系统的特性。甚至还有硬件。做 Python 库、命令行工具或 Web 服务，依赖各不相同。部署步骤也不一样。 但它们有一个共同模式（ ）。最后都要产出一个别人能下载的对象，叫 构件 （artifact）。拿到构件，再满足它对环境的假设。这样就该跑出同样的结果。 本讲的脉络。讲义用 Python 生态举例，换成别的语言，概念大体相同 为什么会在这里踩坑 自己电脑上装过的东西，你早就忘了。代码一直能跑，你就以为它没有依赖。直到换了新电脑，或者交给同学，才发现缺这缺那。"}, {"u": "ch06.html#s2", "c": "第 6 讲 · 打包与交付代码", "t": "pip install 会顺藤摸瓜，把依赖的依赖都装上", "x": "pip install requests 不只装 requests。它会查出 requests 依赖的包，连同依赖的依赖，一起装好。 bash · 最小例子（示意，完整输出见下面的讲义原文） pip install requests # 你只点名了一个包 # Collecting charset-normalizer、idna、urllib3、certifi…… # 实际装了 5 个，另外 4 个是 requests 自己要的 python -c 'import requests; print(requests.__path__)' # 看看装到哪去了 打个比方 pip 像去超市买火锅底料。你只拿了一包底料，收银员说还得配蘸料。蘸料又要配香油。它把这一串都装进你的袋子。 讲师的例子是一个三行的 Python 程序。它用 requests 库下载课程网站。直接运行就报错。因为 requests 不是 Python 自带的，是别人写的。你的程序和它之间，于是有了 依赖 （dependency）关系。 讲义原文 $ python fetch.py Traceback (most recent call last): File \"fetch.py\", line 1, in <module> import requests ModuleNotFoundError: No module named 'requests' pip 是随 Python 运行时一起提供的安装工具。 pip install requests 依次做了四件事： 到 Python 包索引 PyPI 查找 requests。 找出适合当前平台的构件。 解析依赖 。requests 自己也依赖别的包。安装器要给所有 传递依赖 挑出兼容版本。传递依赖就是依赖的依赖，它们要先装好。 下载构件并解包，把文件复制到该放的位置。 讲义原文 $ pip install requests Collecting requests Downloading requests-2.32.3-py3-none-any.whl (64 kB) Collecting charset-normalizer<4,>=2 Downloading charset_normalizer-3.4.0-cp311-cp311-manylinux_x86_64.whl (142 kB) Collecting idna<4,>=2.5 Downloading idna-3.10-py3-none-any.whl (70 kB) Collecting urllib3<3,>=1.21.1 Downloading urllib3-2.2.3-py3-none-any.whl (126 kB) Collecting certifi>=2017.4.17 Downloading certifi-2024.8.30-py3-none-any.whl (167 kB) Installing collected packages: urllib3, idna, charset-normalizer, certifi, requests Successfully installed certifi-2024.8.30 charset-normalizer-3.4.0 idna-3.10 requests-2.32.3 urllib3-2.2.3 $ python -c 'import requests; print(requests.__path__)' ['/usr/local/lib/python3.11/dist-packages/requests'] 视频里讲师装完再运行，拿到 HTTP 状态码 200。意思是一切正常。再查安装位置，发现装进了 全局默认的 Python （ ）。 为什么会在这里踩坑 装完能跑，你就不会去看它装到了哪。讲师这次就装进了全局 Python。以后另一个项目要别的版本，两边就会打架。这就是第 4 节依赖冲突的来源。 下面的演示把这四步拆开。依赖从 requests 节点分裂出来，逐个选版本。最后按依赖顺序装进 site-packages。"}, {"u": "ch06.html#s3", "c": "第 6 讲 · 打包与交付代码", "t": "Python 只定规范，工具让大家来竞争", "x": "各语言管包的思路不同。Rust 用一个 cargo 全包。Python 只定规范，谁都能写遵守规范的工具。 bash · 写法示意 cargo build && cargo test && cargo publish # Rust：一个工具从头管到尾 pip install requests # Python：老牌安装器 uv pip install requests # 同一套规范，uv 实现得更快 打个比方 Python 像只规定插座标准的国家。插座形状统一了，哪家厂都能造插头。cargo 像一家包办到底的厂商，从手机到充电器全是自己做。 做法 例子 特点 统一工具链 Rust 的 cargo 编译、测试、依赖管理、发布，一个工具全包 统一在 规范 层面 Python：pip 和 uv ，setuptools、 hatch 和 poetry 语言只定规则，也就是 PEP。谁都能写守规则的工具，彼此竞争 大而全的发行版 LaTeX 的 TeX Live、MacTeX 预装成千上万个包，很少需要自己装 Python 的规则来自两份规范。 PEP 517 定义构建系统的接口。 PEP 621 规定项目元数据写在 pyproject.toml 里。接口是标准化的，所以才有人写出比 pip 快得多的 uv。 为什么会在这里踩坑 网上教程有的用 pip，有的用 poetry，有的用 uv。命令混着抄，包很容易装进不同的环境。先认准一个工具，再照着它的文档走。"}, {"u": "ch06.html#s4", "c": "第 6 讲 · 打包与交付代码", "t": "两个包要的版本没有交集，就是依赖地狱", "x": "安装器要在所有约束的交集里挑版本。交集为空就无解。解法是给每个项目一个独立的环境。 bash · 最小例子（示意，Linux 路径） python -m venv venv # 建环境：其实就是建一个目录 source venv/bin/activate # 激活：把 venv/bin 插到 PATH 最前面 which python # 现在找到的是 venv/bin/python deactivate # 撤销：PATH 换回原样 打个比方 依赖冲突像两个室友抢一台空调。一个要 20 度，一个要 28 度，怎么调都不行。虚拟环境就是给两人各分一间房，各开各的空调。 依赖一多就会 冲突 。两个程序要同一个依赖，版本范围却不兼容。讲义的例子是这样的： tensorflow==2.3.0 要 numpy>=1.16.0,<1.19.0 。 pandas==1.2.0 要 numpy>=1.16.5 。取交集， numpy>=1.16.5,<1.19.0 里任何版本都行。 项目里再来一个包要 numpy>=1.19 ，就 没有任何版本 能同时满足。这种局面叫 依赖地狱 （dependency hell）。 视频里讲师故意造了冲突（ ）。一个包要 numpy > 2.0，另一个要 numpy < 2.0。安装器打了一大段信息，结论就是无解。笔记在本机用 4 个手工 wheel 复现了这个情形。见练习 1 的 ex01-e： bash · 本机实测（uv 0.11.26，两个包对 shared 的要求相反） $ uv pip install --no-index --find-links wheels liba libb × No solution found when resolving dependencies: ╰─▶ Because only liba==1.0.0 is available and liba==1.0.0 depends on shared>=1.0,<2.0, we can conclude that all versions of liba depend on shared>=1.0,<2.0. And because libb==1.0.0 depends on shared>=2.0 and only libb==1.0.0 is available, we can conclude that all versions of liba and all versions of libb are incompatible. And because you require liba and libb, we can conclude that your requirements are unsatisfiable. 上面 liba 要 shared<2.0 ，libb 要 shared>=2.0 。交集为空，解析器直接认输。 本机实测：分两次装，冲突悄悄发生 先装 liba，拿到 shared 1.5.0。再装 libb，安装器为了满足它，把 shared 换成了 2.1.0。liba 的要求就这样被破坏了。只有 uv pip check 才查得出来： bash · 本机实测（ex01-e 节选） $ uv pip install --no-index --find-links wheels libb + libb==1.0.0 - shared==1.5.0 + shared==2.1.0 $ uv pip check Found 1 incompatibility The package `liba` requires `shared>=1.0,<2.0`, but `2.1.0` is installed 解决办法是隔离。每个程序的依赖，放进各自的 环境 （environment）。Python 里就是建一个虚拟环境（virtual environment，venv）： 讲义原文（Linux） $ which python /usr/bin/python $ python -m venv venv $ source venv/bin/activate $ which python /home/missingsemester/venv/bin/python $ which pip /home/missingsemester/venv/bin/pip $ pip list Package Version ------- ------- pip 24.0 环境就是一份独立的语言运行时。它带着自己那套已安装的包。讲师强调，venv 没什么神秘的 ，就是一个目录。 source 激活时，只改了 shell 的 PATH 等环境变量。于是敲 python ，找到的是这个目录里的那个（ ）。 bash · 本机实测（Windows 的脚本目录叫 Scripts，路径用了占位符） $ python -m venv venv; ls venv Include Lib Scripts pyvenv.cfg $ cat venv/pyvenv.cfg home = <Python> include-system-site-packages = false version = 3.13.5 executable = <Python>\\python.exe command = <Python>\\python.exe -m venv <沙箱>\\venv $ bash envdiff.sh # 练习 1：激活前后 printenv 的差别 5c5 < PATH=<Python>:/usr/bin:/bin --- > PATH=<沙箱>/ex01/venv/Scripts:<Python>:/usr/bin:/bin 6a7 > PS1=(venv) 12a14,15 > VIRTUAL_ENV=<沙箱>/ex01/venv > VIRTUAL_ENV_PROMPT=venv 为什么 shell 会用 venv 里的 python ：激活脚本把 venv/bin 插到 PATH 最前面。Windows 上是 venv/Scripts 。按第 1 讲的规则，shell 只用第一个命中的。 import 为什么找 venv 里的包 ：venv 的 python 一跑， sys.prefix 就指向 venv。 sys.path 里的 site-packages 也换成了 venv 自己的。练习 1 的 ex01-d 实测过这一点。讲师在新 venv 里查 requests，结果不在这里。因为之前装在了全局（ ）。 每个项目一个环境 是好习惯。依赖清清楚楚，也不会陷进依赖地狱。 讲义提醒：别动系统自带的 Python 很多操作系统自带 Python 这类运行时。系统自己的功能可能就依赖它们。别往里面装包，也别升级它。请用独立的环境。 为什么会在这里踩坑 装了包却 import 不到，十有八九是环境不对。可能装进了全局，跑的却是 venv 里的 python。也可能反过来。先敲 which python 和 which pip ，看两者是不是同一个环境。 下面的演示分两幕。第 1 幕手推约束取交集，看交集怎么变空。再看本机解析器的真实报错，和两个环境的解法。第 2 幕看虚拟环境怎样通过 PATH 生效。"}, {"u": "ch06.html#s5", "c": "第 6 讲 · 打包与交付代码", "t": "uv 是更快的 pip，还能按项目切 Python 版本", "x": "uv 能顶替 pip 等一串工具，最大的好处是快。它还能给每个环境指定不同的 Python 版本。 bash · 写法示意 uv pip install requests # 用法和 pip 一样，只是快得多 uv venv --python 3.12 venv312 # 这个环境用 3.12，系统默认版本不受影响 venv312/bin/python --version # 不激活也行：写全路径，就用这个解释器 打个比方 uv 像带了一串钥匙的管家。项目 A 要 3.11 的门，项目 B 要 3.12 的门，它都开得了。不用你把整栋楼的锁都换掉。 Python 的打包工具多年来几经演变。讲师认为现在最好用的是 uv 。它能整体替代 pip 和另外几个工具。最受称道的是 快 。大项目上，解析和安装能从几分钟缩到几秒（ ）。讲义说装 uv 只要 pip install uv 。还强烈建议，能用 uv pip 的地方就别用 pip 。 讲义原文 $ uv pip install requests Resolved 5 packages in 12ms Prepared 5 packages in 0.45ms Installed 5 packages in 8ms + certifi==2024.8.30 + charset-normalizer==3.4.0 + idna==3.10 + requests==2.32.3 + urllib3==2.2.3 环境不只隔离依赖（ ）。它还能隔离 语言运行时的版本 。讲师的机器默认是 3.11。项目需要 3.12 时，这样做： 讲义原文 $ uv venv --python 3.12 venv312 Using CPython 3.12.7 Creating virtual environment at: venv312 $ source venv312/bin/activate && python --version Python 3.12.7 要在多个 Python 版本上测试时，这招很有用。有的语言会自动给每个项目建依赖环境。大多数语言也支持一台机器装多个版本。再按项目指定用哪个，原理相同（讲义）。 讲义推荐 · uv uv 一个工具管很多事。建虚拟环境用 uv venv ，装包用 uv pip 。构建用 uv build ，锁定用 uv lock 。看依赖树用 uv tree ，发布用 uv publish 。本页所有 uv 输出，都来自本机的 uv 0.11.26。 为什么会在这里踩坑 uv venv 只建环境，不会替你激活。本机实测，它最后一行只是提示 Activate with: .venv\\Scripts\\activate 。不 source 一下，敲 python 用的还是全局那个。"}, {"u": "ch06.html#s6", "c": "第 6 讲 · 打包与交付代码", "t": "打包就是把代码装进 Python 认得的位置", "x": "Python 只在几个固定位置找模块。打包就是写好 pyproject.toml ，让安装器把代码放进环境的 site-packages。 bash · 最小例子（示意） python -c \"import greet\" # 在 greet.py 旁边：成功，当前目录在 sys.path 里 cd elsewhere && python -c \"import greet\" # 换个目录：ModuleNotFoundError uv pip install . # 按 pyproject.toml 装进环境的 site-packages python -c \"import greeting\" # 装好以后，哪个目录都能 import 打个比方 没打包的代码像摊在书桌上的笔记，离开书桌就找不到。打包像把它交给图书馆编目上架。谁来借，按书名就能找到。 开发者读写的是 源代码 。 构件 是从源码产出的分发物，可以直接安装或部署。小到一个能运行的代码文件，大到一整台虚拟机。先看最朴素的情况： bash · 本机实测（练习 2 · ex02-a，greet.py 是讲义原文） $ python -c \"from greet import greet; greet('World')\" Hello, World! $ mkdir elsewhere && cd elsewhere $ python -c \"from greet import greet; greet('World')\" Traceback (most recent call last): File \"<string>\", line 1, in <module> from greet import greet; greet('World') ^^^^^^^^^^^^^^^^^^^^^^^ ModuleNotFoundError: No module named 'greet' 换了目录就找不到。Python 只在几个地方找模块。一是当前目录，二是已安装的包，三是 PYTHONPATH 里的路径。 打包 解决的正是这个问题，把代码装到一个已知的位置。做法要按 Python 的规则来（ ）。先写一个项目文件，也叫 manifest。在 Python 里就是 pyproject.toml ： pyproject.toml（讲义原文） [project] name = \"greeting\" version = \"0.1.0\" description = \"A simple greeting library\" dependencies = [\"typer>=0.9\"] [project.scripts] greet = \"greeting:cli\" [build-system] requires = [\"setuptools>=61.0\"] build-backend = \"setuptools.build_meta\" greeting.py（讲义原文） import typer def greet(name: str) -> None: print(f\"Hello, {name}!\") def cli() -> None: typer.run(greet) if __name__ == \"__main__\": cli() 段落 作用（据视频 15:15 讲解） name / version / description 包名、版本和描述。安装后 Python 靠包名找到你 dependencies 声明依赖。没装好 typer ≥ 0.9，就装不了这个库。typer 是流行的命令行库，类似标准库的 argparse。这里主要用它引出依赖 [project.scripts] 安装时额外生成一个 greet 命令。它调用 greeting 模块里的 cli 函数 [build-system] 用什么构建系统产出构件 讲义说， requirements.txt 和 setup.py 这些老办法还能用。但应尽量用 pyproject.toml 。装好以后，在任何目录都能 import，还多了一个 greet 命令： bash · 本机实测（练习 2 · ex02-b，依赖从 PyPI 下载） $ uv venv Using CPython 3.13.5 Creating virtual environment at: .venv $ uv pip install . Resolved 9 packages in 769ms Building greeting @ file:///<沙箱>/ex02/greeting Downloading pygments (1.2MiB) Downloaded pygments Built greeting @ file:///<沙箱>/ex02/greeting Prepared 9 packages in 27.84s Installed 9 packages in 3.06s + annotated-doc==0.0.5 + colorama==0.4.6 + greeting==0.1.0 (from file:///<沙箱>/ex02/greeting) + markdown-it-py==4.2.0 + mdurl==0.1.2 + pygments==2.21.0 + rich==15.0.0 + shellingham==1.5.4 + typer==0.27.3 $ source .venv/Scripts/activate; greet Alice Hello, Alice! 讲师现场踩的坑：忘了激活 装完去别的目录 import，还是失败（ ）。因为忘了激活环境。包装进了 venv，shell 里的 python 却还是全局那个。遇到明明装了却找不到，先敲 which python 。 为什么会在这里踩坑 在源码目录里测 import，永远会成功。因为 python -c 会把当前目录放在 sys.path 的第一位。这不说明包装好了，上面 ex02-a 就是例子。要换一个目录再试，才算数。"}, {"u": "ch06.html#s7", "c": "第 6 讲 · 打包与交付代码", "t": "wheel 就是一个带元数据的 zip 包", "x": "构件分两种。源码要在本机编译，预编译的二进制下载就能用。Python 的构件叫 wheel，本质就是一个 zip。 bash · 写法示意 uv build # 一次产出 sdist 和 wheel 两个文件 unzip -l dist/greeting-0.1.0-py3-none-any.whl # wheel 能直接用 unzip 打开 uv pip install ./greeting-0.1.0-py3-none-any.whl # 把这一个文件交给别人就能装 打个比方 源码包像宜家的散件，回家得自己拧螺丝，还得有工具。预编译的包像组装好的成品家具。但成品有尺寸，你家门框得对得上。也就是系统和 CPU 要匹配。 上面那样从源码装，别人得拿到你的全部文件。往往还要一整套编译工具链。实际分发软件时，分成两种： 从源码安装 下载原始代码，在本机编译。需要编译器和构建工具，大项目要编很久。 安装预编译二进制 下载别人编好的构件。又快又简单，但必须匹配你的 操作系统 和 CPU 架构 。比如 ripgrep 的 Releases 页 ，给每种平台各放一个文件（ ）。Linux 分 x86_64 和 ARM，macOS 分 Intel 和 Apple Silicon，还有 Windows。 Python 的构件叫 wheel 。里面有代码文件和元数据。元数据包括名字、版本和依赖。它还记着每个文件该放到环境里的哪个位置。 uv build 会产出两个文件： bash · 本机实测（练习 2 · ex02-d，用 grep 滤掉了冗长日志） $ uv build 2>&1 | grep -E '^(Building|Successfully)' Building source distribution... Building wheel from source distribution... Successfully built dist\\greeting-0.1.0.tar.gz Successfully built dist\\greeting-0.1.0-py3-none-any.whl $ unzip -l dist/greeting-0.1.0-py3-none-any.whl Archive: dist/greeting-0.1.0-py3-none-any.whl Length Date Time Name --------- ---------- ----- ---- 155 2026-10-29 17:25 greeting.py 118 2026-10-29 17:26 greeting-0.1.0.dist-info/METADATA 91 2026-10-29 17:26 greeting-0.1.0.dist-info/WHEEL 39 2026-10-29 17:26 greeting-0.1.0.dist-info/entry_points.txt 9 2026-10-29 17:26 greeting-0.1.0.dist-info/top_level.txt 463 2026-10-29 17:26 greeting-0.1.0.dist-info/RECORD --------- ------- 875 6 files .whl 就是 wheel。讲师说它不神奇，就是一个 zip（ ）。 .tar.gz 是 源码分发包 （sdist），留给需要从源码构建的系统。 讲义里 unzip -l 列出 5 个文件。本机的 setuptools 多生成了一个 entry_points.txt 。它来自 [project.scripts] 那一段。 把这一个 wheel 文件交给别人， uv pip install ./greeting-0.1.0-py3-none-any.whl 就能装好。 greet 命令也一起装上。 讲义：这种做法的局限 有的库依赖平台相关的东西，比如做 GPU 加速的 CUDA。它的构件只能在装了 CUDA 的系统上用。还可能要为每种平台和架构分别构建 wheel。平台指 Linux、macOS、Windows，架构指 x86 和 ARM。wheel 文件名里的标签就是干这个的，见下面演示的后半段。 为什么会在这里踩坑 pip install 有时会突然开始编译，还报一堆编译器错误。多半是没找到匹配你平台的 wheel。pip 只好下载 sdist，在本机从源码构建。本机缺编译器，就会报错。"}, {"u": "ch06.html#s8", "c": "第 6 讲 · 打包与交付代码", "t": "版本号要按整数逐段比，不能当字符串比", "x": "SemVer 的版本号是 MAJOR.MINOR.PATCH 三段整数。改哪一段，就承诺了多大程度的兼容。 bash · 本机实测（Python 3.13.5） $ python -c 'print(\"1.10.0\" > \"1.9.0\")' # 当字符串比：逐个字符，'1' 小于 '9' False $ python -c 'print((1, 10, 0) > (1, 9, 0))' # 拆成整数再逐段比，10 大于 9 True 打个比方 版本号像门牌“3 栋 10 号”和“3 栋 9 号”。按数字比，10 号在后面。当字符串比，“1”比“9”小。于是 10 号排到了 9 号前面。 代码是连续开发的，发布却是 离散的 。先在开发环境（dev）里证明能用。再交付（ship）到生产环境（prod）。库一直在变。版本号标记的是它在某一刻的状态。每个版本改了什么，写在 变更日志 （changelog）里（ ）。 可是每个依赖都在变，依赖的依赖也在变。全都追踪一遍，根本不现实。 uv tree 能看到整棵依赖树。光是一个 typer，就牵出 7 个包： bash · 本机实测（练习 2 · ex02-c） $ uv tree greeting v0.1.0 └── typer v0.27.3 ├── annotated-doc v0.0.5 ├── colorama v0.4.6 ├── rich v15.0.0 │ ├── markdown-it-py v4.2.0 │ │ └── mdurl v0.1.2 │ └── pygments v2.21.0 └── shellingham v1.5.4 于是有了版本号约定。最常见的是 语义化版本 （ Semantic Versioning ，SemVer）。版本号形如 MAJOR.MINOR.PATCH ，三段都是整数。 升级哪一段 例子 承诺 PATCH 1.2.3 → 1.2.4 只修 bug 或文档，完全向后兼容 MINOR 1.2.3 → 1.3.0 新增功能，向后兼容。新功能只在新版本里有 MAJOR 1.2.3 → 2.0.0 破坏性变更，几乎不做任何保证。可能要改代码 ripgrep 从 15.0.0 升到 15.1.0，正是因为加了新功能（ ）。讲义提醒，这只是简化版。完整规范还解释了两件事。一是 0.1.3 升到 0.2.0 为什么可能有破坏性变更。二是 1.0.0-rc.1 是什么意思。 在 pyproject.toml 里，依赖可以按 PEP 440 写出不同的约束： pyproject.toml（讲义原文，注释译成中文） [project] dependencies = [ \"requests==2.32.3\", # 精确版本：只能是这一个 \"click>=8.0\", # 最低版本：8.0 或更新 \"numpy>=1.24,<2.0\", # 区间：至少 1.24，但小于 2.0 \"pandas~=2.1.0\", # 兼容发布：>=2.1.0 且 <2.2.0 ] ~= 是 Python 的兼容发布运算符。它大致相当于 npm 和 cargo 里的 ^ ，都按 SemVer 的兼容性划范围。笔记用手写代码和 packaging 库各算了一遍，结果一致： bash · 本机实测（练习 2 · ex02-g） $ python semver_check.py 字符串比较 \"1.10.0\" > \"1.9.0\" ? False 元组比较 (1, 10, 0) > (1, 9, 0) ? True ^1.2.3 => >=1.2.3, <2.0.0 ^0.2.3 => >=0.2.3, <0.3.0 ^1.2.3 手写: ['1.2.4', '1.9.0'] packaging: ['1.2.4', '1.9.0'] 一致: True ^0.2.3 手写: ['0.2.9'] packaging: ['0.2.9'] 一致: True ~=2.1.0 接受: ['2.1.0', '2.1.7'] tensorflow ∩ pandas: <1.19.0,>=1.16.0,>=1.16.5 -> ['1.16.5', '1.18.5'] 再加 numpy>=1.19: 无解（依赖地狱） 补充（非视频内容）：版本号要逐段按整数比 第一行就是常见 bug。把版本号当字符串比，先比 '1' 和 '9' 。于是 1.10.0 就“小于” 1.9.0 了。下面的演示用手推面板，一步步比给你看。 不是所有软件都用 SemVer。 日历版本 （CalVer）按发布日期编号。比如 Ubuntu 的 24.04 是 2024 年 4 月发布的，还有 24.10 。一眼就看出新旧，但不表达兼容性。SemVer 也不是绝对可靠。维护者偶尔会失手，在 minor 或 patch 里引入破坏性变更。这是讲义的提醒。 为什么会在这里踩坑 自己写脚本比版本时，最容易直接比字符串。上面实测， \"1.10.0\" > \"1.9.0\" 的结果是 False。比版本请用 packaging 库的 Version ，别自己拼。"}, {"u": "ch06.html#s9", "c": "第 6 讲 · 打包与交付代码", "t": "库写宽范围，应用把版本全钉死", "x": "库要和用户的其他依赖装在一起，约束越宽越好装。应用是最终产品，钉死版本才能人人一样。 toml · 写法示意 # 库的 pyproject.toml：给用户留余地 dependencies = [\"requests>=2.0,<3\"] # 只卡主版本 # 应用的依赖：全部钉死 dependencies = [\"requests==2.32.3\"] # 只能是这一个，测过的就是它 打个比方 库像通用插头，要尽量适配各种插座。应用像定制家具，尺寸按你家量好，一厘米都不改。 版本写死，大家装到的都一样，不会出问题。只写范围，就是希望它和这些版本都兼容。怎么选，要看你在做什么： 库（library）写宽范围 库会被别的代码导入，和用户的其他依赖装在一起。约束写得太死，用户就容易冲突，装不上。视频里看了 requests 的依赖（ ）。3 个都是宽范围，基本只卡主版本。 应用和服务（application）全部钉死 应用是最终消费者。它通过界面或 API 提供功能，不被别人 import。钉死精确版本，才能保证每个用户的体验可复现。ripgrep 的依赖没有一个范围（ ）。全是测过的确切版本。 钉住 （pinning）一个库，就是写确切版本，不写范围。比如写 requests==2.32.3 ，不写 requests>=2.0 。 为什么会在这里踩坑 把应用的习惯带到库里，最容易出事。假设你的库钉死了 numpy 1.x 的某个版本。用户项目里，别的包却要 numpy 2。两个约束没有交集，用户就装不上你的库。这就是第 4 节的依赖地狱。"}, {"u": "ch06.html#s10", "c": "第 6 讲 · 打包与交付代码", "t": "锁文件把整棵依赖树的版本和哈希都记下来", "x": "包管理器算出一组满足全部约束的确切版本。它把结果存进锁文件。别人照着装，拿到的就和你一样。 bash · 写法示意 uv lock # 按 pyproject.toml 解析，写出 uv.lock uv sync # 照着 uv.lock 装，版本和哈希都对得上 uv sync --locked # 锁文件过期就直接报错，CI 和部署用它 打个比方 pyproject.toml 像购物清单，写着“鸡蛋一盒”。锁文件像购物小票，写着哪个牌子、哪一批、条码多少。照着小票买，每次都一模一样。 代码坐在层层抽象之上。下面有运行时、第三方库和操作系统，甚至硬件。任何一层不同，都可能改变行为。包管理器要考虑所有约束，传递依赖的也算。它算出一组满足全部约束的版本，存进 锁文件 （lock file）。视频里先看了 Cargo 生成的锁文件。每个包都有确切版本和 校验和 （checksum），依赖的依赖也有。校验和的意思是，下载时这个文件就该是这个哈希。 bash · 本机实测（练习 2 · ex02-c，长 URL 截到 120 列） $ uv lock warning: No `requires-python` value found in the workspace. Defaulting to `>=3.13`. Resolved 9 packages in 426ms $ sed -n '/^name = \"typer\"/,/^$/p' uv.lock | cut -c1-120 name = \"typer\" version = \"0.27.3\" source = { registry = \"https://pypi.org/simple\" } dependencies = [ { name = \"annotated-doc\" }, { name = \"colorama\", marker = \"sys_platform == 'win32'\" }, { name = \"rich\" }, { name = \"shellingham\" }, ] sdist = { url = \"https://files.pythonhosted.org/packages/03/51/d33db42cc72ffd8c30777547b42d01f0cbf9d95a770457698d0174b3e wheels = [ { url = \"https://files.pythonhosted.org/packages/07/ea/2e31b67051e91a133189e9c000c222502ddc6969856416de0d095de4c0b0/ ] typer>=0.9 被锁成了解析当天的最新版。视频里锁到的是 0.21.1 （ ），本机今天锁到的是 0.27.3 。这说明不锁定的话，不同时间装会得到不同结果。 锁文件同时记着 sdist 和 wheel 的下载地址和哈希。它是写给机器看的，不是给人读的。 别人用 uv sync 按锁文件安装，保证拿到你测试时的那些版本。只看 pyproject.toml 的人，可能装到更新的版本（ ）。 本机实测：锁文件过期会被拒绝 bash · 本机实测（练习 2 · ex02-f：改了约束但没重新 lock） $ uv sync --locked; echo \"退出码：$?\" The lockfile at `uv.lock` needs to be updated, but `--locked` was provided. To update the lockfile, run `uv lock`. 退出码：1 补充实验（非视频内容）：构件本身能逐字节复现吗 讲义提到了 Nix 和 Bazel 这类工具。它们追求无论何时何地，都构建出逐位相同的结果。笔记在本机做了个最小实验，见练习 2 的 ex02-e。同一份源码，只改文件的修改时间。构建两次 wheel，sha256 完全不同。因为 zip 里记着文件时间。用 SOURCE_DATE_EPOCH 把时间固定以后，情况就变了。修改时间不同、输出目录不同，两次结果也一模一样： bash · 本机实测 2ace89ce6f47ce642f1a278b274d36f6b0de10b10993b063d6d32d67824ead58 *../w1/greeting-0.1.0-py3-none-any.whl 4866bd92707c7ac63ce8bb84a560291052c92201543594ea6dceb7ff9031868c *../w2/greeting-0.1.0-py3-none-any.whl $ export SOURCE_DATE_EPOCH=1767225600 f247708af96321949617d438b3ee206042234c3c42e1da614e8b32e66250da85 *../w3/greeting-0.1.0-py3-none-any.whl f247708af96321949617d438b3ee206042234c3c42e1da614e8b32e66250da85 *../w4/greeting-0.1.0-py3-none-any.whl 为什么会在这里踩坑 最常见的坑是只提交 pyproject.toml，不提交 uv.lock。同事和 CI 各自重新解析，装到的版本就不一样。另一个坑是改了依赖，忘了 uv lock 。 uv sync --locked 会直接拒绝，上面实测退出码是 1。 下面的演示串起三件事：范围、锁定、校验哈希。最后再放一遍上面的可复现构建实验。"}, {"u": "ch06.html#s11", "c": "第 6 讲 · 打包与交付代码", "t": "语言包管理器管不到的，交给 Nix 这类工具", "x": "pip 只管 Python 包。编译器、CUDA、OpenSSL 这类系统级依赖，得用管得更广的工具。 bash · 写法示意 pip install cupy-cuda12x # pip 只管 Python 这一层 nvcc --version # CUDA 工具包得先在系统里装好，pip 管不着 nix-shell -p python312 gcc # Nix：连编译器和系统库一起钉死 打个比方 pip 像小区物业，只管楼里的事，水厂和电网它管不了。Nix 像连水电一起承包的开发商。从地基到灯泡，全记在账上。 只要离开编程语言自己的环境，就得用管得更广的工具。讲师举了个例子。你以为 Python 3.12 就是 3.12。可构建 Python 要用 C 编译器，编译器的版本也会不同。 Nix 这类包管理器能管操作系统里的所有包。它用可复现的方式，管住每一处可变的地方。甚至有个操作系统 NixOS 就基于这个理念。它用版本控制的配置文件，管理整台电脑（讲义）。代价是拿灵活性换来了复杂度。 讲义推荐 · Nix / Bazel Nix 和 Bazel 提供 密闭 （hermetic）构建。编译器、系统库，连构建环境本身都钉死。而且按内容寻址。这样无论何时何地构建，结果都逐位相同。越来越多项目还用 nix flakes ，按项目管理系统级的库和程序。 CuPy 离不开 CUDA，这种依赖写不进 pip CuPy 是调用 NVIDIA CUDA 指令的 Python 包装层。它的安装说明不是一句 pip install。而是先装好兼容的 CUDA 工具包。这种依赖根本写不进 Python 的打包信息。看它发布的 wheel，不光分操作系统和 CPU 架构。还要按 CUDA 运行时版本 和 Python 版本 分别编译。你得自己挑对文件（ ）。还有 GPU 驱动、特定版本的编译器、OpenSSL 这类共享库。它们至今常常要在系统层面安装。 升级有风险，不升级也有风险（讲义） 新版本会有意无意地带来破坏。旧版本又会随时间暴露安全漏洞。这对矛盾永远存在。讲义的建议有两条。一是用持续集成（第 9 讲）拿新版本依赖跑测试。二是用 Dependabot 这类自动化工具发现依赖的新版本。即便这样，开发和生产环境的差异，仍会让升级出问题。所以要有 回滚 （rollback）预案。撤销升级，重新部署已知良好的版本。 为什么会在这里踩坑 pip 装 CuPy 显示成功，一跑起来却报 CUDA 相关的错。pip 的成功只说明 Python 这一层装好了。系统层的 CUDA 和驱动，它根本不检查。遇到这类报错，先查系统依赖，别反复重装 Python 包。"}, {"u": "ch06.html#s12", "c": "第 6 讲 · 打包与交付代码", "t": "容器共享宿主内核，所以比虚拟机轻", "x": "虚拟机连操作系统一起交付，开销大。容器复用宿主的内核，只隔离应用这一层，轻得多。 bash · 写法示意（Linux 宿主，本机没有 Docker） uname -r # 宿主的内核版本 docker run --rm python:3.12 uname -r # 容器里看到的是同一个内核：内核是共享的 打个比方 虚拟机像在你家院子里再盖一栋小房子，水电全套自带。容器像在你家隔出一个房间。墙是自己的，水电总闸还是你家那个。 CUDA 这类依赖，最好别让用户自己凑。那就把用户需要的一切都随构件交付。这几乎就是交付整台电脑。 虚拟机（VM） 电脑里运行电脑。它模拟整台计算机，自带一套独立的操作系统。隔离得很彻底。Windows 里能跑 Linux，反过来也行。给别人一个虚拟机镜像，所有依赖都在里面。缺点是 开销大 。跑一个应用，得带一整套操作系统（ ）。 容器（container） 应用大多只关心用户态的依赖，不需要改操作系统本身。所以容器复用宿主操作系统的核心，也就是 共享内核 。它只隔离应用这一层。应用连同依赖、库和文件系统，打成一个包。比 VM 轻，启动更快，运行也更高效（ ）。 只有部分操作系统原生支持容器，比如 Linux 和 BSD。在 Windows 或 Mac 上跑容器，其实是先跑一个 Linux 虚拟机。容器跑在这台虚拟机里面。好在生产环境部署的应用基本都是 Linux，问题不大。 本笔记的实测环境：没有可用的 Docker 本机是 Windows 11。Docker Desktop 的后端一启动就崩，WSL 里也没有可用的 Linux 发行版。所以本讲的 docker 命令都 未实测 。输出取自讲义原文或视频描述。练习里的 Dockerfile 和 compose 文件照样写出来了，也加了注释。 为什么会在这里踩坑 以为容器是轻量版虚拟机，什么系统都能装。其实它和宿主共用一个内核。Linux 容器里跑不了 Windows 程序。在 Mac 和 Windows 上，Docker 还得先起一个 Linux 虚拟机，有额外开销。"}, {"u": "ch06.html#s13", "c": "第 6 讲 · 打包与交付代码", "t": "docker run 一条命令，就得到一台隔离的机器", "x": "docker run 镜像 命令 用镜像起一个容器，在里面跑命令。看着像在用本机程序。其实文件系统和进程都是隔离的。 bash · 写法示意（本机没有 Docker） docker run -it python:3.12 python # -it：交互式，并分配一个终端 docker run -it python:3.12 bash # 进去看看：文件系统是容器自己的 ps aux # 在容器里敲：几乎没有进程，只有你启动的那个 cat /etc/os-release # 官方 python 镜像底下是 Debian 打个比方 镜像像一份冷冻的预制菜，Python 和系统都封在里面。docker run 就是加热上桌。吃完收走，下次再热一份，味道一样。 目前最流行的是 Docker 。它把构建、分发、运行容器的方式标准化了。底层的容器运行时 containerd 是行业标准，Kubernetes 等工具也在用。所以镜像可以复用。Kubernetes 还额外提供容错等功能。 讲义原文（-it：交互式，并分配终端） $ docker run -it python:3.12 python Python 3.12.7 (main, Nov 5 2024, 02:53:25) [GCC 12.2.0] on linux >>> print(\"Hello from inside a container!\") Hello from inside a container! 看起来像在用本机 Python，其实跑在一个隔离的容器里。讲师的原话是，这不只是一个环境（ ）。它是一整台被隔离的机器。退出 Python，容器也跟着停止。 把 python 换成 bash 进去看看（ ）。文件系统是容器自己的。 ps aux 几乎看不到进程。容器不做操作系统的簿记工作。里面只有你启动的那些进程。 python:3.14 这样的镜像，是 Docker Hub 上的官方镜像（ ）。它就是某个 Linux 装好了 Python。查 /etc/os-release ，底下是 Debian。需要 Node 就拉 Node 的镜像。 为什么会在这里踩坑（补充，非视频内容） docker run 每次都用镜像起一个新容器。上一个容器里装的包、改的文件，新容器里都没有。想留下改动，就写进 Dockerfile 重新构建，或者挂载卷。"}, {"u": "ch06.html#s14", "c": "第 6 讲 · 打包与交付代码", "t": "Dockerfile 每条指令是一层，改哪层就从哪层重建", "x": "镜像是把整个文件系统当构件交付。Dockerfile 一条指令生成一层，Docker 会缓存每一层。 Dockerfile · 最小例子（示意） FROM python:3.12 # 第 1 层：基础镜像 RUN pip install numpy # 第 2 层：装依赖 COPY . /app # 第 3 层：拷源码。改了源码，只从这层往后重建 打个比方 镜像分层像叠千层蛋糕，每条指令抹一层。改了第 3 层的奶油，下面两层蛋糕坯不用重烤。直接拿来用。 实际的程序往往依赖整个文件系统。那就干脆把 整个文件系统 当构件交付，这就是容器镜像。镜像用 Dockerfile 以编程方式构建。依赖、系统库和配置都写得清清楚楚。Dockerfile 看着像 bash（ ）。其实它是专门描述镜像的另一种语言： Dockerfile（讲义原文 · 第一版） FROM python:3.12 RUN apt-get update RUN apt-get install -y gcc RUN apt-get install -y libpq-dev RUN pip install numpy RUN pip install pandas COPY . /app WORKDIR /app RUN pip install . 镜像和容器 ：镜像（image）是打包好的构件，像模板。容器是镜像的运行实例。同一个镜像可以跑多个容器。 分层 ：FROM、RUN、COPY 这些指令，每条产生一层。构建时能看到一串编号，每层都被 Docker 记下来（ ）。不同镜像有相同的层时，可以去重。 缓存 ：改了 Dockerfile 的某一行，只重建这一层和它之后的层。 标签 ： docker build -t greet . 给镜像起名。没给标签，就默认用 latest （ ）。 为什么会在这里踩坑 把拷源码的 COPY 写在装依赖前面，是最常见的坑。源码一改，COPY 这层就变了。它后面的装依赖层全部重建，每次都要重新下载。下一节的改进版调整了顺序。"}, {"u": "ch06.html#s15", "c": "第 6 讲 · 打包与交付代码", "t": "好的 Dockerfile：镜像小、层少、版本锁死", "x": "改进版换了 slim 基础镜像，还合并了 RUN。它清掉了包管理器缓存，先装锁定的依赖再拷源码。 Dockerfile · 最小例子（示意） FROM python:3.12-slim # slim 版，不带一堆用不上的东西 RUN apt-get update && apt-get install -y gcc && \\ rm -rf /var/lib/apt/lists/* # 一条 RUN 一层：装完马上清缓存 COPY pyproject.toml uv.lock ./ # 先只拷依赖清单 RUN uv sync --locked # 清单不变，这层就命中缓存 打个比方 搬家装车，大件先上，零碎最后放。依赖清单很少变，是大件。源码天天改，是零碎。顺序对了，每次只用重装最后那几箱。 讲义指出了第一版的问题。它用了完整版的 Python 镜像，没用 slim 版。多条分开的 RUN 产生了多余的层。没锁版本。也没清理包管理器缓存，把没用的文件也打了进去。常见的错误还有两个。一是用 root 身份运行容器。二是不小心把 密钥 打进镜像层。改进版是这样的： Dockerfile（讲义原文 · 改进版） FROM python:3.12-slim COPY --from=ghcr.io/astral-sh/uv:latest /uv /usr/local/bin/uv RUN apt-get update && \\ apt-get install -y --no-install-recommends gcc libpq-dev && \\ rm -rf /var/lib/apt/lists/* WORKDIR /app ENV PATH=\"/app/.venv/bin:$PATH\" COPY pyproject.toml uv.lock ./ RUN uv sync --locked --no-dev --no-install-project COPY . . RUN uv sync --locked --no-dev builder 模式 ：uv 不从源码编译。而是从 ghcr.io/astral-sh/uv 镜像里，只拷出 uv 这一个二进制。这样就不必把编译用的全套工具带进最终镜像。 合并 RUN，加 --no-install-recommends ，再删掉 apt 的列表缓存。讲师说，最终产品不会再装别的东西（ ）。 视频里比了两版镜像的体积。第一版接近 2 GB ，优化版大约 半个 GB （ ）。 补充（非视频内容）：为什么先单独拷依赖清单 依赖清单很少变，源码经常变。所以先只拷 pyproject.toml 和 uv.lock，把依赖装好，再拷源码。改源码时，装依赖那层的输入没变，直接命中缓存。练习 3 里，课程网站自己的 Dockerfile 也是这样。它先拷 Gemfile 和 Gemfile.lock。 讲义：Docker 的三个局限 镜像通常和平台绑定。 linux/amd64 的镜像放到 linux/arm64 上，比如 Apple Silicon，只能慢速模拟运行。 容器需要 Linux 内核。macOS 和 Windows 上的 Docker 其实跑着一个 Linux 虚拟机，有额外开销。 容器共享宿主内核，隔离比虚拟机弱。在多租户环境里，这是安全隐患。 问答：Dockerfile 基本都是手写的 Dockerfile 不是自动生成的，绝大多数是手写。过程就是弄清你的程序运行需要什么。讲师说，那个例子其实用不着 C 编译器。加上 gcc，只是为了演示安装和清理的惯例。但如果包里有要编译的 C 扩展，就确实需要 gcc。讲师说，一用起来你就会发现问题。缺了这个那个，应用就跑不了。CuPy 需要 CUDA，那就两条路。要么选一个自带 CUDA 的基础镜像，要么在 Dockerfile 里装上它。 为什么会在这里踩坑（补充，非视频内容） 密钥最容易在这里泄露。 COPY . . 会把整个目录拷进去， .env 里的密钥也在内。后面再 RUN rm .env 也没用，它还留在前一层里。要用 .dockerignore 把它排除在外。 下面的演示把两版 Dockerfile 一层层叠起来。看改一行源码时，哪些层命中缓存，哪些要重建。再看优化版为什么小："}, {"u": "ch06.html#s16", "c": "第 6 讲 · 打包与交付代码", "t": "每个服务一个容器，Compose 一次全拉起来", "x": "数据库、缓存这类服务各放一个容器，通过网络通信。Compose 用一个 YAML 文件声明它们，一条命令一起启动。 bash · 写法示意（本机没有 Docker） docker compose up -d # 读 docker-compose.yml，按依赖顺序起所有服务 docker compose ps # 看 web 和 cache 是不是都在跑 docker compose down # 一起停掉，删掉容器 打个比方 Compose 像餐厅的排班表。厨师、服务员、收银各管一摊，表上写清谁先到岗。店长照表一喊，所有人一起开工。 再往上一层，你开始依赖 整个服务 。比如数据库、缓存和消息队列。一种做法是把 Postgres 装进你的 Dockerfile。然后祈祷它的依赖和你的不冲突。另一种是把它们放进不同的容器，让它们互相通信。依赖地狱真实存在，所以后一种常见得多（ ）。讲义的例子是缓存。别自己写，用久经考验的 Redis 或 Memcached 。它们各自部署在自己的容器里。每个组件都是独立的服务，通过网络通信，通常走 HTTP API。这叫 微服务架构 。 视频的例子是一个访问计数网页（ ）。每次访问，Web 应用发 HTTP 请求，从数据库 etcd 读出计数。加一，再写回去。两个容器都要部署，还要互相连通。可以手敲一串 docker run ，再去学 Docker 网络。但实践中会用一门专门描述服务部署的配置语言： docker-compose.yml（讲义原文） services: web: build: . ports: - \"8080:8080\" environment: - REDIS_URL=redis://cache:6379 depends_on: - cache cache: image: redis:7-alpine volumes: - redis_data:/data volumes: redis_data: Docker Compose 读这个文件，翻译成一串 docker 命令。 docker compose up 让两个服务一起启动。它们之间的网络和共享卷，也由它处理。 web 用主机名 cache 就能连到 Redis。Docker 内部的 DNS 会自动解析服务名。 depends_on 是 声明式 的依赖。数据库没跑起来，就别启动 Web 服务。手动做这件事很麻烦（ ）。 视频里 docker compose up 之后，日志里能看到 etcd 和 web 两个容器。每访问一次，计数加一（ ）。 本机没有 Docker。练习 4 用一个 30 行的 Redis 替身，代替 redis 镜像。还故意先启动 web，看看会怎样： bash · 本机实测（练习 4 · ex04-b，Redis 用替身） $ PORT=28080 REDIS_URL=redis://127.0.0.1:26379 python app.py & WEB=$! web: listening on 127.0.0.1:28080, cache = redis://127.0.0.1:26379 $ curl -s -w 'HTTP %{http_code}\\n' 127.0.0.1:28080 cache unavailable: TimeoutError HTTP 503 $ PORT=26379 python fake_redis.py & CACHE=$! cache: fake redis on 127.0.0.1:26379 $ for i in 1 2 3; do curl -s 127.0.0.1:28080; done This page has been visited 1 times. This page has been visited 2 times. This page has been visited 3 times. 补充（非视频内容）：depends_on 只管先后，不管就绪 默认情况下， depends_on 只保证 cache 容器先启动。它不保证 Redis 已经能接受连接。要等就绪，得配合 healthcheck。所以服务本身也要能容忍依赖暂时不可用。上面的 app.py 连不上缓存时返回 503，不会直接崩溃。 部署要求还会更复杂。比如跨多台机器扩展，服务崩溃时容错，还要高可用。这时就轮到 Kubernetes（k8s）这样的编排平台。它能管理集群上成千上万个容器。但它学习曲线陡，运维开销大。小项目往往用不着（讲义）。 服务之间靠 HTTP API 通信（讲义） 多容器之所以可行，部分是因为服务都用标准 API 互调。最常见的是 HTTP REST API。比如程序调用 OpenAI 或 Anthropic 这类 LLM 服务。底层就是给它们的服务器发一个 HTTP 请求，再解析响应： 讲义原文（需要 API 密钥，本页未执行） $ curl https://api.anthropic.com/v1/messages \\ -H \"x-api-key: $ANTHROPIC_API_KEY\" \\ -H \"content-type: application/json\" \\ -H \"anthropic-version: 2023-06-01\" \\ -d '{\"model\": \"claude-sonnet-4-20250514\", \"max_tokens\": 256, \"messages\": [{\"role\": \"user\", \"content\": \"Explain containers vs VMs in one sentence.\"}]}' 为什么会在这里踩坑 在 compose 里把地址写成 localhost ，最容易踩坑。在 web 容器里，localhost 是 web 自己，Redis 在另一个容器。要写服务名，比如 redis://cache:6379 。练习 4 的踩坑部分专门讲了这件事。 下面的演示用练习 4 的本机实测输出，演三件事。先看没有编排时的 503。再看缓存就绪后的计数。最后看 Compose 的声明式依赖："}, {"u": "ch06.html#s17", "c": "第 6 讲 · 打包与交付代码", "t": "只改配置不改代码，就能换一台机器部署", "x": "同一份代码，靠配置区分开发、预发布和生产。配置从命令行参数、环境变量、配置文件读进来。 bash · 写法示意 PORT=9100 python app.py # 环境变量覆盖默认端口 python app.py --port 9200 # 命令行参数优先级更高 export API_KEY=… # 密钥放环境变量，别写进代码，更别提交 打个比方 配置像空调遥控器。同一台空调，夏天调 26 度，冬天调 20 度。你不会为了换个温度，去拆开空调改电路板。 代码打包好了，还要考虑别人怎么运行它。还有怎么改变它的行为。讲师给了一个心智模型（ ）。 同一个应用，只改配置，不改源码。 这样就该能部署到两台不同的机器上。比如只是换个监听端口，就不该去改源码。讲义也这么说。同一份代码库只靠换配置，就能部署到不同环境。比如开发、预发布（staging）和生产。 配置的方式在第 2 讲见过。有命令行参数、环境变量和配置文件（dotfiles）。视频里，Web 程序从环境变量 ETCD_URL 读数据库地址。etcd 更适合用命令行参数配置。讲义给了两个例子： 用环境变量配置（讲义原文，注释译成中文） import os DATABASE_URL = os.environ.get(\"DATABASE_URL\", \"sqlite:///local.db\") DEBUG = os.environ.get(\"DEBUG\", \"false\").lower() == \"true\" API_KEY = os.environ[\"API_KEY\"] # 必填：没设置会抛异常 config.yaml（讲义原文，程序用 yaml.load 读取） database: url: \"postgresql://localhost/myapp\" pool_size: 5 server: host: \"0.0.0.0\" port: 8080 debug: false 练习 4 的 app.py 同时支持这几种来源，逐层覆盖。顺序是默认值、配置文件、环境变量、命令行参数。越往后越优先。这个优先级是常见惯例，属于补充： bash · 本机实测（练习 4 · ex04-a） $ python app.py --print-config # 只有默认值：8080 {\"host\": \"127.0.0.1\", \"port\": 8080, \"redis_url\": \"redis://localhost:6379\"} $ echo '{\"port\": 9000}' > app.json && python app.py --print-config # 配置文件盖过默认值 {\"host\": \"127.0.0.1\", \"port\": 9000, \"redis_url\": \"redis://localhost:6379\"} $ PORT=9100 python app.py --print-config # 环境变量再盖过配置文件 {\"host\": \"127.0.0.1\", \"port\": 9100, \"redis_url\": \"redis://localhost:6379\"} $ PORT=9100 python app.py --port 9200 --print-config # 命令行参数最后说了算 {\"host\": \"127.0.0.1\", \"port\": 9200, \"redis_url\": \"redis://localhost:6379\"} 讲义：密钥要格外小心 配置里常有 API 密钥这类敏感数据。它们要小心处理，免得意外泄露。 绝不能提交进版本控制 。也别打进镜像层，见第 15 节。 为什么会在这里踩坑 图省事，把端口和数据库地址直接写在代码里。换台机器部署，就得改源码、重新打包。密钥写在代码里更糟，一 push 就跟着公开了。从第一天起，就从环境变量读。"}, {"u": "ch06.html#s18", "c": "第 6 讲 · 打包与交付代码", "t": "systemd 让服务开机自己启动，不用人守着", "x": "在 /etc/systemd/system 下写一个单元文件，就注册了一个服务。之后由操作系统负责启动和停止它。 bash · 写法示意（本机是 Windows，没有 systemd） sudo systemctl start myapp # 现在就启动，执行 ExecStart 那一行 systemctl status myapp # 看它跑没跑起来 sudo systemctl enable myapp # 补充：WantedBy 要 enable 之后才生效 打个比方 systemd 像大楼的物业值班表。表上写着“每天早上开灯”，到点自然有人去开。你不用每天亲自跑一趟。 多服务应用的部署解决了。还剩一个问题：谁来启动它们？总不能指望机器每次重启后，有人 SSH 上去敲 docker compose up 。生产环境希望服务开机自启，失败时重启。Linux 上最流行的是 systemd。在 /etc/systemd/system 下写一个声明式的单元文件，就能注册新服务。 /etc/systemd/system/myapp.service（讲义原文） [Unit] Description=My Application Requires=docker.service After=docker.service [Service] Type=oneshot RemainAfterExit=yes WorkingDirectory=/opt/myapp ExecStart=/usr/bin/docker compose up -d ExecStop=/usr/bin/docker compose down [Install] WantedBy=multi-user.target 行 含义（据视频 52:51 的 TL;DR） Requires / After=docker.service 依赖 Docker。必须等 Docker 服务起来后再启动 WorkingDirectory 进入这个目录执行命令 ExecStart=… up -d 启动。 -d （detach）让它在后台运行，不卡住命令行 ExecStop=… down 有人要停止服务时执行 WantedBy=multi-user.target 开机进入多用户模式时启动。讲义说，这保证系统启动时就运行 之后就用 systemctl start myapp 、 systemctl status myapp 和 systemctl stop myapp 管理。视频里 start 之后，看似什么都没发生。status 显示 compose up 已经执行了。现在这组服务归操作系统管，机器重启后会自动启动。再访问网页，显示已访问 4 次（ ）。 讲师建议：用 LLM 学专用语法 systemd 有自己的一套语法。讲师说，这正是 LLM 特别有用的地方（ ）。直接问它有哪些选项，它会把这门专用语法教给你。 为什么会在这里踩坑（补充，非视频内容） 写好单元文件只 start ，没有 enable 。当下服务能跑，重启机器后却没起来。 WantedBy 要 systemctl enable 之后才生效。改了单元文件，还要先跑 systemctl daemon-reload 。"}, {"u": "ch06.html#s19", "c": "第 6 讲 · 打包与交付代码", "t": "发布就是把构件放到别人找得到的地方", "x": "构件可以直接放成文件，也可以挂在 GitHub Releases 上。还可以推到 PyPI 这样的中央索引。安装器按文件名里的平台标签挑 wheel。 bash · 写法示意 pip install requests # 从中央索引 PyPI 取 pip install git+https://github.com/psf/requests.git # 从 GitHub 克隆，再从源码构建 go get github.com/gorilla/mux # Go 没有中央索引，路径就是地址 打个比方 发布像开店。可以自己摆地摊，也就是直接放文件。也可以进商场，也就是 PyPI、npm 这类中央索引。顾客按招牌找上门。 构件做好了，放在哪？分发的形式和语言、环境密切相关： 直接放文件 ：上传构件供人下载。 Ubuntu 的软件包仓库 就是这样（ ）。它本质上是一个 .deb 文件的 HTTP 目录列表。 GitHub ：已成为发布源码和构件的事实标准。GitHub Releases 能给打了标签的版本附上预编译的二进制。 从 GitHub 直接安装 ：包管理器能直接从仓库装（ ）。可以从源码装，克隆后构建 wheel 再安装。也可以装某个 Release 里的 wheel。 去中心化 ：Go 没有中央仓库。模块路径 github.com/gorilla/mux 写明了代码在哪。 go get 直接去那里取（讲义）。pip、cargo、brew 等则有中央索引。 讲义原文（注释译成中文） # 从源码安装（会克隆并构建） $ pip install git+https://github.com/psf/requests.git # 安装某个标签/分支 $ pip install git+https://github.com/psf/requests.git@v2.32.3 # 直接安装 GitHub Release 里的 wheel $ pip install https://github.com/user/repo/releases/download/v1.0/package-1.0-py3-none-any.whl 那 pip 平时从哪下载？加上 --verbose ，再过滤出 .whl 就看得到。视频里要先卸载再装（ ）： 讲义原文（长 URL 中间的哈希目录用 … 省略） $ uv pip install requests --verbose --no-cache 2>&1 | grep -F '.whl' DEBUG Selecting: requests==2.32.5 [compatible] (requests-2.32.5-py3-none-any.whl) DEBUG No cache entry for: https://files.pythonhosted.org/packages/1e/db/…/requests-2.32.5-py3-none-any.whl.metadata DEBUG No cache entry for: https://files.pythonhosted.org/packages/1e/db/…/requests-2.32.5-py3-none-any.whl $ uv pip install numpy --verbose --no-cache 2>&1 | grep -F '.whl' DEBUG Selecting: numpy==2.2.1 [compatible] (numpy-2.2.1-cp312-cp312-macosx_14_0_arm64.whl) 文件名里的 py3-none-any 是三个标签。意思是任何 Python 3、任何操作系统、任何架构都能用。含编译代码的包则和平台绑定。 cp312-cp312-macosx_14_0_arm64 只给 macOS 14 以上、ARM64 上的 CPython 3.12，也就是 Apple Silicon。换个平台，pip 会下载另一个 wheel。或者从源码构建（讲义）。 为什么会在这里踩坑 在 Mac 上下载好 wheel，拷到 Linux 服务器上装，会报平台不支持。原因就写在文件名里，比如 macosx_14_0_arm64 。只有纯 Python 的包才是 none-any 。带编译代码的包，要按目标平台另下一份。"}, {"u": "ch06.html#s20", "c": "第 6 讲 · 打包与交付代码", "t": "发布到注册表，别人一条命令就能装", "x": "PyPI、npm、Docker Hub 这些都是注册表。 uv publish 把包传上去，别人就能按名字安装。 bash · 写法示意 uv build # 先产出 dist/ 里的 wheel 和 sdist uv publish --publish-url https://test.pypi.org/legacy/ # 传到练习用的 TestPyPI，要 token uv pip install --index-url https://test.pypi.org/simple/ greeting # 别人这样装 打个比方 注册表像应用商店。你把 App 交上去，商店登记版本号和校验和。用户搜名字就能下载，还能确认下到的是你那一份。 要让别人找得到你的包，就要把它发布到注册表（registry）。Python 的主注册表是 PyPI。pip 帮不了这一步，uv 可以： 讲义原文 $ uv publish --publish-url https://test.pypi.org/legacy/ Publishing greeting-0.1.0.tar.gz Publishing greeting-0.1.0-py3-none-any.whl $ uv pip install --index-url https://test.pypi.org/simple/ greeting TestPyPI 是一个独立的练习用注册表。专门用来测发布流程，不会污染真正的 PyPI。视频里 greeting 这个名字已经被人占了。讲师改用 missing-semester 包演示。上传前，他把版本号比上次测试升了一个 patch（ ）。本机没有 TestPyPI 账号，只跑了不上传的 --dry-run ，见练习 5 的 ex05-a： bash · 本机实测 $ uv publish --dry-run --trusted-publishing never --publish-url https://test.pypi.org/legacy/ dist/* Checking 2 files against https://test.pypi.org/legacy/ Checking greeting-0.1.0-py3-none-any.whl (1.5KiB) Uploading greeting-0.1.0-py3-none-any.whl (1.5KiB) Checking greeting-0.1.0.tar.gz (1.0KiB) Uploading greeting-0.1.0.tar.gz (1.0KiB) dry-run 下会打印 Uploading，但不会真的上传。见 uv help publish 对 --dry-run 的说明。 信任 ：用户怎么确认，下载的包真的来自你，没被篡改？注册表用 校验和 验证完整性。有的生态还支持 包签名 （讲义）。它用密码学证明作者身份。 各语言的注册表 ：Rust 有 crates.io ，JavaScript 有 npm ，Ruby 有 RubyGems 。容器镜像有 Docker Hub 。私有或内部的包，组织会自建仓库。比如私有 PyPI 和私有镜像仓库。也可以用云厂商的托管服务。 Docker 镜像 ：只能推到你有权限的注册表（ ）。讲师只能推以自己用户名开头的镜像。所以先按这个规则重新打标签，再 docker push 。之前推过的层会被跳过。之后谁都能从 Docker Hub 拉下这个镜像。里面是完整的文件系统。 问答：怎么和同学共享镜像？ 用镜像仓库（container registry）（ ）。Docker Hub 不是唯一的，GitHub 也有。只要双方都能访问同一个仓库，就能 push 和 pull。读取私有内容要认证，证明你是你，而且你有权限。 把 Web 服务部署到互联网，还需要更多基础设施。要注册域名，配置 DNS 指向服务器。通常还要 nginx 这样的反向代理，处理 HTTPS 和路由流量。文档、静态网站这类简单场景，用 GitHub Pages 就够了。它直接从仓库免费托管（讲义，练习 6）。 为什么会在这里踩坑 同一个版本号不能重复上传。传错了想覆盖 0.1.0，注册表会拒绝。只能把版本升到 0.1.1 再传。讲师现场也是先升了 patch 才上传的。"}, {"u": "ch06.html#s21", "c": "第 6 讲 · 打包与交付代码", "t": "一页带走：构件加上它对环境的假设", "x": "把本讲浓缩成几行命令。每行的注释就是结论和考点。 bash · 本讲速查（注释即考点） source venv/bin/activate # 激活就是把 venv/bin 插到 PATH 最前面 bash venv/bin/activate # 白跑：子进程改完 PATH 就退出了，必须 source uv pip install . # 按 pyproject.toml 把包装进当前环境 uv build # 产出 sdist 和 wheel，wheel 就是带元数据的 zip \"1.10.0\" > \"1.9.0\" # 当字符串比是 False，版本号要按整数逐段比 ^0.2.3 # 等于 >=0.2.3,<0.3.0，不允许升到 0.3.0 pandas~=2.1.0 # 等于 >=2.1.0,<2.2.0，不允许 2.2.0 dependencies = [\"typer>=0.9\"] # 库写范围给用户留余地，应用靠锁文件钉死 uv lock && uv sync --locked # 不同时间解析结果不同，锁文件记下确切版本和哈希 COPY pyproject.toml uv.lock ./ # 依赖层放前面，改一行源码，这层照样命中缓存 docker run python:3.12 uname -r # 容器共享宿主内核，所以轻。代价是隔离更弱 redis://cache:6379 # 容器里连别的服务用服务名，localhost 是自己 systemctl enable myapp # WantedBy 要 enable 才会开机自启（补充） 交付代码，就是定义构件，再说清它对环境的假设。 安装器查索引、选构件、递归解析依赖，再下载安装。约束的交集为空，就是依赖地狱。用 每个项目一个环境 来隔离。 虚拟环境只是一个目录。激活就是把它的 bin 或 Scripts 插到 PATH 最前面，必须 source 。 pyproject.toml 描述项目。 uv build 产出 sdist 和 wheel。wheel 是带元数据的 zip，文件名里的标签说明适用平台。 SemVer 里，PATCH 修 bug，MINOR 加功能，MAJOR 破坏兼容。版本号按整数逐段比。库写范围，应用钉死。 锁文件记着整棵树的确切版本和哈希。 uv sync 照着装，结果可复现。 VM 交付整个操作系统。容器共享内核，只隔离应用层。Dockerfile 每条指令一层，层可以缓存。 Compose 声明多个服务和它们的依赖顺序。配置在运行时注入，密钥不进版本控制。systemd 负责开机自启。 发布到 PyPI 或 TestPyPI、GitHub、镜像仓库。用校验和与签名建立信任。 下一步 这一讲把前几讲的工具串到了交付这一步。虚拟环境靠的是第 1、2 讲的 PATH 和环境变量。第 5 讲 Git 的标签，对应发布的版本。第 9 讲的持续集成，会自动跑构建和测试。下一讲是智能体编程。它也能帮你写 Dockerfile 和 systemd 单元这类专用语法。现在去做 本讲练习的可视化笔记 。"}, {"u": "ch07.html", "c": "第 7 讲 · 智能体编程", "t": "开头", "x": "本讲结论 编码智能体由两部分组成。一是 语言模型 ，它按上下文给出续写的概率。二是 harness 。它在循环里调用模型，替模型读写文件、跑命令。然后把结果喂回给模型。懂了这一点，就懂了三件事。一是为什么要审批工具调用。二是为什么要管理上下文。三是为什么它会犯错。"}, {"u": "ch07.html#s1", "c": "第 7 讲 · 智能体编程", "t": "智能体自己读、改、跑，你只管审批", "x": "编码智能体会自己调用工具。它读文件、改代码、跑检查，最后向你报告。你要做的，是下指令和审批。 最小例子（示意） $ claude # 在项目目录里启动智能体，讲师用的是 Claude Code > Turn this into a proper command-line program ... # 用大白话下任务 # 它先读 dl.py，再整份改写，再跑 mypy，最后自己运行一遍 # 改文件不问你，跑 bash 每条都要你确认：这是讲师的配置 打个比方 像请了个装修师傅。他自己量尺寸、买材料、动手干。你只在他拆墙之前点个头。 第 3 讲讲了 AI 自动补全和行内对话（inline chat）。这一讲讲更强的形态： 编码智能体 （coding agent）。讲义的定义是这样的。它是一个对话式 AI 模型，能使用工具。工具包括读写文件、网页搜索和执行 shell 命令。它可以嵌在 IDE 里，也可以是独立的命令行或图形程序。它的自主程度很高。 演示接着用第 3 讲的例子。那是一个从课程网页抓链接的小脚本，下面是讲义原文： dl.py（讲义原文） from urllib.request import urlopen def download_contents(url: str) -> str: with urlopen(url) as response: return response.read().decode('utf-8') def extract(content: str) -> list[str]: import re pattern = r'\\[.*?\\]\\((.*?)\\)' return re.findall(pattern, content) print(extract(download_contents(\"https://raw.githubusercontent.com/missing-semester/missing-semester/refs/heads/master/_2026/development-environment.md\"))) 讲师在终端里启动 Claude Code，用自然语言下任务。讲义给出的提示词是： 提示词（讲义原文） Turn this into a proper command-line program, with argparse for argument parsing. Add type annotations, and make sure the program passes type checking. 智能体先调用工具 读 dl.py。然后一次改写整个文件。它加上了 main 函数和参数解析（ ）。 接着按要求调用 mypy 做类型检查。改文件时它没问讲师。讲师的配置是“编辑文件不用批准”。他用 Git 跟踪一切，事后统一审查。但 bash 这类会改动电脑状态的命令， 每一条都要他确认 。免得它删掉重要文件（ ）。 类型检查通过后，它又主动跑了一遍脚本，确认能用。然后报告完成（ ）。 本机实测：原版 dl.py 过不了严格类型检查 讲义说，类型检查失败时，它“很可能会继续迭代”。笔记在本机用 mypy --strict 查了两份代码。一份是原版，一份是练习 1 的手写版（ex01-b）： bash · 本机实测（mypy 只装在沙箱 venv 里） $ .venv/Scripts/mypy --strict dl_cli.py # 手写版：通过 Success: no issues found in 1 source file $ .venv/Scripts/mypy --strict dl.py # 讲义原版：报 no-any-return dl.py:5: error: Returning Any from function declared to return \"str\" [no-any-return] Found 1 error in 1 file (checked 1 source file) 类型检查器认为 response.read() 返回 Any。手写版先把它标注成 bytes ，再 decode，就通过了。这正是那种适合让模型在反馈回路里自己迭代的错误。 讲义的小提示 智能体走错了，就直接用文字纠正它。比如 PATH 上明明有 mypy ，它却去调 python -m mypy 。还可以让它接着跑脚本、看输出，再提个修改。比如“只保留绝对 URL”。 讲义推荐的编码智能体 很多 IDE 和 AI 编程插件都内置了智能体，见第 3 讲。其他流行的有 Anthropic 的 Claude Code 、OpenAI 的 Codex ，还有开源的 opencode 。讲师个人偏好命令行形态的智能体。本讲演示用的是 Claude Code。 为什么会在这里踩坑 图省事把所有权限都放开，最容易出事。它跑的是你机器上的真命令，删错文件撤不回来。讲师的折中是：文件改动有 Git 兜底，所以放行。bash 命令什么都能干，所以逐条确认。"}, {"u": "ch07.html#s2", "c": "第 7 讲 · 智能体编程", "t": "智能体按用量花钱，基本离不开云端模型", "x": "好用的模型都在云端，按用量或订阅付费。讲师开场那个任务，大约花了 19 美分。 最小例子（示意） /cost # Claude Code 里查本次会话花了多少，开场任务约 19 美分 # 想省钱：换小而快的模型，或者在服务商那里设每月上限 # 本地模型能离线跑，但能力差得多，难任务效果不好 打个比方 像打车。车越好越贵，按里程计费。也可以办月卡，超了再说。自己骑车不花钱，就是跑不了远路。 问题 讲师的回答（视频） 能限制花费吗？ 能，各工具的设置不同。可以选模型，强的贵，小而快的便宜。有的服务能设每月上限。他自己不设上限，而是盯着用量。Claude Code 里有 /cost 命令。刚才那个任务花了大约 19 美分（ ）。 学生怎么入门？ 可以先买每月 20 美元左右的订阅，含一定用量。超出了，再想想自己的用法。很多公司觉得，比起工程师的时间，工具费不算高。 一定要联网、付费吗？ 基本是。也可以在本机跑本地模型，但能力低得多。简单任务还行，难任务效果不好。现阶段用托管模型更实际（ ）。 本笔记 不调用任何付费 API 或智能体 。需要账号的步骤，练习页只给做法和验收标准。不编造使用体验。 为什么会在这里踩坑（补充） 在大仓库里反复读文件、跑测试，花费涨得很快。因为每次推理，都要把整段上下文再发一遍。所以时不时看一眼 /cost 。"}, {"u": "ch07.html#s3", "c": "第 7 讲 · 智能体编程", "t": "它记得前面的对话，走偏了随时打断", "x": "智能体保留之前的对话，可以接着下指令。看它走偏了，就按 Ctrl + C 打断，补一句话纠正。 最小例子（示意） > 把类型注解删掉 # 多轮：接着上一轮说，它知道指的是哪个文件 ^C # 它想太久或乱调工具，Ctrl+C 打断 > mypy 装在这里，这样调用 # 补一句纠正，它接着干 > 除了这个函数，其他都别动 # 没法硬性禁止它改某段代码，只能这样说 打个比方 像带一个实习生，这是讲义给的心智模型。脏活累活他干，但需要你指路。偶尔做错了，你得纠正。 多轮 ：智能体保留之前的对话，可以接着下指令。讲师故意让它“把类型注解删掉”。它照做了（ ）。更实际的用法是这样的。需求还不清楚时，先给个大概。看了结果，再一点点调整。 打断 ：看它走偏、想得太久或乱调工具，就按 Ctrl + C 打断。这是讲师那个工具的按键。再补一句，比如“mypy 装在这里，这样调用”（ ）。 问：能禁止它碰某个文件吗？ 讲师用的工具，做不到“硬性禁止改某段代码”。他的做法是一切交给 Git 跟踪，改了不该改的就 revert。也可以用自然语言说“除了这个函数，其他都别动”。它一般会遵守（ ）。 问：测试驱动开发好用吗？ 好用。自己写测试，或者让智能体帮你写。再让它实现，直到测试通过。智能体在 反馈回路 里特别能干。把报错和复现命令给它，让它一直改到通过（ ）。 为什么会在这里踩坑 看它走偏了还不打断，最费事。等它跑完再说“别这样”，已经晚了。走错的那些步骤都留在上下文里，会接着干扰它。早打断，早纠正。"}, {"u": "ch07.html#s4", "c": "第 7 讲 · 智能体编程", "t": "语言模型只是条件概率分布，推理就是抽样", "x": "LLM 拿到提示 x，算出各种续写 y 的概率。用它的时候，就是按概率抽一个续写出来。 python · 最小例子（示意，sample 是假想函数） history = [\"User: 1+1 等于几？\"] reply = sample(llm, history) # 按概率抽一个续写，多半是 \"2\" history += [reply, \"User: 把 1 都换成 2 呢？\"] reply = sample(llm, history) # 整段历史再发一遍，它才“记得”上文 打个比方 像手机输入法的联想词。它只管猜下一个词最可能是什么，然后挑一个。它“记得”上文，只因为每次都重发了整段记录。 讲师说要讲到“刚好够用”的抽象层次。不教你自己实现，但让你明白三件事。它擅长什么，局限在哪，harness 为什么有那些功能。编码智能体大致分两部分。底层是 语言模型 ，外面包着一层 agent harness 。 LLM 是什么 把 LLM 看成一个条件概率分布 π θ (y | x)。x 是提示字符串，y 是续写字符串。使用它就是从分布里 抽样 ：ŷ ~ π θ (· | x)。讲师说，“这就是 AI 语言模型的全部”。大量工作，都花在让这个分布有用上（ ）。 上下文窗口 LLM 有一个固定的 上下文窗口 （context window）。输入串和输出串的长度都有上限（ ）。后面讲的“上下文管理”，全都源于这一点。 那聊天应用怎么支持追问？讲师在黑板上举了个例子。用户问“1 + 1 等于几”，模型答“2”。用户再问“把 1 都换成 2 呢？”。单看这一句，没法回答。 办法是给每条消息加上 轮次标记 （turn marker）。每次都把 整段对话历史 当成新的输入 x（ ）。然后再推理一次。讲义的说法也一样。每来一条新的用户提示，就推理一次。提示串就是完整的历史。 下面的演示分两幕。第一幕看一次推理怎么抽样。第二幕看多轮对话怎么拼接历史。 为什么会在这里踩坑 以为模型有记忆，是最常见的误解。它“记得”上一轮，只因为应用把历史又发了一遍。所以对话越长，每次推理的输入越长。最后会撞上上下文窗口。同一个问题问两次，答案也可能不同。因为每次都是抽样。"}, {"u": "ch07.html#s5", "c": "第 7 讲 · 智能体编程", "t": "harness 在循环里调模型、跑工具、喂回结果", "x": "模型除了输出文字，还能输出“调用工具”的请求。harness 真的去执行，把结果追加进上下文，再推理一次。直到模型输出给用户的文字。 python · 最小例子（示意，简化自练习页的 mini_harness.py） while True: out = llm(ctx) # 把整个上下文发给模型，推理一次 if out.is_text: break # 模型输出了文字：循环结束，控制权交还用户 ctx += [out, run_tool(out)] # 是工具调用：在你的机器上真的执行，结果追加回去 打个比方 模型像只会写纸条的军师，自己不出门。harness 是跑腿的。军师写“去查一下 dl.py”，跑腿的去查，把结果塞回来。军师再写下一张，直到写出“汇报完毕”。 再加一个想法：对模型的输出做特殊解释。模型除了给用户写文字，还能输出“调用工具”的请求。它被训练得会输出这种请求。比如“运行 mypy dl.py ”（ ）。包在模型外面的那层代码，叫 agent harness ，也叫 scaffolding。它做两件事（ ）： 在循环里调用 LLM，拿到输出。 如果输出是工具调用，就 在你的机器上真的执行 。工具输出会作为新的输入追加进去，再推理一次。比如 mypy 打印的“error line 1, expected int…”。直到模型输出给用户的文字，控制权才回到用户。 讲师回看开场演示时的拆解（视频 23:52 到 26:26）。一个用户提示背后，是多次 LLM 推理和多次工具调用 写文件的工具 ：在 Claude Code 里，模型可以给出一个 diff。diff 就是一段文字，由 harness 解释并应用到文件上（ ）。 问：harness 和模型之间有标准接口吗？ 不算完全标准化，但互通性不错。比如开源的 opencode，能配合不同家的模型（ ）。Anthropic 和 OpenAI 的都行。 问：模型是随机的，harness 是确定的，它们怎么配合？ 靠抽样。harness 每次调用模型，都是抽一个输出，再据此行动。模型并不像人那样聪明。有时它会调用你机器上没有的命令。有时会写出错误的代码。但实践中效果相当不错（ ）。 补充实验：50 多行的 harness 骨架（练习页补充） 讲义说，tool-calling 智能体的核心概念， 200 行代码就能实现 。练习页的 mini_harness.py 把它缩到最小。工具是真的。“模型”是假的，按顺序吐出预设的回复。所以结果能复现。本机实测输出如下： bash · 本机实测（练习页 extra-a） $ python ../extra/mini_harness.py --approve \"检查 dl.py 能否编译\" [推理 #1] 输入 1 条 / 25 字节 → {\"tool\": \"read_file\", \"args\": {\"path\": \"dl.py\"}} [harness] 执行 read_file → 结果 444 字节：from urllib.request import urlopen [推理 #2] 输入 3 条 / 517 字节 → {\"tool\": \"run\", \"args\": {\"argv\": [\"python\", \"-m\", \"py_compile\", \"dl.py\"]}} [harness] 执行 run → 结果 8 字节：(exit 0) [推理 #3] 输入 5 条 / 599 字节 → {\"tool\": \"run\", \"args\": {\"argv\": [\"grep\", \"-c\", \"^def \", \"dl.py\"]}} [harness] 执行 run → 结果 10 字节：2 [推理 #4] 输入 7 条 / 676 字节 → {\"text\": \"dl.py 能通过编译，里面定义了 2 个函数。\"} [harness] 模型输出了文本而不是工具调用：本轮结束，控制权交还用户 注意每次推理的输入都在变长。这就是上下文。 下面的演示用这段真跑输出，一步步走完循环。最后一步看拒绝运行命令时会怎样。 为什么会在这里踩坑 以为一句请求只调一次模型，就会低估时间和花费。上面一个请求背后，是 4 次推理、3 次工具调用。每次推理都带着越来越长的上下文。还有一个坑。harness 执行的是真命令，模型却可能编出不存在的命令。所以命令要审。"}, {"u": "ch07.html#s6", "c": "第 7 讲 · 智能体编程", "t": "推理在云端，上下文里有什么就上传什么", "x": "强模型要很强的硬件，基本都在云端推理。每次推理都要上传整个上下文。你的提示、它读过的文件、命令输出，都在里面。 三种选择（示意） # 默认：上下文整段发给服务商，可能被保存，甚至用于训练 # 另有协议或隐私配置：先读条款，看清它到底保证了什么 # 开源 harness 加本地开源模型：数据不出电脑，代价是能力弱、硬件跑不动 打个比方 像把作业拍照发给网上的家教。你拍进去的每一页，他都看得到。拍得越多，他知道得越多。 能力强的模型需要很强的硬件来推理。所以它们基本都在云端运行。除非另有协议，你就是在把数据发给服务商。他们可能拿去训练。在意隐私，就去读条款。或者找一套适合你的配置（ ）。 讲义提到，多数 AI 编码工具默认会把大量数据发到云端。有时 harness 在本地，推理在云端。有时更多部分在云端。服务商可能拿到了你 整个仓库的副本 。还有你和工具的全部交互。 问：Claude 既是模型又是 harness 吗？ 组合有好几种。在这个例子里，harness 的一部分可以看作和模型一起在云端。也有开源 harness 完全在本地运行。但每次推理，数据照样发到云端（ ）。 讲义还说，开源的编码工具和开源 LLM 已经相当不错。只是还比不上专有模型。可对多数人来说，硬件跑不动最前沿的开源模型。 下面的演示画出数据的流向。看哪些内容离开了你的电脑。 为什么会在这里踩坑 让智能体读了 .env 或密钥文件，这些内容就进了上下文。下一次推理，它们就跟着请求上传了。所以别让它碰不该外传的文件。公司的代码，先问清楚能不能用云端工具。"}, {"u": "ch07.html#s7", "c": "第 7 讲 · 智能体编程", "t": "写清规格、给它测试，它就能自己改到通过", "x": "实现功能，先写好测试再让它实现。修错误，让它能自己运行失败的检查。处在反馈回路里，它就会自己迭代。 最小例子（提示词取自视频和讲义） > make it look retro # 开放式指令：讲师对课程网站只说了这一句 > fix the issues with mypy # 修错误：它自己跑 mypy、看报错、改代码、再跑 > commit the changes # 它先看 status、diff 和 log，再仿照仓库风格写提交信息 打个比方 像给学生发一份带标准答案的练习册。他做完自己对答案，错了接着改。不用你一道道批。 实现新功能 。指令可以很具体，也可以很开放，再慢慢迭代。讲师在课程网站仓库里只说了一句 make it look retro 。意思是让它看起来复古一点。然后就让它去跑了（ ）。 讲义说，写好规格说明“更像艺术而非科学”。要描述得足够让它朝对的方向走。但不要细到你自己把活干完了。 测试驱动 尤其有效。先写测试，或者让智能体帮你写。审查测试确实表达了你要的东西，再让它实现。 模型在不断进步。你对它能做什么的直觉，也要跟着更新。课程网站的 Tufte 风格旁注，就是用 Claude Code 实现的 。 修复错误 。编译器、linter、类型检查器或测试报错时，可以直接说 fix the issues with mypy 。关键是把它放进 反馈回路 。模型能自己运行失败的检查，就能自主迭代。做不到时，你再手动反馈。 讲义举了个例子。在某个提交上，让 Claude Code 查本讲讲义的错字和语法： Review the agentic coding lecture for typos and grammatical issues 。再让它修复。修复被提交为 f1e1c41 。 视频 28:42 到 32:47 的修 bug 演示。讲师手写了失败的测试。智能体复现、阅读、修改、跑回归测试。最后按仓库风格写提交信息 讲师说这种演示不好做。智能体不算快，修这个 bug 跑了一分多钟。让它又快又好，是很多人正在研究的方向（ ）。 让它 commit the changes 时，它先看 git status 和 git diff ，确认改动是自己做的。再看 git log ，模仿已有提交信息的风格。讲师说，“它学会了不要瞎编提交信息”（ ）。 为什么会在这里踩坑 测试写错了，智能体就会朝错的方向使劲。它还可能为了让测试通过，去改测试本身。所以测试要你亲自审过，再交给它。练习 3 专门防了这一手。"}, {"u": "ch07.html#s8", "c": "第 7 讲 · 智能体编程", "t": "提示词很关键，工作范围一般是整个仓库", "x": "提示词会影响代码质量、啰嗦程度和耗时。智能体大体能看到启动目录下的所有子目录。 最小例子（示意） $ cd my-repo && claude # 一般以 Git 仓库为单位启动，它大体能看到所有子目录 > 有个 bug，修它 # 现在的模型，一句话就能自己搞定 > 读 PRD.md，写实现计划，再实现 # 复杂功能：先写一份需求文档交给它 打个比方 提示词像给外包写的需求单。小活一句话就行。大活得写清楚，不然交回来的东西对不上。 提示词会影响代码质量、啰嗦程度和耗时吗？ 绝对会，而且目前更像艺术而非科学。模型在不断进步。两年前的旧模型，得手把手描述。现在一句“有个 bug，修它”，它就能自己搞定。复杂、严肃的功能，可能要好几段提示。甚至得戴上产品经理的帽子，写一份 PRD。PRD 就是产品需求文档。再让它“读懂、写实现计划、再实现”（ ）。 在某个目录启动，它能看到所有子目录吗？ 大体上是。有些还能请求访问目录外的东西，各工具细节不同。一般以 Git 仓库为单位来用（ ）。 为什么会在这里踩坑 在家目录里启动智能体，它就能看到整个家目录。读到什么，什么就可能进上下文、被上传。所以要在具体项目的目录里启动。"}, {"u": "ch07.html#s9", "c": "第 7 讲 · 智能体编程", "t": "重构、评审、读代码、当 shell，结果都要审", "x": "这几种用法是一个路子。用大白话把活交给它，再审它交回来的结果。 最小例子（示意） > review my latest changes that are not yet committed # 代码评审（讲义的提示词） > explain this code base to me # 上手陌生代码库 > 用 find 找出 30 天前的文件 # 当 shell 用，不用记参数 打个比方 像有个熟悉各种工具的室友。你说“帮我把照片都缩小一半”，他知道该用哪个命令。但他递回来的东西，你得自己看一眼。 用例 要点 重构 从改方法名，到把一块功能拆成独立模块。改方法名，第 3 讲的代码智能也能做。本讲就是让 Claude Code 从“开发环境”一讲里拆出来的。做得还行，但不完美。有些练习没搬对位置，有的直接消失了。讲师手动恢复了它们（ PR #344 ， ）。 代码评审 给一点指导，就能得到有用的反馈。比如 review my latest changes that are not yet committed 。如果它能 web fetch，或者装了 GitHub CLI ，还能直接审 PR。提示词是 Review the pull request {链接} 。讲师常在性能优化、重构这类场景里让它审查。这类改动前后，语义应当等价。它真的抓到过细微的行为差异（ ）。 读懂代码库 适合上手陌生项目。比如参加开源，或者加入实验室的代码库（UROP）。可以说 explain this code base to me 。也可以问“这个功能该改哪些文件”（ ）。 当 shell 用 不必记住各种命令和参数。直接说“用 find 找出 30 天前的文件”。或者说“用 mogrify 把所有 jpg 缩小一半”。讲师现场演示了一次。先让它“用 ag 找出所有带重命名导入的 Python 文件”。重命名导入就是 import x as y 。再追加一句“忽略 lib 目录”。它生成命令、运行，再总结结果（ ）。 问答：课程作业里能用吗？（ ） 先问你的老师。有的课禁止任何 AI 工具，连自动补全和行内对话都不行。有的课随便用。请遵守规则，别作弊。有些公司为学业场景推出了特殊模式。它不直接给答案，更像助教。没有这种模式也没关系。你可以说“有个 bug，别告诉我在哪，给我指个方向”。把它当成替补助教。 为什么会在这里踩坑 让它“当 shell 用”最省事，也最容易翻车。它生成的命令，会直接在你机器上跑。批量删文件、改图片，跑完就撤不回来。先看清它要执行的命令，再批准。"}, {"u": "ch07.html#s10", "c": "第 7 讲 · 智能体编程", "t": "氛围编程：一行代码不写，只用英语聊", "x": "智能体已经强到能从头到尾实现整个项目。你一行代码都不写，只用英语和它聊。 最小例子（示意） > make it look retro # 高层描述：讲师对课程网站说的就这一句 # 看结果，不满意就再提修改，循环几轮 # 前端、网页设计这类创意活，这样做效果非常好 打个比方 像跟设计师说“我想要复古一点的感觉”。你不画图，只看稿子提意见。改到满意为止。 make it look retro 就是个小例子。讲义链接了一位讲师 完全靠氛围编程做出的真实项目 。课程网站的旁注功能也是这么做的。讲师说，负责的人“一行代码都没自己写”（ ）。前端、网页设计这类创意工作，很适合这么做。给个高层描述，看结果，再提修改，效果非常好。练习 3 就是做一次。 为什么会在这里踩坑 “一行都不写”不等于“不用管”。你不看代码，就更难发现它悄悄写错的地方。所以先写好需求和验收测试，再让它去氛围编程。练习 3 就是这么安排的。"}, {"u": "ch07.html#s11", "c": "第 7 讲 · 智能体编程", "t": "常敲的一段话存起来，一键调用", "x": "反复对智能体说的同一段话，可以存起来。之后一键调用。在 Codex 和 Claude Code 里，这个功能已被技能取代。 最小例子（示意） # 每次评审都要敲的一段话（讲师的例子）： 关注代码质量和正确性，安全在这个项目里不太重要…… # 存成可复用提示或技能，之后一键调用，不用到处复制粘贴 打个比方 像输入法里的自定义短语。敲个缩写，整段话就出来了。 你可能经常对智能体敲同一段话。比如每次评审都要说：“关注代码质量和正确性。安全在这个项目里不太重要……”。多数工具支持把整段提示存起来，之后一键调用。不用再从某个文本文件里复制粘贴。 讲义提醒，工具演进很快。有些工具里，“可复用提示”这个独立功能已被弃用。在 Codex 和 Claude Code 里，它被 技能（skills） 取代了，见 第 16 节 。 为什么会在这里踩坑 把同一段长提示到处复制粘贴，版本很快就乱了。这里改了，那里忘了改。存成一份，每次都调用它，才好维护。"}, {"u": "ch07.html#s12", "c": "第 7 讲 · 智能体编程", "t": "并行跑多个智能体，用 worktree 各占一个目录", "x": "智能体一干就是二三十分钟，可以同时开好几个。git worktree 给每个智能体一份独立的目录和分支，互不干扰。 bash · 最小例子（示意） git worktree add -b bugfix ../wt-bugfix # 新目录加新分支，共享同一个仓库 git worktree add -b retro ../wt-retro cd ../wt-bugfix && claude # 每个目录里各开一个智能体 # 各自提交到各自的分支，最后再合并（第 5 讲） 打个比方 像几个装修队同时干活。各自包一个房间，互不进门。最后再一起验收。 智能体可能一干就是 20、30 分钟，没必要干看着。可以同时启动好几个。一个修 bug，一个写功能 A，一个写功能 B。也可以让几份智能体做 同一个 任务，挑最好的结果。LLM 是随机的，多跑几次有好处（讲义）。讲课时，讲师就同时开着两个 Claude。一个把网站改复古，一个修 bug（ ）。 多个智能体在同一个目录里改文件，会互相冲突。在 Git 仓库里， git worktree 能创建完全独立的检出。也就是一个新目录，加一个新分支。在各自目录里启动智能体，提交到各自的分支。最后再合并，见第 5 讲。练习 1 用它给“四种做法”各建一个工作区。下面是本机实测： bash · 本机实测（练习 1 · ex01-a，节选） $ git worktree add -q -b \"$mode\" \"../wt-$mode\" # 循环 4 次 $ git worktree list <沙箱>/ex01/task 015fb06 [main] <沙箱>/ex01/wt-agent 015fb06 [agent] <沙箱>/ex01/wt-autocomplete 015fb06 [autocomplete] <沙箱>/ex01/wt-hand 015fb06 [hand] <沙箱>/ex01/wt-inline 015fb06 [inline] 下面的演示先看冲突，再看 worktree 怎么把智能体隔开。 为什么会在这里踩坑 两个智能体开在同一个目录，会同时改同一批文件。一个刚改好，另一个就覆盖掉了。用 worktree 隔开，才能各干各的。合并时如果改了同一处，照样会冲突，按第 5 讲处理。"}, {"u": "ch07.html#s13", "c": "第 7 讲 · 智能体编程", "t": "MCP 是把智能体接到外部工具的标准协议", "x": "harness 和工具之间，有一个标准协议叫 MCP。装上某个 MCP server，智能体就能用它提供的工具。 最小例子（讲义的例子） > 读 Notion 里这份规格 # 前提：装了 Notion MCP server > 在 Notion 里新建一页，写实现计划 > 再实现一个原型 # 讲义里这三步是一句话说完的 打个比方 MCP 像电器的标准插座。工具做成标准插头，哪个智能体都能插上用。 前面问到 harness 和模型之间的接口。和它相关的还有一件事。连接 harness 和 工具 ，也有一个标准协议。它叫 MCP，全称 Model Context Protocol。比如 Notion MCP server 能让智能体读写 Notion 文档。找 MCP 可以去 Pulse 、 Glama 这类目录（讲义）。 为什么会在这里踩坑（补充） MCP server 给智能体接上了新能力，也接上了新风险。它能读写你账号里的数据。装之前看清来源，就像对待第 3 讲的编辑器扩展一样。"}, {"u": "ch07.html#s14", "c": "第 7 讲 · 智能体编程", "t": "上下文越满模型越差，换任务就清空", "x": "上下文塞得越多，模型越容易分心。做不相关的事，就清空。走错了路就回退，把最近几步从历史里弹出去。 最小例子（示意） /clear # 清空上下文，开始新任务（Claude Code 的命令，补充） # 回退：把消息从历史末尾弹出去，假装没发生过 # 比追加一句“别这么做了”更省上下文 打个比方 上下文像一张草稿纸。写满了，新东西就挤不下。没写满，乱涂的地方多了也看花眼。换题就换张新纸，写错了就擦掉。 回到“模型有固定的上下文窗口”。比如它只支持 10 万个 token 的输入。实践中，即使没超出窗口，输入太多也会让任务变难。上下文被“污染”了。管好输入，模型通常表现更好（ ）。 讲义的总结是这样的。让智能体拿到需要的信息，但避免不必要的内容。不然会撑爆窗口，或者降低表现。harness 会自动提供并管理一部分上下文。但大量控制权在用户手里。 清空 ：最基本的控制。聊天时，消息只会越积越多。编码智能体还会把每次工具调用和输出都加进去。做一件和之前无关的事，就杀掉重启。或者用命令清空上下文（ ）。 回退 ：你让它做了某事，又改主意了。可以打断它，再追加一条指令。但它已经做的那些都还在上下文里，没用还添乱。多数 harness 有回退命令。它把消息从历史末尾“弹出去”（ ）。就当没发生过。 下面的演示把上下文画成一根纸带。看它怎么被塞满，再怎么回退和清空。 为什么会在这里踩坑 一个会话从早用到晚，什么都往里塞。模型就越来越糊涂。前面无关的文件、失败的尝试，都在分散它的注意力。换任务就清空，这是最该养成的习惯。"}, {"u": "ch07.html#s15", "c": "第 7 讲 · 智能体编程", "t": "对话太长就压缩成摘要，查新库读 llms.txt", "x": "对话太长时，harness 用 LLM 把历史前缀总结成摘要。摘要替换掉原来的历史。模型不知道新库，就把 llms.txt 这种纯文本文档放进上下文。 最小例子（示意） /compact # Claude Code 里手动压缩，还能看到压缩后的摘要 # 同一件事没做完：压缩，接着干。换不相关的事：直接清空 https://ai.pydantic.dev/llms.txt # 给 LLM 读的纯文本文档，比原始 HTML 省上下文 打个比方 压缩像开会时的会议纪要。三小时的讨论记成半页纸，后来的人看纪要就够了。llms.txt 像说明书的精简版，没有广告和花边，全是干货。 压缩 （compaction）。窗口有限，怎么支持无限长的对话？对话很长时，聊天工具和编码智能体会调用 LLM。可以自动触发，也可以手动触发。它把 历史前缀 总结成摘要，再用摘要替换原来的历史。Claude Code 里可以手动用 /compact ，还能看到摘要长什么样。讲师建议你自己试试。来回聊几轮，让它调几次工具。再压缩，看看摘要（ ）。 问答：该压缩，还是新开会话？（ ） 更像艺术而非科学。还在做同一件事，就继续，LLM 写的摘要通常相当不错。要做不相关的事，就清空上下文。别留一堆没用的东西，哪怕只是摘要。 bash · 本机实测（练习页 extra-c，窗口设成 600 字节） $ python ../extra/mini_harness.py --approve --limit 600 \"检查 dl.py 能否编译\" … [推理 #3] 输入 5 条 / 599 字节 → {\"tool\": \"run\", \"args\": {\"argv\": [\"grep\", \"-c\", \"^def \", \"dl.py\"]}} [harness] 执行 run → 结果 10 字节：2 [harness] 上下文 676 字节 > 上限 600：压缩成 2 条 / 112 字节 [推理 #4] 输入 2 条 / 112 字节 → {\"text\": \"dl.py 能通过编译，里面定义了 2 个函数。\"} 下面的演示用这段真跑输出。看上下文怎么超限，又怎么被压缩。 llms.txt 。模型训练完就被“冻结”了。它有一个 知识截止日期 （knowledge cutoff）。让它用昨天才发布的库，它一无所知。办法是在推理时，把资料放进上下文。给它一个文档链接，让它用 web fetch 工具去读（ ）。 可直接抓 HTML 很啰嗦。样式、统计脚本，对任务毫无用处。 /llms.txt 是一个提议中的标准位置。那里放给 LLM 在推理时读的纯文本文档。比如 cursor.com/llms.txt 、 ai.pydantic.dev/llms.txt 、 apify.com/llms.txt 。每个 token 的信息密度更高，也更省上下文。模型表现也更好（ ）。 为什么会在这里踩坑 模型说某个库“没有这个函数”，不一定是你写错了。可能是库在它的知识截止日期之后才更新。别跟它争，把最新文档喂给它。优先用 llms.txt，别让它啃整页 HTML。"}, {"u": "ch07.html#s16", "c": "第 7 讲 · 智能体编程", "t": "AGENTS.md 每次全文加载，技能用到才读", "x": "AGENTS.md 是写给智能体的 README，每次启动全文进上下文。技能只预先放一行描述，正文等用到时再读进来。 最小例子（字节数来自练习 4 实测） AGENTS.md # 每次启动全文加载：515 字节 .claude/skills/run-tests/SKILL.md # 启动时只加载描述 158 字节，用到才读正文 322 字节 CLAUDE.md # Claude Code 找的是它，里面写一行 @AGENTS.md 就能共用 打个比方 AGENTS.md 像贴在工位上的规章，每天上班都先读一遍。技能像柜子里的操作手册，柜门上只贴标签。要用哪本，才把哪本拿出来翻。 AGENTS.md 可以理解为“写给编码智能体的 README”。它放在仓库里。每次启动智能体，它的 全部内容 都会预先放进上下文。Claude Code 找的是 CLAUDE.md 。课程仓库自己就有一份，讲师在视频里展示了。讲义还链接了 pydantic-ai 的真实例子 。 为什么需要 ：智能体启动时上下文是空的。它对你的仓库一无所知。你的惯例写进 AGENTS.md，就不必每次都说。比如类型检查用哪个命令，单测用哪个（ ）。讲义的例子是，要求它改完代码总跑类型检查。有的智能体能自动生成它，比如 Claude Code 的 /init 。 技能是“加一层间接” 。AGENTS.md 太大，还没开口就占了一大块窗口。而且某个时刻，往往只需要其中一部分。技能只预先放一份清单和描述。正文放在单独的文件里。智能体需要时才打开读入。这大致像一次工具调用（ ）。 bash · 本机实测（练习 4 的 ex04-a，按 UTF-8 字节估算） $ python ctx_cost.py AGENTS.md 启动时加载全文 515 字节 code-checker 启动时只加载描述 215 字节，用到时才加载正文 442 字节 run-tests 启动时只加载描述 158 字节，用到时才加载正文 322 字节 如果把这些正文全写进 AGENTS.md，每次启动要多占 764 字节的上下文 补充（非视频内容）：课程仓库的 AGENTS.md 与 README 说法不一 练习 2 实测发现，两份文件给的命令不一样。README 写的是 docker compose up --build 。AGENTS.md 写的是旧式的 docker-compose up --build 。智能体读了哪个，就照哪个说。这也提醒你两件事。AGENTS.md 要和代码一起维护。智能体的回答，要拿原始证据核对。 下面的演示对比两种加载方式。字节数来自上面的实测。 为什么会在这里踩坑 什么都往 AGENTS.md 里写，它就越写越长。每次启动都占一大块窗口，不管这次用不用得上。偶尔才用的长流程，做成技能。上面实测，两份正文写进 AGENTS.md，每次启动要多占 764 字节。"}, {"u": "ch07.html#s17", "c": "第 7 讲 · 智能体编程", "t": "子任务交给子智能体，只把结论收回来", "x": "主智能体把一件子任务交给子智能体。子智能体用全新的上下文去干，干完只交回结果。主智能体的上下文不会被细节撑满。 最小例子（示意） > use the code checker subagent # 显式调用（讲义） # 子智能体：全新的上下文，跑 mypy 和 ruff，读完几百行输出 # 主智能体：只收到一句“检查通过”，或者一份问题清单 打个比方 像经理派实习生去查资料。实习生翻了一下午文档，回来只交一页总结。经理的桌面一直是干净的。 既然有一个智能体，为什么不能有多个？部分原因还是上下文管理。主智能体发现一个子任务时，不在自己的上下文里做。它启动另一个智能体，只把子任务作为提示交给它。子智能体做完，把控制权和结果交回来。这样主智能体的上下文不会被细节污染。子智能体也只拿到它需要的信息（讲义）。 子智能体可以自己写，也被用来实现智能体的部件。有的智能体把 WebFetch 做成了子智能体。主智能体只说“抓这个网页，总结这一方面”。最后只有相关信息进主上下文（ ）。 子智能体还能并行。比如写完功能后，同时派出两个子智能体。一个做代码评审，一个修类型错误。都完成后，主智能体再继续，这样也更快（ ）。 讲义说，Claude Code 能从一句话生成子智能体，在 /agents 里新建。可以试试下面这句提示。生成后，说 use the code checker subagent 就能显式调用。也可以让主智能体在改完 Python 文件后自动调用它。练习 4 写好了一份这样的子智能体定义。 提示词（讲义原文） A Python code checking agent that uses mypy and ruff to type-check, lint, and format *check* any files that have been modified from the last git commit. 下面的演示看子智能体怎么接活、干活。最后它只交回摘要。 讲义：用 LLM 来写这些提示 技能、子智能体这些高级功能，都要写提示词。可以先让 LLM 帮你起草。有些智能体甚至内置了这个功能。 为什么会在这里踩坑 子智能体看不到主对话的历史。派活时只说“检查一下”，它不知道查什么。查哪些文件、按什么标准，都要写进提示。另外，它的 description 要写清什么时候用。主智能体只看得到描述，靠它决定要不要委派。"}, {"u": "ch07.html#s18", "c": "第 7 讲 · 智能体编程", "t": "AI 不是魔法：看着对的代码也要审", "x": "它只是一个概率模型。给定一堆输入 token，它给出下一个 token 的条件概率。它不像人那样聪明，会犯错，而且错得很像对的。 python · 最小例子（示意，补充） def mean(xs: list[float]) -> float: return sum(xs) / len(xs) # 看着没毛病，测试也许都过了 mean([]) # 空列表：ZeroDivisionError # 审 AI 写的代码，专挑边界情况看：空输入、None、超大值 打个比方 AI 像一个口才很好的新同事。说得头头是道，偶尔也会一本正经地胡说。你指出来，他还可能坚持自己是对的。 工具很强，但 AI 不是魔法，会犯错（ ）。 审查输出 ：检查正确性和安全漏洞。讲师多次遇到这种代码。乍看合理，实则有细微错误，找 bug 花了很久。 验证可能比写更难 。关键代码，讲师常常干脆自己写，不用 AI（ ）。 跑偏与“煤气灯” ：它会钻进兔子洞。有时它明明错了，你指出来，它还坚持自己是对的。这会让你很困惑。 调试死循环 ：改代码，跑测试，失败。再改，再失败。代码越改越糟，得盯着点。 别把它当拐杖 （讲义）：警惕过度依赖和一知半解。还有一大类编程任务，AI 仍然做不了。计算思维依然有价值（ ）。讲师说，“离计算机科学家过时还远着呢”。 为什么会在这里踩坑 智能体说“全部测试通过”，不等于真通过了。它可能没跑测试，也可能改了测试。练习页有个补充实验。命令被拒绝执行，假模型照样说“能通过编译”。真实模型也可能这样。所以要看原始输出，自己跑一遍验收。"}, {"u": "ch07.html#s19", "c": "第 7 讲 · 智能体编程", "t": "一页带走：智能体就是模型加循环", "x": "把本讲浓缩成几行。每行的注释就是结论和考点。 本讲速查（注释即考点） ŷ ~ π_θ(· | x) # LLM 是条件概率分布，推理就是抽样，同一问题两次答案可能不同 x = 整段历史 + 新问题 # 模型没有记忆，多轮对话靠每次重发完整历史 推理 → 工具 → 追加 → 再推理 # harness 循环：mini_harness 一个请求是 4 次推理、3 次工具调用 改文件放行，bash 逐条确认 # 文件改动有 Git 兜底能 revert，shell 命令执行了就难撤销 git worktree add -b x ../wt-x # 并行智能体各占一份检出、一条分支，互不覆盖 /clear 回退 /compact # 无关新任务清空，走错路回退，同一件事做长了压缩 AGENTS.md # 每次启动全文加载：放每次都需要的规矩 技能 # 启动时只加载描述：放偶尔才用的长流程 子智能体 # 独立上下文干一整件子任务，只把结论交回主智能体 # 推理大多在云端：读过的文件、命令输出都会发给服务商 编码智能体就是 LLM 加 harness。LLM 是条件概率分布，推理就是抽样。上下文窗口有上限。 多轮对话靠每次重发完整历史。harness 在循环里调用模型，执行它要的工具。工具结果追加回上下文，直到模型输出文字。 会改动电脑状态的工具调用，要逐个审批。用 Git 跟踪改动，事后审查。 推理大多在云端。读过的文件、命令输出，都会发给服务商。 实现功能用测试驱动，修错误要放进反馈回路。它还能重构、评审、读代码、当 shell 用。氛围编程是全程只用自然语言。 管上下文的有：清空、回退、压缩和 llms.txt。还有 AGENTS.md、技能和子智能体。扩展能力的有：可复用提示、并行智能体加 git worktree、MCP。 审查一切输出。关键代码自己写。警惕兔子洞和调试死循环。 在整门课里的位置 · 下一步 本讲把前面几讲串了起来。智能体调用的，正是前面几讲的工具。第 1 讲的 shell，第 4 讲的调试手段，第 5 讲的 Git。它能帮你写第 6 讲那些 Dockerfile 和 systemd 单元。第 9 讲的 linter、类型检查和测试，正是它要的反馈回路。现在去做 本讲练习的可视化笔记 。"}, {"u": "ch08.html", "c": "第 8 讲 · 代码之外", "t": "开头", "x": "本讲结论 工程师有一半时间在和人打交道。注释、README 和提交信息，都是写给未来读者的。它们要记 为什么 ，不只记“是什么”。提 issue、提 PR、做评审、向人提问，都要 尊重对方的时间 。用了 AI，就要 说出来 。"}, {"u": "ch08.html#s1", "c": "第 8 讲 · 代码之外", "t": "好工程师一半靠代码，一半靠沟通", "x": "这一讲不写代码，也不上白板。讲的是怎么和人协作。一类是写给后来者看的文字。一类是和别人一来一回的交流。 bash · 最小例子（示意） # 一个人写代码，电脑看得懂就行 # 一群人写代码，还得让人看得懂 git blame chunker.py # 半年后，有人追查到你写的这一行 git show ff12122 # 他能看到的，只有你当时写下的那段话 打个比方 代码像一台机器，沟通像它的说明书。机器再好，说明书没人看得懂，就没人敢接手修。 讲师认识的工程师，大多技术都很强。真正吃力的，是和人协作。比如在开源社区里打交道。又比如在大代码库里和别人一起干活。还有向前辈学，再教给新人。 他估计，做个好工程师，大约 50% 靠写好代码和系统。另外 50% 靠和人沟通（ ）。 本讲四块内容。视频 1:54 把沟通分成单向和双向两类。讲义另列了教与学、AI 礼仪 讲义开篇 好工程师写的代码，别人要能看懂、能维护。还能在上面接着搭。这个“别人”也包括未来的你。好工程师还要把话说清楚，想好了再贡献。不管在开源社区还是公司内部，都做个好公民。 为什么会在这里踩坑 很多人觉得代码能跑就完事了。可半年后接手的人，只看得到代码和你留下的文字。文字没写，他就只能猜。猜错了，就会把你的修复改回去。"}, {"u": "ch08.html#s2", "c": "第 8 讲 · 代码之外", "t": "注释写代码里看不出的“为什么”", "x": "单向沟通是写给以后某个工程师看的。最主要的载体是代码注释。注释该写的，是读代码看不出来的东西。 python · 最小例子（示意） CHUNK_SIZE = 1464 # 坏：把代码念了一遍，读者早就知道 # 好：交代这个数从哪来 # 1492 (PPPoE MTU) - 20 (IPv4 头) - 8 (UDP 头) = 1464 CHUNK_SIZE = 1464 打个比方 注释像菜谱旁边的批注。“放两勺盐”菜谱上已经写了。值钱的批注是“别换成酱油，会发苦”。 单向沟通 没有对话。读者可能很久以后才读到，那时你不在场。这个读者也可能是半年后的你自己（ ）。 讲师见过最多的注释，是解释代码做了什么。这也是最没用的。代码就在那儿，读一遍就知道（ ）。值得写进注释的，是 代码里不容易看出来 的东西。讲义列了七类，几乎总是值得写： 类型 写什么 反例 → 正例（讲义的例子） TODO 标出没做完的地方。写清缺什么，为什么推迟 TODO: optimize → TODO: this O(n²) loop is fine for n<100, but will need indexing if we scale 引用 代码来自论文、别处的代码或某份文档时，贴上链接。用永久链接，并注明和原文的差异 视频 的例子。排序函数里有串怪代码。配上出处，读者就懂了 正确性论证 不简单的代码为什么能算对。代码给出步骤，注释解释步骤为什么成立 讲义没给例子 来之不易的教训 花了 30 分钟以上才调通，修法又不直观的地方 “过去的你没意识到需要它，未来的读者也不会” 常量的来历 魔法数字是随便选的？测出来的？还是正确性要求的？ “为什么是 1492？为什么是 16 位？”哪怕写“随意选的”也有信息量 承重的选择 正确性依赖一个看着不起眼的实现细节 “必须是 BTreeSet，因为下面依赖迭代顺序” “为什么不” 故意不用显而易见的做法时，写明原因。不然有人会“修”回去，然后弄坏 视频 ：明明是个 map，却没用标准库的 HashMap 讲师最喜欢“为什么不”这类注释（ ）。比如你花了两小时，才发现标准库的 map 在这里不行。于是换了别的结构。你不写下来，就会有个 聪明的后来者 把它改回标准库。然后把你踩过的坑再踩一遍（ ）。 chunker.py 节选（练习 2 的示例仓库，中文注释是笔记加的） # 1492 (PPPoE MTU) - 20 (IPv4 header) - 8 (UDP header). # Ethernet allows 1500, but on PPPoE (DSL) links 1472-byte chunks got fragmented. CHUNK_SIZE = 1464 # 上面两行英文注释：常量的来历 def retransmit(pending: list[bytes], send) -> None: # A list, not a set: packets must be resent in their original send order. for packet in pending[:MAX_IN_FLIGHT]: # 上面那行：承重的选择，也是 why-not send(packet) 真实项目里的好注释长什么样？ 练习 1 在本机装的 CPython 标准库源码里真跑了 grep。每一类都找到了实例。 比如 heapq.py 里有一段 why-not 注释。它说，我们 本可以 提前跳出循环。但这不是好主意，尽管很多书都这么写。 random.py 里还有一句“原论文漏掉了对 log(v) 的调用”。这就是在注明和参考文献的差异。 TODO 写在代码里的好处 也可以记在 issue 跟踪器里。但 TODO 写在代码旁边更好找。用第 1 讲的 grep 一搜就有（ ）。 为什么会在这里踩坑 看到 Don't use += ! 这种只说“不要”的注释，很多人会当它多余。顺手一“优化”，bug 就回来了。练习 1 做了实验。换成 += 后，调用者传进来的 bytearray 被悄悄改了。所以写 why-not 注释时，原因也要写上。"}, {"u": "ch08.html#s3", "c": "第 8 讲 · 代码之外", "t": "README 按漏斗写，先说是什么，最后才说怎么装", "x": "README 通常是别人接触你项目的第一站。它要像漏斗。顶上让人几秒内判断“是不是我要的”。往下再一层层加深。 markdown · 最小例子（示意） # mytool <!-- 第 1 问：这是什么，一句话说完 --> Turn a CSV into a chart. <!-- 第 2 问：凭什么值得你关心 --> mytool plot data.csv <!-- 第 3 问：先给用法，让人看到效果 --> pip install mytool <!-- 第 4 问：决定要用了，再看怎么装 --> 打个比方 README 像商店橱窗。路人先看招牌和样品，觉得有意思才进门。你不能让他在门口先填会员表。 README 后来成了什么都往里放的大杂烩。有的又长又没用，有的很短却正好够用（ ）。讲师建议按顺序回答四个问题： 漏斗顶部让人几秒钟内判断“是不是我要的”。往下再逐层加深（视频 6:50 到 7:24，讲义） 顺序很重要 ：很多项目一上来就给安装步骤（ ）。可读者还没决定要不要用。讲义说要先展示用法。人们想先看到能得到什么，再花力气安装。 保持简洁 ：README 是拿来快速翻的参考。其他内容放到别的文件里。 CONTRIBUTING.md （ ）：写怎么报 bug、怎么提 PR、怎么测试。还有项目里不常见的约定。README 写给 用户 ，CONTRIBUTING 写给 协作者 。 本机实测：三个千星项目的 README 顺序 用 练习 3 的脚本，读本机已装包自带的 README。requests 第 5 行就给出代码示例，第 28 行才讲安装。rich 开头是 28 行徽章和多语言链接。它第 46 行讲完“Installing”，后面才有用法。不过它第 34 行有一张功能演示图。flask 根本没提安装。三份是否同样有用，留给你在练习里判断。 为什么会在这里踩坑 很多 README 第一屏就是一长串徽章和安装命令。读者还不知道这是什么，就被劝退了。写 README 时，站在第一次路过的人的角度。看他前 10 秒能读到什么。"}, {"u": "ch08.html#s4", "c": "第 8 讲 · 代码之外", "t": "提交信息记“为什么”，改了什么 diff 里都有", "x": "提交信息很容易只写“改了什么”。可改了什么，看 diff 就知道。读者想知道的是 为什么改、为什么这样改 。 bash · 最小例子（示意） git commit -m \"fix\" # 坏：blame 追到这里，线索就断了 git commit -m \"Use 1464-byte chunks so packets fit PPPoE links\" # 好：标题带着原因 git blame -L 5,5 chunker.py # 第 5 行最后是哪次提交改的 git log -S'1464' --oneline # 1464 这个数是哪次提交加进来的 打个比方 提交信息像病历。化验单上的数字谁都能看，那就是 diff。医生写的“为什么开这个药”，换个医生才接得上手。 第 5 讲讲了 Git 的命令。这里讲 Git 卫生 ，也就是和别人协作时怎么用好它。提交信息连起来，就是代码库的变迁史。它记的是代码为什么变成这样（ ）。 git blame 文件 给每一行标出最后改它的提交。你可以去看那次提交的信息，再一路往前追。但这类工具有个前提。提交信息得 写清为什么 （ ）。 bash · 本机实测（练习 2 的示例仓库，哈希可复现） $ git blame --date=short -L 3,7 chunker.py # 只看第 3 到 7 行，每行标出最后改它的提交 ff121228 (Alyssa P. Hacker 2026-01-12 3) # 1492 (PPPoE MTU) - 20 (IPv4 header) - 8 (UDP header). ff121228 (Alyssa P. Hacker 2026-01-12 4) # Ethernet allows 1500, but on PPPoE (DSL) links 1472-byte chunks got fragmented. ff121228 (Alyssa P. Hacker 2026-01-12 5) CHUNK_SIZE = 1464 7809933e (Ben Bitdiddle 2026-01-08 6) RETRY_TIMEOUT = 30 # seconds 4140218c (Ben Bitdiddle 2026-01-20 7) MAX_IN_FLIGHT = 16 $ git log -S'1464' --format='%h %s' # 1464 是哪次加进来的：信息写得很清楚 ff12122 Use 1464-byte chunks so packets fit PPPoE links $ git log -S'RETRY_TIMEOUT = 30' --format='%h %s' # 这一行是哪次加的：只有 fix 7809933 fix 第 5 行追到一条写得很好的信息。第 6 行追到的只有一个 fix ，线索就断了。 git log -S'字符串' 俗称 pickaxe，这一条是补充。它列出让这个字符串出现次数变了的提交。常用来查“这一行是哪次加进来的”。下面的演示先逐行追查。再用 -S 找出 1464 是哪次加进来的。 正文要回答四个问题 标题一行说清改了什么。正文回答下面四个问题。没有的项可以省。 什么问题逼你改？ 为什么非改不可。 考虑过哪些别的办法？ 为什么没用别的办法。修 off-by-one 这种没有备选的，可以省略（ ）。 有什么取舍和影响？ 优化常常是常见情况变快，少数情况变慢。运行更快但编译更慢，也值得写。C、Rust 这类有单独构建步骤的语言就常这样（ ）。 有什么出人意料的地方？ 看 diff 看不出的后果。评审者可能正好不同意这个取舍（ ）。 讲义推荐这样写复杂改动。最后一段最要紧。写明取舍是有意的，后人才不会以为你漏了问题 示例仓库里的好提交信息（git log 实测，场景示意） Use 1464-byte chunks so packets fit PPPoE links Problem: uploads from DSL customers stalled under ~3% packet loss. Their PPPoE links have an MTU of 1492 bytes, so every 1500-byte IP packet was split into two fragments, and losing either one lost both. Solution: size chunks for the smaller MTU (1492 - 20 - 8 = 1464) and write the arithmetic next to the constant. Implications: about 0.5% more packets on links that could carry 1500. 详略跟着复杂度走 改一个错别字，只要一行标题。花了几个小时才查清的竞态 bug，值得写好几段（讲义）。就算项目只有你一个人，也别全写成 “fix foo”。更别写 “blah”。一两年后，你自己也想不起为什么（ ）。 下面的演示拿同一个 diff 来改。把只写了 update 的信息，补成一条好信息。照着四个问题和 P、S、I 三段来补。 为什么会在这里踩坑 赶时间时，大家都爱写 fix 和 update 。当时觉得自己记得住。可 blame 追过来的，往往是几个月后的你。那时 diff 只告诉你 64 改成了 16。为什么改，没人知道。"}, {"u": "ch08.html#s5", "c": "第 8 讲 · 代码之外", "t": "让 LLM 写提交信息，得先把“为什么”喂给它", "x": "直接让 LLM 根据 diff 写提交信息，它只看得到 what，看不到 why。于是写出一大段描述，正好和我们想要的相反。 提示词 · 最小例子（示意） # 坏提示：它只看得到 diff，只能复述“改了什么” 给这个 diff 写一条提交信息。 # 好提示：点名要 why，缺信息就让它先问你 重点写为什么改、怎么取舍。哪里不清楚，先问我再写。 打个比方 只给 diff 让 LLM 写，像让快递员看包裹外形写贺卡。他只能写“一个方盒子”，写不出“生日快乐”。 讲师给了两种用法： 做法 2 里，你就像智能体能调用的一个“工具”。讲义说，它像查 MCP 工具一样向你要上下文 讲师建议 LLM 默认不会这样做。你得明确告诉它想要什么，并让它去收集缺的信息。否则它会写出看着厉害、其实没用的信息（ ）。 为什么会在这里踩坑 diff 里只有 64 改成 16。LLM 很可能写出“调整参数以优化性能”这种话。“优化性能”是它猜的。真实原因是网关只缓存 16 个包，这只有你知道。"}, {"u": "ch08.html#s6", "c": "第 8 讲 · 代码之外", "t": "一次提交只做一件事，用 git add -p 拆开", "x": "一周没提交，最后 git add . 一把梭。提交里就混满了不相关的改动。 git add -p 按块逐个问你，能把它们拆成几个独立的提交。 bash · 最小例子（示意） git add -p # 逐块问你：这块要不要放进下一次提交 y # 要：这块是新功能 n # 不要：这块只是格式化，留到下一次 git commit -m 'Add mode()' # 这次提交只讲一件事 打个比方 git add -p 像收拾行李时一件件过手。这件放进今天的箱子，那件留到明天。最后每个箱子只装一类东西。 最典型的是顺手跑了格式化器。diff 很大，大部分只是格式变化。只有少数是语义变化（ ）。 逻辑上独立的部分，应该拆成不同的提交。 git add -p 是 patch 模式。它把 diff 切成块（hunk），逐块问你。这块要不要放进下一次提交？答 y 或 n 就行。 bash · 本机实测（stats.py 示例：块 1 是格式，块 2 是新功能） $ printf 'n\\ny\\n' | git add -p # 第 1 块答 n，第 2 块答 y @@ -1,5 +1,5 @@ def mean(xs): - return sum(xs)/len(xs) + return sum(xs) / len(xs) (1/2) Stage this hunk [y,n,q,a,d,k,K,j,J,g,/,e,p,P,?]? @@ -13,3 +13,7 @@ def median(xs): def spread(xs): return max(xs) - min(xs) + + +def mode(xs): + return max(set(xs), key=xs.count) (2/2) Stage this hunk [y,n,q,a,d,K,J,g,/,e,p,P,?]? $ git diff --cached --stat # 暂存区里只有新功能那 4 行 stats.py | 4 ++++ 1 file changed, 4 insertions(+) $ git commit -q -m 'Add mode()'; git add -A; git commit -q -m 'Format mean() with spaces around /' # 先提交功能，格式化单独再提交 $ git log --oneline # 两件事成了两个提交 eceb177 Format mean() with spaces around / 3cd2a59 Add mode() b9513e2 Add stats helpers 补充（非视频内容） 这里用 printf 'n\\ny\\n' | 代替手敲 n 和 y，只是为了能自动真跑。平时直接在终端里回答就行。输出里的提示没换行，是因为输入来自管道，不是终端。 LLM 也能帮忙拆 ：让它找出 diff 里语义相关的部分。再让它分别提交。之后你可能要做点清理（ ）。 拆开的提交可以分成多个 PR （ ）。开源项目收到混着无关改动的大 diff，会让你回去重整。拆开后，维护者能先合并没争议的部分。有争议的慢慢谈。你的改动反而进得更快。 讲义说，别把重构和新功能混在一起。也别混进几个不相关的 bug 修复。拆好的提交还让 git bisect 好用得多，见 第 8 节 。 为什么会在这里踩坑 格式化器一跑，几百行全变了。你只改了两行逻辑，却和格式变化一起提交。评审者要在几百行里找那两行，很容易漏看。日后 bisect 找到这个提交，也分不清是哪一行惹的祸。"}, {"u": "ch08.html#s7", "c": "第 8 讲 · 代码之外", "t": "写太多等于没写，读者过了临界点就不读了", "x": "认真写注释、提交信息和 README 之后，有个危险。钟摆会摆过头，写得太多。 提交信息 · 最小例子（示意） # 太长：把 diff 又复述一遍，读者翻两行就放弃 This commit changes the value of MAX_IN_FLIGHT in chunker.py from 64 to 16 ... # 刚好：标题说 what，正文只补 diff 里看不到的 why Limit in-flight packets to 16 to match the gateway buffer 打个比方 文字像菜的分量。一碟刚好吃完。端上一大盆，客人看一眼就饱了，一口都不想动。 读者的反应大致是这样。没有文字，就没得读。文字不多，会读完。超过某个临界点，就一个字都不读了。或者只读第一段（ ）。 讲师建议 写之前先问自己：如果我是读者，会读吗？用 LLM 写东西时尤其要注意。它很擅长生成大量文字。你通常得明确要求“简洁的摘要，不要长篇大论”。讲义的说法是，只解释“为什么”。“怎么做”相信读者自己想得出。 为什么会在这里踩坑 用 LLM 写 PR 描述最容易写长。它会把每个文件改了什么都复述一遍。维护者翻两屏还没看到重点，干脆不看了。真正要紧的那句 why，反而埋在了中间。"}, {"u": "ch08.html#s8", "c": "第 8 讲 · 代码之外", "t": "bisect 二分找到坏提交，信息写得烂照样白找", "x": "git bisect 在好版本和坏版本之间二分查找。几步就能找出引入 bug 的提交。可那个提交要是没写为什么，你还得从头调试。 bash · 最小例子（示意） git bisect start HEAD v1.0 # 告诉它：HEAD 是坏的，v1.0 是好的 git bisect run sh test.sh # 测试脚本退出码 0 算好，非 0 算坏 git bisect reset # 找完了，回到原来的分支 # 16 个提交最多测 4 次。可找到的提交只写着 update，还是白找 打个比方 bisect 像查水管哪段漏水。从中间截断看一眼，漏的那半再从中间截。16 段水管查 4 次就够。可找到那段后，图纸上没写它为什么这么接。你还是不知道怎么修。 你升级了某个软件，发现一个以前没有的 bug。告诉 bisect 哪个版本好、哪个版本坏。它就检出中间的提交让你测。你回答好或坏，范围减半，直到只剩一个（ ）。 如果能用测试复现 bug，还可以写 git bisect run 脚本 。脚本用退出码表示好坏，整个过程全自动（ ）。 bash · 本机实测（示意仓库共 16 个提交，第 11 个藏了 bug） $ git bisect start HEAD <第 1 个提交> # HEAD 坏，第 1 个提交好 Bisecting: 7 revisions left to test after this (roughly 3 steps) [580a77cde90ff6e2b343602f3c86c076d7543355] Release step 8 $ git bisect run sh test.sh # test.sh: python -c 'from calc import add; assert add(2, 2) == 4' running 'sh' 'test.sh' Bisecting: 3 revisions left to test after this (roughly 2 steps) [b1e99566e803c1c80f7a5ccf23e296d8308d1dd2] Release step 12 running 'sh' 'test.sh' … AssertionError Bisecting: 1 revision left to test after this (roughly 1 step) [18f924a1f02b97f2fc3e0e8f39c534141dff1f33] Release step 10 running 'sh' 'test.sh' Bisecting: 0 revisions left to test after this (roughly 0 steps) [e532b6c1a67c456289b442b4bb8255b98726cd33] Release step 11 running 'sh' 'test.sh' … e532b6c1a67c456289b442b4bb8255b98726cd33 is the first 'bad' commit 示意仓库里，第 11 个提交把 a + b 改成了 a - b 。15 个候选只测了 4 次（⌈log₂ 16⌉ = 4）。但讲师的重点在后半句。找到的提交要是没写原因，bisect 就帮不上多大忙。一次改了一堆不相关东西的提交，也一样。你还得花很多时间调试（ ）。上面找到的 “Release step 11” 就是这样一个反例。 下面的演示把这次真跑的二分过程一步步画出来。还会手推要测几次。 为什么会在这里踩坑 bisect 最怕两种提交。一种信息什么都没说，比如 “Release step 11”。另一种一次改了十几个文件。前一种让你不知道为什么改。后一种让你不知道是哪一处惹的祸。"}, {"u": "ch08.html#s9", "c": "第 8 讲 · 代码之外", "t": "维护者远少于用户，你提的东西要信息多、废话少", "x": "最常见的协作是 贡献 。你提 bug 报告或代码改动，对方是这个项目的权威。维护者人少、时间少，所以要高信噪比。 issue 标题 · 最小例子（示意） it doesn't work # 坏：维护者得追问好几轮，才知道哪里坏了 Report is broken!!! # 坏：感叹号再多，信息也是零 Report titles lose letters: \"analytics.csv\" is shown as \"Analyti\" # 好：一眼看出是什么问题 打个比方 维护者像小诊所里唯一的医生，门口排着几百个病人。你进门就说清症状、病史和用药，他几分钟就能开方。你只说“我不舒服”，他得一样样问。 要记住一个比例。用户比贡献者多几个数量级。贡献者又比维护者多一个数量级。开源项目可能有上百万用户。维护者却只有一两个（ ）。 为什么要“高信噪比” 一半是尊重对方的时间，一半是为了自己。格式糟糕的 issue 或 PR，维护者可能直接关掉。也可能不理，或者放一年再说。大家都知道，“以后有空”永远不会来（ ）。 为什么会在这里踩坑 提 issue 的人常觉得，“我只是报个错，维护者自然会查”。可维护者每天要看一堆 issue。信息不全的那个，最容易被跳过。"}, {"u": "ch08.html#s10", "c": "第 8 讲 · 代码之外", "t": "bug 报告要让维护者读一遍就能复现", "x": "好的 bug 报告带齐复现要的全部信息。最值钱的是最小可复现示例。它省下的，正是维护者本来要做的工作。 issue 正文 · 最小例子（示意，改写自练习 4 的样本） Environment: Windows 11, Python 3.13.5 # 环境：系统和版本号 1. Run `python report.py` # 编号步骤，越具体越好 print(\"analytics.csv\".rstrip(\".csv\")) # 一行最小复现，别人复制就能跑 Expected: `analytics` Actual: `analyti` # 期望和实际都要写 打个比方 最小复现像修车时只带坏零件去店里。你把整辆车开去说“有异响”，师傅得先拆半天。你把那个会响的轴承递过去，他当场就能看。 好的 bug 报告要带上让别人能复现的全部信息。讲义的清单如下： 项目 说明 环境 操作系统、软件版本号、相关配置文件（ ） 期望和实际 两样都要写。有时你看到的正是设计如此，那就是文档的 bug。这个差值对维护者很有用 复现步骤 可能是最重要的部分。写成编号的步骤，越具体越好。“点那个按钮”太含糊。比如“以管理员身份登录，在 /settings 页面点 Submit”（ ） 已经试过什么 免得别人重复建议，也表明你花了力气 最小可复现示例是金子 （ ）。甩一个十万行项目说“编译后不对”，毫无用处。要从你的程序出发，砍掉一切和 bug 无关的东西。这很费劲。可这本来就是维护者修 bug 前必须做的事。用户比维护者多，这份活最好由你来干。缩减的过程本身，也常让你看懂问题，甚至自己修好。 先搜重复 （ ）。重复的 issue 越多，已有的讨论越难找。维护者也得在噪声里找信号。 别发“+1”“我也是” （ ）。它们会发邮件通知所有订阅者，却不带任何信息。要表态，就给首帖点个赞。维护者可以按赞数排序（ ）。有用的跟帖是“我做出了最小复现”。或者“这样做每次都能复现”。 给维护者宽容 （ ）：他们多是志愿者。几周后礼貌跟进可以，每天催不行。讲师自己就有放了六个月没看的 PR。 安全漏洞别公开发 ：讲义说，先私下联系维护者。给他们合理的修复时间，再公开。很多项目有 SECURITY.md。 坏 issue（示意） 好 issue（示意，练习 4 的样本） Report is broken!!! The titles in the report are wrong. Please fix ASAP… +1 from my team too Report titles lose letters: \"analytics.csv\" is shown as \"Analyti\" 搜过重复，写了环境：Windows 11，Python 3.13.5 编号步骤，加一行最小示例 期望 analytics ，实际 analyti 试过改成 .CSV 清单 0/7：至少要追问 7 次（ 练习 4 本机实测） 清单 7/7：维护者第一次读就能复现 问答：有没有“标准的好 bug 报告”可以照着写？（ ） 讲师说，没有一份“照着看就行”的范本。本讲的练习就是让你自己去找。看维护者怎么回应，很快就能看出哪份报告好用。也能看出哪里有摩擦。这是耳濡目染学会的。 很多项目有 issue 和 PR 模板。模板保证了格式，却补不上“不懂好报告的目的”。模板里的空，可以填得好，也可以填得差。好 bug 报告的目的，是 省下维护者修 bug 的时间 （ ）。 下面的演示分两幕。第 1 幕看 issue 缺几项，维护者就要追问几轮。第 2 幕用练习 5 的缩减器缩程序。31 行最后缩成一行最小复现。 为什么会在这里踩坑 做最小复现时，很多人删到一半就停了。觉得剩下的维护者能看懂。可剩下的几十行，维护者还得再找一遍。练习 5 里，自动缩减只缩到 17 行。看懂 bug 在 title_for 里之后，人工才缩到 1 行。"}, {"u": "ch08.html#s11", "c": "第 8 讲 · 代码之外", "t": "提 PR 前先读规矩、看许可证，一个 PR 只做一件事", "x": "PR 就是带着几个提交去问维护者：能不能并进你的项目？所以先照项目的规矩来，再把为什么写清楚。 bash · 最小例子（示意） cat CONTRIBUTING.md # 先读规矩：怎么测试，提交信息怎么写 cat LICENSE # 合并后，你的代码按这个许可证发布 git switch -c fix-title # 一个分支只做一件事 git request-pull main ../fork.git fix-title # 生成一封“带附件的邮件” 打个比方 提 PR 像往别人家里送一件家具。先问清他家门多宽，东西归谁，这就是 CONTRIBUTING 和许可证。一次只送一件，再附张纸条，说明为什么适合他家。 视频 有学生问“PR 是什么”。讲师说，别人有一个仓库。你带着一个或一组 git 提交去问他。能不能把这个并进你的项目？ 读 CONTRIBUTING.md ，照着做。讲义建议从小处开始。修个错别字、改改文档，就是熟悉项目流程的好起点。这样不用一边学流程，一边在内容上来回拉扯。 看许可证 （ ）。改动合并后，会按项目的许可证发布，比如 GPL。copyleft 许可证要求衍生作品也开源。你如果是公司员工，还要看公司的规定。上班时间写的代码，不一定能贡献出去（ ）。讲义推荐 choosealicense.com 。 隔离改动 ：一个 PR 只放你真想被接受的改动。每个 PR 都能单独评审。有时几处看似无关的改动，得一起才能实现一个功能。那就放进同一个 PR，但要保持提交整洁。再告诉评审者“请逐个提交地看”。维护者很感激这种评审指引（ ）。 写清为什么 （ ）。PR 描述像一封邮件，附件是你的 git 提交。要说明项目为什么该接受这个功能、修复或文档改动。主动指出需要特别留意的地方。看 CONTRIBUTING.md 的要求，可能还要写取舍和测试方法。 合并 PR，维护者就接下了长期责任（ ） 你加了一千行，维护者就要永远维护这一千行。你却可以拿到功能就走。所以他们不光要考虑想不想要这个功能。还要考虑这种实现自己能不能长期扛。会不会和以后的功能冲突。 好意的改动也可能被拒。可能是方向不合，也可能是加了不想要的复杂度。还可能是需求没说清。讲义说，证明它值得维护成本，是 贡献者 的责任。 收到评审意见时（讲义） 你的代码不是你！评审者想让代码变好，不是在批评你本人。不同意就问清楚。你可能会学到东西，对方也可能会。 补充（非视频内容）：“带附件的邮件”在 git 里真的存在 GitHub 出现之前，贡献者用 git request-pull 生成拉取请求。再用邮件发给维护者。Linux 内核至今还这样做。下面在本机用两个裸仓库，模拟上游和你的副本。示例提交修的是练习 5 的 rstrip bug。 bash · 本机实测 $ git request-pull main ../fork.git fix-title The following changes since commit c862d6f577748fd323f73a693609c47ba8888e15: Add report (2026-01-22 10:00:00 +0000) are available in the Git repository at: ../fork.git fix-title for you to fetch changes up to b4073679f4185259f8db98b8321d5646973a327b: Use removesuffix() so titles keep their last letters (2026-01-22 10:00:00 +0000) ---------------------------------------------------------------- Alyssa P. Hacker (1): Use removesuffix() so titles keep their last letters report.py | 2 +- 1 file changed, 1 insertion(+), 1 deletion(-) PR 页面上有的，它都有。从哪个提交开始，去哪里拉，有哪些提交，改了多少。“为什么”还是要你自己写。写在邮件正文或提交信息里。 下面的演示走一遍贡献的全过程，从读 CONTRIBUTING 到被合并。看代码怎么在上游、你的副本和你的电脑之间往返。再看 PR 的状态怎么变。右侧是本地模拟的真跑输出。 为什么会在这里踩坑 第一次提 PR，很多人把格式、改名和新功能一起塞进去。维护者没法只收其中一部分，只好让你拆开重来。还有人不看许可证，就贡献了公司不让外传的代码。"}, {"u": "ch08.html#s12", "c": "第 8 讲 · 代码之外", "t": "另起炉灶的 fork 很贵，只能当最后手段", "x": "PR 被拒后，你可以把项目复制一份。作为独立项目长期维护。但这很昂贵，需要很好的理由。 最小例子（示意） # PR 被拒了，fork 之前先问自己两个问题 # 1. 我要的和原项目的目标范围，本质上不同吗？ # 2. 我愿意一个人长期维护、同步上游、处理 issue 吗？ # 两个都是“是”，才 fork，并注明原项目。只是“我的功能没进”，就别 fork 打个比方 fork 像和合伙人闹翻后自己另开一家店。招牌、进货、账本都得自己扛。原来那家的改进，你这边也用不上。 先分清两个“fork”（补充） GitHub 上提 PR 的常规流程里，也有一步叫 fork。它在你的账号下复制一份仓库，改完再向原仓库提 PR。那只是工作副本。讲师这里说的 fork 是另一回事。它是把项目复制一份，换个名字。然后 作为独立项目长期维护 。 维护者可能会说“超出范围”或“太多了”。也可能说“我不想要这个功能”。这时你可以另起炉灶（ ）。但这很昂贵。两个项目各有一个维护者，代码却大量重叠。维护者的时间被分摊了。一边的改进，另一边享受不到。 所以它被视为 最后手段 ，需要很好的理由（ ）。讲义也建议优先贡献给上游。确实要 fork，而且许可证允许，就注明原项目。 讲师的判断标准（视频 36:51 到 37:59）。只因为“我的功能没被接受”就 fork，最后你会不开心 问答：有人会主动申请当某部分的维护者吗？（ ） 看项目规模。Linux 内核有很多子系统，各有维护者。带来一整个新子系统的人，几乎默认要负责维护它。小项目就少见了。2000 行的项目里，说“我来维护这 50 行”没有意义。改动会扩散到整个代码库，多个维护者还有协调成本。 不过，持续贡献正是成为维护者的路。维护者往往就是贡献最多的人。某天原维护者可能会问你，愿不愿意接手（ ）。 为什么会在这里踩坑 PR 被拒的那一刻，最容易冲动 fork。可几个月后，上游又修了一堆 bug。你得一个个手动合过来。合不动了，你的 fork 就成了没人维护的旧版本。"}, {"u": "ch08.html#s13", "c": "第 8 讲 · 代码之外", "t": "AI 写的 PR 可以交，但你得答得上为什么", "x": "LLM 生成的 PR 大多没用，因为提交者没当好过滤器。用 AI 可以，前提是你理解每处改动，并为它负责。 最小例子（示意） # 维护者在 PR 下面问：为什么用 removesuffix，不用 rsplit？ # 答不上来：说明改动不是你做的，PR 多半会被关 # 答得上来：AI 只是帮你打字，你仍然为它负责 打个比方 AI 像一个手很快的实习生。他写的东西可以交上去，但签字的是你。客户问起来你答不上，丢的是你的信用。 现在开源项目里有大量 LLM 生成的 PR。少数有用，多数没用。提交者只说一句“实现这个功能，提交并开 PR”。结果往往不够精简，夹带无关改动，why 也写得不好。 维护者问“为什么这样改”，提交者答不上来。因为改动不是他做的（ ）。所以维护者普遍怀疑 AI 写的 PR。 讲师与讲义的态度 不是说不能用 LLM。它在实现改动、写提交信息、写 PR 描述上都很有用。它甚至能帮你处理评审意见。但 你必须参与其中 。你得理解为什么要改，为什么这样改。 如果你只是描述了 bug，按下回车，再把结果贴进 PR。那维护者自己也能做。他们没做，多半是有原因的（ 到 ）。 讲义说，用 AI 找问题、写修复都可以。前提是你仍然做足功课，把它打磨成值得合并的贡献。别把这份活转嫁给本就超负荷的维护者。 为什么会在这里踩坑 让 AI 改一个 bug，它可能顺手改了别处。你没细看就提交，diff 里就混进一堆无关改动。维护者一问“这几行为什么改”，你也答不上来。"}, {"u": "ch08.html#s14", "c": "第 8 讲 · 代码之外", "t": "评审针对代码不针对人，还要给能动手的建议", "x": "评审是关于代码的一场异步对话。好意见针对代码，能直接动手改。它用提问的口气，讲清原因，还分清哪些必须改。 评审意见 · 最小例子（讲义的例子，注释是笔记加的） You wrote confusing code. # 坏：评判的是人 Don't use globals here. # 坏：只说不要，对方不知道怎么改 Can you replace these globals with a config dataclass, so that tests can run in parallel? # 好：提问、给替代方案、讲原因 nit: maybe call this retry_timeout_s # nit 开头：可改可不改（这一条是示意） 打个比方 评审像两个厨师试同一锅汤。说“你不会做饭”没用。说“盐是不是少了？客人口味偏重”，对方马上就能改。 评审常被想象成“新人提 PR，前辈挑错，直到 PR 变好”。但那不是评审的本意。评审只是 一场关于代码的异步对话 。有人提出改动，另一个人思考它。两人像头脑风暴一样，讨论好在哪、不好在哪。 正因为有“前辈挑错”的心态，评审的话常像在评判人。要记住，评审针对的是 代码 （ 到 ）。看它在这个项目里、为这个目的、在此时是否合理。 你被要求评审的时间，会比想象中早得多。哪怕只是大学的小组项目，也至少应该互相评审。评审还是最快的学习方式之一。你能看到别人的做法，学到模式和惯用法。看到别人犯的错，以后自己就不犯。 新鲜的眼光还能发现老手忽略的问题。讲义还说，你的疑问往往暴露出一些假设。它们该写成文档，或者该简化掉。 建议 不好的写法 更好的写法 评审代码，不评审人 You wrote confusing code. This function is confusing. 给出能动手的意见（ ） Don't use globals here. Can you replace these globals with a config dataclass?（视频补上了原因：这样测试能并行跑） 提问，不下命令（ ） Handle the null case. What happens if X is null here? 解释为什么（ ） Consider using a constant here. Consider using a constant here so we can easily adjust the timeout based on environment. 分清阻塞和建议（ ） 所有意见混在一起 不阻塞的意见用 nit: 开头。nit 在英语里指不要紧的小事 肯定好的地方（ ） 只挑错 指出巧妙的解法、干净的实现 知道何时停（ ） 留一百条评论 抓大放小。细枝末节，事后自己顺手整理 为什么给替代方案 ：光说“别用全局变量”不够。它没说该怎么做，也没说错在哪。有条经验是“全局变量让测试没法并行”。对方要是不知道，就无从下手。也许对方用全局变量有充分理由。这时一个能动手的问题，能把讨论打开。“别用全局变量”只会让对话从负面开始（ ）。 为什么别留太多 ：对方会累，会拖延。还分不清哪条最要紧。改了一处，别处的意见可能就失效了。留一百条，可能只有五十条值得处理。同一种命名问题，在第一处说一次就够了。比如“本仓库用这种命名，请全局统一”（ ）。 为什么要夸 ：想象结对编程时，对方一开口就说你错了。评审也一样。一句肯定不用对方做任何事，点一下 resolve 就行。但它让评审更平衡，对方也更愿意照你的意见改。在开源项目里，这还决定他们会不会再来。见视频 和 。 AI 评审不能代替人（ ） 现在很多人用 AI 做评审，效果可以很好。但它做的基本是“零上下文”评审，只看描述和 diff。评审里真正要紧的意见，往往不在 diff 里。这个改动适不适合整个代码库和产品方向？有没有破坏向后兼容，而项目还没准备发破坏性版本？这些 AI 不知道。 所以 AI 满意，不代表维护者满意（ ）。讲义说，AI 适合做第一轮，不能代替用心的人工评审。 学生追问，给它更多上下文行不行？讲师认为在一定程度上可以，但会碰到边界。比如你可以给它讲破坏性变更。它能用英语复述一遍。可它不一定懂这个项目的破坏性变更策略。他不认为给够上下文，就能得到完美评审（ ）。 下面的演示把讲义的反例逐条改成好的评审意见。再看留太多评论和 AI 零上下文评审有什么问题。 为什么会在这里踩坑 评审别人时，很容易一口气留几十条“这里不对”。写的人觉得自己很认真。收到的人只觉得被否定，还分不清哪条最要紧。结果改得更慢，下次也不想找你评审了。"}, {"u": "ch08.html#s15", "c": "第 8 讲 · 代码之外", "t": "先说你懂多少，再问具体的是非题", "x": "问好问题，能让对方一下子找到你的知识缺口。先做功课，说出你的理解，问具体的是非题。没听懂就接着追问。 提问 · 最小例子（讲义的例子，注释是笔记加的） How do SQL joins work? # 太泛：对方只能从头讲起，多半讲到你不关心的地方 Does a LEFT JOIN include rows where the right table has no match? # 具体的是非题：对方一个字就能答，还能顺手纠正你的误解 打个比方 提问像看病。你说“我哪里都不舒服”，医生只能从头查。你说“右膝上楼时疼，没摔过”。医生马上就知道往哪查。 工程师不写代码的时间里，很大一部分在提问或回答。对象有导师、老师、助教，还有做完了实验的同学。讲师最希望大家先学会 问好问题 ，这是第一阶段。回答好问题是第二阶段（ ）。 讲义推荐了 Julia Evans 的两篇文章。一篇是 How to ask good questions ，另一篇是 How to get useful answers to your questions 。 讲义列出的建议，按“问之前 → 问的时候 → 问之后”排序 说出理解 （ ）。对方就知道哪些不用重复，能直接找到你的知识缺口。 是非题 ：有点反直觉。可一串是非题能很快确认，你哪里对、哪里错。这样也不会扯得太远。问题要具体。“SQL join 怎么工作？”太泛。“LEFT JOIN 会包含右表没有匹配的行吗？”就能回答（讲义例子）。 承认不懂 （ ）。装懂只会让对方没法判断你的水平。反过来，被问到不会的，就说“我不知道”。讲义说，后面还可以接一句。比如“但我觉得……”，或者“我可以去查”。 别接受不完整的答案 （ ）。很多人没听懂，说声“好的谢谢”就走了。那等于没学到。要问到懂为止，或者问到明显待太久了。 先做功课 （ ）：同事之间随口一问没关系。但什么都没查就问，对方会有点烦。 对 LLM 同样适用（ ） 告诉它你知道什么，问具体的问题。别因为它给了答案就停下，用是非题接着追问。在 Stack Overflow 或论坛上也这样问。后来搜到这个帖子的人也会受益，这叫水涨船高。 下面的演示把讲义里太泛的问题，一步步问具体。再用十行 SQLite 实验自己回答它。结果来自练习 7 的真跑。 为什么会在这里踩坑 很多人怕显得笨，不懂也点头。回去一写代码就卡住，只好再问一遍。其实当场多问一个是非题，成本最低。练习 7 里多追问了一句。结果发现 WHERE 会把 LEFT JOIN 补出的 NULL 行滤掉。"}, {"u": "ch08.html#s16", "c": "第 8 讲 · 代码之外", "t": "用了 AI 就说出来，还要说清用在哪部分", "x": "AI 用得越来越多，相关规范却还没定型。讲师给了几条底线。用了就披露，并说清用在哪。守团队的规矩，考试面试别偷用。 PR 描述 · 最小例子（示意） Tests in test_report.py were generated by an LLM and reviewed by me. The fix in report.py is hand-written. # 说清哪部分用了 AI，审查者才知道该细看哪里 # 只写一句“用了 AI”不够，对方不知道该细看哪部分 打个比方 披露 AI 像论文里写清分工。谁做了实验，谁写了初稿，都写明白。审稿人才知道该在哪里多看两眼。 AI 在软件工程乃至整个社会里，用得越来越多。第 7 讲讲了战术层面的事。这里讲“软”的部分： 用了就披露 （ ）：这不是羞耻的事。目的是设定预期，让作品得到合适程度的审查。有些代码你没细读、没完全弄懂。别人得知道，要多看几眼（ ）。讲师自己就在用 LLM 写一个大项目，毫不避讳。但交付时他会说明：“这些代码我没全读过，是个起点。” 说清用在哪部分 （ ）。只说“全是 vibe coding 出来的”，信息太少。换个说法就清楚了。“备份工具是我写的，前端样式用 LLM 做。”又比如“测试是 LLM 生成的，实现是我写的”。这种区分对审查者很有用。讲义也坦白，它的部分内容用了 LLM。包括校对、头脑风暴，以及代码片段和练习的初稿。 遵守团队和项目的规范 （ ）。有些规定出于法律原因。比如健康、金融数据不能离开公司。智能体却可能把它们传到云端（ ）。那里你管不了。有些规定只是尊重项目开发者的意愿。公开说明你的用法，能避免代价高昂的错误。 学习时要有意取舍 （ 到 ）。用 AI，你会学得少一些。有时这没关系，但应该是有意的选择。讲义说，学习时让 AI 替你快速拿答案，恰恰适得其反。你学到的多半是提示词技巧，不是任务本身。 考试与面试 （ ）。这些场合本来就是评估 你 的能力。少数公司允许面试时用 AI，前提是让他们看你怎么用。拿不准就问。明确禁止外部工具时，就别用。讲义说，偷偷用“ 一定会 反噬你”。 本页的 AI 披露 按本讲的建议说明一下。这份中文笔记由 AI 根据官方讲义和人工字幕整理撰写。所有标着“本机实测”的输出，都是在本机真跑得到的。示意内容已逐处标注。 为什么会在这里踩坑 有人担心说了用 AI 会被看低，就悄悄不提。审查者以为每一行都是你亲手写的，就会少看几眼。等 AI 写的那段出了问题，信任也一起没了。"}, {"u": "ch08.html#s17", "c": "第 8 讲 · 代码之外", "t": "一页带走：写给人看的东西，都要写清为什么", "x": "把本讲浓缩成几行。每行的注释就是结论和考点。 本讲速查（注释即考点） CHUNK_SIZE = 1464 # 1492-20-8 # 注释写代码里看不出的 why。只复述代码的注释最没用 git commit -m \"fix\" # 坏：blame 追到这里就断了。复杂改动按 P、S、I 三段写 \"给这个 diff 写提交信息\" # LLM 只看得到 what。在同一会话里让它提交，或让它缺什么就问你 git add -p # 一次提交只做一件事，格式化和新功能分开提交 git log -S'1464' --oneline # 查某个字符串是哪次提交加进来的 git bisect run sh test.sh # 16 个提交最多测 4 次。信息写得烂，找到了也帮助不大 \"analytics.csv\".rstrip(\".csv\") # 最小复现：用户远多于维护者，缩减的活由你来干 Can you replace these globals ...? # 好评审：针对代码、用提问、给替代方案、讲原因 nit: ... # nit 开头表示不阻塞，作者先处理必须改的 Tests were generated by an LLM. # 披露要说清用在哪部分，再守住团队和考试的规矩 注释、README 和提交信息，是写给未来读者的单向沟通。要记 why 。what 读代码、看 diff 就知道，why 会随时间流失。 值得写的注释有七类。带上下文的 TODO、引用、正确性论证、教训。还有常量来历、承重选择和 why-not。 README 按漏斗写：是什么，为什么关心，怎么用，怎么装。CONTRIBUTING.md 写给协作者。 复杂提交按 Problem、Solution、Implications 写。用 git add -p 拆成逻辑独立的提交。git blame、log -S 和 bisect 好不好用，全看提交信息。 维护者远少于用户。bug 报告写清环境、期望和实际、步骤、试过什么。最好附上最小复现。先搜重复，不发 +1，礼貌跟进，漏洞私下报。 PR 先读 CONTRIBUTING，看许可证，只做一件事，写清为什么。被拒时，fork 是最后手段。用 AI 可以，但你得理解它，并为它负责。 评审要针对代码、能动手、用提问、讲原因。分清阻塞和 nit，肯定优点，别留太多。AI 评审只能做第一轮。 提问前先做功课。说出理解，问具体的是非题，承认不懂，追问到懂。用了 AI 就披露，并遵守规则。 在整门课里的位置，下一步 前七讲教你和计算机打交道，这一讲教你和人打交道。第 5 讲的 Git，在这里成了沟通工具。第 7 讲的智能体，在这里多了礼仪。最后一讲是代码质量。它会补齐格式化、lint、测试和 CI 这些 自动化的协作约定 。 现在去做 本讲练习的可视化笔记 。能在本机真跑的部分都已真跑。比如示例仓库的 git 历史和最小复现缩减器。还有 issue、评审、提问三个检查脚本。要去真实开源社区的部分，给出了步骤和验收标准。"}, {"u": "ch09.html", "c": "第 9 讲 · 代码质量", "t": "开头", "x": "本讲结论 代码好不好，别靠人盯，交给工具链自动把关。 格式化器 统一写法， linter 找反模式。 测试 加 覆盖率 验证行为。 pre-commit 钩子 在本地拦， CI 在服务器上拦。 命令运行器 把长命令变短。 正则表达式 是贯穿这些工具的小语言。编辑器的搜索替换也靠它。"}, {"u": "ch09.html#s1", "c": "第 9 讲 · 代码质量", "t": "检查交给工具链，在多个关口各跑一遍", "x": "本讲讲一条质量流水线。同一套检查，在编辑器、提交前和服务器上各跑一遍。 bash · 最小例子（示意） ruff format --check src # 格式化器：只报告写法问题，不改文件 ruff check src # linter：不运行代码，找反模式 python -m pytest # 测试：真跑代码，看结果对不对 git commit # 钩子：提交前自动把上面几步跑一遍 打个比方 像机场安检。值机、安检口、登机口各查一次。离飞机越近，越没法绕过去。 本讲先讲格式化器、linter 和测试。再讲 pre-commit 钩子、持续集成和命令运行器。最后讲正则表达式。 很多工具只认一门语言。它们得懂这门语言的语义（ ）。但概念是通用的，每门语言都找得到对应的工具。比如 Python 的 Ruff 能格式化，也能 lint。 Prettier 则能跨好几门语言。 同一套检查，在离代码越来越远的地方各跑一次。命令运行器让每一步只敲一个短命令，比如 just、npm scripts、hatch 讲师全程用一个叫 Minilib 的 Python 小库演示。它只有一个文件，用 Hatch 管理（ 、 ）。里面是些没啥用、正好拿来演示的函数，比如 fizzbuzz 和 left_pad。 视频没有完整展示源码。所以笔记照视频的描述， 重建了一份 Minilib 。它放在 本讲练习页 的 minilib/ 目录里。视频提到的格式问题、lint 问题和两个 bug，都故意留着。本页的“本机实测”大多跑在它上面。 为什么会在这里踩坑 检查只在自己电脑上跑，换个人就忘了。你今天记得跑格式化，同事明天直接提交。所以检查要写进钩子和 CI，让机器替人记着。 本机环境 本机有 Python 3.13.5、pytest 9.1.1、coverage 7.14.3 和 git。还有 Vim、GNU sed 4.9 和 GNU grep 3.0，grep 支持 -P 。 本机没有全局安装 ruff、pre-commit、semgrep、hatch、just、make 和 shellcheck。练习要用的 ruff、pre-commit 和 semgrep，每次运行时临时装进沙箱 venv。用完就删，不碰全局环境。所以视频里的 hatch fmt 、 hatch test ，本页直接换成调用 ruff 和 pytest 。"}, {"u": "ch09.html#s2", "c": "第 9 讲 · 代码质量", "t": "格式化器只改写法，不改程序的意思", "x": "格式化器只动表面写法：引号、空格、import 顺序、行长。改完以后，程序的语法树和原来一模一样。 python · 最小例子（取自下面的实测 diff） def hypot(a,b): # 格式化前：逗号后、* 两边都没空格 return sqrt(a*a + b*b) def hypot(a, b): # 格式化后：只补了空格 return sqrt(a * a + b * b) # 语法树没变，程序的意思也没变 打个比方 格式化器像报社的排版员。他只调字距和换行，一个字都不改。所以稿子交给他，你不用再校对一遍。 格式化器英文叫 auto-formatter。有了它，人不用再操心这些细节。脑力可以花在更难的问题上。更大的好处是 整个团队的代码风格统一 （讲义）。 两种模式 （ ）。检查模式加 --check ，只报告，退出码非 0，适合放进 CI。修复模式直接改写文件。 可配置的程度不同 。Prettier 能配很多选项，配置文件要提交进仓库。Black 和 gofmt 几乎不让你配。这是为了躲开 “自行车棚效应” 。引号用单的还是双的，不值得花时间争（ ）。 编辑器集成 ：可以设成保存时自动格式化。讲师没演示这一步。 代码 得先能被解析 ，格式化器才能干活（ ）。 bash · 本机实测（重建的 Minilib） $ ruff format --check --diff src # 只看要改什么，不动文件 --- src\\minilib\\utils.py +++ src\\minilib\\utils.py @@ -1,4 +1,5 @@ \"\"\"A few small utility functions (reconstructed Minilib, with deliberate issues).\"\"\" + import subprocess … - return 'fizz' + return \"fizz\" … -def hypot(a,b): - return sqrt(a*a + b*b) +def hypot(a, b): + return sqrt(a * a + b * b) … 1 file would be reformatted, 1 file already formatted $ ruff format src # 去掉 --check，才真正写回文件 1 file reformatted, 1 file left unchanged 视频里讲师敲的是 hatch fmt -f --check ，底下也是 Ruff。 为什么会在这里踩坑 CI 里忘了加 --check ，格式化器就直接改文件。它改完照样返回 0，CI 永远是绿的。另一个坑在语法错误。代码解析不了，格式化器只会报错。所以先修语法错误，再谈格式。 EditorConfig 让各家编辑器守同一套规矩 在项目根目录放一个 .editorconfig 。不管用 Vim、VS Code 还是 Cursor，缩进和换行都一样。 EditorConfig 是一种文件格式，加上一类编辑器插件。讲师演示了一下：保存时，行尾空格自动消失。Missing Semester 的仓库也用它。 minilib/.editorconfig 节选（注释是笔记加的） root = true # 编辑器往上找配置，找到这里就停 [*] # 对所有文件 end_of_line = lf # 换行符用 LF insert_final_newline = true # 文件末尾留一个换行 trim_trailing_whitespace = true # 保存时删掉行尾空格 charset = utf-8 [*.py] indent_style = space # Python 用空格缩进，一层 4 个 indent_size = 4 下面的演示逐处看格式化器改了哪些字符。最后比对语法树，说明它为什么能放心自动跑。"}, {"u": "ch09.html#s3", "c": "第 9 讲 · 代码质量", "t": "linter 不运行代码，靠读代码找反模式", "x": "linter 做 静态分析 。它不运行代码，光读代码就能找出反模式。它比格式化器深一层，看的是语义（ ）。 python · 最小例子（节选自重建的 Minilib） import subprocess # I001：os 应该排在 subprocess 前面 import os # F401：导入了没用，能安全地自动删掉 def divide(a, b): if b == 0: raise ValueError(\"divide by zero\") # EM101：字符串直接写进异常，要人工改 打个比方 linter 像带你的老同事扫一眼代码。他不用跑程序，光看就知道哪里迟早出事。 规则 ：每个 linter 带一组规则和预设，可以按项目配置。Ruff 大约有 800 条规则（ ）。 误报 ：有些规则会误报。所以都能按文件或按行关掉，Python 里写 # noqa: 规则编号 。 文档 ：好的 linter 会讲清每条规则。查什么，为什么不好，该怎么写。讲义举的例子是 SIM102 ，也就是可以合并的嵌套 if。 自动修复 ：有些问题能自动修。讲师强调要分清两种（ ）。 安全修复 保证不改变语义。 不安全修复 要加 --unsafe-fixes ，讲师打趣说“如果你觉得刺激”。很难写出安全变换的问题，只能由人来改。 bash · 本机实测（重建版报 6 个问题） $ ruff check --output-format=concise src # 一行一个问题，带 [*] 的能安全自动修 src\\minilib\\__init__.py:1:1: F403 `from minilib.utils import *` used; unable to detect undefined names src\\minilib\\utils.py:2:1: I001 [*] Import block is un-sorted or un-formatted src\\minilib\\utils.py:3:8: F401 [*] `os` imported but unused src\\minilib\\utils.py:10:5: RET505 [*] Unnecessary `elif` after `return` statement src\\minilib\\utils.py:24:26: EM101 Exception must not use a string literal, assign to variable first src\\minilib\\utils.py:33:12: S602 `subprocess` call with `shell=True` identified, security issue Found 6 errors. [*] 3 fixable with `--fix` (1 unsafe fix available with `--fix --unsafe-fixes`). 视频里报了 7 个错误，3 个能自动修。本机重建版是 6 个，也是 3 个能修。 规则 查的是什么 视频里怎么处理 F403 import * 让别的静态分析不知道定义了哪些名字 讲师有意保留，好写 from minilib import 某函数 。于是加了 # noqa: F403 （ ） I001 / F401 import 没排序。导入了却没用 能安全地自动修，带 [*] 号 RET505 if 分支已经 return，后面的 elif 和 else 就多余 自动修成普通 if（ ） EM101 异常里直接写字符串字面量，回溯里会出现两遍 照规则文档改。先赋给变量，再 raise（ 到 ） S602 shell=True 让 shell 解析命令字符串。文件名里的 ; 这类字符，会被当成代码执行 讲师先加 # noqa: S602 ，好引出下一个工具。实际应该修掉（ ） 规则文档就是老师 讲师用搜索引擎查 EM101。Ruff 也能直接在终端里查，命令是 ruff rule EM101 。本机实测见 练习 1 。它会给出 What it does、Why is this bad 和 Example 三段。照它的说明，把 raise ValueError(\"divide by zero\") 拆成两步。先写 msg = \"divide by zero\" ，再写 raise ValueError(msg) 。 为什么会在这里踩坑 看到报错就加 # noqa ，等于剪断警报器的线。S602 这类安全问题尤其不能压。讲师加 noqa 只是为了引出下一个工具。还有一个坑是随手开 --unsafe-fixes 。它可能改掉程序的行为，改完一定要看 diff。 下面的演示从 6 个问题走到 All checks passed。看哪些交给 --fix ，哪些照文档手改，哪些有意豁免。"}, {"u": "ch09.html#s4", "c": "第 9 讲 · 代码质量", "t": "semgrep 在语法树上匹配，正则换个写法就漏", "x": "grep 一个字符一个字符地比，代码换个写法就找不到。semgrep 先把代码解析成语法树，再按结构匹配。 python · 最小例子（取自练习 4 的样本） subprocess.Popen(cmd, shell=True) # 1 号：grep 和 semgrep 都能找到 subprocess.Popen( cmd, shell=True, ) # 3 号：拆成多行，grep 一次只看一行，漏了 P(cmd, shell=True) # 5 号：Popen 的别名，字符级搜索认不出 # subprocess.Popen(cmd, shell=True) # 8 号：只是注释，grep 第一版却报了 打个比方 grep 像按字形查字典。同一个词换行写，它就不认识了。semgrep 像懂语法的语文老师。句子怎么断行、换什么代称，主谓宾它都认得。 通用 linter 的规则适合起步。可项目常有自己的规矩。比如“别用 pickle，有安全隐患”，又比如“别用 exec”。 semgrep 全名是 semantic grep，用起来像 grep。不同在于，它先把代码 解析成语法树 ，在树上匹配。它支持多种语言。 讲师先用正则搜 subprocess.check_output(.*, shell=True 。他用的工具是 ag，一个 grep 的替代品。一开始能找到。可代码稍微一改，正则就匹配不上了。比如多加一个关键字参数，或者把调用拆成多行。他只能不停地补正则，像打地鼠（ 到 ）。换成 semgrep 是这样写： 讲义原文 $ semgrep -l python -e \"subprocess.Popen(..., shell=True, ...)\" 模式里的 ... 表示任意参数。讲师演示了一下。拆成多行、多了参数，semgrep 都找得到（ ）。 练习 4 在本机沙箱里装了 semgrep 1.182.1。它拿 9 种写法逐个测了一遍，结果画在下面的演示里。 为什么会在这里踩坑 拿 grep 做代码规范检查，会两头出错。调用拆成多行，它就漏报。注释和字符串里出现这串字，它又误报。练习 4 实测过 6 处真调用。grep 最多找到 3 处，semgrep 找到 5 处。semgrep 也有盲区。 shell=True 藏进字典再用 **kw 传进去，它就看不出来。"}, {"u": "ch09.html#s5", "c": "第 9 讲 · 代码质量", "t": "测试就是再写一段代码，去检查原来的代码", "x": "测试是一段会自己跑的代码。它调用被测函数，结果不符合预期就报错。代码一直在改，测试就一直跑。它确认你没弄坏东西（ ）。 tests/test_fizzbuzz.py（内容同视频，注释是笔记加的） from minilib import fizzbuzz # 忘了这行，报的是 NameError，不是断言失败 def test_fizzbuzz_3(): # 名字以 test_ 开头，pytest 才会找到它 assert fizzbuzz(3) == \"fizz\" def test_fizzbuzz_30(): assert fizzbuzz(30) == \"fizzbuzz\" # 30 同时是 3 和 5 的倍数 打个比方 测试像给代码配一把尺子。每次改完，拿尺子量一遍。长短不对，马上就知道。 测试是让人相信“代码是对的”的标准手段。这是个很深的话题，这里只讲高层概念。 概念 含义 单元测试 unit test 测单个函数。比如 fizzbuzz 该返回什么，left_pad 该返回什么 集成测试 integration test 测模块之间、服务之间怎么配合 功能测试 functional test 端到端地测，看软件是否满足用户需求 测试驱动开发 TDD 先把规格写成测试，哪怕只是一部分。再写实现，最后跑测试确认实现达标（ ） 回归测试 regression test 修完 bug 就写一个测试，保证它以后不会悄悄回来（讲义） 性质测试 property-based test 见 本讲第 7 节 mock 用假的实现替代数据库、Web API 这类外部依赖。出自讲义，视频问答也讲了（ ）。见 本讲第 16 节 在 pytest 里，测试就是普通函数。它放在约定的位置，名字以 test_ 开头。它不带参数、不返回值，里面写 assert 。pytest 会自己找到并运行它们（ ）。 测试怎么组织，要看语言和框架。做自己的项目时，查一下这门语言用什么测试框架就行。 bash · 本机实测 $ python -m pytest -q # 点是通过，F 是失败 .F [100%] ================================== FAILURES =================================== ______________________________ test_fizzbuzz_30 _______________________________ def test_fizzbuzz_30(): > assert fizzbuzz(30) == \"fizzbuzz\" E AssertionError: assert 'fizz' == 'fizzbuzz' … 1 failed, 1 passed in 0.96s 讲师的过程是这样的。第一个测试一跑就报 NameError。原来他忘了 import，测试本身也会有 bug（ ）。补上以后就通过了。第二个测试 fizzbuzz(30) 失败了。具体的输入和输出，让他很快找到原因。判断 15 的分支应该放在最前面（ 到 ）。 为什么会在这里踩坑 测试一红，先别急着改被测代码。看清报的是什么错。 AssertionError 说明被测代码结果不对。NameError 这类别的异常，多半是测试自己写错了。 更隐蔽的坑是函数名没以 test_ 开头。pytest 根本不会跑它。本机实测： bash · 本机实测（补充，非视频内容） $ printf 'def check_fizz():\\n assert 1 == 2\\n\\n\\ndef test_ok():\\n assert True\\n' > test_a.py $ python -m pytest -q -p no:cacheprovider test_a.py # check_fizz 必挂，却没人跑它 . [100%] 1 passed in 1.30s 只跑了 test_ok 一个。必挂的 check_fizz 被悄悄跳过，结果还是全绿。"}, {"u": "ch09.html#s6", "c": "第 9 讲 · 代码质量", "t": "覆盖率只看哪行跑过，不管结果对不对", "x": "跑测试时，覆盖率工具记下哪些代码行被执行过。它只看测到了哪里，不看测得对不对。 手推 · 最小例子（数字来自下面的实测和视频） # Cover = (Stmts - Miss) / Stmts，也就是跑到的语句占多少 (22 - 11) / 22 # 本机 TOTAL：50% (18 - 9) / 18 # 视频：utils.py 有 18 条语句，漏了 9 条，也是 50% (18 - 7) / 18 # 讲师补了 fizzbuzz(95) 的测试，多覆盖 2 条，约 61%（视频 28:28） 打个比方 覆盖率像检查学生有没有把课本每一页都翻过。翻过不代表看懂了。 测试写得好不好，程序很难回答。写测试要创造力，是一门越练越好的手艺。不过有工具帮忙，就是 代码覆盖率 （ ）。工具能逐行显示覆盖情况。Codecov 这类服务还能跟踪覆盖率的历史变化（讲义）。 bash · 本机实测（视频里用 hatch test -c） $ python -m coverage run -m pytest -q --tb=no # 在覆盖率统计下跑测试 $ python -m coverage report -m # -m 列出没跑到的行号 Name Stmts Miss Cover Missing ------------------------------------------------------- src\\minilib\\__init__.py 1 0 100% src\\minilib\\utils.py 21 11 48% 10-15, 19, 23-25, 29, 33 ------------------------------------------------------- TOTAL 22 11 50% Missing 列怎么读 这一列是没执行到的行号。10-15 是 fizzbuzz 的后几支。注意第 13 行 return \"fizzbuzz\" 。明明测了 fizzbuzz(30)，它还是没跑到。说明这行永远走不到，bug 就在这里。 HTML 报告 coverage html 生成网页报告。它用颜色逐行标出哪些执行过。看一眼就知道下一步该测什么（ ）。讲师说，这也是评估开源项目质量的好指标（ ）。 问答：能用 AI 提高覆盖率吗？（ ） 完全可以，这也是本讲的练习之一。先搭一个闭环。让 AI 智能体能自己跑测试，自己生成覆盖率报告。XML 格式更紧凑，更适合给 LLM 看。然后告诉它：把覆盖率提到 100%。 智能体写测试相当不错。但覆盖率不是完美指标，AI 写的测试也不完美。讲师见过一个前端项目，覆盖率 100%。可那些测试几乎没用（ ）。所以要审查它的输出。必要时多给点指引，比如“去测功能”。讲义也说，别过度追求覆盖率，专心写高质量的测试。 为什么会在这里踩坑 把覆盖率当 KPI，就会有人写不带 assert 的测试。每行都跑过，覆盖率 100%，bug 一个没抓到。练习 2 实测过这种测试，left_pad 的截断 bug 一直都在。 下面的演示逐条语句算覆盖率。最后看一个真实例子：覆盖率 100%，bug 还在。"}, {"u": "ch09.html#s7", "c": "第 9 讲 · 代码质量", "t": "性质测试不写具体答案，只写结果该守的规律", "x": "普通测试写的是“这个输入得到这个输出”。性质测试只写函数该满足的性质。输入由测试库成批生成。 python · 视频里的两条性质（按视频描述整理，示意） @given(st.text(max_size=20), st.integers(0, 50)) # 字符串最长 20，整数取 0 到 50 def test_left_pad_1(s, i): assert len(left_pad(s, i)) >= i # 性质 1：结果长度至少为 i @given(st.text(max_size=20), st.integers(0, 50)) def test_left_pad_2(s, i): assert s in left_pad(s, i) # 性质 2：原字符串要完整留在结果里 打个比方 像验收一台榨汁机。你不必算出每个橙子该出多少汁。只查两条：汁不比橙子多，杯里没有橙子皮。然后扔一千个随机橙子进去试。 left_pad 的规格是给字符串左边补空格。补完的长度至少为 i。讲师写了一个“巧妙”的实现，里面藏着 bug。他借这个例子介绍 性质测试 ，英文是 property-based testing。上面两条性质，整理自视频 到 。 它更接近形式化规格，但通常只是 部分规格 （ ）。这种方法由 Haskell 的 QuickCheck 发明并推广。Python 里对应的库是 Hypothesis 。 Hypothesis 不做数学证明。它随机生成输入，看性质成不成立。人要给一点提示。比如字符串最长 20，整数取 0 到 50（ ）。 讲师故意写了几个错误实现，第一条性质照样成立。可见性质只是部分规格（ ）。 现场还踩了个坑：忘了写 assert 。表达式算出 True 或 False，转手就被丢掉。测试永远“通过”（ ）。 第二条性质找到了具体反例： s = '00' ， i = 1 （ ）。拿着它就能去调试。 补充（非视频内容）：不装 Hypothesis 也能体会它的思路 本机没装 Hypothesis。练习不要求，按规范也不额外安装。笔记用 30 行标准库代码，模仿它的两件事。一是随机生成输入，二是把反例“缩小”到最简。在重建的 left_pad 上真跑，源码在下面演示的代码面板里： bash · 本机实测（prop.py 是笔记作者写的） $ python prop.py len(left_pad(s, i)) >= i -> holds for 500 random inputs s in left_pad(s, i) -> fails: ('ab0a0baab0abbbba', 5), shrunk to ('00', 1) 缩小后的反例，和视频里 Hypothesis 给的一模一样。 left_pad('00', 1) 先补成 ' 00' ，再取最后 1 个字符，得到 '0' 。字符串比 i 长时，就被截断了。 为什么会在这里踩坑 写测试最容易漏的就是 assert 。表达式单独一行，Python 算完就扔，测试永远是绿的。本机实测： bash · 本机实测（补充，非视频内容） $ printf 'def test_no_assert():\\n 1 + 1 == 3\\n' > test_b.py # 忘了写 assert $ python -m pytest -q -p no:cacheprovider test_b.py # 1 + 1 == 3 明明是错的 . [100%] 1 passed in 0.63s 另一个坑是只测“短字符串补齐”。没人去试比 i 长的字符串，截断 bug 就一直藏着。"}, {"u": "ch09.html#s8", "c": "第 9 讲 · 代码质量", "t": "pre-commit 钩子不通过，git 就拒绝提交", "x": "每次提交前，git 先跑一遍钩子。任何一个钩子返回非 0，这次提交就不会生成。 bash · 最小例子（示意） pre-commit install # 每个克隆做一次，写入 .git/hooks/pre-commit git commit -m 'Add double()' # 先跑钩子：格式不对，这次提交被拒 ruff format src && git add -A # 修好格式，重新暂存 git commit -m 'Add double()' # 钩子全过，提交才生成 git commit --no-verify # 应急时跳过钩子，所以服务器上还要 CI 打个比方 钩子像小区门口的门禁。刷不过卡就进不了门。可门边还有个侧门，叫 --no-verify。 Git 的 钩子 （hook）会在某些操作前后，运行你指定的脚本。 pre-commit 钩子 在每次提交之前运行。 pre-commit 框架让配置更省事。在 .pre-commit-config.yaml 里列出要跑的检查。每个开发者只需执行一次 pre-commit install （ ）。 minilib/.pre-commit-config.yaml（练习 1，注释是笔记加的） repos: - repo: local # 钩子就是本机已有的命令，不用去 GitHub 下载 hooks: - id: ruff-format name: ruff format --check entry: ruff format --check # 只检查，不修改 language: system # 直接在 PATH 里找 ruff types: [python] # 只把暂存的 .py 文件交给它 - id: ruff-check name: ruff check entry: ruff check language: system types: [python] 讲师的配置跑的是 hatch fmt --check 。这里换成直接调用 ruff。 bash · 本机实测（新加的 double() 里写了 x*2） $ git commit -m 'Add double()' # 钩子先跑，格式检查没过 ruff format --check......................................................Failed - hook id: ruff-format - exit code: 1 unformatted: File would be reformatted --> src\\minilib\\utils.py:37:13 | 36 | def double(x): - return x*2 37 + return x * 2 | 1 file would be reformatted ruff check...............................................................Passed 钩子返回非 0 的退出码，git 就拒绝提交。修好之前，提交进不去。这样就能在所有开发者身上，强制同一套质量标准。不然人很容易忘了先跑格式化（ ）。 学生的总结很到位。pre-commit 钩子就是仓库里的一组检查。每次提交前，它们必须全部通过。确实需要时，可以加一个参数跳过，就是 git commit --no-verify （ ）。 为什么会在这里踩坑 第一，钩子不随克隆带走。配置文件在仓库里，真正的钩子却装在 .git/hooks/ 下。新同事没跑 pre-commit install ，钩子就不存在。第二， --no-verify 一加就绕过去了。本机实测，带着两个 lint 错误也提交成功。所以服务器上还得有 CI 再查一遍。 下面的演示走一遍完整流程。提交被拦，修好格式，再提交成功。最后看 --no-verify 怎么绕过。"}, {"u": "ch09.html#s9", "c": "第 9 讲 · 代码质量", "t": "CI 在服务器上重跑同一套检查，谁也绕不过", "x": "前面的检查都在本机跑。持续集成服务在远程服务器上跑同样的脚本。每次 push、每个 PR，甚至按时间表，它都会跑一遍。 yaml · 最小例子（示意，省掉了检出代码和装 ruff） on: [push, pull_request] # 每次 push、每个 PR 都触发 jobs: lint: runs-on: ubuntu-latest # 每个作业一台全新的虚拟机 steps: - run: ruff check . # 退出码非 0，这个作业就变红 打个比方 钩子是自家门口的门禁，CI 是机场安检。自家门禁可以不装，也能绕开。机场安检谁都得过。 持续集成 服务通常和代码托管平台搭配，比如 GitHub Actions 。它在特定事件发生时运行你的脚本。时间表可以细到每周一上午 9 点（ ）。 触发 能抓住什么（讲义） 每次 push 引入主线的错误 每个 pull request 贡献者带进来的问题。很多人连格式化器都不跑。结果直接显示在 PR 页面上（ ） 定时 外部依赖的问题。比如依赖悄悄发了破坏性改动。版本号却按语义化版本标成兼容（第 6 讲） 能跑什么 ：格式检查、lint 和测试。编译型语言确认能编译，静态类型语言跑类型检查。讲师的演示里，类型检查作业失败了（ ）。 矩阵 ：远程机器不在乎跑得久。可以在多个系统和多个语言版本的组合上，并行跑测试。比如 Windows、Linux、macOS 各配几个版本。讲师管这叫“笛卡尔积”（ ）。 只检查不修改 ：CI 里的工具通常用 check 模式。格式不对就报错，不替你改（讲义）。 状态徽章 ：README 里常放 CI 状态和覆盖率的徽章（讲义）。 组成 ：工作流是 .github/workflows/ 下的 YAML 文件。结构是触发事件、若干作业 jobs、每个作业的步骤 steps。可以复用别人写好的 action，比如检出代码、安装 Python。最后一步通常是一条 shell 命令。任何一步退出码非 0，就算失败（ ）。 讲师建议（ ） 讲师自己也不背 GitHub Actions 的写法。需要时查文档，或者从相似的仓库里找个例子改改。也可以让编码智能体来写，它们很擅长这个。 讲义也建议，找和你项目相似的高质量开源项目。研究它们的 pyproject.toml 、 .github/workflows/ 和 DEVELOPMENT.md 。 本机的替代做法 本页没有把代码推到 GitHub。那是对外动作，要用你本人的账号。 练习 3 写好了完整的 ci.yml 。还写了一个 ci_local.sh ，在本机依次执行同样的检查命令。下面演示里的控制台输出，就是它真跑的结果。 为什么会在这里踩坑 CI 只能抓你写了检查的东西。练习 3 里，left_pad 的截断 bug 一直在，CI 却是绿的。因为没有一条测试去测它。还有一个常见的坑：本地能过，CI 不过。CI 每次都用全新的机器。你本地顺手装过的包，它那里没有。"}, {"u": "ch09.html#s10", "c": "第 9 讲 · 代码质量", "t": "同一套 CI 设施，还能用来自动部署", "x": "CI 的基础设施不只能跑测试。很多项目还用它自动发布和部署。这就是持续部署，简称 CD。 yaml · 最小例子（写法示意） on: push: branches: [main] # 只有推到主分支才部署 jobs: deploy: runs-on: ubuntu-latest steps: - run: ./build.sh && ./publish.sh # 构建失败，就不会发布 打个比方 CI 是质检员，CD 是质检完直接装车发货的传送带。质检不过，货就不上车。 比如为每个操作系统编译二进制并自动发布。也可以把应用部署到 Web 服务，或者构建 Docker 镜像（讲义）。第 6 讲讲过这些构件。 Missing Semester 自己就是这样。讲义仓库每次 git push ，网站就自动构建。构建好的网站发布到 GitHub Pages（ ）。CI 里还能跑覆盖率，再上传到 Codecov 这类服务。在网页上就能长期跟踪（ ）。 讲义里的真实例子 Missing Semester 仓库有一个链接检查工作流。它基于讲师自己写的 proof-html action。这个工作流经常失败，多半是第三方网站的问题。但它确实帮他们抓到、修好了很多失效链接。有的是拼写错误。更多是别的网站挪了内容，却没加重定向。还有的是整个网站没了。 为什么会在这里踩坑 依赖外部网站的检查天生不稳定。链接检查常常变红，多半不是你的错。可也别因此把它关掉，它确实抓到过很多真问题。部署也一样，要挂在测试后面。测试一红就不发布，坏版本才不会上线。"}, {"u": "ch09.html#s11", "c": "第 9 讲 · 代码质量", "t": "命令运行器把长命令收成一个短名字", "x": "长命令记不住，也容易敲错。命令运行器给它们起个短名字。本地和 CI 敲的就是同一条命令。 justfile（示意，未实测，注释是笔记加的） # 以后敲 just lint 就行 lint: uv run ruff check --fix format: uv run ruff format # 最长的那条命令，也只用敲 just typecheck typecheck: uv run mypy --strict --install-types --non-interactive src tests 打个比方 像手机里的快捷指令。一长串操作存成一个按钮，按一下全做完。 讲师一直在敲 hatch fmt 和 hatch test 。Hatch 是 Python 的项目管理器。它读 pyproject.toml ，内置了这些命令。 hatch fmt 底下用的是 Ruff。 没有这类工具时，你可能得手敲很长的命令（ ）。比如 mypy --strict --install-types --non-interactive src tests 。 命令运行器 把它们变成短别名。写好上面的 justfile，敲 just lint 、 just format 、 just typecheck 就行（ ）。讲义的例子是把 uv run ruff check --fix 换成 just lint 。 很多语言的项目工具自带这个功能，不一定要装 just。比如 npm 在 package.json 里写 scripts ，Hatch 有 tool.hatch.envs.*.scripts （讲义）。just 本机没装，上面的 justfile 没有实测。本机装了 Node.js，所以用 npm scripts 真跑了一次： bash · 本机实测（check 就是先 lint 再 test） $ npm run check # 一个短名字，背后是 lint 和 test 两步 > minilib-tasks@0.1.0 check > npm run lint && npm test > minilib-tasks@0.1.0 lint > ruff check --output-format=concise src All checks passed! > minilib-tasks@0.1.0 test > python -m pytest -q .. [100%] 2 passed in 0.64s 补充（非视频内容） 实测时把 npm_config_cache 和 npm_config_logs_dir 指到了临时目录。这样不会在你的家目录留下 npm 的缓存和日志。 为什么会在这里踩坑 本地敲一套命令，CI 里又手写一套。时间一长两边对不上，就会出现“本地能过、CI 挂了”。CI 配置里也只写 just lint ，两边跑的就保证是同一条命令。"}, {"u": "ch09.html#s12", "c": "第 9 讲 · 代码质量", "t": "正则表达式是描述一组字符串的小语言", "x": "一个正则表达式描述一个字符串集合。某个字符串在这个集合里，就叫匹配上了。 bash · 本机实测（用 grep -E 代替 ag） $ printf 'import numpy as np\\nimport os\\nfrom x import y as z\\n' > imp.py # 造 3 行 $ grep -nE 'import .* as .*' imp.py # 找出所有重命名过的 import 1:import numpy as np 3:from x import y as z 打个比方 正则像一张招聘启事。“三年经验，会 Python”。它不点名要谁，只描述一类人。符合条件的都算匹配。 这是加讲的话题。它原本排在第 3 讲，因为时间不够挪到了这里。正则表达式英文叫 regular expression，简称 regex。它是描述 字符串集合 的语言。也可以说，它描述的是字符串模式（ ）。它横跨很多领域： 命令行工具的参数 ：前面用 ag 搜代码就是一例。测试成千上万时，可以只跑名字匹配某个模式的那些。讲义举的是 go test -run [regexp] ，视频里是 hatch test 的参数（ ）。 编辑器的搜索与替换 ：讲师在 Vim 里搜 \\d\\+ 。所有数字都高亮出来，还能整体替换（ ）。 程序里 ：几乎每门语言都有正则库。能做模式匹配、校验和轻量解析（讲义）。讲义的例子是 ag \"import .* as .*\" ，找出所有重命名过的 Python import。 为什么会在这里踩坑 .* 很宽。 import .* as .* 连注释和字符串里的这句话都会匹配。正则只认字符，不懂代码结构。这正是 本讲第 4 节 里 grep 输给 semgrep 的原因。"}, {"u": "ch09.html#s13", "c": "第 9 讲 · 代码质量", "t": "正则只检查字符的形状，不检查意思", "x": "正则一个字符一个字符地比形状。 \\d{4}-\\d{2}-\\d{2} 认得出日期的样子，却认不出 99 日根本不存在。 bash · 本机实测（Python 3.13 re、GNU grep 3.0） $ python -c 'import re; print([bool(re.fullmatch(r\"\\d{4}-\\d{2}-\\d{2}\", s)) for s in [\"2026-01-14\", \"2026-01-99\", \"26-1-14\"]])' # 1 月 99 日也算匹配 [True, True, False] $ python -c 'import re; print([bool(re.fullmatch(r\".+@.+\", s)) for s in [\"alyssa@mit.edu\", \"nonsense@@@email\", \"@mit.edu\"]])' # 三个 @ 也能过 [True, True, False] $ grep -nE 'hello [^abc]' h.txt # h.txt：hello a / hello b / hello d / hello ab / hello f 3:hello d 5:hello f $ grep -nE '\\bdef\\b' d.py # d.py 第 2 行是字符串 \"hello, blah blah define\" 1:def foo(): 打个比方 正则像只看轮廓的门卫。身高体型对得上就放行，从不查身份证。 正则本来是计算机理论里的概念。各种语言和工具都有自己的实现。于是有了很多 方言 ，英文叫 flavor。核心概念相同，表面语法略有差别。 比如 Vim 里要写 \\d\\+ ，加号前面也要反斜杠。ag 里写 \\d+ 就行（ ）。这些小差别要么记住，要么用到时再查。本讲用 Python 的正则语法 。 讲义推荐 · regex101 regex101.com 这类网站像一个“正则调试器”。写几条测试字符串和一个正则，它就标出哪些匹配上了。它还逐项解释正则的含义。不同语言的方言，也能一键切换（ ）。 写法 匹配 例子（讲义和视频） abc 字面字符串，字符没有特殊含义时 abc . 任意一个字符 [abc] 方括号里的任意一个字符 hello[abc] 匹配 helloa、hellob。不匹配 hellod [^abc] 除了这几个以外的任意一个字符 d [a-f] 范围内的任意一个字符 c 可以，q 不行 a|b 左边或右边 missing|semester 、 hello|world \\d \\w 数字、单词字符 3、x \\b 单词边界。它是一个位置，不是字符 “missing semester” 里有 4 处：m 前、g 后、s 前、r 后 (...) 分组，也会捕获。见 本讲第 14 节 (hello|world) ...? ...* ...+ 0 或 1 次，任意次，1 次及以上 words? 、 .* 、 \\d+ ...{N} 恰好 N 次 \\d{4} \\. \\\\ 字面的点、字面的反斜杠 ^ $ 行首、行尾 ^world$ 匹配 world。不匹配 hello world hi（ ） 讲义给了四个直观例子。 abc 和 missing|semester 最简单。 \\d{4}-\\d{2}-\\d{2} 匹配 YYYY-MM-DD 形式的日期。但它只查形状， 2026-01-99 也能匹配 。 .+@.+ 匹配邮箱，只做最基本的检查，nonsense@@@email 也能过。完全不误判的邮箱正则 确实存在 ，但没法实用。 学生问了一个好问题： hello [^abc] 会匹配 hello ab 吗？答案是不会（ ）。手推一遍： 手推（注释是推理步骤） hello ab # 模式是 hello [^abc]，从第 1 个字符开始比 ^^^^^^ # 前 6 个字符是 hello 加空格，逐个对上 ^ # 第 7 个字符是 a，可 [^abc] 偏偏不收 a，这里失败 # 换个起点重试，后面再也凑不出 hello 加空格，整行不匹配 hello d # 第 7 个字符是 d，不在 a、b、c 里，匹配 \\b 的经典用途是找 Python 的函数定义 def 。字符串里 define 开头的那个 def 不能算（ ）。再手推一遍： 手推（注释是推理步骤） def foo(): # d 前面是行首，f 后面是空格 # 两头都是单词边界，\\bdef\\b 匹配 \"hello, blah blah define\" # define 的 d 前面是空格，算边界 # 可 f 后面紧跟 i，两个单词字符之间没有边界，不匹配 为什么会在这里踩坑 拿正则校验日期，以为过了就合法。1 月 99 日能过，13 月也能过。本机实测： bash · 本机实测（补充，非视频内容） $ python -c 'import re; print([bool(re.fullmatch(r\"\\d{4}-\\d{2}-\\d{2}\", s)) for s in [\"2026-01-14\", \"2026-13-01\"]])' # 13 月也能过 [True, True] 真要校验日期，得交给日期解析函数。第二个坑是方言。Vim 里的 \\d\\+ 原样拿到 Python 里，意思就变了。 \\+ 在 Python 里是字面的加号。 下面第一个演示比字符类、否定和 \\b 。一个字符一个字符地比。 第二个演示看量词怎么“吃”字符。还有贪婪的 .+ 怎么回溯。 补充（非视频内容）：贪婪与非贪婪 * 、 + 、 ? 、 {m,n} 默认是 贪婪 的。它们先尽量多吃，后面匹配不上，再一点点退回。在后面加一个 ? ，写成 *? 或 +? 。这就变成 非贪婪 的，尽量少吃。练习 6 的提示，正是让你读 Python 文档里这一段。 手推 (.+)@(.+) 匹配 nonsense@@@email 的过程： 手推 + 本机实测 # 第 1 步：第 1 组 .+ 很贪，一口吃到末尾 # 第 2 步：后面要一个 @，可已经没字符了，失败 # 第 3 步：往回吐一个字符 l。下一个字符是 l 不是 @，接着吐 # 第 4 步：一直吐到剩下 @email，下一个正好是 @，对上了 # 第 5 步：第 2 组 .+ 吃掉 email，匹配成功 re.match(r\"(.+)@(.+)\", \"nonsense@@@email\") # groups() 是 ('nonsense@@', 'email')，span(1) 是 (0, 10) re.match(r\"(.+?)@(.+)\", \"nonsense@@@email\") # 非贪婪：groups() 是 ('nonsense', '@@email')，span(1) 是 (0, 8)"}, {"u": "ch09.html#s14", "c": "第 9 讲 · 代码质量", "t": "括号会记下匹配到的那一段，替换时能引用", "x": "括号除了分组，还会 捕获 。它记下这一段匹配到了什么。之后能在程序里取出来，也能在替换里引用。 讲义原例 + 本机实测（注释是笔记加的） >>> import re >>> re.match(r\"\\d{4}-(\\d{2})-\\d{2}\", \"2026-01-14\").group(1) # 只有月份套了括号 '01' >>> re.match(r\"(\\d{4})-(\\d{2})-(\\d{2})\", \"2026-01-23\").groups() # 三段都套上，一次全取 ('2026', '01', '23') 打个比方 捕获组像拿荧光笔画重点。画过的几段，回头能单独抄出来，也能原样贴到别处。 regex101 上会把它标成 Capture group。 程序里取子串 ：从一堆 YYYY-MM-DD 的日期里，取出年份或月份。上面就是讲义的例子（ ）。 r\"…\" 是 Python 的原始字符串，能少写很多转义用的反斜杠。 编辑器里的替换 ：讲师在 Vim 里演示过。他把每个数字换成重复两遍的自己。15 变成 1515，0 变成 00（ 到 ）。命令拆开看： Vim · 命令拆解（注释是笔记加的） :%s/\\(\\d\\+\\)/\\1\\1/g # %s 对每一行做替换 # \\( \\) Vim 方言里，分组括号要加反斜杠 # \\d\\+ 一个或多个数字，+ 也要加反斜杠 # \\1\\1 第 1 个捕获组，连写两遍 # g 一行里所有匹配都换，不只换第一个 VS Code 里用 $1 、 $2 引用捕获组（讲义）。 bash · 本机实测（n.txt 三行：x = 15 / y = 0 / z = x + 7） $ vim -u NONE -Es -c '%s/\\(\\d\\+\\)/\\1\\1/g' -c 'wq' n.txt; cat n.txt # Vim 无界面模式跑同一条替换 x = 1515 y = 00 z = x + 77 $ sed -E 's/([0-9]+)/\\1\\1/g' n_orig.txt # sed -E 方言：括号和 + 都不加反斜杠 x = 1515 y = 00 z = x + 77 讲师说，同样的办法能从 Web 服务器日志里抽出访客 IP。写一个带捕获组的正则就行。可以在程序里调正则库，也可以交给 grep（ ）。 为什么会在这里踩坑 各家的引用写法不一样。sed 和 Vim 用 \\1 ，VS Code 用 $1 。Python 的 re.sub 也用 \\1 ，但替换串要写成原始字符串。不然 \"\\1\" 会先被 Python 转成一个控制字符： bash · 本机实测（补充，非视频内容） $ python -c 'import re; print(repr(re.sub(r\"(\\d+)\", \"<\\1>\", \"x = 15\")))' # 替换串没加 r 'x = <\\x01>' $ python -c 'import re; print(repr(re.sub(r\"(\\d+)\", r\"<\\1>\", \"x = 15\")))' # 加了 r，\\1 才是捕获组 'x = <15>'"}, {"u": "ch09.html#s15", "c": "第 9 讲 · 代码质量", "t": "正则数不了数，解析 HTML 要用真正的解析器", "x": "正则没有计数器。“n 个 a 后面跟 n 个 b”，它就表达不了。层层嵌套的 HTML 更不行。 bash · 本机实测（补充，非视频内容） $ printf '<b>a<b>b</b>c</b>\\n' > h.html # 两层嵌套的 b 标签 $ grep -oE '<b>.*</b>' h.html # 贪婪：一口吞到最后一个 </b> <b>a<b>b</b>c</b> $ grep -oP '<b>.*?</b>' h.html # 非贪婪：停在第一个 </b>，外层的开头配上了内层的结尾 <b>a<b>b</b> 打个比方 正则像只会看眼前一步的人。数括号得记住前面开了几层，它没这个记性。 正则是描述字符串集合的紧凑语言，但能力有限。讲义说，有些集合不属于 正则语言 ，正则写不出来。比如“若干个 a 后面跟 同样多 个 b”。写成集合是 {aⁿbⁿ | n ≥ 0}。这一点可以用 泵引理 证明。 更实际的例子是 HTML，它也不是正则语言。拿正则去“解析” HTML，做不对（ ）。上面的实测就是一个小例子。 现代正则引擎有前瞻（lookahead）和反向引用（backreference）这些扩展。能力超出了理论上的正则语言，很实用。但表达力仍然有限。更复杂的语言要用真正的解析器，比如 pyparsing 。它是一种 PEG 解析器。 补充（非视频内容）：为什么正则数不了数 理论上的正则，都能换成一台有限状态机。机器只有有限个状态，比如 k 个。下面用鸽笼原理手推一遍： 手推（注释是推理步骤） # 假设有台 k 个状态的机器，恰好认得 {aⁿbⁿ} # 依次喂它 1 个 a、2 个 a……直到 k+1 个 a，记下每次停在哪个状态 # k+1 次读数，只有 k 个状态，必有两次停在同一个状态 # 设这两次分别读了 i 个和 j 个 a，i 不等于 j # 接下来都喂 i 个 b。两边从同一状态出发，走法一模一样 # 所以 a^i b^i 和 a^j b^i 要么都接受，要么都拒绝 # 可前者该接受，后者该拒绝。矛盾，这样的机器不存在 说白了，机器记不住任意大的 n。HTML 能一层层无限嵌套，道理一样。 怎么学（讲义） 先掌握本讲这些基础。其余的用到时再查，不必背下整门语言。 讲义：让 LLM 帮你写正则 对话式 AI 很擅长生成正则。讲义给了一句提示词，大意如下。 “写一个 Python 风格的正则。从 Nginx 日志行里，匹配出请求的路径。” 后面再附上一行示例日志： 169.254.1.1 - - [09/Jan/2026:21:28:51 +0000] \"GET /feed.xml HTTP/2.0\" 200 2995 \"-\" \"python-requests/2.32.3\" 。 不管谁写的正则，都要拿真实数据测一测。下面是笔记作者自己写的一版，没问 LLM。在本机对这行日志真跑： bash · 本机实测（补充） $ python -c 'import re; print(re.search(r\"\\\"[A-Z]+ (\\S+) HTTP/[\\d.]+\\\"\", open(\"access.log\").read()).group(1))' # 第 1 组就是请求路径 /feed.xml 为什么会在这里踩坑 LLM 写的正则看着很专业，可它没见过你的真实日志。格式和它设想的稍有不同，它就悄悄配错。也可能什么都配不上。所以一定拿几行真日志测过再用。"}, {"u": "ch09.html#s16", "c": "第 9 讲 · 代码质量", "t": "问答：测外部 API 就用 mock 顶替", "x": "课后问答里最实用的一条是 mock。代码里调了外部 API，测试时就拿假的顶替。 python · 最小例子（写法示意） class FakeClient: # 接口和真客户端一样，背后是自己写的 def get(self, url): raise TimeoutError(\"simulated\") # 想测出错分支，就让它直接报错 def test_timeout(): assert fetch_title(FakeClient(), \"/x\") is None # 注入假客户端，离线也能跑 打个比方 mock 像消防演习用的假人。外形和真人一样，想让它怎么倒就怎么倒。也不怕伤到谁。 代码里能用正则吗？ 当然能，前面在 Python REPL 里演示的就是。Python 的正则库叫 re 。有的语言标准库里没有正则。比如 Rust，用的是流行的第三方库。搜索工具也常常借用现成的正则库（ ）。笔记补充：ripgrep 用的是 Rust 的 regex 库。ag 是 C 写的，用的是 PCRE。 现场演示 AI 补测试 （ ）。AI 一开始给的测试很有用。可你让它生成得越多，它越会生成没用的。除非你好好引导它。人和 AI 一起协作，能达到很好的效果。这次讲师只给了几句提示。让 AI 一边写测试一边修 bug，直到不再变化。最后覆盖率到了 100%（ ）。测试覆盖了 3、5、15 的倍数，还有异常分支。提示词不需要特殊格式，LLM 很能理解英文指令。技巧只影响最后那几个百分点（ ）。 测试和代码放同一个文件？ Rust 习惯把小的单元测试写在同一个文件里。复杂的集成测试另外放。Python 也有 doctest。编译型语言把测试写进源文件，有个代价。改测试也得重编译（ 到 ）。 代码里有大量 API 调用，怎么测？ （ ）用 mock 。实现一个和真实 API 接口相同的版本。背后的逻辑是你自己写的，很简单。比如假的 OpenAI 或 YouTube 客户端。测试时把它注入进去。你能让它返回错误，也能离线跑。另一种做法是对真实 API 跑一次，把网络通信全部 录下来 。以后测试时直接回放。Python 里有 pytest 的 VCR 插件。也可以直接测真实 API。几种做法各有利弊（ ）。 哪里找好的提示词？ 没有现成的提示词仓库。OpenAI、Anthropic 这些公司都写了不错的提示词指南。示例提示词多半和具体代码库绑定。录屏的智能体编程过程，可能更值得看（ ）。 为什么会在这里踩坑 测试直接打真实 API，又慢又花钱。网络一抖，测试还会随机失败。CI 一会儿红一会儿绿。没人分得清是代码坏了，还是网络坏了。用 mock 或者录制回放，测试才稳定。"}, {"u": "ch09.html#s17", "c": "第 9 讲 · 代码质量", "t": "一页带走：本讲结论都在这几行里", "x": "把本讲浓缩成几行命令。每行的注释就是结论和考点。 本讲速查（注释即考点） ruff format --check src # 只改表面写法，语法树不变，所以能放心自动跑 ruff check --fix src # 只自动修安全的问题。语义问题写不出安全变换，要人看过再改 semgrep -l python -e \"subprocess.Popen(..., shell=True, ...)\" # 按语法树匹配，拆行和别名都认得 coverage report -m # return \"fizzbuzz\" 那行一直没覆盖：它是死代码，bug 就在这 pre-commit install # 每人各装一次，没装的人不受约束 git commit --no-verify # 钩子还能被绕过，所以要 CI 在服务器上统一查 re.fullmatch(r\"\\d{4}-\\d{2}-\\d{2}\", \"2026-01-99\") # 能匹配：正则只看形状，校验日期要用日期解析 re.match(r\"(.+)@(.+)\", \"nonsense@@@email\") # 贪婪：第 1 组吃到 nonsense@@，停在最后一个 @ 前 sed -E 's/([0-9]+)/\\1\\1/g' # \\1 引用第 1 个捕获组，15 变成 1515 格式化器只改表面语法，语法树不变。它统一团队风格，分检查和修复两种模式。EditorConfig 统一编辑器设置。 linter 做静态分析。规则能配置，也能按行写 # noqa 。安全修复交给工具，其余看文档人工改。semgrep 在语法树上匹配，适合写项目自己的规则。 测试分单元、集成、功能三类。TDD、回归测试、性质测试、mock 是常用方法。pytest 自动发现 test_ 开头的函数。 覆盖率 = (语句数 − 未执行) / 语句数。它能指出没测到、甚至永远执行不到的代码。但 100% 覆盖不等于正确。 pre-commit 钩子在本地查，CI 在服务器上查，查的是同一套。CI 支持 push、PR、定时触发和矩阵。CD 用同一套设施自动部署。命令运行器把长命令变短。 正则描述字符串集合。基础是字面量、字符类、量词和锚点 ^ $ 。再加上 \\d \\w \\b 、分组捕获和替换里的 \\1 。各工具方言略有不同。正则表达力有限，复杂语言要用解析器。 在整门课里的位置 · 下一步 这是本课的最后一讲。前面各讲的工具，在这里汇成一条自动化的质量流水线。第 1 讲的 shell、grep、sed，第 5 讲的 Git。还有第 6 讲的发布与依赖，第 7 讲的智能体。流水线从编辑器到钩子，再到 CI 和部署。正则表达式则会陪你用几乎所有工具。 现在去做 本讲练习的可视化笔记 。在沙箱里给 Minilib 配上格式化器、linter 和 pre-commit。再补测试、量覆盖率、跑本地 CI。正则题用 grep、sed、Vim 和 Python 全部真跑。"}, {"u": "labs/lab01.html", "c": "练习 1 · 课程概览 + Shell 入门", "t": "开头", "x": "LAB 01 · 对应 第 1 讲 · 课程概览 + Shell 入门 练习可视化笔记 · Shell 入门 讲义第 1 讲一共 18 道练习，这里逐题讲。每题先亮结论，再给真跑的代码和输出。接着打个比方讲原理，最后指出坑在哪。考点都写在代码注释里。官方不给答案，题解是笔记作者写的。 所有输出都由脚本在本机真跑后自动收集 。生成时间是 … 。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 本机没有对应环境，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab01.html#env", "c": "练习 1 · 课程概览 + Shell 入门", "t": "环境检查：本机是 Git Bash，不是真 Linux", "x": "本页命令都在 Windows 的 Git Bash 里真跑。需要真 Linux 的几条，标成了未实测。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机限制与处理办法 没有真正的 Linux ：本机的 Docker Desktop 一启动就崩。日志说 …\\Docker\\run\\dockerInference 这个文件无法访问。那是 10 月 16 日残留的套接字文件。WSL 里也只有 docker-desktop 这个内部发行版。需要 Linux 的 4 条命令标成了 未实测 。它们在练习 1、2、9 里，页面写明了视频里的现象。 Git Bash 不是 Linux ：它把 NTFS 映射成 Unix 路径，但不记录执行位。以 #! 开头的文件会自动显示成 rwx ，练习 9 实测过。 缺 jq 和 stress ：练习 16 的 jq 命令没实测。改用 Python 的 json 模块，真跑出同样的结果。练习 12 用一个 exec sleep 30 的小脚本冒充 stress，准备步骤里写明了。 隐私 ：练习 13 和 18 涉及家目录和历史记录。笔记没读你的真实文件。13 题改在课程仓库副本上跑，18 题改用一份示意历史。命令本身不变。 怎么用这一页 代码块右上角有个“复制”。它复制的是源文件的原始字节，不带行号和注释层。“注释”按钮能隐藏或显示所有注释。开关状态记在浏览器里。每道题标题右边可以勾“完成”。想自己验证，就按 页尾“自查” 的方法重跑。"}, {"u": "labs/lab01.html#ex01", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 1 · $SHELL 只记登录 shell，不一定是眼前这个", "x": "Git Bash 实测 Linux 未实测 原题 ：本课需要 Bash 或 Zsh 这样的 Unix shell。Windows 上别用 cmd.exe 或 PowerShell，可以用 WSL 或 Linux 虚拟机。用 echo $SHELL 检查，输出像 /bin/bash 或 /usr/bin/zsh 就对了。 echo $SHELL 只能看出登录时用的 shell。想确认眼前这个是不是 bash，看 $BASH_VERSION 更准。 ▶ 跑 打个比方 $SHELL 像入职登记表上写的部门。你后来借调到别的组，登记表不会跟着改。 ? 原理 $SHELL 是一个环境变量，记的是你的 登录 shell 。 $BASH_VERSION 只有 bash 自己会设置。所以它能直接说明，正在解释这行命令的就是 bash。 ! 为什么会在这里踩坑 误解 以为 $SHELL 就是当前正在跑的 shell。 真相 它只是登录 shell 的记录。在 bash 里再敲 zsh 进入 zsh， $SHELL 不会变。想知道当前进程是谁，看 $BASH_VERSION 或 ps -p $$ 。 $$ 是当前 shell 的 PID。 考点（答案写在注释里） echo $SHELL # 登录 shell，进了 zsh 也不会变 echo $BASH_VERSION # 只有 bash 会设置，空的就说明不是 bash ps -p $$ # $$ 是当前 shell 的 PID，看它到底是谁 # 在 PowerShell 里 echo $SHELL 是空的 # Unix shell 才会从环境里继承 SHELL，所以这正说明你不在 Unix shell 里"}, {"u": "labs/lab01.html#ex02", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 2 · ls -l 开头 10 个字符：类型加三组权限", "x": "Git Bash 实测 Linux 未实测 原题 ： ls 的 -l 参数是干什么的？运行 ls -l / ，每行前 10 个字符是什么意思？提示： man ls 。 第 1 个字符是文件类型。后面 9 个分成三组 rwx，依次给属主、属组和其他人。 ? 原理 -l 是长格式，每个文件占一行。依次是权限、链接数、属主、属组、大小、时间和名字。前 10 个字符是这样拆的： 类型：- 普通文件，d 目录，l 符号链接。c 和 b 是设备文件。r 读，w 写，x 执行，目录的 x 表示能进入。- 表示没有这个权限 ▶ 跑 打个比方 rwx 像一扇门上的三把锁：能看、能改、能进。三组锁分别发给房主、室友和路人。 补充（非视频内容）：在真 Linux 上你会看到 Ubuntu 的 /bin 是指向 usr/bin 的符号链接，显示成 lrwxrwxrwx … bin -> usr/bin 。 /tmp 显示成 drwxrwxrwt 。最后的 t 是粘滞位，人人能写，但只能删自己的文件。 /dev/null 以 c 开头，是字符设备。这些都没在本机实测，因为没有 Linux 环境。 ! 为什么会在这里踩坑 误解 Git Bash 里所有目录都是 drwxr-xr-x ，属组是 197610 。以为 Linux 就是这样。 原因 Git Bash 按 Windows 的文件属性，拼出 Unix 风格的权限。数字属组是从 Windows 的 SID 映射来的。这些权限位在 NTFS 上并不真实存在。 考点（答案写在注释里） drwxr-xr-x # d 是目录，属主 rwx，属组和其他人 r-x # 目录的 r：能列出里面的文件名 # 目录的 x：能进去，也能访问里面的文件 # 只有 r 没有 x：看得到名字，打不开内容（补充，非视频内容）"}, {"u": "labs/lab01.html#ex03", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 3 · glob 由 shell 展开，没匹配上就原样留着", "x": "Git Bash 实测 原题 ： find ~/Downloads -type f -name \"*.zip\" -mtime +30 里的 *.zip 是 glob。glob 是什么？建一个测试目录，试试 ls *.txt 、 ls file?.txt 和 ls {a,b,c}.txt 。参考 Bash 手册的 Pattern Matching 。 * 和 ? 由 shell 按磁盘上已有的文件展开。 {a,b,c} 不看磁盘，直接生成三个词。 K 先回顾 glob 和正则的区别，见 第 1 讲第 9 节 。 ? 原理 写法 含义 谁展开 * 任意长度的任意字符，可以是 0 个 shell 展开。按 已有的文件 匹配，结果按名字排序 ? 恰好 1 个任意字符 同上 {a,b,c} 花括号展开，直接生成 a、b、c 三个词 shell 展开。 不管文件在不在 ▶ 跑 读输出时注意两点。 file?.txt 匹配到 file1 和 file2， 没有 file10 ，因为 ? 只匹配一个字符。 {a,b,c}.txt 不看磁盘，照样生成 c.txt。于是 ls 报错，整条命令退出码是 2。 打个比方 glob 像点名册，只喊到场的人。花括号像摆座位牌，不管人来没来，牌子先摆上。 ! 为什么会在这里踩坑 错误写法 echo *.md ，以为没匹配时什么都不输出 实际 bash 默认把 没匹配上的 glob 原样留着 。于是输出字面上的 *.md ，见上面 ex03-b 的第一行。后面要是接 rm ，就会去删一个叫 *.md 的文件。 正确写法 想要“没匹配就为空”，先 shopt -s nullglob 。实测输出 [] 。 考点（答案写在注释里） ls *.txt # 不加引号：要的就是 shell 先展开成文件列表 find . -name \"*.zip\" # 加引号：模式原样交给 find，它在每层目录里自己匹配 find . -name *.zip # 坑：当前目录正好有 zip 时，find 收到的是具体文件名"}, {"u": "labs/lab01.html#ex04", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 4 · 三种引号：要不要展开，认不认转义", "x": "Git Bash 实测 原题 ： '单引号' 、 \"双引号\" 和 $'ANSI 引号' 有什么区别？写一条命令，echo 一个字符串。它要同时含有字面的 $ 、 ! 和换行符。参考 Quoting 。 单引号里什么都不展开。双引号会展开变量。 $'…' 会把 \\n 这类转义变成真字符。 ? 原理 '…' \"…\" $'…' $name 变量展开 不展开 展开 不展开 \\n \\t 原样两个字符 原样两个字符 变成换行或制表符 ! （交互式） 安全 可能触发历史展开 安全 ▶ 跑 题目要的答案在下面，三种写法输出完全一样： 打个比方 单引号是密封袋，里面原样封存。双引号是透明袋，变量会被换成实物。 $'…' 是带说明书的袋子， \\n 会按说明变成换行。 ! 为什么会在这里踩坑 错误写法 echo \"Cost: $5!\" 实际 双引号里的 $5 是 第 5 个位置参数 ，通常为空。所以输出变成 Cost: ! ： 错误写法 在交互式 shell 里敲 echo \"Cost: 5!Thanks\" 报错 bash: !Thanks: event not found 。 ! 后面跟字符，会被当成引用历史命令。脚本里默认不开历史展开，所以只在终端里踩坑。 正确写法 带 ! 的串用单引号。下面用 bash -i 模拟交互式 shell 实测： 考点（答案写在注释里） echo 'It'\"'\"'s' # 输出 It's # 单引号里写不了单引号，所以拆成三段 # 'It' 先关掉单引号，\"'\" 用双引号包一个 '，'s' 再开单引号 # 三段挨着，shell 把它们拼成一个词（补充，非视频内容）"}, {"u": "labs/lab01.html#ex05", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 5 · 2>&1 要写在 > file 后面", "x": "Git Bash 实测 原题 ：shell 有三条标准流：stdin(0)、stdout(1) 和 stderr(2)。运行 ls /nonexistent /tmp ，把 stdout 和 stderr 分别重定向到两个文件。怎么让两者进同一个文件？参考 Redirections 。 > out 2> err 让两路各进各的文件。想进同一个文件，写 > all 2>&1 ，顺序不能反。 K 先回顾 重定向见 第 1 讲第 13 节 。那里演示的第 2 幕画了接线过程。 实测改动 Git Bash 的 /tmp 是 Windows 临时目录，里面全是不相干的文件。所以实测时把 /tmp 换成沙箱里的 demo 目录，它只有一个文件。命令结构完全不变。 ▶ 跑 两者进同一个文件有两种写法。结果逐字节相同，用 cmp 验证过： 打个比方 2>&1 是让 2 号“跟 1 号走”。它只看 1 号 此刻 在哪。1 号要是还没搬家，2 号就跟着留在终端。 ! 为什么会在这里踩坑 错误写法 ls /nonexistent demo 2>&1 > wrong.txt 现象 错误信息还是打在终端上，文件里只有正常输出。 原因 重定向 从左到右 处理。 2>&1 的意思是，1 号此刻指向哪，2 号就跟着指向哪。执行它时 1 号还连着终端，于是 2 号也连到终端。之后的 > wrong.txt 只改了 1 号。 正确写法 先改 1 再复制，写成 > file 2>&1 。或者用 bash 的 &> file 。 考点（答案写在注释里） cmd 2>/dev/null | wc -l # 只数 stdout 的行数 # stderr 被扔进 /dev/null，而且管道本来就只接 stdout cmd > all 2>&1 # 对：先把 1 改到文件，2 再跟过去 cmd 2>&1 > all # 错：2 先跟了终端，报错还在屏幕上"}, {"u": "labs/lab01.html#ex06", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 6 · a && b || c 不等于 if-else", "x": "Git Bash 实测 原题 ： $? 是上一条命令的退出码，0 表示成功。 && 只在前一条成功时运行下一条。 || 只在前一条失败时运行。写一行命令，仅当 /tmp/mydir 不存在时才创建它。参考 Exit Status 。 答案是 [ -d /tmp/mydir ] || mkdir /tmp/mydir 。目录存在时，左边退出码是 0，右边直接跳过。 ? 原理 目录存在时， [ -d /tmp/mydir ] 退出 0， || 右边被跳过。不存在时退出 1，就执行 mkdir 。整行的退出码，是最后真正执行的那条命令的退出码。 ▶ 跑 第二次运行时， mkdir 根本没执行，所以不会报 File exists。另一个常见答案是 mkdir -p /tmp/mydir 。 -p 在目录已存在时也返回成功。实测完，脚本自动删掉了 /tmp/mydir。 打个比方 || 像“不行就找备胎”。前一条办成了，备胎就不用出场。 ! 为什么会在这里踩坑 误解 以为 a && b || c 就等于 if a; then b; else c; fi 。 实际 a 成功但 b 失败 时，c 也会执行。实测 true && false || echo … 打印了 “c ran”。if 版本不会进 else： 考点（答案写在注释里） cd mydir && rm -rf * # cd 失败，rm 就不跑 cd mydir; rm -rf * # 危险：cd 失败后，照样在当前目录 rm -rf * # 所以脚本里推荐 set -e，或者用 && 串起来"}, {"u": "labs/lab01.html#ex07", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 7 · cd 必须内建，因为子进程改不了父进程的目录", "x": "Git Bash 实测 原题 ：为什么 cd 必须内建在 shell 里，而不能是一个独立程序？提示：想想子进程能影响父进程什么，不能影响什么。 外部程序跑在子进程里。它只能改自己那份当前目录，退出时那份就没了。 ? 原理 每个进程都有自己的当前目录。shell 运行外部程序时，会创建一个子进程。子进程拿到的是父进程目录的 拷贝 。它只能改自己的拷贝，退出时拷贝也跟着消失。所以外部的 cd 程序改不了你 shell 的目录。“fork 加拷贝”这一层是补充的系统知识，不在视频里。 ▶ 跑 打个比方 子进程像你复印了一张地图交给跑腿的。他在复印件上画了新路线，你手里的原件一点没变。 下面的演示把这段输出画成两个进程框。看子进程的当前目录怎么被拷贝、修改，然后消失： 考点（答案写在注释里） ./setenv.sh # 脚本在子进程里跑，里面的 export FOO=1 随它消失 echo $FOO # 所以这里还是空的 source setenv.sh # 在当前 shell 里执行，FOO 才会留下 . setenv.sh # 和 source 一样。第 2 讲会讲环境变量"}, {"u": "labs/lab01.html#ex08", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 8 · [ -f \"$1\" ] 的引号一个都不能省", "x": "Git Bash 实测 原题 ：写一个脚本，接收文件名参数 $1 。用 test -f 或 [ -f … ] 检查文件在不在。存在和不存在时，打印不同的信息。参考 Conditional Expressions 。 核心就一行 if [ -f \"$1\" ]; then 。 $1 外面的双引号一定要加。不然空参数和带空格的文件名，都会出错。 K 先回顾 if 与退出码、test 和 [ ，见 第 1 讲第 14 节 。脚本参数是 $1 。 {} 写 ▶ 跑 打个比方 双引号像给文件名套个信封。名字里有空格也好，是空的也好，信封都只算一件。 ! 为什么会在这里踩坑： $1 没加引号 现象 不传参数时，错误版说文件 '' 存在 。文件名带空格时，报 [: my: binary operator expected 。正确版两种情况都对。 原因 不加引号的 $1 会先按空白切词。空参数让 [ -f ] 只剩一个参数 -f 。test 规定单个非空字符串就算真。带空格时，参数变成 -f my file.txt 三个，语法就错了。 正确写法 变量展开 永远加双引号 ，写成 \"$1\" 。shellcheck 会对这个报 SC2086。 考点（答案写在注释里） [ -f $1 ] # 错：$1 会被切词，空参数时误判为存在 [ -f \"$1\" ] # 对：引号保证它永远是一个参数 [[ -f $1 ]] # [[ ]] 是 bash 关键字，里面不切词，所以不出错 # 讲义说 [[ ]] 更安全，就是这个原因。为了习惯和可移植，照样加引号（补充）"}, {"u": "labs/lab01.html#ex09", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 9 · ./ 运行要 x 权限，bash 读文件只要 r", "x": "Git Bash 实测 Linux 未实测 原题 ：把上一题的脚本存成 check.sh ，试试 ./check.sh somefile 会怎样。再 chmod +x check.sh 后重试。为什么需要这一步？提示：对比 chmod 前后的 ls -l check.sh 。 ./check.sh 是让内核 执行 这个文件，没有 x 就拒绝。 bash check.sh 是让 bash 读 它，只要 r 就行。 ? 原理 在 Linux 上，新建的文件默认是 -rw-r--r-- ，没有 x。 ./check.sh 会被拒绝，报 Permission denied ，退出码 126。 chmod +x 给 u、g、o 都加上 x。之后内核读第一行的 #! ，找到解释器去运行。 视频 讲师现场演示了 Permission denied。 演示了 chmod +x 之后 ls 的颜色变化。 ▶ 跑 下面是本机 Git Bash 的实测结果。NTFS 不记录 x 位，所以 chmod 前后都是 rwx，也复现不了 Permission denied： 打个比方 ./check.sh 是让这张纸自己站起来干活，得有许可证。 bash check.sh 是你拿着纸照着念，看得见字就行。 考点（答案写在注释里） bash check.sh # 运行的是 bash，它本身有 x。check.sh 只是被读进去的数据 ./check.sh # 把 check.sh 本身当程序执行，所以它自己得有 x chmod +x check.sh # 加上 x，Linux 下就不再 Permission denied"}, {"u": "labs/lab01.html#ex10", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 10 · set -x 让你看到展开后的真实参数", "x": "Git Bash 实测 原题 ：在脚本的 set 参数里加上 -x 会怎样？写个简单脚本观察输出。参考 The Set Builtin 。 set -x 会在每条命令执行前，把展开后的样子打到 stderr。变量被切成几个参数，一眼就能看出来。 {} 写 ▶ 跑 带 + 的是追踪行，写到 stderr。不带的是程序真正的输出。追踪最有用的场景，是排查变量被切词这类问题： 一眼就能看到 ls a b 。 $f 没加引号，被切成了两个参数。 打个比方 set -x 像给脚本装了行车记录仪。每条命令出发前，都先拍一张它真实的样子。 考点（答案写在注释里） + echo 'hello missing 1' # 追踪用引号标出参数边界：这是一个参数 + ls a b # 这里是两个参数，说明 $f 被切词了 bash -x script.sh # 不改脚本也能开追踪"}, {"u": "labs/lab01.html#ex11", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 11 · 备份名带日期：用 $(date +%Y-%m-%d)", "x": "Git Bash 实测 原题 ：写一条命令，把文件复制成带今天日期的备份。比如 notes.txt 变成 notes_2026-01-12.txt 。提示： $(date +%Y-%m-%d) 。参考 Command Substitution 。 一行答案是 cp notes.txt \"notes_$(date +%Y-%m-%d).txt\" 。 $( ) 先跑 date，再把输出塞进文件名。 ▶ 跑：一行命令版 {} 写：通用脚本版（补充） ▶ 跑 带空格的 my report.md 也正确备份了。忘了传参数时， set -u 让脚本立刻报错退出。它不会去执行 cp \"\" \"_2026-…\" 。 打个比方 命令替换像填空题。shell 先把括号里的题做完，再把答案抄进空格里。 考点（答案写在注释里） date +%Y-%m-%d # 2026-10-29：年月日的字典序就是时间顺序 date +%d-%m-%Y # 29-10-2026：按名字排序就乱了 ls notes_* # 用年月日命名，ls 默认就按日期排好（补充）"}, {"u": "labs/lab01.html#ex12", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 12 · 测试命令换成 \"$@\"，参数原样传下去", "x": "Git Bash 实测 原题 ：修改讲义里的 flaky test 脚本。让它把测试命令当参数接收，不再写死 cargo test my_test 。提示： $1 或 $@ 。参考 Special Parameters 。 把第 19 行的 cargo test my_test 换成 \"$@\" 。调用时给的每个参数，都会原样变成一个词。 K 先回顾 讲义脚本的逐行解释见 第 1 讲第 16 节 。还会用到后台 & 、 $! 和重定向 > file 2>&1 。 {} 写（绿色是相对讲义新增或改动的行） 为了能真跑，再写一个第 4 次必定失败的假测试： ▶ 跑 打个比方 \"$@\" 像原封不动地转交一摞信。每封信还是一封，不拆开，也不合并。 ! 为什么会在这里踩坑：把整条命令塞进一个引号 现象 bash fake_test.sh: command not found ，第 1 轮就“失败”了。 原因 引号让 bash fake_test.sh 成了 一个 参数。 \"$@\" 原样展开成这一个词。shell 就去找一个名字带空格的程序。下面的演示画出了两种调用的差别。 正确写法 每个词分开传： ./flaky.sh bash fake_test.sh 。脚本里用 \"$@\" 。别用 $* 、 \"$*\" 或 $1 。 $1 只拿得到命令名，丢了它的参数。 考点（答案写在注释里） if [ $# -eq 0 ]; then ... # 一个参数都没给，就报用法退出 # 去掉这个检查会怎样：没有参数时 \"$@\" 展开为空 # while 的条件成了空命令，退出码是 0 # 于是无限打印 Run N passed（补充推理，未实测）"}, {"u": "labs/lab01.html#ex13", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 13 · 提取、排序、计数、再排序、取前 N", "x": "Git Bash 实测 原题 ：用管道找出家目录里最常见的 5 种扩展名。提示：组合 find、grep/sed/awk、sort、 uniq -c 和 head。 先把扩展名抠出来，再 sort | uniq -c 计数，最后 sort -rn | head -5 。和讲义的 SSH 日志流水线是同一个套路。 ? 原理 和讲义的 SSH 日志流水线是同一个套路 实测改动 题目的答案是 find ~ … 。笔记不想读你家目录里的私人文件，也想让结果能复现。所以实测时，把 ~ 换成了 课程讲义仓库 的一份本地克隆。.git 目录也排除了。这份克隆在生成笔记后已经删掉。 ▶ 跑 用 awk 按 . 分列，取最后一列，结果相同： 打个比方 像统计班里同学的姓。先把姓抄下来，按顺序排好。同姓的数一数，再按人数排个名次。 ! 为什么会在这里踩坑：awk 版把 ./ 里的点也算进去了 原因 路径都以 ./ 开头。没有扩展名的文件，比如 Dockerfile，按 . 切开后 NF 是 2。最后一列成了 /Dockerfile 。它们都只出现 1 次，没进前 5 名，但统计里混进了垃圾。sed 版先用 -name '*.*' 只挑名字里有点的文件，就没有这个问题。 考点（答案写在注释里） sort | uniq -c # 对：先排序，相同的扩展名才挨在一起 uniq -c | sort # 错：uniq 只合并相邻行，没排序就数不准 sort -rn # -r 倒序，-n 按数值，次数多的排前面"}, {"u": "labs/lab01.html#ex14", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 14 · 文件名过管道，用 -print0 配 xargs -0", "x": "Git Bash 实测 原题 ： xargs 把 stdin 里的行变成命令参数。用 find 和 xargs 找出目录里所有 .sh 文件。再用 wc -l 统计每个的行数，不许用 find -exec 。加分项：处理带空格的文件名，提示 -print0 和 -0 。 xargs 默认按空白切参数，文件名里的空格会把它切坏。 find -print0 | xargs -0 改用空字节分隔，文件名原样保留。 ▶ 跑：朴素写法 xargs 退出码 123，表示它调用的命令有失败。 my script.sh 被拆成了两个参数。 ▶ 跑：加分版，也就是正确答案 打个比方 换行分隔像用逗号隔开名单，名字里一有逗号就乱了。空字节像用一种名字里绝不会出现的符号来隔。 下面的演示把字节流里的分隔符画出来。 \\n 换成 \\0 之后，xargs 再也不会从文件名中间下刀。 考点（答案写在注释里） find . -name '*.sh' -exec wc -l {} \\; # 每个文件启动一次 wc find . -name '*.sh' -print0 | xargs -0 wc -l # 攒成一批交给一次 wc，所以有 total 行 find . -name '*.sh' -exec wc -l {} + # 用 + 结尾，-exec 也能批量（补充）"}, {"u": "labs/lab01.html#ex15", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 15 · 从网页抠数据，先找每项只出现一次的模式", "x": "Git Bash 实测（联网） 原题 ：用 curl 取课程网站 https://missing.csail.mit.edu/ 的 HTML，管道给 grep，数出列了几讲。提示：找每讲只出现一次的模式。用 curl -s 关掉进度输出。 每一讲都是一个 href=\"/2026/讲名/\" 链接。用 grep -o 抠出来， sort -u 去重， wc -l 一数，就是 9。 ? 原理 首页上每一讲都是一个链接，形如 <a href=\"/2026/course-shell/\"> 。 grep -o 只输出匹配到的部分，一个匹配占一行。 sort -u 去重， wc -l 计数。 ▶ 跑 打个比方 像在通讯录里数人数。要挑每人只出现一次的东西数，比如手机号。数名字容易把同名的人算重。 ! 为什么会在这里踩坑：模式太宽 原因 结果是 10 不是 9。顶部导航栏的 lectures 链接 href=\"/2026/\" 也含 /2026/ 。另外 grep -c 数的是 行数 ，不是匹配次数。同一行有两个匹配，只算 1。 考点（答案写在注释里） grep -o 'href=\"/2026/[a-z-]*/\"' | sort -u | wc -l # 9：只认讲次链接 grep -c '/2026/' # 10：导航栏也被算进去了 # 网页一改版，模式就可能失效。正经做法是用 HTML 解析器（补充）"}, {"u": "labs/lab01.html#ex16", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 16 · jq 三件套：.[] 展开、select 过滤、.字段 取值", "x": "jq 未实测 Python 交叉验证 原题 ： jq 是处理 JSON 的利器。用 curl 下载 https://microsoftedge.github.io/Demos/json-dummy-data/64KB.json ，再用 jq 取出 version 大于 6 的人的名字。提示：先 jq . 看结构，再试 jq '.[] | select(...) | .name' 。 答案是 jq -r '.[] | select(.version > 6) | .name' 。数据里 version 是小数，6.1 也算大于 6。 ? 原理 数据是一个对象数组。每个对象长这样： {\"name\": \"Adeel Solangi\", \"language\": \"Sindhi\", \"id\": \"…\", \"bio\": \"…\", \"version\": 6.1} 。这是本机 curl 实测看到的第一条。 ▶ 跑 交叉验证：同样的数据和条件，用 Python 真跑。一共 197 人，其中 89 人 version 大于 6，前 8 个名字如下。jq 版的输出应当一致。 -r 让 jq 输出不带引号的原始字符串。 打个比方 jq 像一条筛子流水线。 .[] 把一箱人倒出来。 select 只放过符合条件的， .name 只留下名牌。 考点（答案写在注释里） jq '.[] | select(.version > 6) | .name' # 每个名字带双引号，是 JSON 字符串 jq -r '.[] | select(.version > 6) | .name' # -r 输出原始文本，方便再接给别的命令"}, {"u": "labs/lab01.html#ex17", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 17 · awk 里跟数字比，别跟字符串比", "x": "Git Bash 实测 原题 ： awk '$3 ~ /pattern/ {$4=\"\"; print}' 只打印第 3 列匹配 pattern 的行，并去掉第 4 列。写一条 awk 命令，只打印第 2 列大于 100 的行。再把第 1、3 列交换。用 printf 'a 50 x\\nb 150 y\\nc 200 z\\n' 测试。 答案是 awk '$2 > 100 {print $3, $2, $1}' 。 100 不能加引号，加了就成了按字典序比。 ▶ 跑：写法一，直接按新顺序打印 ▶ 跑：写法二，真的交换字段再 print 给 $1 和 $3 赋值后，awk 会重组整行。分隔符用输出分隔符，默认是空格。所以不带参数的 print ，打印的就是交换后的行。 打个比方 字典序比数字，像查字典只看第一个字母。9 开头的 99 排在 1 开头的 100 后面，于是它“更大”。 下面的演示逐行播放 awk 的执行过程。还会 手推 字符串比较，看 99 为什么“大于” 100： ! 为什么会在这里踩坑：和字符串常量比较 错误写法 awk '$2 > \"100\"' 现象 50 和 99 也被当成“大于 100”。 原因 只要一边是字符串常量，awk 就按字典序比较。 \"99\" 和 \"100\" 先比第 1 个字符。 '9' > '1' ，直接判定 99 更大。 正确写法 和数字常量比： $2 > 100 。 考点（答案写在注释里） awk '$2 > 100' # 对：跟数字比，按数值大小 awk '$2 > \"100\"' # 错：跟字符串比，按字典序，99 会赢"}, {"u": "labs/lab01.html#ex18", "c": "练习 1 · 课程概览 + Shell 入门", "t": "练习 18 · 仿照 SSH 流水线，统计自己最常用的命令", "x": "Git Bash 实测 原题 ：拆解讲义里的 SSH 日志流水线，每一步在做什么？然后仿照它，从 ~/.bash_history 或 ~/.zsh_history 里找出你最常用的 shell 命令。 取每行第一个词，再接 sort | uniq -c | sort -rn | head 。套路和练习 13 一模一样。 K 拆解答案 逐段拆解写在 第 1 讲第 12 节 的表格里。那一节的演示会逐段播放。每一级都是在示意日志上的 真跑输出 。 实测改动 实测没读你真实的历史记录。用的是一份 20 行的示意历史文件 ex18/history.txt 。在自己电脑上，把文件名换成 ~/.bash_history 就行。 ▶ 跑 统计“命令加第一个参数”，比如 git status 和 git push 分开算： 打个比方 就像翻自己的外卖记录，看哪家店点得最多。 补充（非视频内容）：zsh 的历史格式 开了 EXTENDED_HISTORY 的 zsh，历史行长这样： : 1700000000:0;git status 。要先用 sed 's/^: [0-9]*:[0-9]*;//' 去掉时间戳前缀，再统计。这条没在本机实测。 考点（答案写在注释里） awk '{print $1}' history.txt | sort | uniq -c | sort -rn | head -5 # 只看命令名 awk '{print $1, $2}' history.txt | sort | uniq -c | sort -rn | head -3 # 命令加第一个参数 # 坑：zsh 历史行开头带时间戳，不先用 sed 去掉，第一列就全是冒号"}, {"u": "labs/lab01.html#selfcheck", "c": "练习 1 · 课程概览 + Shell 入门", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。 考点速查（注释里写着答案） ls file?.txt # 匹配不到 file10.txt：? 只匹配一个字符（练习 3） [ -f $1 ] # 去掉引号：空参数误判存在，带空格报错（练习 8） cmd > file 2>&1 # 2>&1 复制的是 1 号此刻的去向，所以写在后面（练习 5） bash flaky.sh \"bash fake_test.sh\" # 第 1 轮就失败：整串成了一个命令名（练习 12） /usr/bin/cd # 做不成：子进程改完目录就退出，父 shell 不受影响（练习 7）"}, {"u": "labs/lab02.html", "c": "练习 2 · 命令行环境", "t": "开头", "x": "LAB 02 · 对应 第 2 讲 · 命令行环境 练习可视化笔记 · 命令行环境 讲义第 2 讲一共 24 道练习，这里逐题讲。讲义按 8 个小节分组编号，这里改成连续编号。每题的标签里注明了“讲义小节 · 第几题”。每题先亮结论，再给真跑的代码和输出。接着打个比方讲原理，最后指出坑在哪。考点都写在代码注释里。官方不给答案，题解是笔记作者写的。 所有输出都由脚本在本机真跑后自动收集 。生成时间是 … 。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 本机没有对应环境，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab02.html#env", "c": "练习 2 · 命令行环境", "t": "环境检查：本机是 Git Bash，没有 Linux 虚拟机", "x": "本页命令都在 Windows 的 Git Bash 里真跑。要用虚拟机或 tmux 的几条，标成了未实测。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机限制与处理办法 没有 Linux 和虚拟机 ：Docker Desktop 启动不了。WSL 里也没有发行版。讲义“远程机器”那组练习要一台 Linux 虚拟机。凡是要 VM 上 sshd 的步骤，都标成了 未实测 。能在本机跑的部分照样真跑。比如生成密钥、解析 ~/.ssh/config 、模拟追加 authorized_keys。还有用 Python 写的转发器，演示端口转发的数据路径。最后是对示意配置文件跑加固脚本。 Git Bash 缺的工具 ：tmux、mosh、pgrep、pkill、sshd 都没有。练习 6 用 /proc/<PID>/cmdline 自己实现了 pgrep -lf 和 pkill -f。练习 9 和 23 未实测。 没有交互终端 ：本页命令由脚本批量执行，按不了 Ctrl-Z。所以用 set -m 打开作业控制，再用 kill -TSTP %1 代替 Ctrl-Z。你按 Ctrl-Z 时，终端驱动发的正是 SIGTSTP。需要交互式 shell 的地方，用 bash -i <<'EOF' 把命令从 stdin 喂进去。输出里会看到提示符 bash-5.3$ 。 隐私 ：每条命令都在一个全新的临时目录里跑。 HOME 也指向这个沙箱。 没有读写你真实的家目录、~/.ssh 和历史记录 。输出里的 /tmp/ms26-xxxxxxxx ，就是那次运行的沙箱目录。练习 3 要比较全部环境变量。为了不把本机环境打到页面上，先用 env -i 清空环境再做。 怎么用这一页 代码块右上角有个“复制”。它复制的是源文件的原始字节，不带行号和注释层。“注释”按钮能隐藏或显示所有注释。每道题标题右边可以勾“完成”。想自己验证，就按 页尾“自查” 的方法重跑。"}, {"u": "labs/lab02.html#ex01", "c": "练习 2 · 命令行环境", "t": "练习 1 · -- 之后的参数，一律不当选项", "x": "讲义 · Arguments and Globs · 1 Git Bash 实测 原题 ：你可能见过 cmd --flag -- --notaflag 这样的命令。 -- 是个特殊参数，告诉程序停止解析选项。它之后的一切，都当作位置参数。这有什么用？试试 touch -- -myfile ，然后不用 -- 删掉它。 答案是 rm ./-myfile 。加个路径前缀，文件名就不以 - 开头了。程序不会再把它当选项。 K 先回顾 参数只是字符串，flag 是程序自己解析的约定。见 第 2 讲第 2 节 。glob 在程序运行前展开，见 第 3 节 。 ? 原理 程序从左到右看参数。以 - 开头的当选项，其余当文件名。文件名本身以 - 开头时，就分不清了。 -- 是绝大多数程序都认的约定，getopt 系列解析库都支持。它之后的参数一律不当选项。另一个办法是给文件名加路径前缀，写成 ./-myfile 。这样它就不以 - 开头了。 ▶ 跑 读输出： rm -myfile 被当成了选项 -m -y … 。GNU rm 报 unknown option，还贴心地提示 rm ./-myfile 。加上 -- 之后 exit=0。最后 ls | wc -l 为 0，说明文件确实删掉了。题目要求“不用 -- 删掉”，答案就是 rm ./-myfile 。 打个比方 -- 像检票口喊一声“后面的都是乘客”。之后哪怕有人举着“司机”的牌子，也只当他是乘客。 ! 为什么会在这里踩坑：glob 展开出一个“选项” -- 真正保命的是这种场景。目录里恰好有个叫 -l 的文件。 现象 ls * 输出的是 a.txt 和 b.txt 的 长格式 。文件 -l 却不见了。 原因 shell 把 * 展开成 -l a.txt b.txt ，按字母序 - 排在前面。ls 收到的就是 ls -l a.txt b.txt 。换成 rm * ，目录里又有个叫 -rf 的文件，后果可想而知。 正确写法 ls -- * 或 rm ./* 。这样 -l 就被当作文件名列了出来。 搜索内容以 - 开头时，道理一样： grep -v notes.txt 把 -v 当成了反向匹配选项。notes.txt 成了模式，grep 转去读 stdin。这里 stdin 是空的，于是返回 1。 grep -- -v notes.txt 才是在 notes.txt 里找 -v。 考点（答案写在注释里） cmd --flag -- --notaflag # --notaflag 只是普通位置参数，不会被当成选项 # -- 本身被解析库吃掉，不出现在位置参数里 rm ./-myfile # 不用 -- 也能删：加个路径前缀 grep -- -v notes.txt # 在文件里搜 -v，而不是打开反向匹配"}, {"u": "labs/lab02.html#ex02", "c": "练习 2 · 命令行环境", "t": "练习 2 · 需求逐条翻成 flag： ls -lath --color=auto", "x": "讲义 · Arguments and Globs · 2 Git Bash 实测 原题 ：读 man ls ，写一条 ls 命令。要求是：包含所有文件，含隐藏文件。大小用人类可读格式，比如 454M 而不是 454279954。按修改时间排序。输出带颜色。样例输出见讲义。 答案是 ls -lath --color=auto 。单字母 flag 能合并，顺序随意。 ? 原理 需求 flag（man ls） 列出所有文件，包括以 . 开头的 -a ，也就是 --all 大小人类可读 -h ，要配合长格式 -l 才看得到大小 按修改时间排序，最新的在前 -t 彩色 --color=auto ，输出到终端时才上色 答案是 ls -lath --color=auto 。讲义源码里注释掉的参考答案，就是这一条。单字母 flag 顺序随意， -ltha 也一样。 ▶ 跑 读输出：准备步骤用 touch -d 设了文件时间，和讲义样例相近。 .. 是沙箱所在的临时目录，刚被修改过，所以排第一。 .hidden 和 baz 时间相同。 1153434 字节显示成 1.2M ，因为 -h 向上取整。文件日期超过半年，ls 就显示年份，不显示时刻。 打个比方 flag 像点奶茶的选项：大杯、少冰、加珍珠。每个字母管一件事，合在一张单子上写就行。 ! 为什么会在这里踩坑：管道里看不到颜色 现象 --color=auto 接管道时，没有任何颜色代码。 --color=always 才把转义序列写进输出。 cat -v 把它显示成 ^[[01;34m ，01;34 是粗体蓝色。 原因 auto 的意思是，stdout 是终端才上色。颜色码写进管道或文件，只会变成乱码。所以 auto 是正确的默认值。本页输出都是经管道收集的，只能用 cat -v 让你看见颜色码。 考点（答案写在注释里） ls -lath --color=auto # a 全部，l 长格式，t 按时间，h 人类可读 ls -lAth # . 和 .. 也有修改时间，所以会参与排序。-A 去掉它们 ls --color=always | cat -v # 颜色码写进了管道，显示成 ^[[01;34m 这类乱码"}, {"u": "labs/lab02.html#ex03", "c": "练习 2 · 命令行环境", "t": "练习 3 · printenv 看子进程的环境，export 看 shell 的记录", "x": "讲义 · Arguments and Globs · 3 Git Bash 实测 原题 ：进程替换 <(command) 让你把命令输出当文件用。用 diff 加进程替换，比较 printenv 和 export 的输出。为什么不一样？提示： diff <(printenv | sort) <(export | sort) 。 环境变量是进程的一个属性。printenv 看的是 子进程收到的 环境。export 看的是 shell 自己记的 导出表。 K 先回顾 进程替换和环境变量，见 第 2 讲第 5 节 ，有演示。 实测改动 直接在你的 shell 里跑，会把整个环境打出来。里面有 PATH、用户名和各种令牌。为了不把本机环境写进页面，先用 env -i 清空环境。只给 HOME 和 PATH，再启动一个干净的 bash 做比较。命令本身不变。 ▶ 跑 读输出时， < 是 printenv 的行， > 是 export 的行： 格式不同 ：printenv 打印 NAME=value 。export 不带参数时，打印能被 shell 重新读入的 declare -x NAME=\"value\" 。所以每一行都“不同”。 只在 export 里 ： EMPTY 。它被标成导出，但从没赋值。shell 记得这个标记，可它不会进入子进程的环境。printenv 自然看不到。 只在 printenv 里 ： _=/usr/bin/printenv 。bash 启动每个子进程前，会把 $_ 设成该程序的路径。再把它放进 那个子进程的 环境。shell 自己的导出表里没有这一项。 两边都没有 ： local_var 。它是没 export 的本地变量。 Git Bash 特有： MSYSTEM 、 SYSTEMROOT 、 WINDIR 就算 env -i 也会被 MSYS 运行时补回来。OLDPWD 是 cd / 之前的沙箱目录。 declare -p local_var 显示 declare -- ，没有 x 标记。对比 export 输出里的 declare -x ，x 就是“导出”标记。 打个比方 export 表像公司的对外公开名单。printenv 看的是新员工手里那份复印件。名单上挂了名、却没填内容的，复印件里就没有。 考点（答案写在注释里） diff <(printenv | sort) <(export | sort) # diff 要两个输入，stdin 却只有一个 # <( ) 把两条命令的输出各变成一个文件名 # 本机实测是 /dev/fd/63 这类 export EMPTY # 只标记导出、没赋值：export 里有，printenv 里没有 declare -p local_var # declare -- 表示没导出，-x 才是导出"}, {"u": "labs/lab02.html#ex04", "c": "练习 2 · 命令行环境", "t": "练习 4 · marco 和 polo 必须是函数，还得 source 进来", "x": "讲义 · Environment Variables · 1 Git Bash 实测 原题 ：写 bash 函数 marco 和 polo 。执行 marco 时，以某种方式保存当前工作目录。之后不管你在哪个目录，执行 polo 都要 cd 回去。回到的就是执行 marco 时的那个目录。可以把代码写进 marco.sh ，用 source marco.sh 载入或重新载入。 marco 把当前目录存进一个变量，polo 再 cd 回去。它们必须在当前 shell 里运行，所以要 source，不能 bash 一个脚本。 K 先回顾 变量与 export，见 第 2 讲第 5 节 。cd 为什么必须是内建命令，见 第 1 讲练习 7 。 {} 写 ▶ 跑 在深层目录 marco，跳到 /usr/bin ，polo 一下就回来了。 打个比方 marco 像在地图上插面小旗，polo 是“导航回小旗”。旗子得插在你手里那张地图上。插在复印件上，你自己的地图没变化。 ! 为什么会在这里踩坑：把它当脚本运行 错误写法 bash marco.sh ，然后 marco 报错 marco: command not found ，exit=127 原因 bash marco.sh 在子进程里定义了两个函数。子进程一结束，函数跟着消失。就算函数还在，它在子进程里 cd，也改不了你的 shell。 source 才让文件在 当前 shell 里逐行执行。 防御 没先运行 marco 就 polo 怎么办？第 10 行检查 MARCO 是不是空的，给出提示并 return 1。不检查的话， cd \"\" 在 bash 5.3 里会报 cd: null directory 。这是本机另测的。 考点（答案写在注释里） source marco.sh # 在当前 shell 里定义函数，之后 marco 和 polo 才能用 bash marco.sh # 函数定义在子进程里，跑完就没了 echo \"$PWD\" > ~/.marco # 改存进文件，就能跨终端：这边 marco，那边 polo（补充） # 代价是多一次文件读写"}, {"u": "labs/lab02.html#ex05", "c": "练习 2 · 命令行环境", "t": "练习 5 · 用返回码驱动循环，每轮覆盖写日志", "x": "讲义 · Return Codes · 1 Git Bash 实测 原题 ：有个命令偶尔才失败。为了调试，要抓到失败那次的输出。可等它失败很费时间。写一个 bash 脚本，反复运行下面的脚本，直到它失败。标准输出和标准错误要分别存进文件。最后把它们全部打印出来。加分项：报告跑了多少次才失败。 让返回码驱动循环，成功就再跑一轮，失败就停。两条流用 > 每轮覆盖，写进两个文件。循环停下时，文件里正好只剩失败那一轮。 K 先回顾 返回码与 ! ，见 第 2 讲第 6 节 。重定向 stdout 和 stderr，见 第 4 节 。它和第 1 讲的 flaky 测试脚本是同一个套路。见 第 1 讲第 16 节 。 {} 写 被测脚本是讲义原文，一字未改： 题解： ▶ 跑 失败那一轮的两条流，分别落在 out.log 和 err.log 里。每次运行的轮数都不同，连跑三次： 讲义的 Markdown 源码里，藏着一份注释掉的参考答案。它用 until [[ \"$?\" -ne 0 ]] 判断上一轮的返回码。再用 &> 把两条流写进同一个文件。照着它跑一遍： 它能工作，但两条流混进了一个文件。分不清哪句来自 stderr。题目要求“分别存进文件”。所以上面的题解用了两个文件。 打个比方 这像守在机器前一直试，试到出事为止。每次只留最后一张小票，出事那张自然就在手里。 ! 为什么会在这里踩坑：用了追加，或者没重定向 错误写法 bash random.sh >> out.log 2>> err.log ，也就是追加 后果 日志里堆着上百轮 “Everything went according to plan”。失败那一轮埋在了最后。用 > 每轮覆盖，循环结束时文件里 只剩 失败那一轮。这正是我们要的。 错误写法 while bash random.sh; do count=$((count+1)); done ，不重定向 后果 能停在失败处，但上百行成功输出会刷屏。失败信息一闪而过，题目还要求最后打印全部。这条是推理，没单独实测。 考点（答案写在注释里） if ! bash random.sh > out.log 2> err.log; then break; fi # 每轮覆盖，失败就跳出 # 每轮失败概率 1/100，要跑的轮数服从几何分布 # 期望是 1/p = 100 轮，标准差约 99.5 # 所以三次实测是 26、10、25 轮，差这么多很正常"}, {"u": "labs/lab02.html#ex06", "c": "练习 2 · 命令行环境", "t": "练习 6 · pgrep -f 按完整命令行找进程，不用手打 PID", "x": "讲义 · Signals and Job Control · 1 Git Bash 实测（模拟 pgrep） Linux 未实测 原题 ：在终端里启动 sleep 10000 。用 Ctrl + Z 挂起它，再用 bg 让它在后台继续跑。然后用 pgrep 找到它的 PID，用 pkill 杀掉它。全程不许亲手输入 PID。提示： -lf 。 Linux 上的答案是 pgrep -lf \"sleep 10000\" 加 pkill -f \"sleep 10000\" 。 -f 匹配的是完整命令行，不只是程序名。 K 先回顾 作业控制与信号，见 第 2 讲第 8 节 ，有状态机演示。 ? 原理 pgrep 列出命令行匹配的进程。 -f 匹配完整命令行， -l 顺便显示名字。pkill 给匹配到的进程发 SIGTERM。两者都来自 procps 包，原理是遍历 /proc/<PID>/cmdline 。Git Bash 没有 procps，但 MSYS 运行时同样提供了 /proc。于是自己写一个： {} 写（Git Bash 下的替代品） ▶ 跑 读输出：先确认本机确实没有 pgrep 和 pkill。 kill -TSTP %1 代替 Ctrl-Z 后，作业显示 Stopped。 bg %1 发 SIGCONT，让它在后台 Running。 pgrep_lf 打印出那个 sleep 的 PID 和完整命令行。 pkill_f 发 SIGTERM，jobs 报告 Terminated。再查一次，已经没有匹配的进程。全程没有手打 PID。 打个比方 pgrep -f 像按快递单上的完整地址找包裹。只按程序名找，就像只按“张三”找。会翻出一堆同名的。 ! 为什么会在这里踩坑：本机实测踩到的两个坑 现象 1 第一版脚本在 sleep 10000 & 之后，立刻 kill -TSTP %1 。jobs 仍显示 Running。接着 bg 报 “job 1 already in background”，pkill 也杀不掉它。 原因 这是竞争。信号发出时，sleep 可能还没完全启动。bash 也还没来得及收到“已暂停”的通知。进程其实已经停下了，Git Bash 的 ps 第一列显示 S。而停住的进程在 Git Bash 下，连 TERM 和 KILL 都处理不了。最后只能从 Windows 那边结束它。加一句 sleep 0.3 让状态稳定，问题就消失了。上面的题解就是这样写的。 现象 2 pgrep_lf 把测试脚本自己也匹配上了。前提是没跳过 bash 进程。 原因 脚本是用 bash -c '…sleep 10000…' 运行的。这个 bash 的命令行里，也有 “sleep 10000”。真正的 pgrep 有同样的问题。在脚本里用 pgrep -f 时，小心匹配到自己的父进程（补充）。 考点（答案写在注释里） pgrep -l sleep # 只匹配进程名，所有 sleep 都会找到 pgrep -lf \"sleep 10000\" # 匹配完整命令行，能精确到参数 10000 pkill -f \"sleep 10000\" # 默认发 SIGTERM"}, {"u": "labs/lab02.html#ex07", "c": "练习 2 · 命令行环境", "t": "练习 7 · wait 只能等自己的子进程，别人的要轮询", "x": "讲义 · Signals and Job Control · 2 Git Bash 实测 原题 ：想等一个进程结束，再启动另一个。限制进程是 sleep 60 & 。一种办法是用 wait ：启动 sleep，让一条 ls 等它结束。但换到另一个 bash 会话里，这招就不灵了。因为 wait 只对子进程有效。有一点课上没讲： kill 成功时返回 0，否则返回非 0。 kill -0 不发信号，但进程不存在时返回非 0。写一个 bash 函数 pidwait 。它接收一个 PID，一直等到该进程结束。用 sleep 避免白白占用 CPU。 自己的子进程，直接 wait $pid 。别的进程就用 kill -0 轮询，每轮 sleep 1 秒，直到它返回非 0。 实测改动 把 sleep 60 缩短成 sleep 3 ，不然每次生成页面都要干等一分钟。逻辑完全相同。 ▶ 跑：第一部分，wait 时间戳差 3 秒。wait 一直阻塞到后台 sleep 结束，之后 ls 才运行。 {} 写：第二部分，pidwait ▶ 跑 读输出：另一个 bash 里， wait $P 立刻失败了。 bash -c 是一个新的 shell 进程。报错是 pid … is not a child of this shell ，退出码 127。题目说的情况真实出现了。同一个“外人” shell 里换成 pidwait，就能一直等到 sleep 结束。开始和结束的时间戳差 4 秒。那是 sleep 剩下的约 3 秒，加上最多 1 秒的轮询间隔。 打个比方 wait 像父母等自家孩子放学，学校会通知。pidwait 像等邻居家孩子，只能每隔一会儿去门口看一眼。 考点（答案写在注释里） wait $P # 只对本 shell 的子进程有效，否则报 not a child，返回 127 kill -0 $P # 不发信号，只测进程还在不在 while kill -0 \"$1\" 2>/dev/null; do sleep 1; done # pidwait 的核心 # 删掉 sleep 1：循环不停地启动 kill -0，把一个 CPU 核心占满 # sleep 越长越省 CPU，但发现得越晚"}, {"u": "labs/lab02.html#ex08", "c": "练习 2 · 命令行环境", "t": "练习 8 · 让 find 打印“时间 路径”，再统一排序", "x": "讲义 · Files and Permissions · 1（进阶） Git Bash 实测 原题 ：进阶题。写一条命令或脚本，递归找出目录里最近修改的文件。更一般地，你能按修改时间列出所有文件吗？ 让 find 给每个文件打印一行“时间戳 路径”。按数值排序后，最后一行就是最新的。这比在 ls 的输出上做文章可靠得多。 K 先回顾 find 见 第 1 讲第 10 节 。sort、tail、cut 流水线见 第 1 讲第 12 节 。 ? 原理 GNU find 的 -printf 能打印每个文件的元数据。 %T@ 是修改时间的 Unix 时间戳，带小数。 %p 是路径。 %TY-%Tm-%Td %TH:%TM 是人能读的日期。先打印“时间 路径”，再按数值排序。最后一行就是最新的。 -printf 是 GNU 扩展，macOS 自带的 BSD find 没有。可以改用 stat ，或者装 GNU findutils（补充）。 ▶ 跑 打个比方 ls -tR 像每个班各自按身高排队。find 加 sort 像全校站成一排再排。想找全校最高的，只能用后一种。 ! 为什么会在这里踩坑：ls -tR 不是全局排序 现象 ls -tR 确实递归了，但每个目录 各自 排序。最新的 helpers.py 埋在最后一段。你没法一眼看出全局最新的是谁。 正确写法 让 find 把所有文件压平成一个列表。再统一排序，就是上面的写法。 考点（答案写在注释里） find proj -type f -printf '%T@ %p\\n' | sort -n | tail -n 1 # 全局最新的文件在最后一行 ls -tR proj # 每个目录各排各的，不是全局 # 为什么用 %T@ 排：精确到小数秒，同一分钟改的文件也分得出先后 # “2026-01-13 08:15”按字典序排也对，但只精确到分钟"}, {"u": "labs/lab02.html#ex09", "c": "练习 2 · 命令行环境", "t": "练习 9 · tmux 先练熟三层结构，配置放进 dotfiles", "x": "讲义 · Terminal Multiplexers · 1 tmux 未实测 原题 ：跟着这篇 tmux 教程 学一遍。然后按 这些步骤 ，做一些基本定制。 会话、窗口、窗格三层先练熟，再写一份 ~/.tmux.conf 。本机没有 tmux，配置写好了，但没实测。 K 先回顾 tmux 的三层结构和前缀键，见 第 2 讲第 11 节 ，有演示。 ? 怎么做（在 Linux、macOS 或 WSL 上） 安装： sudo apt install tmux 或 brew install tmux 。 照第 2 讲第 11 节的表格逐个练。先 tmux new -s work 开会话，再用 <C-b> \" 或 % 分割，用 <C-b> 方向键 切换。然后 <C-b> c 开窗口， <C-b> d 分离。最后 tmux ls 看一眼， tmux a -t work 接回。 在 VM 里跑一个 sleep 1000 。分离后断开 SSH，重连再接回，确认它还在跑。这是 tmux 最有价值的地方。 写配置文件。下面这份放在 dotfiles 仓库里。练习 14 的安装脚本会把它链接到 ~/.tmux.conf 。改完在 tmux 里按 前缀 r 重载。 {} 写 ▶ 跑 本机能做的只有两件事。确认 tmux 不存在，再数一下配置里有 9 条有效指令。 检验标准 要在有 tmux 的机器上看。 tmux show-options -g prefix 应输出 prefix C-a 。 tmux list-keys 里能看到 | 和 - 绑定到 split-window。鼠标能点选窗格。 打个比方 tmux 配置像给工具箱重新排格子。前缀改成 C-a，就像把最常用的扳手挪到手边。 考点（答案写在注释里） tmux source-file ~/.tmux.conf # 改了配置，开着的 tmux 不会自动生效 # tmux server 只在启动时读一次配置 # 配置里绑的“前缀 r”就是干这个的 # 不想 source，就杀掉 server 重开。和改了 .bashrc 要 source 一个道理"}, {"u": "labs/lab02.html#ex10", "c": "练习 2 · 命令行环境", "t": "练习 10 · alias dc=cd 一行搞定，但只在交互式 shell 里生效", "x": "讲义 · Aliases and Dotfiles · 1 Git Bash 实测 原题 ：建一个别名 dc 。你把 cd 打错时，它也能用。 答案就一行 alias dc=cd ，放进 dotfiles 的 bash/aliases 。脚本里它不起作用，因为非交互式 shell 不展开别名。 K 先回顾 alias 见 第 2 讲第 13 节的别名部分 。练习 13、14 会把它放进 dotfiles。 ▶ 跑 第一行说明，Git Bash 里本来没有叫 dc 的命令。在 Linux 上， dc 往往是个真实存在的程序。它是“桌面计算器”，bc 的兄弟。别名会盖过它，这一点没实测。随后在交互式 bash 里定义别名， dc /usr 确实切换了目录。 打个比方 别名像输入法里的自定义短语，只有你手打时才会替换。脚本是印好的文章，没人在打字，替换就不会发生。 ! 为什么会在这里踩坑：脚本里别名不生效 现象 在 bash -c 里写 alias dc=cd; dc /usr ，结果报 dc: command not found 。 原因 非交互式 shell 默认不展开别名， expand_aliases 选项是关着的。而且 bash 是读完 一整行 才执行的。同一行里刚定义的别名，对这一行本身不起作用。所以第二个例子做了两件事。打开选项，再把定义和使用分在两行。 结论 别名是给人敲命令用的。脚本里请用函数。 考点（答案写在注释里） alias dc=cd # 对：= 两边没有空格 alias dc = cd # 错：alias 收到 dc、=、cd 三个参数，当成查询，找不到就报 not found alias dc=cd; dc / # 同一行定义、同一行用，不生效。bash 读完一整行才执行"}, {"u": "labs/lab02.html#ex11", "c": "练习 2 · 命令行环境", "t": "练习 11 · 先 sort 再 uniq -c，数出最常用的 10 条命令", "x": "讲义 · Aliases and Dotfiles · 2 Git Bash 实测 原题 ：运行 history | awk '{$1=\"\";print substr($0,2)}' | sort | uniq -c | sort -n | tail -n 10 ，得到你最常用的 10 条命令。考虑给它们写更短的别名。注意，这条适用于 Bash。zsh 要用 history 1 代替 history 。 awk 先删掉行号， sort | uniq -c 计数， sort -n | tail 取最多的 10 条。用得最多的，最值得起别名。 实测改动 不读你的真实历史。用 history -r ex11/history.txt ，把一份 20 行的示意历史读进 bash 的历史列表。再运行题目里的原命令。 ? 原理 awk 给 $1 赋空串后，会用空格重组整行。开头因此多出一个空格，再用 substr($0,2) 去掉它 ▶ 跑 git status 用了 6 次，ls -la 用了 4 次。给它们起 gs 、 ll 这样的别名最划算。这两个已经写进 dotfiles 的 bash/aliases。 打个比方 像月底翻外卖记录，看哪家点得最多。点得最多的那家，最值得设成快捷下单。 ! 为什么会在这里踩坑：统计把自己也算进去了 现象 你刚敲下的 history … 这一行，在 执行前 就被记进了历史。编号是 21，交互式 bash 就是这样。 影响 统计结果里会多出一条 “history | awk …”，次数为 1。不碍事，但别惊讶。 考点（答案写在注释里） sort | uniq -c # 对：先排序，散在各处的 git status 才会挨在一起 uniq -c # 错：uniq 只合并相邻的重复行（第 1 讲） history 1 # zsh 要这样写，才列出全部历史"}, {"u": "labs/lab02.html#ex12", "c": "练习 2 · 命令行环境", "t": "练习 12 · dotfiles 就是一个按工具分目录的 git 仓库", "x": "讲义 · Aliases and Dotfiles · 3 Git Bash 实测 原题 ：给你的 dotfiles 建一个文件夹，并设置版本控制。 建一个 git 仓库，按工具分子目录。练习 13 到 17 都在它上面接着做。 K 先回顾 dotfiles 的组织方式，见 第 2 讲第 14 节 ，有演示。git 本身第 5 讲细讲。 ? 结构 按工具分子目录。文件名去掉开头的点，链接时再加上。这样在仓库里就不会被 ls 隐藏 ▶ 跑 提交作者用 -c user.name=… 临时指定，免得读写你的全局 git 配置。沙箱里的 HOME 也是临时目录。 打个比方 dotfiles 仓库像一个搬家专用箱。按房间分好格子，搬到哪都能原样摆回去。 考点（答案写在注释里） dotfiles/bash/bashrc # 仓库里不带点：ls 看得见，按工具分组也清楚 ~/.bashrc # 家目录里带点的名字，由安装脚本建链接时决定 # 很多人的 dotfiles 仓库都这样组织（补充）"}, {"u": "labs/lab02.html#ex13", "c": "练习 2 · 命令行环境", "t": "练习 13 · PS1 用单引号，提示符才会每次重新展开", "x": "讲义 · Aliases and Dotfiles · 4 Git Bash 实测 原题 ：给至少一个程序加一些定制，比如你的 shell。起步可以很简单，比如设置 $PS1 来定制提示符。 写一份自己的 bashrc。提示符显示当前目录和上一条命令的失败码。PATH 里加上 ~/bin。别名单独放一个文件。 K 先回顾 PS1、PATH 和配置文件的加载时机，见 第 2 讲第 13 节 。 {} 写 ▶ 跑 读输出：这里的提示符是 bash 真实画出来的。家目录显示成 ~ 。 ls /nonexistent 失败，返回 2。下一个提示符前面就出现了 [2] 。再下一条命令成功， [2] 就消失了。别名文件也被加载了。 打个比方 PS1 像车上的仪表盘。单引号是装了一块实时跳动的表。双引号是拍张照片贴上去，永远停在拍照那一刻。 ! 为什么会在这里踩坑：rcfile 只在交互式 shell 里读 现象 1 bash --rcfile … -c '…' 里 PS1 是空的。带 -c 的 bash 不是交互式的，根本不读 rcfile。 现象 2 把 bashrc 当脚本运行，也就是 bash bashrc 。第 2 行的 return 报 “can only `return' from a function or sourced script”，exit=1。bashrc 是给 shell source 的，不是拿来执行的。 考点（答案写在注释里） PS1='$(r=$?; [[ $r -ne 0 ]] && echo \"[$r] \")\\w \\$ ' # 单引号：$( ) 和 $? 原样存进去 # 每次显示提示符时，bash 再展开一遍 # 换成双引号：赋值那一刻就执行了 $( )，提示符永远定格在当时的值"}, {"u": "labs/lab02.html#ex14", "c": "练习 2 · 命令行环境", "t": "练习 14 · 安装脚本只做一件事：给每个文件建软链接", "x": "讲义 · Aliases and Dotfiles · 5 Git Bash 实测 原题 ：设一个办法，在新机器上快速装好 dotfiles。而且不用手工操作。可以简单到一个 shell 脚本，为每个文件调用一次 ln -s 。也可以用 专门的工具 。 bash install.sh 一条命令装好全部配置。它能反复跑，不覆盖已有文件。在 Git Bash 上也能建出真正的符号链接。 K 先回顾 符号链接见 第 2 讲第 14 节 ，有演示。 set -euo pipefail 见第 1 讲。 {} 写 ▶ 跑 读输出：家目录里原有的 .bashrc 被改名备份了。4 个链接都建好了。 ls -l 第一个字符是 l ，末尾的 -> 指向仓库。第二次运行只是重建链接， 没有 再备份。因为它现在已经是链接了。这就叫幂等。 链接的意义在这里。直接改仓库里的文件，家目录立刻生效： 打个比方 软链接像把家里所有开关都接到一块总控面板上。改总控面板，各个房间马上跟着变。 ! 为什么会在这里踩坑：Git Bash 的 ln -s 默认是复制 现象 没设 MSYS 时， ln -s 不报错。但 [ -L ] 判断它不是链接，它是一份 拷贝 。之后你改仓库，家目录的配置纹丝不动。 正确写法 看脚本第 8 到 10 行。在 MINGW 或 MSYS 下，导出 MSYS=winsymlinks:nativestrict 。建不出真链接时就直接报错，不会悄悄复制。这需要 Windows 开发者模式或管理员权限。在 Linux 和 macOS 上，ln -s 一直是真链接。 考点（答案写在注释里） ln -sfn \"$src\" \"$dst\" # -f 替换已有链接，脚本能反复跑 # -n 目标是指向目录的链接时，别把新链接建进那个目录里 rm \"$dst\"; ln -s … # 先删再建也行，但多一步，多一个失败点（补充） [ -L ~/.bashrc ] # 为真才是链接。Git Bash 不设 MSYS 时，这里是假"}, {"u": "labs/lab02.html#ex15", "c": "练习 2 · 命令行环境", "t": "练习 15 · 从 git clone 出来的副本测，才等于新机器", "x": "讲义 · Aliases and Dotfiles · 6 Git Bash 实测（空 HOME 代替 VM） VM 未实测 原题 ：在一台全新的虚拟机上，测试你的安装脚本。 本机没有 VM，就造一个空的 HOME 代替。从仓库克隆，再跑安装脚本，最后开个新 shell 检查。 ? 思路 “全新”的关键是家目录里什么都没有。你手工改过的东西，一样都不能有。本机没有 VM，就造一个 空的 HOME 目录 。从 git 仓库克隆，而不是直接用工作目录。再运行安装脚本，打开新的交互式 shell 检查效果。 ▶ 跑 空 HOME 里一开始是 0 个文件。克隆，安装，再开新 shell。别名 dc 能用，PATH 末尾也多了新 HOME 下的 bin。 打个比方 这像搬新家前，先在空房子里试摆一遍。只用搬家箱里有的东西，旧房子里顺手放的一样不带。 ! 为什么会在这里踩坑：在 Windows 上克隆，换行符变了 现象 Git for Windows 的系统配置里有 core.autocrlf=true 。没有 .gitattributes 的仓库，克隆出来的 install.sh 是 CRLF 换行。加了 * text=auto eol=lf 之后，克隆出来是 LF。中间几行 warning，是 git 在提交时提醒你。它会把工作区里的 CRLF 规范成 LF。 为什么危险 Git Bash 的 bash 能容忍 CRLF。本机实测，带 CRLF 的 bashrc 照样加载。所以在 Windows 上测不出问题。把这样的文件拿到 Linux 上，bash 会报 $'\\r': command not found 。这条没实测，是补充。“在全新机器上测试”能抓到的，正是这类问题。 做法 仓库里放一个 .gitattributes ，练习 12 已经加了。 考点（答案写在注释里） git clone REPO \"$HOME/.dotfiles\" # HOME 指向空目录。从仓库克隆，才等于新机器拿到的东西 # 开发目录里可能有没提交的文件，或者只在本地的改动 # 上面的 CRLF 问题，也只有经过 clone 才会冒出来 * text=auto eol=lf # 写进 .gitattributes，统一用 LF"}, {"u": "labs/lab02.html#ex16", "c": "练习 2 · 命令行环境", "t": "练习 16 · 逐个迁移，机密文件不进仓库", "x": "讲义 · Aliases and Dotfiles · 7 Git Bash 实测（示意家目录） 原题 ：把你当前所有工具的配置，都迁进 dotfiles 仓库。 一次只迁一个工具。mv 进仓库，install.sh 加一行，重建链接，再提交。私钥和带令牌的配置一律不进仓库。 ? 步骤 盘点 ：列出家目录和 ~/.config 下的配置文件。 逐个迁移 ： mv ~/.vimrc dotfiles/vim/vimrc 。在 install.sh 里加一行 link vim/vimrc .vimrc 。跑一次安装脚本，把链接建回来，确认工具还正常。 排除机密 ：私钥 ~/.ssh/id_* 和带令牌的配置 不进仓库 。 ~/.ssh/config 可以进。但先查查里面有没有内网地址，这类信息别公开。 提交 ：每迁一个工具就提交一次，出了问题好回滚。 讲师建议，别一次性照搬别人的整份配置，要逐行理解。见 第 2 讲第 14 节 。 ▶ 跑：盘点（在示意家目录上） 准备步骤造了一个假家目录。里面有私钥文件和历史文件。盘点命令只挑出了配置文件。 id_ed25519 和 .bash_history 没被列出来，它们本来也不该进仓库。本页没读你的真实家目录。 打个比方 迁配置像收拾行李箱。衣服鞋子都装进去，护照和银行卡单独贴身带。 考点（答案写在注释里） link vim/vimrc .vimrc # 迁一个工具：mv 进仓库，install.sh 加一行 link nvim .config/nvim # ~/.config 下的整个目录也能链接（补充） # install.sh 里 ln -sfn 的 -n，就是为这种情况准备的 mkdir -p ~/.config # 链接前先确保父目录存在"}, {"u": "labs/lab02.html#ex17", "c": "练习 2 · 命令行环境", "t": "练习 17 · 发布前先扫一遍机密，推送要你自己来", "x": "讲义 · Aliases and Dotfiles · 8 发布前检查实测 发布未实测 原题 ：把你的 dotfiles 发布到 GitHub。 推送前先 grep 一遍私钥头、password、token 这类字样。没有匹配，再建仓库推上去。 ? 步骤 发布前扫一遍可疑内容，下面真跑了。 在 GitHub 网页上新建一个空仓库 dotfiles，不要勾选生成 README。 git remote add origin git@github.com:你/dotfiles.git ，再 git push -u origin main 。用 SSH 推送前，要先把练习 18 的公钥加到 GitHub 账户。这就是讲师说的“GitHub 用你的公钥验证你”。 在 README 里写一句安装方法： git clone … ~/.dotfiles && bash ~/.dotfiles/install.sh 。 本笔记没有替你建账户，也没有推送。这要用你的 GitHub 账号。而且发布是公开操作，应该由你自己来。 ▶ 跑：发布前的机密扫描 在 dotfiles 和 ssh 配置里找可疑字样。比如私钥头、password、token、secret 和 api key。结果没有匹配，grep 返回 1。 打个比方 发布前扫机密，像寄快递前检查箱子。别把家门钥匙一起封进去。 考点（答案写在注释里） grep -rnIiE 'BEGIN .*PRIVATE KEY|password|passwd|token|secret|api[_-]?key' dotfiles ssh # 返回 1：没找到 # 万一把私钥推上去了，删掉文件再提交一次不够。它还在 git 历史里 # 要立刻作废这对密钥，从所有 authorized_keys 和 GitHub 删掉公钥，换新的 # 清理历史只是次要的（补充）"}, {"u": "labs/lab02.html#ex18", "c": "练习 2 · 命令行环境", "t": "练习 18 · 带口令的 ed25519 密钥：.pub 能给人，私钥不能", "x": "讲义 · Remote Machines · 1 Git Bash 实测（沙箱 HOME） 原题 ：本组练习需要一台 Linux 虚拟机。可以参考讲义链接的 安装教程 。进入 ~/.ssh/ ，看看有没有一对 SSH 密钥。没有的话，用 ssh-keygen -a 100 -t ed25519 生成。推荐设口令，并使用 ssh-agent 。 ssh-keygen 生成两个文件。 id_ed25519.pub 可以给别人， id_ed25519 绝不能给。口令不对时，连本机都解不开私钥。 K 先回顾 SSH 密钥见 第 2 讲第 9 节 ，有演示。 ▶ 跑 沙箱 HOME 里原本没有 ~/.ssh。生成后得到私钥 id_ed25519 和公钥 id_ed25519.pub。指纹和 randomart 每次都不同。口令用了一句示例短语，真用时请自己想一句。 读输出：口令错误时，连本机都解不开私钥，exit=255。口令正确时， -y 从私钥推出公钥，和 .pub 文件开头一致。私钥文件以 -----BEGIN OPENSSH PRIVATE KEY----- 开头，这里只打印了第一行。 打个比方 私钥加口令，像把钥匙锁进一个带密码的小盒。盒子被偷了，没有密码也打不开。 ! 为什么会在这里踩坑：私钥文件的权限 本机现象 上面 ls -l 显示私钥是 -rw-r--r-- ，所有人可读。这是 Git Bash 根据 Windows 权限拼出来的显示。Windows 版 OpenSSH 另有一套检查方式。 在 Linux 上 私钥权限太宽时，ssh 会拒绝使用。它会提示 “UNPROTECTED PRIVATE KEY FILE!”。要 chmod 600 ~/.ssh/id_ed25519 和 chmod 700 ~/.ssh 。这条没实测，是补充。 考点（答案写在注释里） ssh-keygen -a 100 -t ed25519 # -a 100：用口令派生密钥时，做 100 轮 KDF 运算 # 你解锁慢一点点，攻击者暴力猜口令却要慢 100 倍（补充） ssh-keygen -y -f ~/.ssh/id_ed25519 # 用口令解开私钥，推出公钥 chmod 600 ~/.ssh/id_ed25519 # Linux 上私钥权限太宽，ssh 会拒绝使用"}, {"u": "labs/lab02.html#ex19", "c": "练习 2 · 命令行环境", "t": "练习 19 · ssh -G 不连服务器，也能检查配置", "x": "讲义 · Remote Machines · 2 Git Bash 实测（不连接） 原题 ：编辑 .ssh/config ，加入一个 Host vm 条目。里面有 User、HostName、IdentityFile，还有 LocalForward 9999 localhost:8888。 写好 Host vm 之后， ssh vm 一个词就能连上。还会顺带打开端口转发。没有 VM 时，用 ssh -G vm 看解析结果。 {} 写（题目原样） ▶ 跑 ssh -G 主机 只解析配置，打印最终生效的设置，不会真去连接。所以没有 VM 也能检查配置写对没有。用 -F 明确指定配置文件，保证读的是沙箱里这份。第一行 “Pseudo-terminal will not be allocated…” 是 ssh 的提示。它发现 stdin 不是终端时就会说。本机加了 < /dev/null 也会出现，无害。注意 localforward 9999 [localhost]:8888 ，练习 21 就靠它。 打个比方 ~/.ssh/config 像手机通讯录。存一次“vm”，以后不用每次都背 IP、端口和用户名。 考点（答案写在注释里） Host vm # 具体的主机写在前面 Host *.mit.edu # 通配的写在后面 # 两条同时匹配时，每个选项取第一次出现的值（见 man ssh_config，补充） ssh -G vm # 只打印解析结果，不连接"}, {"u": "labs/lab02.html#ex20", "c": "练习 2 · 命令行环境", "t": "练习 20 · ssh-copy-id 只是往 authorized_keys 追加一行", "x": "讲义 · Remote Machines · 3 本地模拟实测 VM 未实测 原题 ：用 ssh-copy-id vm 把你的 SSH 公钥拷到服务器上。 这个“魔法命令”只做一件事。它把一行公钥追加到服务器的 ~/.ssh/authorized_keys 里。之后登录 VM 就不用密码了。 ? 原理 讲师现场看了 authorized_keys。然后说，这个“魔法命令”只做了一件事。它往服务器上追加了一行公钥（视频 ）。追加进的文件是 ~/.ssh/authorized_keys 。讲义给的手动等价写法是 cat .ssh/id_ed25519.pub | ssh alice@remote 'cat >> ~/.ssh/authorized_keys' 。 ▶ 跑：在本地模拟“追加”这一步 把 ssh alice@remote 换成 (cd fake-vm && …) 。数据流完全一样，只是“远端”成了本地的一个目录。authorized_keys 多了 1 行，内容是类型、公钥和注释 student@laptop。 检验标准 要在有 VM 时看。 ssh -o PasswordAuthentication=no vm true 能成功返回，就说明已经不靠密码了。 打个比方 authorized_keys 像小区门卫手里的访客名单。ssh-copy-id 就是往名单上添一行你的名字。 考点（答案写在注释里） cat .ssh/id_ed25519.pub | ssh alice@remote 'cat >> ~/.ssh/authorized_keys' # 用 >> 追加 # 写成 > 会清空文件。别人或你别的电脑之前放进去的公钥，全没了 ssh -o PasswordAuthentication=no vm true # 能成功，说明已经不靠密码"}, {"u": "labs/lab02.html#ex21", "c": "练习 2 · 命令行环境", "t": "练习 21 · 端口转发：最后一跳是 VM 自己连 localhost", "x": "讲义 · Remote Machines · 4 本机替身实测 VM 未实测 原题 ：在 VM 里执行 python -m http.server 8888 ，启动一个网页服务器。然后在本机浏览器访问 http://localhost:9999 。 浏览器连本机 9999，ssh 把数据经加密连接送到 VM。VM 上的 sshd 再替你连 localhost:8888。只在 VM 本机监听的服务，也能这样搬到你电脑上。 K 先回顾 练习 19 的 LocalForward。 第 2 讲第 10 节 演示的第 2 幕，画了完整的数据路径。 ? 原理 “localhost:8888” 是从 VM 的角度说的。这条连接由 VM 上的 sshd 发起 {} 写：没有 VM 时的“替身” ▶ 跑 读输出：curl 只连了本机 19999。拿到的却是 18888 上 http.server 给的页面，状态码 200。转发器日志记了两次转发。http.server 的访问日志显示，请求来自 127.0.0.1。这和用 ssh -L 时 VM 上看到的一样。因为请求是 sshd 从 VM 本机发起的。中间那行 Killed，是实验结束时 kill -9 清理转发器留下的提示。 打个比方 端口转发像一条专用地下通道。你从自家 9999 号入口进去，从 VM 屋里的 8888 号门出来。外人在街上直接敲 8888 的门，敲不开。 考点（答案写在注释里） LocalForward 9999 localhost:8888 # 本机 9999 进，VM 视角的 localhost:8888 出 # VM 上的服务只绑 localhost，为什么转发后还能访问？ # 最后一跳是 VM 上的 sshd 自己连 localhost:8888，对 VM 来说是本机连接 # 外网直接访问 VM 的 8888 会被拒，这正是端口转发安全的地方"}, {"u": "labs/lab02.html#ex22", "c": "练习 2 · 命令行环境", "t": "练习 22 · 关密码登录前，先确认密钥能登录", "x": "讲义 · Remote Machines · 5 示意配置实测 VM 未实测 原题 ：用 sudo vim /etc/ssh/sshd_config 编辑 SSH 服务端配置。改 PasswordAuthentication 的值，禁用密码认证。改 PermitRootLogin 的值，禁止 root 登录。用 sudo service sshd restart 重启 ssh 服务，再试着 ssh 进去。 两行都改成 no ，服务器就只认密钥，root 也不能直接登录。第 1 讲日志里那些扫描器乱试 admin、root。这下再怎么猜都没用。 {} 写 示意配置，按 Ubuntu 默认文件的相关几行写成： 用脚本代替手工编辑，可重复，也能审查： ▶ 跑：对示意文件执行 检验标准 要在有 VM 时看。改完先用 sudo sshd -t 检查语法。 当前会话保持别退出 ，另开一个终端测试。密钥登录成功， ssh -o PubkeyAuthentication=no vm 被拒，提示 Permission denied (publickey)。Ubuntu 上服务名是 ssh，写成 sudo service ssh restart 。讲义写的 sshd 在部分发行版上适用（补充）。 打个比方 关密码登录像把门上的密码锁拆了，只留指纹锁。拆之前，先确认自己的指纹真能开门。 ! 为什么会在这里踩坑：把自己锁在门外 场景 还没确认公钥登录能用，就关了密码登录。然后还退出了会话。 做法 先做练习 20，验证免密登录能用。改配置时，始终留一个已登录的会话。等新会话测试通过了，再关掉它。VM 至少还有控制台能救。云服务器可能就麻烦了（补充）。 考点（答案写在注释里） #PasswordAuthentication yes # 被注释的行只是告诉你，默认值是 yes PasswordAuthentication yes # 只删 # 等于显式写 yes，什么也没改 PasswordAuthentication no # 要把值改成 no sudo sshd -T | grep -i passwordauth # 核对最终生效的值 # sshd 取第一次出现的值。Include 进来的 sshd_config.d/*.conf 可能先写了 yes"}, {"u": "labs/lab02.html#ex23", "c": "练习 2 · 命令行环境", "t": "练习 23 · （挑战）同一会话断网后接着刷新，才算恢复", "x": "讲义 · Remote Machines · 6 未实测 原题 ：挑战题。在 VM 里装好 mosh ，建立连接。然后断开服务器或 VM 的网卡。mosh 能正确恢复吗？ 本机做不了这个实验，下面给出步骤和判断标准。断网再接上后，同一个会话接着刷新。不用重新登录，就算能恢复。 ? 实验步骤与判断标准 本机和 VM 都装上 mosh，它需要两端各有一个程序。VM 的防火墙要放行 UDP 60000 到 61000。 本机运行 mosh vm ，它会复用 ~/.ssh/config 的设置。在里面跑 top 这类不断刷新的程序。 在虚拟机软件里断开 VM 网卡，等 30 秒以上，再接上。 对照组：用普通的 ssh vm 重复同样的操作。 判断标准 ：断网期间，mosh 窗口顶部会提示失去连接。恢复后同一个会话继续刷新，不用重新登录。这就是“能恢复”。ssh 的会话通常会卡住，等到超时断开。 讲义说 mosh 能处理断线和睡眠唤醒。切换网络和高延迟链路，它也扛得住。以上步骤和预期现象是补充说明，本机未实测。 ▶ 跑 打个比方 ssh 像打电话，信号一断就得重拨。mosh 像发短信，断网时先攒着，网一回来接着收。 考点（答案写在注释里） mosh vm # 断网、睡眠唤醒、换网络都能接着用（讲义） tmux # 有了 mosh 还要 tmux：关掉本机终端或重启电脑，远端的 mosh-server 也会结束 # tmux 让会话不依赖任何客户端，两者常一起用（补充）"}, {"u": "labs/lab02.html#ex24", "c": "练习 2 · 命令行环境", "t": "练习 24 · （挑战）-N 不开 shell，-f 认证完转后台", "x": "讲义 · Remote Machines · 7 参数表实测 转发未实测 原题 ：挑战题。查查 ssh 的 -N 和 -f 是干什么的。想出一条在后台做端口转发的命令。 答案是 ssh -N -f -L 9999:localhost:8888 vm 。只开隧道，不开远端 shell，也不占当前终端。 ? 答案 flag 含义（ man ssh ） -L 9999:localhost:8888 本地转发，和配置里的 LocalForward 同义 -N 不执行远端命令。只做转发，不开 shell -f 认证完成后转入后台。认证时可能要你输入口令 命令是 ssh -N -f -L 9999:localhost:8888 vm 。如果 ~/.ssh/config 里已经写了 LocalForward， ssh -N -f vm 就够了。结束时用 pkill -f 'ssh -N -f' ，这是练习 6 学的。 ▶ 跑 本机 OpenSSH 的用法摘要里， N 和 f 都在无参数选项列表 [-46AaCfGgKkMNnqsTtVvXxYy] 里。 打个比方 -N 是只接网线、不开屏幕。-f 是接好线就把机箱塞进柜子，桌面腾出来给你用。 考点（答案写在注释里） ssh -N -f -L 9999:localhost:8888 vm # -N 不开 shell，-f 认证完转后台 ssh -N -L 9999:localhost:8888 vm & # 用 & 不好：一开始就在后台，要输口令时读不到终端 # -f 还会脱离当前 shell 的作业控制，关掉终端也不受影响（补充） pkill -f 'ssh -N -f' # 用完按命令行找到它，结束隧道"}, {"u": "labs/lab02.html#selfcheck", "c": "练习 2 · 命令行环境", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。练习 5 每次失败的轮数不同。练习 18 的指纹也每次不同。这都是正常的。 考点速查（注释里写着答案） ls * # 目录里有 -l、a.txt、b.txt：打印 a.txt 和 b.txt 的长格式（练习 1） bash random.sh >> out.log 2>> err.log # 题解第 6 行改成追加：失败那轮埋在末尾，cat 打出上百行（练习 5） bash marco.sh # 必须 source：子进程里定义的函数和 cd，跑完就消失（练习 4） bash -c \"wait $P\" # 不是自己的子进程：报 not a child，立刻返回 127（练习 7） ln -s \"$src\" \"$dst\" # 删掉 install.sh 第 8 到 10 行：Git Bash 悄悄复制，改仓库不再生效（练习 14）"}, {"u": "labs/lab03.html", "c": "练习 3 · 开发环境与工具", "t": "开头", "x": "LAB 03 · 对应 第 3 讲 · 开发环境与工具 练习可视化笔记 · 开发环境与工具 讲义第 3 讲一共 4 道练习，都是“去做”的开放题。这里每题先亮结论，再给具体做法。能在本机验证的部分，都真跑了一遍。包括 bash 的 Vim 模式和一局本地 VimGolf。还有一个 100 行的 LSP 客户端，和一个亲手写的编辑器扩展。考点都写在代码注释里。 所有输出都由脚本在本机真跑后自动收集 。生成时间是 … 。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 本机没有对应环境，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab03.html#env", "c": "练习 3 · 开发环境与工具", "t": "环境检查：图形界面的操作，改用命令行验证", "x": "VS Code 里的点点按按没法脚本化。本页用命令行，把同样的功能真跑一遍。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机限制与处理办法 图形界面没法脚本化 ：VS Code 里的操作，都得你自己点。本页给出具体步骤和检验标准。再用命令行，把同样的功能验证一遍。Vim 用 vim -Es 批量回放按键。语言服务器部分，用一个自写的 LSP 客户端。它直接和 gopls 对话。扩展部分，用 Vim 自带的包机制。在沙箱里装一个自己写的插件。 不读你的编辑器配置 ：本机装有 VS Code。但本页 没有 列它的扩展，也没读它的设置。那是你的私人配置。所有命令都在临时目录里跑，HOME 指向临时目录。Vim 用 -u NONE 或演示用的 vimrc 启动，不加载你的 ~/.vimrc。 VimGolf 网站 ：提交成绩要注册账号。还要装它的命令行客户端，这需要 Ruby。本笔记不替你注册账号。练习 2 拿讲义的 FizzBuzz，出了一道同样规则的本地高尔夫。还写了一个计数回放器。真正的 VimGolf 题目怎么做，见该题步骤。 不联网 ：讲义建议的 spf13/cobra 项目要联网下载 Go 模块。练习 3 改用一个只依赖标准库的小项目。检查的功能一样。 怎么用这一页 代码块右上角有个“复制”。它复制的是源文件的原始字节。“注释”按钮能隐藏或显示注释层。每道题标题右边可以勾“完成”。想自己验证，就按 页尾“自查” 的方法重跑。"}, {"u": "labs/lab03.html#ex01", "c": "练习 3 · 开发环境与工具", "t": "练习 1 · 处处开 Vim 模式，shell 里一行 set -o vi 就行", "x": "讲义 · Exercises · 1 Git Bash 实测（shell 部分） 图形软件未实测 原题 ：在所有支持 Vim 模式的软件里开启它，比如编辑器和 shell。接下来一个月，所有文本编辑都用 Vim 模式。觉得某个操作效率低时，你会想“一定有更好的办法”。那就去 Google 一下，多半真的有。 bash 里一行 set -o vi ，就切到 Vim 键位。写进 ~/.inputrc ，所有用 readline 的程序一起切。 K 先回顾 模态编辑和 Vim 的编辑语言，见 第 3 讲第 3 节 到 第 8 节 。讲师建议“强迫自己用一个月”，见 第 9 节 。 ? 怎么开 软件 做法 本页 bash 当前会话用 set -o vi 。长期生效就写进 ~/.bashrc 实测 所有 readline 程序，比如 bash 和 python 交互界面 在 ~/.inputrc 里写 set editing-mode vi ，见下面的文件 实测 zsh bindkey -v 。讲义链接了 zsh 的 内建 Vim 模拟 未实测，本机没有 zsh VS Code 扩展市场装 VSCodeVim 未实测，要图形界面 Claude Code 有 Vim 编辑模式 ，在它的配置里打开 未实测 学习 先跑一遍 vimtutor ，装了 Vim 就有 确认存在 {} 写 ▶ 跑 交互式 bash 默认是 emacs 键位。就是 Ctrl-A 到行首、Ctrl-E 到行尾那一套。 set -o vi 之后换成 vi 键位。这时按 Esc 进入命令模式。可以用 b 、 w 、 0 、 $ 、 dw 、 ciw 编辑命令行。 用 inputrc 开启时，提示符前多了 (ins) ，表示当前在插入模式。按 Esc 后会变成 (cmd) 。本页的命令是批量喂进去的，所以看不到切换。 打个比方 Vim 键位像一门外语。只在一个软件里用，就像只在课堂上说外语。处处都开，才是把自己扔进语言环境。 ! 为什么会在这里踩坑：set -o vi 一关终端就没了 误解 在终端里敲了 set -o vi ，以为从此都是 Vim 键位。 实际 它只改当前这个 shell。新开一个终端，又回到默认的 emacs 键位。上面 ex01-a 里，改之前显示的就是 emacs on 。 正确写法 写进 ~/.bashrc ，只管 bash。写进 ~/.inputrc ，所有用 readline 的程序都生效。 补充（非讲义内容）：一个月怎么算练成 第 1 周 ：不看表也能做到这些。i、a、o 进插入，Esc 回来。hjkl、w、b、e 移动。dw、cw、u 编辑。 第 2 到 3 周 ：开始自然地用计数 3w 和行内查找 f( 。还有文本对象，比如 ci\" 和 da( 。 第 4 周 ：遇到重复操作会停下来。想想有没有更短的按法，并真的去查。这就是讲师说的那种“懒”。 阶段划分是笔记作者给的参考。你的体验以实际为准。 考点（答案写在注释里） set -o vi # 只管当前 shell，关掉终端就失效 set -o | grep '^vi ' # 打开后显示 vi on。emacs 同时变成 off，两者互斥 set editing-mode vi # 写在 ~/.inputrc 里：bash、python 交互界面一起生效 # 不用 Vim 也值得学 Vim：VS Code、zsh、bash、Claude Code 都有 Vim 模式 # 学一次，到处用（第 3 讲第 2 节）"}, {"u": "labs/lab03.html#ex02", "c": "练习 3 · 开发环境与工具", "t": "练习 2 · 本地 VimGolf：讲义 70 键，能压到 64 键", "x": "讲义 · Exercises · 2 Git Bash 实测（本地高尔夫） VimGolf 网站未实测 原题 ：完成 VimGolf 上的一道挑战。 VimGolf 比谁用的按键最少。同一个任务有很多种按法。按键数能比，也能优化。 K 先回顾 讲义修 FizzBuzz 的按键，见 第 3 讲第 10 节 。 j 保持列号、 ci\" 往后找引号，见 第 5 节 和 第 8 节 。 ? 规则和做法 每道题给一个起始文件和一个目标文件。你在 Vim 里把前者改成后者， 按键越少越好 。 Esc 和回车各算 1 键，保存退出也要算。 在 vimgolf.com 上做题的流程如下。这是补充内容，依据网站首页的说明。本页没有实际操作： 挑一道题。网页上有起始文本、目标文本和排行榜。 安装官方命令行客户端 gem install vimgolf ，这需要 Ruby。在网站上用 GitHub 账号登录，拿到 API key。再用 vimgolf setup 填进去。 vimgolf put 挑战ID ：它用一个干净的 Vim 打开起始文件。然后记下你的每次按键。改完按 :wq ，它比对结果并显示按键数。你可以选择提交。 本笔记不替你注册账号。下面拿 讲义的 FizzBuzz 修复 当一道本地题。起始文件是讲义的坏代码。目标文件是按讲义按键修好的结果。再写一个回放器，按 VimGolf 的规则计数。 {} 写：题目 {} 写：两份解法（VimGolf 记法） {} 写：回放器 ▶ 跑 输出怎么读。第一行是 Ex 模式执行 :6 时顺手打出的第 6 行。Ex 模式跳到某行会打印它，不影响结果。讲义的解 70 键，通过。本笔记的解 64 键，也通过。修好的程序输出正确。下面的演示逐组回放这 64 键，并手算省在了哪里。 打个比方 VimGolf 像真的高尔夫，比谁杆数少。可光数杆数不够，球停在哪也得算清楚。下一杆怎么打，全看上一杆停在哪。 ! 为什么会在这里踩坑：同样 2 键，4j 和 6G 不一样 错误写法 用 4j 从第 2 行下到第 6 行，也是 2 键。 现象 diff 显示第 6 行变成了 print(\"fizz\", end=\"buzz\") ，结果 FAIL。 原因 j 会尽量保持列号。上一步光标在第 2 行 C31，到第 6 行还是 C31。那里正好在 end=\"\" 那对空引号里。 ci\" 改的是光标所在的，或者后面最近的那对引号。 6G 和 :6<CR> 会把光标放在第一个非空字符上。后面第一对引号才是 \"fizz\"。 教训 高尔夫解法要算上光标的隐含状态。比如列号、寄存器和上次搜索。这也是回放器每次都从同一个干净状态开始的原因。 bash · 本机实测（把 golf.keys 里的 6G 换成 :6<CR>） $ sed 's/6G/:6<CR>/' golf.keys > colon.keys # 只换这一处，其余按键不动 $ bash check.sh colon.keys # 第一行还是 Ex 模式顺手打出的第 6 行 print(\"fizz\", end=\"\") PASS 65 keystrokes (colon.keys) 考点（答案写在注释里） ww 2w # 都是 2 键，一样。计数到 3 以上，3w 才比 www 省 6G :6<CR> # 落点相同，6G 少 1 键。换成 :6<CR> 实测 PASS 65 键 4j # 也是 2 键，但保持列号，落进 end=\"\" 里，FAIL # 日常编辑里讲师更在意不用想，打高尔夫才斤斤计较"}, {"u": "labs/lab03.html#ex03", "c": "练习 3 · 开发环境与工具", "t": "练习 3 · IDE 的每个功能，背后都是一条 LSP 请求", "x": "讲义 · Exercises · 3 Git Bash 实测（gopls） VS Code 操作未实测 原题 ：为你正在做的项目配置 IDE 扩展和语言服务器。确认预期的功能都正常，比如 跳转到依赖库里的定义 。手头没有代码，可以用 GitHub 上的开源项目，比如 spf13/cobra 。 IDE 里点一下鼠标，背后就是一条 LSP 消息。本页写了个 100 行的客户端，把这些消息逐条发给 gopls。 K 先回顾 语言服务器和 LSP，见 第 3 讲第 11 节 。那里的演示第 2 幕，就是下面这次真实会话。还会用到进程的 stdin 和 stdout，见第 2 讲。 ? 在 VS Code 里怎么做（以 Go 和 cobra 为例） 装 Go。 git clone https://github.com/spf13/cobra ，用 VS Code 打开。 扩展市场装官方 Go 扩展 golang.go。它会提示安装 gopls 等工具，点安装。Python 项目就装 Python 扩展，它自带 Pylance。再按讲义 选择 Python 环境 。不然语言服务器看不到你装的包。 逐项检查。下表就是检验标准： 功能 在 IDE 里怎么试 背后的 LSP 请求 补全 在变量后敲 . textDocument/completion 行内文档 鼠标悬停在函数上 textDocument/hover 跳转到定义，包括依赖库 按 F12 或右键 Go to Definition。能跳进 fmt.Println 这类库函数里 textDocument/definition 查找引用 按 Shift+F12 或 Find All References textDocument/references 边写边查错 故意调用不存在的方法，出现红色波浪线 textDocument/publishDiagnostics，由服务器推送 import 帮助 用了没导入的包，保存时自动补 import textDocument/codeAction，类型是 source.organizeImports {} 写：一个小 Go 项目（第 18 行故意写错） {} 写：最小 LSP 客户端，把点鼠标变成一条条请求 ▶ 跑 输出怎么读。 --> 是客户端发出的消息。带 #编号 的是请求，不带的是通知。 <-- 是服务器的回应或推送。 上表 6 项全部验证通过。补全得到 Area、H、W。悬停得到签名和文档注释。 库函数定义跳到了 Go 标准库的 fmt/print.go 第 306 行 。这是题目特别点名的一项。引用找到 2 处。再改出一个“用了 strings 却没 import”的版本。服务器推来新诊断，organizeImports 代码操作把 \"strings\" 加进了 import 块。 对照一下。同一个错误，命令行的 go vet 也能查出来。但它要先完整分析一遍包。语言服务器在你打开文件时，就把错误推过来了： 打个比方 IDE 像一台自动点菜机。你按一下按钮，它就在后台给后厨发一张单子。这个脚本把点菜机拆开，让你看见每一张单子。 ! 为什么会在这里踩坑：写客户端时遇到的两个坑 现象 第一版客户端发完 didOpen 就一直等诊断，偶尔卡住不动。 原因 gopls 会 反过来 向客户端发请求。比如 workspace/configuration ，问你的设置是什么。客户端不回复，它可能一直等。第 45 到 47 行对这类请求一律回复“没有设置”。真正的编辑器当然会认真回答。这就是“配置语言服务器”在协议层面的样子。 另一个坑 行列号在 LSP 里从 0 开始，人习惯从 1 开始。第 64 到 65 行的 at() 专门做这个转换。打印时再加回 1。差一位，就会在错误的位置请求补全。结果莫名其妙。 考点（答案写在注释里） textDocument/completion # 请求：带 id，服务器用同一个 id 回复 textDocument/didOpen # 通知：没有 id，服务器不回复 publishDiagnostics # 服务器主动推送：文件一打开、一修改，它就重新分析 # 为什么是推送：错误随内容变，编辑器不用轮询，红波浪线跟着打字更新 workspace/configuration # 服务器反过来问客户端。不回复，它可能一直等"}, {"u": "labs/lab03.html#ex04", "c": "练习 3 · 开发环境与工具", "t": "练习 4 · 装扩展，就是把脚本放进编辑器会扫描的目录", "x": "讲义 · Exercises · 4 Git Bash 实测（Vim 插件） VS Code 未实测 原题 ：浏览一个 IDE 扩展列表，装一个看起来对你有用的。 Vim 启动时会扫描 pack/*/start/* 目录，执行里面 plugin/ 下的脚本。放进去就算装好，不需要安装程序。 K 先回顾 去哪找扩展、讲义点名了哪几个，见 第 3 讲第 17 节 。 ? 去哪找、怎么选 列表：Vim 插件看 Vim Awesome ，VS Code 看 按安装量排序的扩展 。这是讲义给的。 讲义点名的方向有三个： 开发容器 、 Remote - SSH 和 Live Share 。Remote - SSH 用的就是第 2 讲的 SSH。练习 1 的 VSCodeVim、练习 3 的语言扩展也算。 判断标准 （补充）：先看发布者可不可信。再看安装量、更新时间和要的权限。扩展能读你的代码，也能运行程序。和第 2 讲的 curl | bash 一样，要谨慎。讲师对 shell 插件的建议也适用。一次只装一个，确认真在用再留下。 VS Code 里怎么装：扩展面板搜索后点 Install。或者在命令行用 code --install-extension 发布者.名字 。 {} 写：自己做一个最小的 Vim 扩展 想看清装扩展的本质，就在沙箱里写个 7 行的 Vim 插件。按 Vim 8 自带的包（packages）约定放好目录，再让 Vim 加载它： ▶ 跑 输出怎么读。不加载配置时， :Hello 不存在，Vim 以返回码 1 退出。用演示 vimrc 启动后，插件被自动加载， :scriptnames 列出了 hello.vim。 :Hello MIT 在文件末尾追加了一行。 打个比方 pack 目录像一排固定的快递柜。插件放进对的格子，Vim 每次开门都会取件。不用签收，也不用安装程序。 ! 为什么会在这里踩坑：目录少了一层，插件不加载 错误写法 把 hello.vim 直接放进 pack/demo/start/ 。没有插件自己的目录，也没有 plugin/ 。 现象 不报“找不到插件”，只是 :Hello 不存在。Vim 以返回码 1 退出，文件没被改动。 原因 Vim 只把 start/ 下的每个 子目录 当成一个插件。再执行它里面 plugin/ 下的脚本。直接放在 start/ 下的文件，不会被执行。 正确写法 放成 pack/demo/start/hello/plugin/hello.vim 。git clone 一个插件仓库到 start/ 下，正好就是这个结构。 bash · 本机实测（flat_vimrc 和演示 vimrc 一样，只是 packpath 指向 flat 目录） $ find flat -type f # 少了 hello/plugin/ 这两层 flat/pack/demo/start/hello.vim $ vim -u flat_vimrc -i NONE -Es -c 'Hello MIT' -c 'wq' n2.txt; echo \"flat layout: exit=$?\" flat layout: exit=1 $ cat n2.txt # 没有追加 Hello 那一行 notes 考点（答案写在注释里） ~/.vim/pack/plugins/start/名字/plugin/x.vim # 启动时自动执行。git clone 到 start/ 下就算装好 ~/.vim/pack/plugins/start/x.vim # 少了两层目录，不会被执行 ~/.vim/pack/plugins/opt/名字/ # opt 下的不自动加载，要手动 :packadd 名字（补充） let g:loaded_hello = 1 # 防重复加载的标记：已加载过就 finish :scriptnames # 列出已加载的脚本，确认插件真的进来了"}, {"u": "labs/lab03.html#selfcheck", "c": "练习 3 · 开发环境与工具", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。 练习 3 需要 PATH 里有 go 和 gopls。想试自己的 VimGolf 解，先复制练习 2 的四个文件。分别是 start.py 、 end.py 、 golf.vim 和 check.sh ，放进同一个目录。再放一个 mine.keys ，在该目录运行 bash check.sh mine.keys 。 考点速查（注释里写着答案） golf.keys 里 6G 换成 :6<CR> # PASS 65 键：多 1 键，落点相同（练习 2 实测） golf.keys 里 6G 换成 4j # FAIL：j 保持列号，ci\" 改错了引号（练习 2 实测） lsp_client.py 第 45 到 47 行 # 服务器也会发请求，不回复它可能一直等（练习 3） set -o vi; set -o | grep '^vi ' # 显示 vi on，emacs 同时变成 off（练习 1 实测） vim -u NONE # 不读个人配置，回放结果在谁的电脑上都一样（练习 2） # VimGolf 官方客户端也是用干净的 Vim 记录按键"}, {"u": "labs/lab04.html", "c": "练习 4 · 调试与性能分析", "t": "开头", "x": "LAB 04 · 对应 第 4 讲 · 调试与性能分析 练习可视化笔记 · 调试与性能分析 讲义第 4 讲一共 10 道练习，调试 5 道，性能分析 5 道。这里逐题讲。每题先亮结论，再给真跑的代码和输出。接着打个比方讲原理，最后指出坑在哪。考点都写在代码注释里。官方不给答案，题解是笔记作者写的。 所有输出都由脚本在本机真跑后自动收集 。生成时间是 … 。本讲很多工具只能在 Linux 上跑。每一处都写明了没实测的原因，以及本机的替代做法。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 本机没有对应环境，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab04.html#env", "c": "练习 4 · 调试与性能分析", "t": "环境检查：本机是 Windows，Linux 工具大多跑不了", "x": "本页命令都在 Windows 的 Git Bash 里真跑。rr、perf 这类只能在 Linux 上跑的，标成了未实测。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机限制与处理办法 没有 Linux ：Docker Desktop 一启动就崩，WSL 里也没有可用的发行版。题目点名的这些工具全都跑不了：rr、Linux 版 strace、perf、bpftrace。还有 taskset、ss 和 hyperfine。这些命令标成 未实测 。旁边给出本机能真跑的等价实验。 有的工具 ：MinGW-w64 的 gcc 13、clang 17、gdb 14，但 没有 AddressSanitizer 运行时。Python 3.13，pdb 和 cProfile 都是标准库。Git Bash 自带的 MSYS 版 strace。Windows 自带的 netstat 和 start /affinity 。 Git Bash 的 time 有坑 。原生 Windows 程序，比如 gcc 编出的 exe 和 python，它算不准。报的 user、sys 几乎总是 0.015 s，只能看 real。性能 1 实测过。 数字会变 ：计时、CPU 百分比、PID 每次运行都不同。本机同时还有别的程序在跑，所以波动偏大。 怎么用这一页 代码块右上角有个“复制”。它复制的是源文件的原始字节，不带行号和注释层。“注释”按钮能隐藏或显示所有注释。开关状态记在浏览器里。每道题标题右边可以勾“完成”。想自己验证，就按 页尾“自查” 的方法重跑。"}, {"u": "labs/lab04.html#d1", "c": "练习 4 · 调试与性能分析", "t": "调试 1 · 归并排序取错了下标，条件断点一停就看见", "x": "Git Bash 实测 原题 ：下面的伪代码实现了归并排序，但有一个 bug。用你喜欢的语言实现它。再用调试器找到并修复 bug。gdb、lldb、pdb 或 IDE 的调试器都行。测试向量： merge_sort([3, 1, 4, 1, 5, 9, 2, 6]) 应返回 [1, 1, 2, 3, 4, 5, 6, 9] 。用断点单步执行 merge 函数，找出是在哪里选错了元素。 bug 在第 18 行：从 right 取元素，却用了 left 的下标 i 。条件断点停在两边各 2 个元素的那次合并。打印一下下标就看见了。 K 先回顾 调试器的基本命令，见 第 4 讲第 3 节 。 {} 写：把伪代码逐行翻译成 Python ▶ 跑：先看现象 结果里 4 和 5 各出现两次，2 和第二个 1 却不见了。有元素被重复取，也有元素被漏掉。下一步用调试器看合并过程。 ? 原理：断点设在哪 8 个元素会调用 merge 7 次。前两次是 1+1 的合并，此时 i 和 j 都是 0。就算代码用错了下标，结果也“碰巧正确”。所以直接 b merge ，要按很多次 c 。加上条件 len(left) == 2 and len(right) == 2 ，第一次停下就是 merge([1, 3], [1, 4]) 。把调试命令写进文件，用 < 喂给 pdb，整个会话就能重放： ▶ 跑：单步走一遍 输出怎么读 ： > msort.py(14)merge() 表示停在第 14 行，在 merge 函数里。 -> 后面是 即将执行 的那行。关键在倒数第 4 行。停在第 18 行时，输出是 (1, 0, 4, 1) 。也就是 i=1、j=0。应该取 right[j] =1，代码却取了 right[i] =4。再下一步， result 就成了 [1, 4] 。为了好读，命令用 sed 去掉了 pdb 打印的 Windows 绝对路径前缀。 ▶ 跑：更快的办法，条件断点直接盯住 i ≠ j 断点设在可疑的第 18 行，条件是 i != j 。只有下标不同时，用错下标才会产生错误结果。 w 打印的调用栈从下往上读。从 <module> 开始，到第 26 行的 merge_sort。再到第 5 行递归，第 7 行调用 merge。最后停在第 18 行。 {} 修：只改一个字母 再写一个和 Python 内置 sorted 对拍的随机测试。防止只对一个测试向量“碰巧正确”： ▶ 跑 打个比方 i 和 j 像两个收银员，各管一条队。第 18 行让 j 那队的顾客，按 i 的号码去结账。两人号码碰巧一样时，看不出毛病。 第 4 讲第 3 节有个调试器演示（ 去看 ）。它的第 1 幕把这次单步画成了动画。调用栈、下标指针和结果数组都在里面。 ! 为什么会在这里踩坑：把 gdb 的条件写法用在 pdb 里 错误写法 b 18 if i != j ，这是 gdb 的写法 真实报错 *** The specified object '18 if i != j' is not a function or was not found along sys.path. 。断点根本没设上，程序直接跑完。之后的 p i, j 在模块作用域里执行，报 NameError。 正确写法 pdb 用逗号： b 18, i != j 。 考点（答案写在注释里） b merge, len(left) == 2 and len(right) == 2 # 条件断点：跳过前两次 1+1 的合并 # 前两次 merge 为什么是对的：两边各 1 个元素，走到 else 时 i = 0 = j # 于是 right[i] 碰巧等于 right[j]。bug 只在 i ≠ j 时显现 # 所以一个测试向量不够，要和 sorted 随机对拍"}, {"u": "labs/lab04.html#d2", "c": "练习 4 · 调试与性能分析", "t": "调试 2 · 循环多跑一圈，越界写进了下一个 id", "x": "rr 未实测 gdb 观察点实测 原题 ：安装 rr ，用反向调试找一个内存破坏 bug。把讲义的程序存成 corruption.c ，用 gcc -g corruption.c -o corruption 编译运行。学生 1 的 id 被改坏了，可改坏它的函数只碰了学生 0。用 rr record ./corruption 和 rr replay 找出凶手。对 students[1].id 设观察点。在损坏发生后 reverse-continue ，找到究竟是哪一行覆盖了它。 curve_scores 的循环跑到了 i = 3。 scores[3] 越界，正好落在 students[1].id 上。gdb 观察点正着跑就能抓到，不一定要 rr。 K 先回顾 rr 与反向调试，见 第 4 讲第 4 节 。gdb 的 watch 与重跑，见同一节的学生提问。 {} 讲义的程序（逐字） ▶ 跑：现象 ? 原理：内存布局 students[2] 是连续的 8 个 int。students[0].scores[3] 的地址，正好是 students[1].id ▶ 跑：rr 版，题目要求的做法 在 Linux 上， rr replay 会进入 gdb 界面。然后依次输入下面的命令。它们未实测，是按讲义和视频的用法写的： rr replay 里的命令（未实测） (rr) break 40 # 停在 if (students[1].id != 1002)：此时已经坏了 (rr) continue (rr) watch -l students[1].id # -l：按地址盯住这 4 个字节 (rr) reverse-continue # 倒着执行，直到它的值变化 预期会停在 curve_scores 第 24 行附近，i = 3 的那次 += 。倒放时 Old 和 New 是反的，New 是更早的 1002。 {} 本机替代：gdb 观察点，正着跑同样能抓到 ▶ 跑 输出怎么读 ： Hardware watchpoint 2 说明 gdb 用的是 CPU 的调试寄存器。这几乎不拖慢程序。命中时打印 Old value = 1002、New value = 1007。程序停在 写入之后 的那条语句，也就是第 23 行的 i++ 。 p i 得 3，两个地址都是 <students+16> 。程序自己的 printf 输出全挤在最后。因为 stdout 接的是管道，会被整块缓冲，到退出才刷出。 ▶ 修：循环上界改成 3 打个比方 观察点像在保险柜上装了警报。谁动了柜子，警报当场就响，还告诉你是谁的手。你不用守着，也不用猜。 第 4 讲第 3 节有演示（ 去看 ）。它的第 2 幕逐步画出了这次观察点。第 4 节的演示，是视频里 rr 倒放的版本。 考点（答案写在注释里） watch -l students[1].id # -l 按地址盯住这 4 个字节，谁写它就停 # 这题的 bug 每次都复现，正着跑 gdb 观察点就够了 # rr 的优势一：偶发 bug 只要录到一次，就能无限次确定性重放 # rr 的优势二：从“发现损坏”处倒着走，不用事先猜断点（视频 17:53–18:25）"}, {"u": "labs/lab04.html#d3", "c": "练习 4 · 调试与性能分析", "t": "调试 3 · free 之后再写，程序照常跑，ASan 才报错", "x": "ASan 未实测 编译期检查实测 原题 ：把讲义的程序存成 uaf.c 。先不加 sanitizer 编译运行： gcc uaf.c -o uaf && ./uaf 。它可能看起来正常。再加上 AddressSanitizer： gcc -fsanitize=address -g uaf.c -o uaf && ./uaf 。读错误报告。ASan 找到了什么 bug？修复它。 第 12 行往已释放的内存写了一个字节。不开检查时，这一写通常“成功”。ASan 会当场拦下，报 heap-use-after-free。本机没有 ASan，靠 gcc 的编译期警告也能发现。 K 先回顾 sanitizer 与 Valgrind，见 第 4 讲第 8 节 。那里的演示画了 ASan 的影子内存。 {} 讲义的程序（逐字） ▶ 跑：不加检查 果然“看起来正常”。free 只是把内存还给分配器，字节还在。往里写，也不会立刻出事。 ▶ 跑：题目要求的 ASan 版 本机为什么不行？下面是真实的链接错误，工具链路径已替换成 <mingw64> ： ? 原理：ASan 会报什么 ASan 给每 8 字节内存配 1 字节“影子”。free 之后，它把这块的影子标成“已释放”。还把内存放进隔离区，暂时不复用。编译器在每次读写前插入检查。于是第 12 行 greeting[0] = 'J' 一执行，就会被拦下。报告写的是 heap-use-after-free ，并给出三段调用栈。第一段是非法写入发生在哪，也就是 WRITE of size 1。第二段是这块内存在哪里被 free。第三段是它最初在哪里被 malloc。报告格式见 ASan 文档，这是补充，本机未实测。视频里 heap overflow 的报告也是这样的结构（ ）。 ▶ 跑：本机能做的，编译期就发现 gcc 12 起有 -Wuse-after-free ，它包含在 -Wall 里。它和 -fanalyzer 静态分析，都指出了第 12、13 行。区别在于覆盖面。编译期分析只能抓住编译器“看得出来”的路径。ASan 在运行时检查每一次真实的访问。指针在函数之间传来传去，它也能抓住。 {} 修：先用、后释放 ▶ 跑：-Wall 与 -fanalyzer 都不再报警 打个比方 退了房的房卡，门锁有时还没换。你刷一下，门照样开。可那间房也许已经住进了别人。ASan 就是退房后立刻换锁的前台。 考点（答案写在注释里） free(greeting); greeting = NULL; // 释放后置 NULL：再误用会当场崩在 NULL 上 // ASan 为什么要隔离已释放的内存？ // 马上复用的话，这块的影子又被标成“可访问”，悬空指针再写进去就查不出来 // 隔离区让刚释放的内存一碰就报错（补充，见 ASan 文档）"}, {"u": "labs/lab04.html#d4", "c": "练习 4 · 调试与性能分析", "t": "调试 4 · ls -l 比 ls 多做了 lstat 和读时区文件", "x": "Linux strace 未实测 MSYS strace 实测 原题 ：用 strace （Linux）或 dtruss （macOS）追踪 ls -l 这类命令的系统调用。它都做了哪些调用？再追踪一个更复杂的程序，看看它打开了哪些文件。 加了 -l，ls 要对每个文件取一次元数据。它还要去读时区文件。Linux 上是 statx，本机 MSYS 里是 lstat。 K 先回顾 strace、 -e 过滤、 -f 跟随子进程，见 第 4 讲第 5 节 。 ▶ 跑：题目要求的 Linux 版 在 Linux 上你会看到下面这些，依据是视频 27:22–33:43。开头是 execve 和加载共享库。然后 openat 打开当前目录，getdents64 读目录项。因为加了 -l，每个文件做一次 statx 和 listxattr。还会打开时区文件。 strace -c 则在结束时打印汇总，列出每种调用的次数和耗时。 ? 原理：本机替代 Git Bash 自带的 strace 是 Cygwin/MSYS 版。它追踪的是 MSYS 运行时里的 POSIX 层调用，运行时就是 msys-2.0.dll。它不追踪 Windows 内核调用。 -m syscall 只保留这一类消息。原始输出一行一个内部函数，非常啰嗦。所以写个 awk 脚本，只挑出 POSIX 层的调用。再去掉路径，压成一条时间线： ▶ 跑：ls ▶ 跑：ls -l 输出怎么读 ：ls -l 一上来就去找翻译文件。找的是“时间格式”的翻译。三种 locale 名各试一次，都返回 -1，表示不存在。然后 lstat 目录本身。读目录时，每读出一个要显示的文件，就 lstat 一次。拿的是大小、权限和时间。最后打开时区文件 /usr/share/zoneinfo/UTC 。这个文件不存在，ls 退回内置的 UTC，写出 102 字节。这和视频在 Linux 上看到的现象一一对应。-l 让程序多做了 stat 和时区相关的工作。 打个比方 ls 像只报菜名的服务员。ls -l 像还要报价格、产地和上菜时间的服务员。多报一样，就得多跑一趟后厨。 考点（答案写在注释里） strace -o t.trace -m syscall ls d # MSYS 版：只看 POSIX 层，写进文件慢慢看 # 不带 -l 也要 readdir 到 . 和 ..：它们也是目录项，读出来再由 ls 决定显不显示 # 系统调用层面看到的是“读了什么”，不是“显示了什么” ls -a d # 推理：readdir 次数不变，变的是 write 的字节数（未实测）"}, {"u": "labs/lab04.html#d5", "c": "练习 4 · 调试与性能分析", "t": "调试 5 · LLM 解释报错很快，对不对要拿编译器核对", "x": "报错本机实测 LLM 对话未实测 原题 ：用 LLM 帮你调试一条难懂的报错。找一条编译器报错，尤其是 C++ 模板或 Rust 的。让它解释，并给出修复。也试试把 strace 或 AddressSanitizer 的输出交给它。 贴完整的代码和报错，问“哪一行是我的错”。拿到回答后，用 rustc --explain 和重新编译去核对。 K 先回顾 AI 辅助调试的长处与局限，见 第 4 讲第 9 节 。 {} 准备两条真实的“难懂报错” ▶ 跑 C++ 版共 26 行。真正的原因是第 7 行把 map 的迭代器交给了 sort。它埋在标准库头文件的深处。这正是讲义说 LLM 擅长解释的那类报错。 ? 怎么问：提问模板 要点有四条。贴 完整 的代码和报错，不要只贴最后一行。问“哪一行是我自己的错”。要求它说明如何验证。允许它反问。strace 和 ASan 的输出也一样，连同你运行的命令一起贴上。 ▶ 核对：编译器自己的官方解释 未实测部分与判断标准 本页没有真的去调用某个 LLM。那需要联网账户，回答也每次不同。所以这里不写“我问了之后它说……”。你自己做时，可以用下面几条判断它靠不靠谱： Rust：它应该指出第 3 行的不可变借用一直活到第 5 行。这和第 4 行的 push 冲突。push 要可变借用，还可能导致重新分配。正确改法有两种。把 push 挪到最后一次使用 first 之后。或者复制出值，写成 let first = scores[0]; 。和上面 rustc --explain E0502 的说法对得上，才算对。 C++：它应该说出两点。map 已经按键有序，不能也不需要用 std::sort。sort 要随机访问迭代器。想按值排序，正确做法是先拷进 std::vector<std::pair<…>> 再排。改完要 重新编译 验证。 危险信号（讲义）：报错消失了，程序的含义却变了。比如 Rust 里到处 clone() ，C++ 里强制类型转换。或者编出不存在的编译器选项、函数。 打个比方 LLM 像一本会说话的错题集。它见过太多类似的错，一眼就认出是哪类。但答案对不对，还得翻到书后对一下标准答案。 考点（答案写在注释里） rustc --explain E0502 # 官方解释：借用期间不能再可变借用。拿它核对 LLM 的回答 g++ -c sort_map.cpp # 26 行报错，真正原因在第 7 行：map 的迭代器不能交给 std::sort # LLM 为什么更擅长“找”而不是“修”：找 bug 靠见过大量类似模式 # 修 bug 要懂这个程序的意图和约束，它容易只让症状消失（讲义 Limitations，视频 53:52）"}, {"u": "labs/lab04.html#p1", "c": "练习 4 · 调试与性能分析", "t": "性能 1 · perf stat 看 CPU 忙不忙、每周期跑几条指令", "x": "perf 未实测 time 实测 原题 ：用 perf stat 获取你选的某个程序的基本性能统计。各个计数器是什么意思？ task-clock 除以墙钟时间，就是用了几个 CPU。IPC 低于 1，往往是在等内存或分支预测失败。本机没有 perf，用 time 看 CPU 忙不忙。 K 先回顾 计时与 real、user、sys，见 第 4 讲第 10 节 。perf 见 第 13 节 。 ▶ 跑 ? 原理：讲义输出逐行解读 计数器（讲义输出） 含义 3,210.45 msec task-clock · 0.998 CPUs utilized 进程实际占用 CPU 的时间。除以墙钟时间约等于 1，说明是单线程，而且一直在算 12 context-switches 上下文切换：进程被换下 CPU 的次数。原因是等待 I/O 或时间片用完 0 cpu-migrations 被调度器挪到另一个 CPU 核上的次数 156 page-faults 缺页：访问的内存页还没映射，要内核去处理。第一次碰到新内存时常见 cycles · 3.845 GHz CPU 时钟周期数。除以 task-clock，得出运行频率 instructions · 0.80 insn per cycle 执行的指令数。IPC 是每周期指令数。低于 1 往往意味着在等内存，或者分支预测失败 branches / branch-misses · 1.00% 分支指令总数和预测失败的比例。失败一次就要清空流水线 表中的解释是补充知识，不是视频内容。可以对照 man perf-stat 和 perf wiki。讲义这段输出的数字很整齐，比如 12,345,678,901。它们明显是示意用的。 ▶ 跑：本机能做的，time 纯计算的 bash 循环，user 加 sys 约占 real 的 86%，CPU 一直在忙。sleep 则几乎全是等待。这两个都是 MSYS 程序，time 的数字可信。 坑 ：对原生 Windows 程序 python，Git Bash 的 time 报 user 0.015 s。而 Python 自己用 time.process_time() 测得 0.47 s。time 拿不到这类子进程的 CPU 时间。 打个比方 perf stat 像汽车的行车电脑。它报油耗、转速、急刹次数。IPC 就像发动机每转一圈跑了多远。转得多却跑得少，多半是在堵车。 考点（答案写在注释里） perf stat ./prog # task-clock 3210 ms、墙钟只有 1600 ms，可能吗？可能 # 多线程程序在两个核上同时跑，CPU 时间之和是墙钟的 2 倍 # perf 会显示约 2.0 CPUs utilized。这和 time 里 user 大于 real 是一回事（视频 56:10）"}, {"u": "labs/lab04.html#p2", "c": "练习 4 · 调试与性能分析", "t": "性能 2 · 采样一看，大头时间花在 sin 和 cos 上", "x": "perf 未实测 Python 两类 profiler 实测 原题 ：把讲义的程序存成 slow.c ，带调试符号编译： gcc -g -O2 slow.c -o slow -lm 。运行 perf record -g ./slow ，再用 perf report 看时间花在哪。试着用 flamegraph 脚本生成火焰图。 sin 和 cos 各占四成多。追踪型的 cProfile 数得准，但把程序拖慢了 2.6 倍。自己写的采样器几乎不拖慢。可它看不见 C 写的内置函数。 K 先回顾 perf、火焰图、callgrind，见 第 4 讲第 13 节 。那里的演示画了从采样到火焰图的过程。 {} 讲义的程序（逐字） ▶ 跑：编译运行 1 亿次 sin 加 1 亿次 cos，这一次用了约 18.5 秒。多次运行在 11–19 秒之间波动。user 0.015 s 又是 Git Bash time 的坑。 ▶ 跑：题目要求的 perf 版 视频里讲师对同一个程序得到了结果。perf report 的 Self 列，cos 43.6%，sin 43.2%。火焰图里，main 之上一半是 cos，一半是 sin。见视频 和 。 {} 本机替代：Python 版加两种 profiler 追踪型用标准库 cProfile。采样型自己写一个，弄明白“采样”到底在做什么： ▶ 跑：追踪型 cProfile 输出怎么读 ：200 万次函数调用一次不落。 tottime 是函数自身的时间，不含它调用的。 cumtime 包括子调用的总时间。这正好对应 perf report 的 Self 和 Children 两列。sin 0.170 s，cos 0.165 s，和视频里“各占一半”的结论一致。 ▶ 跑：采样型 sampler.py 输出就是 flamegraph.pl 要的 folded stacks 格式，写成 外层;…;内层 样本数 。99.2% 的样本落在第 8 行。因为 sin、cos 是 C 写的内置函数，没有 Python 栈帧。采样器就“看不见”它们。perf 遇到没有调试符号、没有帧指针的代码，也会这样。讲义的 debug symbols 提示说的就是这个。 ▶ 跑：两种 profiler 的代价 直接运行 0.40 s。cProfile 下 1.05 s，慢了 2.6 倍。采样器下 0.39 s，几乎不变。这就是讲义说“采样型开销小，生产环境首选”的原因。 打个比方 cProfile 像给每次函数调用都开发票。账一笔不差，可开票本身就耽误时间。采样器像隔一会儿拍张照，几乎不打扰人。可没挂工牌的人，照片里就认不出来。 考点（答案写在注释里） gcc -g -O2 slow.c -o slow -lm # -g 保留函数名和行号，报告里才不是一堆地址 # -O2 可能把 slow_computation 内联进 main，火焰图就少一层（补充推理，未实测） gcc -g -O2 -fno-omit-frame-pointer slow.c -o slow -lm # 想要清晰的调用栈，再加这个"}, {"u": "labs/lab04.html#p3", "c": "练习 4 · 调试与性能分析", "t": "性能 3 · git grep 快 1.82 ± 0.60 倍，误差不小", "x": "hyperfine 未实测 bench.py 实测 原题 ：用 hyperfine 对同一任务的两种实现做基准测试。比如 find 和 fd ， grep 和 ripgrep ，或者你自己代码的两个版本。 可信的基准测试要做四件事。预热，多次重复，报告均值和波动，给倍数附上误差。本机用自己写的迷你 hyperfine，比较了 grep -r 和 git grep。 K 先回顾 hyperfine 见 第 4 讲第 11 节 。那里的演示手推了倍数的不确定度。 ▶ 跑：题目要求的 hyperfine 本机没装 fd，ripgrep 也不在 PATH 上。所以比较对象换成 grep -r 和 git grep 。搜的是课程网站仓库的一份副本，关键词是 “debug”。 {} 写：一个迷你 hyperfine ▶ 跑 输出怎么读 ：两个均值相差近一倍。但 grep 的 σ 很大，有 43.1 ms，最慢一次 255 ms。所以“快 1.82 ± 0.60 倍”的误差也很大。手推一下：r = 147.8 / 81.3 = 1.82。误差是 σᵣ = 1.82 × √((43.1/147.8)² + (12.2/81.3)²) = 1.82 × 0.328 ≈ 0.60。 ▶ 跑：先确认两者做的是同一件事 两者都找到 108 行，结果一致，比较才有意义。git grep 只搜 git 跟踪的文件，默认多线程。grep -r 要遍历目录树上的所有文件。这里用 --exclude-dir=.git 跳过了仓库内部数据，用 -I 跳过二进制文件。 打个比方 比两个人谁跑得快，不能各跑一次就定。要都热好身，各跑二十趟。再看平均成绩，还有每趟成绩晃得多厉害。 ! 为什么会在这里踩坑：各 time 一次就下结论 误区 各 time 一次就下结论。 实际 同一条 grep 命令跑 20 次，最快 104 ms，最慢 255 ms。差了两倍多。第一次运行还可能特别慢，因为文件还不在磁盘缓存里。所以要预热，也就是 --warmup 。 正确做法 预热，多次重复，报告均值 ± σ。比较两个命令前，先确认它们输出相同。尽量在安静的机器上测。 考点（答案写在注释里） python p3/bench.py 3 20 'grep …' 'git grep …' # 预热 3 次，再各测 20 次 # hyperfine 默认经由 shell 运行命令，它会先测空 shell 的启动耗时 # 再从结果里扣掉这部分（补充，见 hyperfine 文档） # bench.py 用 shlex 切词后直接启动程序，不经过 shell，所以没有这个问题"}, {"u": "labs/lab04.html#p4", "c": "练习 4 · 调试与性能分析", "t": "性能 4 · 3 个进程挤 2 个核，合计最多 200%", "x": "taskset / stress / htop 未实测 start /affinity 实测 原题 ：运行一个占用大量资源的程序，同时用 htop 监视系统。试着用 taskset 限制进程能用的 CPU： taskset --cpu-list 0,2 stress -c 3 。为什么 stress 用不满三个 CPU？ 不是 stress 不想用，是只给了它两个 CPU。进程被限制在哪些核上，最多就只能拿到那么多 CPU 时间。 K 先回顾 资源监控见 第 4 讲第 12 节 。CPU 时间除以墙钟时间，见 第 10 节 。 ▶ 跑：题目要求的 Linux 版 ? 原理 stress -c 3 启动 3 个忙等的工作进程，各自都想吃满一个核。 taskset --cpu-list 0,2 只允许它们在 CPU 0 和 CPU 2 上运行。3 个进程挤 2 个核，调度器只能让它们轮流跑。两个核满载，每个 stress 进程平均约 2/3 个核。答案是： 不是 stress 不想用，是只给了它两个 CPU 。 Windows 上对应的工具是 start /affinity 掩码 。掩码 5 是二进制 0101，也就是 CPU 0 和 CPU 2。子进程会继承这个掩码。用一个 Python 脚本代替 stress： ▶ 跑：不限制 ▶ 跑：只允许 CPU 0 和 CPU 2 输出怎么读 ：不限制时，三个 worker 各拿到 80% 多。没到 100%，是因为机器上还有别的负载。限制后合计只有 121%，远不到 300%。也没到理论上限 200%。这两个核上还有其他程序在抢。数字每次运行都会变，但“合计不超过 200%”不会变。 打个比方 三个人抢两台电脑。谁也别想独占一台，只能轮流用。三人加起来，最多也就用满两台。 考点（答案写在注释里） taskset --cpu-list 0,1 stress -c 3 # 开了超线程的机器上，结果可能更差 # 很多系统把同一物理核的两个超线程编成相邻的号，比如 0 和 1 # 它们共享执行单元，两个忙等进程拿不到两个完整物理核的算力 # 这是补充推理，具体编号因系统而异，未实测"}, {"u": "labs/lab04.html#p5", "c": "练习 4 · 调试与性能分析", "t": "性能 5 · netstat 找到 PID，Git Bash 里要用 kill -W", "x": "ss 未实测 netstat 实测 原题 ：常见问题是，想监听的端口已经被别的进程占了。先运行 python -m http.server 4444 ，在 4444 端口起一个最小的 web 服务器。在另一个终端里运行 ss -tlnp | grep 4444 找到这个进程。再用 kill <PID> 结束它。 Linux 上用 ss -tlnp 查端口对应的 PID，再 kill。本机用 netstat 查。Git Bash 内建的 kill 不认 Windows PID，要换 /bin/kill -W 。 K 先回顾 资源监控里的 ss 和 lsof，见 第 4 讲第 12 节 。信号与 kill 见第 2 讲。 ▶ 跑：题目要求的 Linux 版 ss -tlnp 里，-t 只看 TCP，-l 只看监听。-n 不解析名字，-p 显示进程。看别人的进程要 sudo。 {} 本机版：用 netstat 找 PID ▶ 跑 输出怎么读 ：netstat 那一行的最后一列是 PID。tasklist 确认它是 python.exe。第一次 kill $PID 失败了，报 No such process。换成 /bin/kill -W 才成功。最后再查一次，端口已经空闲。脚本的 teardown 还会再检查一遍，确保没有残留的服务器。 打个比方 端口像一个门牌号。netstat 是物业的登记簿，查得到谁住在 4444 号。可 Git Bash 的 kill 拿的是另一本花名册。同一个人，在两本册子上编号不同。 ! 为什么会在这里踩坑：Git Bash 的 kill 不认 Windows PID 错误写法 kill 21200 ，PID 来自 netstat 真实报错 kill: (21200) - No such process ，见上面 p5-a 的输出 原因 bash 内建的 kill 用的是 Git Bash（MSYS）自己的进程号。netstat 和 tasklist 给的是 Windows 进程号。两者不是一回事。 正确写法 /bin/kill -W PID ，-W 表示 Windows PID。或者用 taskkill //PID PID 。 ! 为什么会在这里踩坑：端口冲突在 Windows 上可能不报错 现象 同一个端口起第二个 http.server，没有报 Address already in use。netstat 里出现两行 LISTENING。 原因 Python 的 HTTPServer 默认开着 SO_REUSEADDR ，也就是 allow_reuse_address = True 。这个选项在 Windows 上比 Linux 宽松。它允许另一个套接字绑定到同一端口。在 Linux 上，第二个服务器会直接报 OSError: [Errno 98] Address already in use 。这一条是补充，未实测。 启示 排查端口冲突时，别只靠报错。直接查 netstat 或 ss，看有几个进程在监听。 考点（答案写在注释里） python -m http.server 4444 --bind 127.0.0.1 # 只接受本机连接，做实验更安全 # 默认的 0.0.0.0 会在所有网卡上监听 # 局域网里的其他机器，也能访问你当前目录的文件"}, {"u": "labs/lab04.html#selfcheck", "c": "练习 4 · 调试与性能分析", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。计时、百分比和 PID 每次都会不同。第 4 讲演示里引用的数字，取自本页这次生成的结果。 考点速查（注释里写着答案） j += 1 # msort.py 第 18 行改对、第 16 行误写成这样：输出 [1, 1, 1, 1, 1, 1, 1, 3] # 取了左边的元素却移动右下标，i 永远停在 0。笔记作者本机试过（调试 1） watch students[1].id # 要在 run 之后设：程序装进内存，地址才确定（调试 2） free(greeting); greeting = NULL; # 挪到第 11 行之前：往 NULL 写，Segmentation fault，退出码 139 # 这比 use-after-free 好，错误当场暴露。笔记作者本机试过（调试 3） ls -a d # readdir 还是 5 次：. 和 .. 本来就会读出来（调试 4，推理） sys.setswitchinterval(0.0005) # sampler.py 第 35 行。GIL 默认 5 ms 才让一次，调小后采样才接近 1 ms（性能 2）"}, {"u": "labs/lab05.html", "c": "练习 5 · 版本控制与 Git", "t": "开头", "x": "LAB 05 · 对应 第 5 讲 · 版本控制与 Git 练习可视化笔记 · 版本控制与 Git 讲义第 5 讲一共 8 道练习，这里逐题讲。每题先亮结论，再给真跑的代码和输出。接着打个比方讲原理，最后指出坑在哪。考点都写在代码注释里。官方不给答案，题解是笔记作者写的。 所有输出都由脚本在本机真跑后自动收集 。生成时间是 … 。Git 在本机完全能用。所以这一页几乎每条命令都是真跑的。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 需要账户或额外工具，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab05.html#env", "c": "练习 5 · 版本控制与 Git", "t": "环境检查：每个实验都在全新的临时目录里跑", "x": "本页命令都在 Windows 的 Git Bash 里真跑。实验不碰你的 Git 配置，哈希也能复现。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机设置与处理办法 不碰你的 Git 配置 ：每个实验都在全新的临时目录里跑。 HOME 指向这个临时目录，还设了 GIT_CONFIG_NOSYSTEM=1 。所以读写的 ~/.gitconfig 都是临时的，练习 5、6 改的就是它。 固定的示例身份与时间 ：提交者统一是 Ada Example <ada@example.com> 。提交时间固定为 2026-01-16 10:00 UTC，也就是讲座当天。提交哈希取决于这些信息。固定之后， 你用同样的设置重跑，哈希会完全相同 。练习 4 例外，见那里的说明。 联网只发生一次 ：练习 2 从 GitHub 克隆了课程网站仓库。大小约 13 MB。之后的实验复制这份本地克隆，不再重复下载。 没装的工具 ：本机没有 git-filter-repo 和 GitHub CLI（gh）。练习 3 改用 Git 自带的 filter-branch。练习 7 需要 GitHub 账户，笔记没有替你提交 PR。 怎么用这一页 代码块右上角有个“复制”。它复制的是源文件的原始字节。每道题标题右边可以勾“完成”。想自己验证，就按 页尾“自查” 的方法重跑。"}, {"u": "labs/lab05.html#ex01", "c": "练习 5 · 版本控制与 Git", "t": "练习 1 · 学一条命令，就说出它动了哪些对象和引用", "x": "Git Bash 实测 原题 ：如果你没用过 Git，先读 Pro Git 的前几章。或者玩一遍 Learn Git Branching 。边学边把 Git 命令和数据模型对应起来。 这是开放题。每学一条命令，都要能说出两件事。它新建了哪些对象，挪了哪个引用。 K 先回顾 对象与内容寻址，见 第 5 讲第 6 节 。引用和 HEAD，见 第 7 节 和 第 8 节 。 ? 怎么做 读 Pro Git 第 1 到 3 章，讲基础和分支。或者在 Learn Git Branching 里，过完 Main 页签的前两组关卡。那个网站会把每条命令画成提交图的变化。正适合这道题。 每学一条命令，就在空的实验仓库里真跑一次。再用三招看穿它： git cat-file -p 看对象， cat .git/HEAD 看引用， git log --all --graph --oneline 看图。 判断标准是不看文档也能回答。这条命令执行后，对象库多了什么？哪个引用动了？工作区和暂存区变成什么样？下面 9 组实验就是按这个方法做的。每组都对应第 5 讲的一个演示。 读 Pro Git、玩 Learn Git Branching，要你自己完成。本页不写读后感。 打个比方 学 Git 命令像学下棋。背开局口诀，不如看懂每一步棋盘怎么变。每走一步，就看对象库和引用变成了什么样。 ▶ 跑 1-a：blob 与 SHA-1，哈希和讲义一字不差 第 2 行用 sha1sum 手算出了同一个 ID。Git 哈希的是 blob 17\\0 加上内容。对象存在 .git/objects/44/48adbf… 。前 2 位做目录，后 38 位做文件名。 ▶ 跑 1-b：tree、commit 与引用 根 tree 698281bc… 和 foo tree c68d233a… ，都和讲义完全一致。 git commit 新建了 5 个对象：2 个 blob、2 个 tree、1 个 commit。它还让 master 指向那个 commit。HEAD 里只有一行 ref: refs/heads/master 。 ▶ 跑 1-c：改一个字节，哪些对象会变 bar.txt 变了，foo tree 就变了。foo tree 一变，根 tree 也变，于是有了新 commit。没变的 baz.txt 继续用原来的 blob 4448adbf… 。对象数从 5 变成 9，新增 4 个，不是 5 个。 ▶ 跑 1-d：暂存区的三种状态 git add 只把文件此刻的内容复制进暂存区。之后再改，就出现 MM。 git commit 提交的是暂存区。 git restore 用暂存区覆盖工作区。 ▶ 跑 1-e：分支与合并，复刻视频里的 nato.txt 演示 ▶ 跑 1-f：游离 HEAD 与 reflog ▶ 跑 1-g：rebase 产生新的提交 feature 上两个提交的哈希，从 19113a7、1fc7223 变成了 8736fc2、88a446a。改动一样，但 parent 变了。 ▶ 跑 1-h：远程仓库，本地裸仓库扮演 GitHub bob 推送之后，alice 的 git status 仍说一致。 git fetch 之后，她才知道自己 behind 1。 git pull --ff-only 直接快进。 {} 写 1-i：给 git bisect 造一段历史 ▶ 跑 1-i：git bisect run 15 个嫌疑提交，只测了 4 次就定位到 v11。顺序是 v8 好、v12 坏、v10 好、v11 坏。最后一行确认 git bisect reset 回到了 master 的 v16。 考点（答案写在注释里） git commit -am exclaim # 只改了 bar.txt：新增 4 个对象，不是 5 个（1-c） # baz.txt 没变，新的根 tree 直接引用原来的 blob 4448adbf cp baz.txt copy.txt; git add copy.txt; git commit -m copy # 内容和 baz.txt 一样：blob 不新增，只多了新根 tree 和新 commit # 对象数从 5 变成 7（本机补充实测）。内容寻址天然去重"}, {"u": "labs/lab05.html#ex02", "c": "练习 5 · 版本控制与 Git", "t": "练习 2 · 谁改了哪行：log 加路径，blame 加 show", "x": "Git Bash 实测（联网一次） 原题 ：克隆 课程网站的仓库 。（1）把版本历史画成图。（2）最后修改 README.md 的是谁？提示：给 git log 加一个参数。（3） _config.yml 里 collections: 这一行，最后一次修改的提交说明是什么？提示： git blame 和 git show 。 答案是两条路子。 git log -1 -- README.md 找最后改文件的人。 git blame 找到改某行的提交，再用 git show 看它的说明。 K 先回顾 git log 的选项和路径限定，见 第 5 讲第 10 节 。blame 见 第 19 节 。 ▶ 跑：克隆 一共 861 个提交，最早的在 2019-01-04。克隆完成后，脚本把这份副本留在系统临时目录。后面的实验都复制它，不再联网。 ▶ 跑（1）：历史画成图 图里有很多 Merge branch 和 Merge pull request。贡献者的修改先在各自分支上提交，再合进 master。 ▶ 跑（2）：最后修改 README.md 的人 答案是 git log -1 -- README.md 。 -- 后面的路径，把历史限定在改过这个文件的提交。 -1 只取最新一个。第二行是改过 README.md 的提交总数。答案会随仓库更新而变，这里是生成本页时的结果。 {} 写（3）：blame 加 show ▶ 跑（3） 答案是 “Redo lectures as a collection”，时间是 2020-01-17。 collections: 这一行，就是那次把讲义改成 Jekyll collection 时加的。 打个比方 git blame 像查监控录像，看是谁最后动了这一行。git show 是调出那次的工单，看他为什么动。 ! 为什么会在这里踩坑：在 U 盘上的仓库里跑 git 现象 笔记作者第一次在 U 盘上的仓库副本里跑 git log 。结果报 fatal: detected dubious ownership in repository at '…' 。后面还有一句 is on a file system that does not record ownership。 原因 从 Git 2.35.2 起，为了安全，Git 有一条新规矩。属主不是当前用户的目录，它拒绝在里面运行。FAT32 不记录属主，于是一律被当作可疑。 解决 把仓库放到 NTFS 盘上。或者按提示，把这个目录加进 safe.directory 。只对你信任的目录这样做。本页实验都在系统临时目录里跑，所以没这个问题。这是补充，是本机遇到的情况。 考点（答案写在注释里） git log -1 -- README.md # -- 后面是路径：只看改过这个文件的提交 git blame -L 19,19 _config.yml # 这一行最后是哪次提交改的 # 那次提交只是改了缩进，怎么找更早真正写这行的人（补充） git blame -w _config.yml # -w 忽略空白改动 git blame <提交>^ -- _config.yml # 从那次的父提交开始，再 blame 一次 git log -L 19,19:_config.yml # 看这一行的完整演变"}, {"u": "labs/lab05.html#ex03", "c": "练习 5 · 版本控制与 Git", "t": "练习 3 · 从历史里删文件，就得重建它之后的每个提交", "x": "Git Bash 实测 filter-repo 未实测 原题 ：初学 Git 时，常犯两种错。一是提交了不该管的大文件，二是加进了敏感信息。试着往仓库里加一个文件，提交几次。然后把它从 历史 里删掉，不只是从最新提交里删。可以参考 GitHub 的文档 Removing sensitive data 。 只删最新提交里的文件，旧快照里它还在。要从历史里抹掉，得重建它出现之后的每个提交。这串提交的哈希必然全变。 K 先回顾 提交不可变、引用可变，见 第 5 讲第 7 节 。不可达的对象会被回收，见 第 13 节 。 ▶ 跑：问题重现 最新提交已经是 remove secret 了。可 git show HEAD~2:secret.txt 照样打印出 key。每个提交都是完整快照，旧快照里的文件永远在。 {} 写：改写全部历史 ▶ 跑 输出怎么读 ：第一个提交 984ec36 本来就没有 secret.txt。它的树不变，哈希也没变。从 config 开始，三个提交都换了新哈希：bc3c8bf、67efda1、b721e90。之后没有任何提交含 secret.txt。那个 blob 也被 gc 删了， git cat-file 找不到它。 打个比方 改写历史像重印一套账本。改了第 2 页，后面每页的“上一页编号”都得跟着改。旧账本还在柜子里，得把柜子也清掉。 ▶ 跑：GitHub 文档推荐的工具 filter-repo 更快，也更安全，不用手动清理备份引用。装好以后，一条命令就完成。BFG Repo-Cleaner 是另一个常见选择。 ! 为什么会在这里踩坑 误区 1 以为 git rm secret.txt && git commit 就删干净了。见 ex03-a，历史里它还在。 误区 2 filter-branch 跑完就以为完事了。 refs/original/ 备份和 reflog 还指着旧提交。不清理的话，gc 不会删那个 blob。scrub.sh 第 7 到 9 行就是干这个的。 误区 3 以为改写本地历史，就能撤回推出去的秘密。别人的克隆、GitHub 上的缓存和 fork 都可能还有旧提交。第一步永远是 作废那个 key （视频 27:05）。改写历史只是第二步。推送时还要 force push，并通知协作者。 考点（答案写在注释里） git rm secret.txt && git commit # 只删了最新快照里的，HEAD~2 的快照里照样有 bash scrub.sh secret.txt # 去掉第 7 到 9 行再跑：cat-file -t 仍输出 blob # 原因：refs/original 和 reflog 还指着旧提交，gc 不删可达对象（本机补充实测） # 大文件同理：进了历史，每个克隆都要下载它。只能改写历史瘦身 # 更好的做法是一开始就用 .gitignore 或 Git LFS（补充）"}, {"u": "labs/lab05.html#ex04", "c": "练习 5 · 版本控制与 Git", "t": "练习 4 · stash 就是两个临时提交加一个引用", "x": "Git Bash 实测 原题 ：从 GitHub 克隆一个仓库，改一个已有的文件。执行 git stash 会怎样？运行 git log --all --oneline ，看到了什么？用 git stash pop 撤销刚才的 stash。什么场景下这会有用？ stash 把改动存成两个提交。一个存暂存区，一个存工作区。 refs/stash 指着后者，工作区随即变干净。 K 先回顾 暂存区见 第 5 讲第 9 节 。合并提交可以有两个 parent，见 第 12 节 。 ▶ 跑：在练习 2 克隆的课程网站仓库里 输出怎么读 ：stash 之后，工作区干净了。 git log --all --graph 顶部多出两个提交。 index on master 存暂存区， WIP on master 存工作区，后者有两个 parent。 git stash pop 把改动放回工作区，再删掉这条 stash。输出里的 Dropped refs/stash@{0} 说的就是这个。 打个比方 stash 像把桌上没写完的作业先塞进抽屉。桌面清空了，可以干别的。回来再把抽屉里的东西摊回桌上。 ! 为什么会在这里踩坑：stash 提交没出现在顶部 现象 笔记作者第一次跑时，把提交时间固定成了 2026-01-16。结果 stash 的两个提交，没出现在 git log 顶部。 原因 固定时间让 stash 提交比仓库里最新的提交还早。 git log 按时间排序时，它们就排不到顶部。 处理 这一条实验 不 固定提交时间。所以这两个 stash 哈希每次运行都不同。 什么时候有用 写到一半，得马上切去别的分支修紧急 bug。现在的改动还不值得提交。 本地有没提交的修改， git pull 拒绝合并。先 stash，pull 完再 pop。 想试试没有这些改动时，测试过不过。 考点（答案写在注释里） git stash # 存成两个提交：index on master 存暂存区，WIP on master 存工作区 git stash list # refs/stash 指着 WIP 那个提交，它有两个 parent git stash pop # 放回工作区，再删掉这条 stash # pop 时冲突了，stash 会被保留。解决完要手动 git stash drop（补充，见 git help stash）"}, {"u": "labs/lab05.html#ex05", "c": "练习 5 · 版本控制与 Git", "t": "练习 5 · 别名的值不写 git，整串要加引号", "x": "Git Bash 实测 原题 ：和很多命令行工具一样，Git 有配置文件 ~/.gitconfig 。在里面建一个别名，让 git graph 输出 git log --all --graph --decorate --oneline 的结果。可以直接 编辑 ~/.gitconfig ，也可以用 git config 命令。参考 Git Aliases 。 答案是 git config --global alias.graph 'log --all --graph --decorate --oneline' 。Git 会自动在别名前补上 git，所以值里不写 git。 ▶ 跑 git config --global 写的就是 ~/.gitconfig 。可以看到 [alias] 一节多了 graph = … 。前几节是本页实验统一设的示例身份和选项。手动编辑这个文件，加上同样两行，效果完全相同。 打个比方 别名像手机里的快捷短语。你打 graph，它替你展开成一长串。展开时，它自动在前面加上 git。 ! 为什么会在这里踩坑：忘了引号，或者别名里多写了 git 错误写法 1 git config --global alias.graph git log --all --graph ，没加引号 真实报错 error: no action specified ，退出码 129，配置文件根本没写。不加引号时，shell 把后面拆成好几个参数。git config 就认不出你想做什么。 错误写法 2 alias.graph 'git log --oneline' ，值以 git 开头 真实报错 expansion of alias 'graph' failed; 'git' is not a git command 。Git 会自动在别名前补上 git，于是变成了 git git log 。想执行任意 shell 命令，别名要以 ! 开头。 正确写法 git config --global alias.graph 'log --all --graph --decorate --oneline' 考点（答案写在注释里） git config --global alias.graph 'log --all --graph --decorate --oneline' # 对 git config --global alias.graph git log --all --graph # 错：没引号，报 no action specified git config --global alias.graph 'git log --oneline' # 错：展开成 git git log git config --global alias.st '!git status -s' # ! 开头，才交给 shell 执行（补充）"}, {"u": "labs/lab05.html#ex06", "c": "练习 5 · 版本控制与 Git", "t": "练习 6 · 全局 gitignore 管住所有仓库的垃圾文件", "x": "Git Bash 实测 原题 ：运行 git config --global core.excludesfile ~/.gitignore_global 。之后就能在 ~/.gitignore_global 里定义全局忽略规则。这条命令只设置了位置，文件要你自己建。设好全局 gitignore，用来忽略系统或编辑器生成的临时文件。比如 .DS_Store 。 两步就够了。先用 core.excludesfile 指定全局规则文件的位置，再把规则写进去。之后每个仓库都会照它忽略。 {} 写：~/.gitignore_global ▶ 跑 输出怎么读 ： ?? 是未跟踪。notes.txt 是正常文件，应该被注意到。 !! 是被忽略。 git check-ignore -v 能查出忽略的来源。哪个文件、第几行的规则，一清二楚。排查“这个文件怎么不见了”时很有用。 打个比方 全局 gitignore 像你随身带的垃圾分类表。不管走到哪个仓库，都按这张表把垃圾挑出去。 ! 为什么会在这里踩坑：规则对已跟踪的文件无效 误区 以为加了忽略规则，提交过的文件就不再被跟踪。 实际 gitignore 只管 未跟踪 的文件。已经在仓库里的文件，要先 git rm --cached 文件 再提交。之后规则才对它生效。这是补充。 考点（答案写在注释里） git config --global core.excludesfile '~/.gitignore_global' # 只设位置，文件要自己建 git status --short --ignored # ?? 是未跟踪，!! 是被忽略 git check-ignore -v .DS_Store # 查出是哪个文件第几行的规则忽略了它 git rm --cached file # 已跟踪的文件先移出暂存区，忽略规则才生效（补充）"}, {"u": "labs/lab05.html#ex07", "c": "练习 5 · 版本控制与 Git", "t": "练习 7 · 没有写权限，就先推到自己的 fork 再发 PR", "x": "未实测（需要 GitHub 账户） 原题 ：Fork 课程网站的仓库 。找一个错别字或别的可改进之处，在 GitHub 上提交 pull request。可以参考 first-contributions 。请只提交有用的 PR，不要刷屏！找不到可改进的地方，就跳过这题。 你没有上游仓库的写权限。所以流程是 fork、克隆、建分支、提交。再推到自己的 fork，最后发 PR 请维护者合并。 ? 原理 你没有上游仓库的写权限。所以先推到自己的 fork，再请维护者把分支合进去 ▶ 跑 打个比方 fork 像把别人的菜谱复印一份带回家。你在复印件上改好，再寄回去问原作者收不收。 未实测部分与判断标准 笔记作者没有替你提交 PR。一来需要你自己的 GitHub 账户。二来讲义明确要求，只提交真正有用的修改。 自己做时，可以这样检查。PR 只包含一个主题的改动，一个分支一件事。提交说明写清改了什么、为什么改。改动前先看仓库有没有贡献指南。再查一下，是否已经有人报过同样的问题。 分支、提交、推送这些本地步骤，前面都实测过。和练习 1-e、1-h 完全一样。 考点（答案写在注释里） git switch -c fix-typo # 一件事开一个分支，别直接在 main 上改 git commit -am \"Fix typo\" # 说明写清改了什么 git push -u origin fix-typo # origin 是你自己的 fork，不是上游 # 最后在 GitHub 网页上发 PR，请上游合并 fix-typo"}, {"u": "labs/lab05.html#ex08", "c": "练习 5 · 版本控制与 Git", "t": "练习 8 · 同一行被两边改了才冲突，解决完要 add", "x": "Git Bash 实测 原题 ：模拟协作，练习解决合并冲突。（1） git init 一个新仓库，建 recipe.txt ，写几行菜谱。（2）提交，然后建两个分支： git branch salty 和 git branch sweet 。（3）在 salty 上把 “1 cup sugar” 改成 “1 cup salt”，提交。（4）在 sweet 上把同一行改成 “2 cups sugar”，提交。（5）回到 master，先 git merge salty ，再 git merge sweet 。发生了什么？看看 recipe.txt。 <<<<<<< 、 ======= 和 >>>>>>> 是什么意思？（6）编辑文件，保留你想要的内容，删掉冲突标记。再用 git add 加 git commit 完成合并，或者用 git merge --continue 。也可以试试 git mergetool 。（7）用 git log --graph --oneline 看合并历史。 两边改了同一行，Git 不替你拍板，就报冲突。你编辑文件、删掉标记，再 git add 标记已解决，最后提交。 K 先回顾 三方合并与冲突，见 第 5 讲第 12 节 。那里演示的第 2 幕就是这道题。 {} 准备的文件 ▶ 跑（1）到（5） 输出怎么读 ：第一次 git merge salty 是 Fast-forward 。master 自己没有新提交，salty 就在它正前方。Git 直接把 master 挪过去，不产生合并提交。 第二次 git merge sweet 时，merge base 是 base recipe。两边都改了同一行，于是报 CONFLICT。状态是 UU ，意思是双方都改了。 再看文件。 <<<<<<< HEAD 到 ======= 之间，是当前分支的内容。此时的 master 就是 salty 的内容。 ======= 到 >>>>>>> sweet 之间，是合并进来的 sweet 的内容。 {} （6）解决：写成你想要的样子 这里两边的意图都保留：糖维持一杯，另加一撮盐。没有“正确答案”。冲突的本质，就是需要人来做决定。 ▶ 跑（6）到（7） 合并提交 7cba7ea 有两个 parent。3f5228a 来自 salty，25b74f8 来自 sweet。 git log --graph 画出了一个菱形。 打个比方 冲突像两个同事改了同一份报价单的同一格。一个写 1 杯盐，一个写 2 杯糖。系统不敢替你选，就把两种写法都摆出来，等你定。 ! 为什么会在这里踩坑：冲突没解决就提交 错误写法 冲突后直接 git commit 。 真实报错 error: Committing is not possible because you have unmerged files. 正确做法 编辑文件，再 git add 标记已解决，然后 git commit 。不想合了，就 git merge --abort 回到合并之前。上面实测里，文件回到了 salty 的内容。还要小心把冲突标记也提交进去。提交前搜一下 <<<<<<< 。 关于 git mergetool（未实测） git mergetool 会给每个冲突文件，依次打开配置好的工具。比如 vimdiff、meld 或 VS Code。通常并排显示 base、ours、theirs 三个版本和结果。要先用 git config merge.tool <工具名> 配置好。本页没有交互式终端，所以没有实测。 考点（答案写在注释里） git merge salty # master 没有新提交：fast-forward，不产生合并提交 git merge sweet # 同一行两种改法：CONFLICT，状态 UU git add recipe.txt # 编辑完、删掉标记，add 才算“已解决” git merge --abort # 不想合了，回到合并之前 # 反过来先 merge sweet 再 merge salty：sweet 快进，salty 冲突 # 只是 HEAD 那一侧成了 \"2 cups sugar\"，另一侧是 \"1 cup salt\"（本机补充实测）"}, {"u": "labs/lab05.html#selfcheck", "c": "练习 5 · 版本控制与 Git", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时真跑收集的。实验在本机临时目录里进行。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。 生成时固定了提交身份和时间。所以除了练习 2 和 4，哈希都是确定的。你手动重跑时，把身份和时间设成和本页一样。得到的哈希就会完全一致。这本身就验证了内容寻址。 考点速查（注释里写着答案） printf 'git is wonderful' | git hash-object --stdin # 10e1b4d8…：少了换行，头变成 blob 16\\0，哈希全变（练习 1） git commit -am exclaim # 只新增 4 个对象：baz.txt 的 blob 被新根 tree 直接复用（练习 1-c） bash scrub.sh secret.txt # 删掉第 7 到 9 行，秘密 blob 还在：备份引用和 reflog 还指着它（练习 3） git merge sweet; git merge salty # 顺序反过来：sweet 快进，salty 冲突（练习 8） git bisect run bash test_add.sh # 靠退出码判好坏：0 好，125 跳过，1 到 127 的其他值算坏（练习 1-i）"}, {"u": "labs/lab06.html", "c": "练习 6 · 打包与交付代码", "t": "开头", "x": "LAB 06 · 对应 第 6 讲 · 打包与交付代码 练习可视化笔记 · 打包与交付代码 讲义第 6 讲一共 6 道练习，这里逐题讲。每题先亮结论，再给真跑的代码和输出。接着打个比方讲原理，最后指出坑在哪。考点都写在代码注释里。官方不给答案，题解是笔记作者写的。 能在本机跑的输出，都由脚本真跑后自动收集 。生成时间是 … 。需要 Docker、账号或域名的步骤，标成了未实测。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 本机没有对应环境或账号，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab06.html#env", "c": "练习 6 · 打包与交付代码", "t": "环境检查：本机能跑 Python 和 uv，跑不了 Docker", "x": "本页命令都在 Windows 的 Git Bash 里真跑。需要 Docker 或账号的步骤，标成了未实测。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机限制与处理办法 没有 Docker ：Docker Desktop 的后端一启动就崩。WSL 里也没有可用的发行版。练习 3、4、5 里的 docker build 、 docker compose 和 docker push 全部标成 未实测 。Dockerfile 和 compose 文件照样写出来，加了注释。能做的静态检查也做了，比如语法和 YAML 结构。练习 4 的服务改用一个 30 行的 Redis 替身，在本机真跑。 Windows 上的 venv ：激活脚本在 venv/Scripts/activate ，不在讲义里的 venv/bin/activate 。其余行为相同。 隐私 ：每条命令的输出都先过一遍 .sanitize.py 。沙箱绝对路径换成 <沙箱> ，Python 安装目录换成 <Python> 。临时目录换成 <TEMP> 。练习 1 还把环境变量精简到几项，所以 diff 很短。这几项是 HOME、SYSTEMROOT、TEMP、TMP 和 PATH。 不全局安装 ：typer 这类第三方包，只装进沙箱 venv。每条命令用自己的那一个。uv 的下载缓存放在临时目录里。最后一条联网命令跑完，缓存就删掉。 需要账号的步骤 一律不代你操作。包括 TestPyPI、ghcr.io、GitHub Pages 和自定义域名。页面给出完整步骤和验收标准。凭据只应由你本人输入。 怎么用这一页 代码块右上角有个“复制”。它复制的是源文件的原始字节，不带行号和注释层。“注释”按钮能隐藏或显示所有注释。每道题标题右边可以勾“完成”。想自己验证，就按 页尾“自查” 的方法重跑。"}, {"u": "labs/lab06.html#ex01", "c": "练习 6 · 打包与交付代码", "t": "练习 1 · 激活 venv 只是改了当前 shell 的几个变量", "x": "Git Bash 实测 原题 ：用 printenv 把环境保存到一个文件。建一个 venv 并激活，再 printenv 到另一个文件。然后 diff before.txt after.txt 。环境里变了什么？shell 为什么会优先用 venv？提示：对比激活前后的 $PATH 。再运行 which deactivate ，推理一下 deactivate 这个 bash 函数在做什么。 激活就是在 当前 shell 里改 PATH，再设几个变量。所以必须 source ，deactivate 再把它们改回去。 K 先回顾 $PATH 的查找规则，见 第 1 讲第 7 节 。环境变量在第 2 讲。虚拟环境见 第 6 讲第 4 节 。 ? 原理 激活脚本只是一段在当前 shell 里执行的 bash 代码 {} 写 ▶ 跑 输出这样读。 5c5 表示第 5 行被改了，PATH 前面多了 <沙箱>/ex01/venv/Scripts 。 6a7 和 12a14,15 表示新增的行。分别是 PS1 、 VIRTUAL_ENV 和 VIRTUAL_ENV_PROMPT 。 shell 优先用 venv，就是因为它的目录插到了 PATH 最前面。 按第 1 讲的规则，第一个命中的赢。 which deactivate 失败了，退出码是 1。which 只在 PATH 的目录里找 文件 。deactivate 却是一个 函数 ，由激活脚本定义在当前 shell 里。只有 type 看得到它。从函数体能读出它做了这些事。先把存在 _OLD_VIRTUAL_PATH 里的旧 PATH 换回来，再恢复 PYTHONHOME 和 PS1。然后 hash -r 清掉命令位置的缓存，unset VIRTUAL_ENV。最后不带参数调用时， unset -f deactivate 把自己也删掉。 PATH 决定运行哪个 python。运行起来之后，import 去哪找包，看 sys.prefix 和 sys.path 里的 site-packages。激活后，两者都指向 venv。 打个比方 激活像在通讯录最上面插了一张名片。你喊一声 python，先接电话的就是 venv 里那个。deactivate 就是把这张名片抽走。 下面的演示把 envdiff.sh 一行行跑给你看。先看两张快照怎么生成，diff 留下哪几行。再看 deactivate 怎么倒回去。 ! 为什么会在这里踩坑：执行了激活脚本，没有 source 错误写法 bash venv/Scripts/activate 或 ./venv/Scripts/activate 现象 没有任何报错，但 which python 还是全局的。 原因 两种写法都会启动一个 子进程 来执行脚本。子进程的 PATH 被改了，随后它退出，改动也跟着消失。道理和第 1 讲练习 7 一样。那题讲的是 cd 为什么必须内建。Linux 上，激活脚本通常没有执行位。 ./activate 会直接报 Permission denied，这条未实测。Git Bash 不检查执行位，所以本机静默“成功”。 正确写法 source venv/Scripts/activate ，或者 . venv/bin/activate 。 补充实验：一个环境装不下互相冲突的两个库 讲义说，依赖冲突要靠每个项目一个环境来解决。不联网也能复现。 make_wheels.py 手工造了 4 个最小的 wheel。 liba 要 shared<2.0 ， libb 要 shared>=2.0 。 三段输出依次是这样的。第一段同时安装，解析器证明无解，退出码 1。第二段先装 liba，选了 shared 1.5.0。第三段再装 libb，安装器 把 shared 换成了 2.1.0 。liba 就这样被悄悄破坏了，只有 uv pip check 查得出来。解法是两个环境： 考点（答案写在注释里） echo $PATH # 激活后，全局目录还在，只是排在 venv 后面 # 同名的 python、pip 先在 venv 里找到，所以不冲突 # 全局目录只给 ls、git 这类 venv 里没有的命令兜底 venv/Scripts/python script.py # 不激活也能用：写全路径，就用这个解释器和它的包 venv/bin/python script.py # Linux 上的写法。激活只是为了少打字 # ex01-f 里的 env-a/Scripts/python 就是这么用的"}, {"u": "labs/lab06.html#ex02", "c": "练习 6 · 打包与交付代码", "t": "练习 2 · pyproject 写范围，uv.lock 钉死整棵树", "x": "Git Bash 实测（联网下载依赖） 原题 ：创建一个带 pyproject.toml 的 Python 包，把它装进虚拟环境。再创建一个锁文件，检查它的内容。 装好以后，任何目录都能 import greeting，还多了 greet 命令。uv.lock 记下了 9 个包的确切版本和哈希。 K 先回顾 构件与 pyproject.toml，见 第 6 讲第 6 节 。wheel 见 第 7 节 ，语义化版本见 第 8 节 。锁文件见 第 10 节 。 ? 原理 先看没打包时的问题。一个裸的 greet.py，只能在它所在的目录里被 import。 Python 只在 sys.path 里找模块。用 python -c 时，sys.path 的第一项是当前目录。换了目录就找不到了。打包就是按规则写好 pyproject.toml 。安装器再把代码放进环境的 site-packages。 {} 写：两个文件都是讲义原文 ▶ 跑：建环境，再安装 输出这样读。 Resolved 9 packages ：greeting 自己，加上 typer，再加 typer 带来的 7 个传递依赖。 Built greeting @ file:///… 表示先构建再安装。uv 在隔离环境里，用 setuptools 把源码构建成 wheel。最后换了个目录 import，也成功了。模块文件在 venv 的 site-packages 里。 ▶ 跑：生成并检查锁文件 输出这样读： 99 uv.lock 和 9 ：锁文件 99 行，有 9 个 [[package]] 条目。依赖树里的每个包都被钉死了，不只是你直接写的 typer。 typer 条目里， version = \"0.27.3\" 是今天解析出的确切版本。pyproject 里只写了 >=0.9 。视频录制时锁到的是 0.21.1。 source 是从哪个索引来的。 dependencies 里有 marker = \"sys_platform == 'win32'\" 。意思是 colorama 只在 Windows 上才需要。 sdist 和 wheels 各带下载地址和 hash = \"sha256:…\" 。哈希被 cut 截掉了。 warning: No requires-python ：pyproject 没写支持哪些 Python 版本。uv 默认按当前解释器 3.13 锁定。给库写上 requires-python = \">=3.9\" 这类范围更好。 ▶ 跑：构建 wheel，看里面有什么 打个比方 pyproject.toml 像招聘启事，写着“3 年以上经验”。uv.lock 像录用名单，写着具体录了谁。下次再招，照着名单来，就不会换人。 补充实验：自己构建的 wheel 能复现吗（ex02-e） 锁文件保证了装进来的依赖逐字节相同。那你自己构建出的 wheel 呢？ 只改源码的修改时间，哈希就变了。设好 SOURCE_DATE_EPOCH 后，两次构建完全相同。下面的演示一行行画出来： 补充：手推版本范围（ex02-g） 锁文件里的版本，是解析器在各个范围的交集里挑的。 semver_check.py 手写了 ^ 的规则。再用 packaging 库交叉验证，pip 内部也在用这个库： ! 为什么会在这里踩坑：改了依赖，忘了重新 lock 现象 把约束改成 typer>=0.9,<0.20 ，再跑 uv sync --locked 。它报 “The lockfile at uv.lock needs to be updated”，退出码 1。 原因 锁文件里的 typer 0.27.3，已经不满足新约束。 --locked 的意思是锁文件必须和 pyproject 一致，否则报错。它专门给 CI 和部署用。宁可失败，也不悄悄换版本。 正确写法 改完依赖就运行 uv lock 。pyproject.toml 和 uv.lock 要 一起提交 。 另一个坑 构建输出放进了项目目录，比如 uv build -o out1 。再构建时，setuptools 报 Multiple top-level packages discovered in a flat-layout 。 原因 没有显式配置时，setuptools 会自动找包。顶层的每个目录，都被当成要打包的包。这叫 flat-layout 自动发现。默认的 dist/ 和 build/ 在排除名单里，你自己起的名字不在。下面是本机实测： 正确写法 用默认的 dist/，或者输出到项目外面。本页用的是 -o ../w1 。 考点（答案写在注释里） dependencies = [\"typer>=0.9\"] # greeting 能被 import，是库：pyproject 写范围，给用户留余地 uv lock # 部署和 CI 要可复现，靠 uv.lock 钉死整棵树。两者不矛盾 uv sync --locked # 锁文件和 pyproject 对不上就报错，退出码 1 uv build -o out1 # 坑：输出目录在项目里，下次构建会被当成包"}, {"u": "labs/lab06.html#ex03", "c": "练习 6 · 打包与交付代码", "t": "练习 3 · 装好 Docker，一条 compose 命令就能预览课程网站", "x": "Git Bash 实测（静态检查） Docker 未实测 原题 ：安装 Docker。用 docker compose 在本地构建 Missing Semester 课程网站。 镜像里只装 Ruby 和 gem 依赖。网站内容运行时挂载进去，Jekyll 监视改动，自动重建。 K 先回顾 容器与镜像，见 第 6 讲第 12 到 15 节 。Compose 见 第 16 节 ，锁文件见 第 10 节 。 ? 原理 课程网站用 Ruby 的静态站点生成器 Jekyll 构建。仓库里自带了下面两个文件。本页是逐字节复制的， cmp 验证过。镜像里只装 Ruby 和 gem 依赖。网站内容通过 绑定挂载 （ ./:/app ）实时映射进容器。Jekyll 的 -w 监视改动，自动重建。 {} 读：课程仓库原文件 ▶ 跑：能在本机验证的部分 输出这样读。 Gemfile 只写了一行 gem 'github-pages' ，这是范围。 Gemfile.lock 把它和全部传递依赖都钉死了。github-pages 是 232 版，jekyll 是 3.10.0，一共 110 个 gem 条目。末尾还记着用哪个 bundler 版本生成的。这和 pyproject.toml 加 uv.lock 是同一个模式。 本机没有 Ruby、Bundler 和 Jekyll。Docker CLI 在，但守护进程连不上。这正是用容器交付要解决的处境。装好 Docker，就不必在宿主机上装 Ruby 工具链。 ▶ 跑：在装好 Docker 的机器上 验收标准如下。第一次 up --build 会拉取 ruby:3.4-alpine3.21 ，再执行 bundle install ，比较慢。日志里会出现 Jekyll 的服务地址提示，形如 Server address: http://0.0.0.0:4000 。这时浏览器打开 http://localhost:4000 ，能看到课程首页。改动任意一个 _2026/*.md ，刷新页面就能看到变化。这靠的是绑定挂载加 -w 。按 Ctrl + C 停止， docker compose down 清理。 打个比方 绑定挂载像把自家书架直接搬进图书馆的阅览室。你在家改了书，阅览室里那本立刻就变。不用每次重新印一本送过去。 考点（答案写在注释里） COPY Gemfile Gemfile.lock /app/ # 只先拷依赖清单：清单很少变，bundle install 那层能命中缓存 - ./:/app # compose 的绑定挂载：网站内容不进镜像，运行时挂进去 # 所以 Dockerfile 根本不用 COPY 网站内容，边改边预览 jekyll serve -w --host 0.0.0.0 # -w 监视改动自动重建，0.0.0.0 让宿主机访问得到"}, {"u": "labs/lab06.html#ex04", "c": "练习 6 · 打包与交付代码", "t": "练习 4 · 同一份代码，只换配置就能进容器", "x": "Git Bash 实测（Redis 替身） Docker 未实测 原题 ：给一个简单的 Python 应用写 Dockerfile。再写一个 docker-compose.yml ，让应用和一个 Redis 缓存一起运行。 web 每收到一次请求，就让 Redis 里的计数加一。监听地址和缓存地址都做成配置。容器里用环境变量覆盖就行。 K 先回顾 Dockerfile 见 第 6 讲第 14、15 节 。Compose 见 第 16 节 ，配置注入见 第 17 节 。 ? 原理 web 每处理一次请求，就让缓存里的计数加一。视频 46:57 的 etcd 计数器是同一个结构 本机没有 Docker，为了也能真跑，应用只用标准库。它自己用 socket 说 Redis 的 RESP 协议。另外写了一个 30 行的 fake_redis.py 当测试替身。真部署时，由 compose 里的官方 redis:7-alpine 镜像提供真的 Redis。 {} 写 本机测试用的替身，不进镜像： ▶ 跑：配置优先级 同一份代码，端口被一层层覆盖。依次是配置文件、环境变量和命令行。8080 变 9000，再变 9100，最后是 9200。Dockerfile 里的 ENV HOST=0.0.0.0 和 compose 里的 REDIS_URL=redis://cache:6379 ，走的都是第 3 层环境变量。 ▶ 跑：两个服务，故意先起 web 输出这样读。缓存没起来时，web 返回 503。Windows 上连不上本机端口，要重试约 2 秒才放弃。所以异常是 TimeoutError，Linux 上通常立即是 ConnectionRefusedError。缓存起来后，计数是 1、2、3。缓存被 kill 后又回到 503，web 始终没崩。这正是 depends_on 要解决的启动顺序问题。它也说明服务本身要容忍依赖暂时不可用。 ▶ 跑：静态检查，以及在装好 Docker 的机器上 有 Docker 时的验收标准如下。 docker compose ps 显示 web 和 cache 两个服务都在运行。连续 curl localhost:8080 ，计数递增。 docker compose down 后再 up -d ，计数接着上次的值。因为具名卷 redis_data 保存了数据。 docker compose down -v 会连卷一起删，计数归零。 打个比方 配置分层像穿衣服。默认值是内衣，配置文件是衬衫。环境变量是外套，命令行参数是雨衣。别人看到的，是最外面那一层。 ! 为什么会在这里踩坑：容器里的 127.0.0.1 和 localhost 错误写法 在容器里还监听 127.0.0.1 。比如把 HOST 写死在代码里。 现象 容器日志显示服务已经启动。宿主机 curl localhost:8080 却连不上。这条未实测，是按原理推断的。 原因 容器有自己的网络命名空间，127.0.0.1 指的是容器自己。端口映射的流量，是从容器的网卡进来的。只有监听 0.0.0.0 才收得到，这条是补充。 正确写法 把监听地址做成配置。本机默认 127.0.0.1，容器里用 ENV HOST=0.0.0.0 覆盖。就是本练习 Dockerfile 的第 6 行。 错误写法 把 REDIS_URL=redis://localhost:6379 写进 compose。 原因 在 web 容器里，localhost 是 web 自己，Redis 在另一个容器。要用服务名 cache ，由 Compose 的内部 DNS 解析。 考点（答案写在注释里） cache: # 为什么 Redis 单独一个服务，不装进 web 的镜像？ image: redis:7-alpine # 各用最合适的镜像，独立升级和扩展，靠网络通信 # 硬塞进一个镜像，就得协调两边的全部依赖，可能很难，甚至做不到（讲义） ENV HOST=0.0.0.0 # 容器里监听所有网卡，端口映射才连得进来 REDIS_URL=redis://cache:6379 # 用服务名，不用 localhost docker compose down -v # -v 连具名卷一起删，计数归零"}, {"u": "labs/lab06.html#ex05", "c": "练习 6 · 打包与交付代码", "t": "练习 5 · 发布有两条链：包进索引，镜像进仓库", "x": "Git Bash 实测（dry-run） 上传 / Docker 未实测 原题 ：把一个 Python 包发布到 TestPyPI 。除非真的值得分享，别发到正式的 PyPI。然后用这个包构建一个 Docker 镜像，推送到 ghcr.io 。 包这条链是构建、上传到索引、别人安装。镜像这条链是构建、推到仓库、别人 docker run。两条都离不开你本人的凭据。 K 先回顾 发布见 第 6 讲第 19、20 节 。Dockerfile 见 第 15 节 。 ? 原理 两条发布链：包索引和镜像仓库 ▶ 跑：本机能做的部分，不上传 输出这样读。 sha256sum 打出的是两个构件的指纹。上传以后，索引页面会显示同样的哈希。安装器下载后，就拿它来校验。 uv help publish 说， --dry-run 会做检查，但不上传任何文件。所以虽然打印了 Uploading，TestPyPI 上并没有这个包。 --trusted-publishing never 关掉了可信发布的自动探测。可信发布只在 GitHub Actions 这类 CI 里才能用。 ▶ 跑：需要你本人账号的步骤 在 test.pypi.org 注册，开启双因素认证。再在账号设置里创建 API token。 把 pyproject.toml 的 name 改成没人用过的名字。greeting 早被占了，视频里讲师也只好换名。每次上传，版本号都要变。同一版本不能重复上传。 运行 uv publish --publish-url https://test.pypi.org/legacy/ ，按提示输入 token。用户名填 __token__ 。 token 只在你自己的终端里输入。别写进脚本，也别提交进 git。 验收：在一个全新的 venv 里，执行 ex05-b 的第二条命令。能装上， greet Alice 输出 Hello, Alice! 就行。注意 TestPyPI 上一般没有 typer。所以要加 --extra-index-url https://pypi.org/simple/ ，让依赖从正式 PyPI 来。补充一句，混用多个索引有依赖混淆的风险。正式项目要谨慎。 {} 写：镜像 ▶ 跑：构建并推送镜像，需要 Docker 和 GitHub 账号 验收标准如下。 docker run --rm ghcr.io/你的用户名/greeting:0.1.0 Alice 输出 Hello, Alice! 。push 成功后，在 GitHub 个人主页的 Packages 里能看到这个镜像。把它设为 public，别的机器不用登录就能 docker pull 。 docker login ghcr.io 需要一个 personal access token，要带 write:packages 权限。它同样只由你本人输入。 打个比方 发布像寄快递，地址写对了东西才送得到。镜像名开头的 ghcr.io/用户名 就是收件地址。你只能往自己名下的地址寄。 视频里讲师推 Docker Hub 时，也得先改名（ ）。新名字是“用户名/镜像名”这种格式。 考点（答案写在注释里） ghcr.io/用户名/greeting:0.1.0 # 主机名决定推到哪个仓库，用户名那段是命名空间 # 你只有权限往自己的命名空间推，所以镜像名必须这样开头 uv publish --dry-run # 只检查不上传：打印了 Uploading，也没真传 version = \"0.1.1\" # 同一版本不能重复上传，每次都要改版本号"}, {"u": "labs/lab06.html#ex06", "c": "练习 6 · 打包与交付代码", "t": "练习 6 · 静态网站推到 GitHub 就能上线", "x": "Git Bash 实测（本地预览） 推送 / 域名未实测 原题 ：按 GitHub Pages 快速入门 做一个网站。加分题，不计分：给它配一个自定义域名。 静态网站就是一堆文件。仓库里放好 index.html 推上去，GitHub Pages 原样发布。自定义域名靠一个 CNAME 文件加一条 DNS 记录。 K 先回顾 发布与静态站点托管，见 第 6 讲第 20 节 。Git 的提交与推送在第 5 讲。 {} 写 ▶ 跑：推送前，先在本地预览 静态站点就是一堆文件，任何静态文件服务器都能预览。Python 自带的 http.server 就够了。 --bind 127.0.0.1 只对本机开放。 CRLF 警告来自 Git for Windows 的系统级 core.autocrlf 设置。提交前把换行符登记成 LF，检出时再换成 CRLF。不影响网站。 ▶ 跑：需要 GitHub 账号和域名的步骤 在 GitHub 新建一个公开仓库，名字是 你的用户名.github.io 。这是快速入门的做法。再把上面的提交推上去。 进仓库的 Settings，再进 Pages，确认来源是 main 分支的根目录。稍等片刻，页面顶部会显示网址。 验收：浏览器打开 https://你的用户名.github.io/ ，看到 “Hello, GitHub Pages!”。 curl -sI 返回 200。 加分：在 Settings 的 Pages 里填入自定义域名。它会提交一个 CNAME 文件，内容就是域名。再到域名服务商那里加一条 CNAME 记录。让这个子域名指向 你的用户名.github.io 。生效后， dig +short 子域名 CNAME 能看到它。最后在 Pages 设置里勾选 Enforce HTTPS。具体以 GitHub 文档为准。 打个比方 GitHub Pages 像商场给的免费橱窗。你把成品摆进去，路过的人就能看到。CNAME 像在橱窗上挂了自家的招牌。 考点（答案写在注释里） index.html # 只放现成的 HTML：GitHub Pages 原样托管，不用构建 _config.yml + *.md # 放 Markdown 加 Jekyll 配置：Pages 内置 Jekyll，在服务器端构建 gem 'github-pages' # 练习 3 的 Gemfile 只依赖它，为的是在本地复现 Pages 的构建环境 CNAME # 课程仓库也有这个文件，它用了自定义域名 missing.csail.mit.edu"}, {"u": "labs/lab06.html#selfcheck", "c": "练习 6 · 打包与交付代码", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。 练习 2 和 5 要联网下载依赖。练习 1 的每条命令都要新建 venv，Windows 上各要 20 到 30 秒。 考点速查（注释里写着答案） bash venv/Scripts/activate; which python # 还是全局的 python：脚本在子进程里跑，改动随它消失（练习 1） uv sync --locked # 改了约束不 lock：报 lockfile needs to be updated，退出码 1（练习 2） uv pip install liba libb # 交集为空，换哪个解析器都无解，只能分两个环境（练习 1） REDIS_URL=redis://localhost:6379 # 写进 compose 会得到 503：web 容器里的 localhost 是它自己（练习 4） export SOURCE_DATE_EPOCH=1767225600 # wheel 是 zip，记着修改时间。时间固定了，哈希才相同（练习 2）"}, {"u": "labs/lab07.html", "c": "练习 7 · 智能体编程", "t": "开头", "x": "LAB 07 · 对应 第 7 讲 · 智能体编程 练习可视化笔记 · 智能体编程 讲义第 7 讲一共 6 道练习，这里逐题讲。这一讲的练习，几乎都是用某个编码智能体去做一件事。这需要账号或付费订阅。所以本页 不调用任何智能体，也不编造使用体验 。每题先亮结论，再给做法和提示词。还有 能自己核对的验收标准 。不依赖智能体的部分，都在本机真跑。比如验收测试、参考实现和命令行做法。还有配置检查，和一个最小的 harness 骨架。考点都写在代码注释里。生成时间是 … 。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 需要智能体账号或 Docker，写明原因和验收标准 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab07.html#env", "c": "练习 7 · 智能体编程", "t": "环境检查：不调用智能体，只跑能验证的部分", "x": "本页命令都在 Windows 的 Git Bash 里真跑。需要智能体账号或 Docker 的步骤，标成了未实测。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机限制与处理办法 不调用智能体 ：Claude Code、Codex 和 opencode 都要账号。它们按用量或订阅付费。所有“让智能体去做”的步骤，都标成 未实测 。页面给出你能照抄的提示词和验收命令。 没有 Docker ：练习 6 的沙箱容器建不起来。只对配置文件做了静态检查。 mypy ：本机没有全局安装。练习 1 的验收需要它。所以只装进那条命令自己的沙箱 venv。下载缓存放在临时目录，跑完就删。 隐私 ：输出经过 .sanitize.py 过滤。本机路径会显示成 <沙箱> 这类占位符。练习 2 和 5 用的是课程网站仓库的本地副本。不读你的其他文件。 题解作者 ：参考实现、测试和配置，都是笔记作者写的。它们都在本机验证过。它们是给你的“尺子”，不是智能体做出来的样子。"}, {"u": "labs/lab07.html#extra", "c": "练习 7 · 智能体编程", "t": "补充实验 · harness 就是一个循环，50 多行就能写完", "x": "Git Bash 实测 假模型 harness 把上下文交给模型，再执行模型要的工具。工具结果追加回上下文。循环到模型输出文字为止。 做练习前，先把这个循环跑一遍。 mini_harness.py 里工具是真的，能读文件、运行命令。 模型是假的 ，按顺序吐出预先写好的回复。所以每次结果都一样。把 fake_llm 换成一次真正的 API 调用。它就成了一个最小的编码智能体。讲义说，核心概念 200 行代码就能实现 。 K 先回顾 harness 的循环，见 第 7 讲第 5 节 。上下文管理和压缩，见 第 14 节 和 第 15 节 。 {} 读 ▶ 跑：批准所有工具调用 输出怎么读。每一行 [推理 #N] ，都是把整个上下文交给模型一次。输入从 25 字节涨到 517、599、676 字节。读过的文件、命令的输出，全都留在上下文里。一个请求，背后是 4 次推理、3 次工具调用。 打个比方 harness 像餐厅的传菜员，厨师是模型。厨师喊要什么料，传菜员就去库房取。取来放到灶台上，厨师再喊下一样。直到厨师说“出菜”。 ▶ 跑：拒绝运行命令 读文件被配置成自动批准，运行命令需要确认。不加 --approve 时，harness 不执行命令，只告诉模型“被拒绝”。这对应讲师的配置（ ）。改文件不问，每条 bash 都要他确认。 ▶ 跑：把“上下文窗口”设成 600 字节 第三次工具调用后，上下文 676 字节，超过了上限。harness 把前缀压缩成一条摘要，变成 2 条、112 字节。最后一次推理只带着摘要。真实的 harness 会再调用一次 LLM 来写这份摘要。第 7 讲有两个演示，用的就是这些输出。一个讲工具调用循环，一个讲压缩。 ! 为什么会在这里踩坑：没验证也敢下结论 现象 extra-b 里，两条命令都被拒绝了。假模型最后照样说“dl.py 能通过编译”。 原因 这个假模型是写死的，不会因为被拒绝而改口。真实模型也可能在没验证的情况下下结论。 正确做法 看 harness 的原始输出，确认工具真的执行了。结论要能被输出撑住，才算数。 考点（答案写在注释里） python mini_harness.py --approve \"…\" # 4 次推理、3 次工具调用，上下文从 25 涨到 676 字节 python mini_harness.py \"…\" # 不批准：run 的结果是“（用户拒绝了这次工具调用）”，39 字节 python mini_harness.py --approve --limit 600 \"…\" # 676 字节超限，压缩成 2 条 / 112 字节 ctx.append({\"role\": \"tool\", \"content\": result}) # 工具结果必须追加进上下文：模型没有记忆，只看得到输入"}, {"u": "labs/lab07.html#ex01", "c": "练习 7 · 智能体编程", "t": "练习 1 · 同一个任务做四遍，先写好统一的尺子", "x": "验收部分 Git Bash 实测 智能体部分未实测 原题 ：同一个编程任务，做四遍。分别用手写、AI 自动补全、行内对话和智能体。然后比较体验。最好选你正在做的项目里的一个小功能。没有的话，可以做开源项目里 “good first issue” 一类的任务。也可以做 Advent of Code 或 LeetCode 的题。 比较之前，先写好验收测试和类型检查。四种做法都用这把尺子量，才说得清谁真做完了。 K 先回顾 AI 自动补全和行内对话，见第 3 讲。开场演示见 第 7 讲第 1 节 。测试驱动见 第 3 节 。git worktree 见 第 12 节 。 ? 做法 选任务 ：本页用讲师开场演示的那个任务当例子。把讲义的 dl.py 改成正经的命令行程序。要用 argparse，加类型注解，还要通过类型检查。再加上讲义建议的“只保留绝对 URL”。你也可以换成自己项目里的小功能。 先写好尺子 ：验收测试 test_dl.py ，加上 mypy --strict 。四种做法都用它判定做没做完。不然没法比较。 隔离 ：用 compare.sh 建四个 git worktree。每种做法在自己的目录、自己的分支里完成，互不污染。 记录 ：每种做法都记下这些数据。用时、交互次数、手动改了几处、是否通过验收。还有 git diff --shortstat 的结果。全部填进 record.txt 。 控制变量 ：建议按固定顺序做。先手写，再自动补全，再行内对话，最后智能体。做到后面几次，你已经熟悉了任务。这一点也记进备注。 {} 写：起点、尺子、手写版、工作区脚本 ▶ 跑：建四个工作区，提交手写版 输出怎么读。四个 worktree 都从同一个基准提交出发。hand 分支相对 main 加了 34 行，其余三个等你来做。CRLF 警告来自 Git for Windows 的系统级 autocrlf 设置，不影响结果。 ▶ 跑：验收（手写版） 输出怎么读。4 个测试通过， mypy --strict dl_cli.py 没有问题。对照组是讲义原版 dl.py ，它过不了严格类型检查，报 no-any-return。演示里的提示词要求 make sure the program passes type checking 。智能体要解决的，正是这个问题。 下面的演示画出类型在哪一步“丢掉”。再看手写版怎么把它补回来。 ▶ 跑：其余三种做法（需要你自己的工具） 验收标准对每种做法都一样。在对应工作区里， python -m pytest -q test_dl.py 全部通过。 mypy --strict dl_cli.py 没有错误。提交到同名分支。然后运行 compare.sh 末尾那段循环，把 git diff --shortstat 填进表格。智能体那一栏，讲义的提示词可以原样使用。它就在上面命令的最后一行。 打个比方 像比较四种上班的交通方式。得先定好终点和打卡规则，才能比谁快、谁省事。 ! 为什么会在这里踩坑：没有尺子就没法比 误解 四种做法各跑一下，看着能用，就算做完了。 实际 原版 dl.py 也“能用”，可它过不了 mypy --strict 。没有统一的验收，就分不清谁真做完了。 正确做法 先写好并审查测试，再让人或智能体去实现。讲义也推荐测试驱动。智能体能自己跑测试、自己迭代。 考点（答案写在注释里） git worktree add -q -b \"$mode\" \"../wt-$mode\" # 每种做法一个目录、一条分支，共享同一个仓库 git diff --shortstat main hand # 1 file changed, 34 insertions(+)：这一栏填进 record.txt data: bytes = response.read() # 去掉这个注解：测试照样过，mypy --strict 报 no-any-return python -m pytest -q test_dl.py # 先写尺子再比较：四种做法共用这一个验收标准"}, {"u": "labs/lab07.html#ex02", "c": "练习 7 · 智能体编程", "t": "练习 2 · 让智能体带你读代码，每个结论都要核对", "x": "核对部分 Git Bash 实测 智能体部分未实测 原题 ：用 AI 编码智能体探索一个不熟悉的代码库。最好是你真正想调试或加功能的项目。想不到的话，试试 opencode 这个智能体。让智能体帮你弄懂，它的安全相关功能是怎么实现的。 智能体靠 list、search、read 这些工具找答案。它说的每个文件、函数和命令，你都要亲手核对一次。 K 先回顾 “读懂代码库”这个用例，见 第 7 讲第 9 节 。上下文管理见 第 14 节 。 ? 做法 在仓库根目录启动智能体。它大体能看到这个目录下的一切（ ）。 从大到小提问。先问 explain this code base to me 。再问具体的，比如 How do I run this site locally? 。这是讲义注释里给课程仓库准备的问题。对 opencode 可以问：它怎么决定一次工具调用要不要用户批准？指出文件和函数。 观察它调用了哪些工具，比如 list、search、read。它的回答应当建立在这些工具的输出之上。 核对 ：它给的文件、函数和命令，都自己过一遍。下面的脚本就是一份人工复核。它把智能体通常会做的只读操作，手动走了一遍。 {} 写 ▶ 跑：以课程网站仓库为例，核对“怎么在本地跑起来” 输出怎么读。答案有两条路。一条是 bundle exec jekyll serve -w 。另一条是在 Docker 里 docker compose up --build 。然后打开 4000 端口。 顺带还有个发现。README 写的是 docker compose ，AGENTS.md 写的是旧式的 docker-compose 。仓库里的技能文件，也用到了 jekyll serve 。智能体只读一个文件，回答就和另一个对不上。这就是要核对的原因。 ▶ 跑：opencode（需要智能体，下载量也大） 验收标准有三条。智能体回答里的每个文件路径都真实存在， ls 能找到。每个函数名，用 grep -rn 能搜到。你能不看回答，顺着这些位置自己讲一遍流程。讲的是一次工具调用，从提出到被批准或拒绝。 打个比方 像问路。路人说“往前两个路口左转”，你还是得看一眼路牌。他记错了，你就白走了。 ! 为什么会在这里踩坑：只读一个文件就下结论 误解 智能体说“用 docker-compose 启动”，就照着敲。 实际 课程仓库的 README 和 AGENTS.md，给的命令不一样。智能体读了哪个，就照哪个说。上面 ex02-a 一搜就看出来了。 正确做法 让它说出依据的文件和行号，你自己 grep 一遍。两处说法不一时，去看代码和配置本身。 考点（答案写在注释里） ls # 智能体的 list 工具：先看顶层有什么 grep -rn --include='*.md' -e 'jekyll serve' . # search 工具：全仓库搜关键命令 sed -n '/^## Development/,/^## License/p' README.md # read 工具：只读最相关的那一段 # 探索要读大量无关文件。交给子智能体去搜去读，只把结论交回主上下文 # 这样主智能体的上下文就不会被撑满（第 7 讲第 17 节）"}, {"u": "labs/lab07.html#ex03", "c": "练习 7 · 智能体编程", "t": "练习 3 · 氛围编程：只写需求和测试，代码全交给它", "x": "验收测试 Git Bash 实测 智能体部分未实测 原题 ：从零开始氛围编程（vibe code）一个小应用。一行代码都不要亲手写。 “一行都不写”不等于“不管”。精力放在需求说明和验收测试上。然后只用自然语言和智能体对话。 K 先回顾 氛围编程见 第 7 讲第 10 节 。实现功能与测试驱动，见 第 7 节 。 ? 做法 建议把精力放在两份文件上。一份是 需求说明 ，一份是 验收测试 。然后在一个全新目录里，只用自然语言和智能体对话。示例应用是一个词频统计命令行工具。 {} 写：需求和尺子（交给智能体的输入） ▶ 跑：先证明尺子本身没问题 测试写错了，智能体就会朝错误的方向努力。所以先用一个参考实现跑一遍测试，确认它们能通过。这份实现 不是 氛围编程的产物，只是给测试“验尺”： ▶ 跑：真正的练习（需要智能体） 验收标准有四条。① 你没在编辑器里手改过任何一行。 git log -p 里的改动，全部来自智能体。② python -m pytest -q test_wordfreq.py 全部通过。③ git diff 显示测试文件没被改动。提示词里写了“不要修改测试”。④ 记下你一共发了几条消息。还有它几次“声称完成”，其实测试没过。 打个比方 像装修时你只给图纸和验收单，不亲自砌墙。可验收单得你自己写，还得先确认它没写错。 ! 为什么会在这里踩坑：它为了通过测试去改测试 现象 智能体报告“全部测试通过”。可测试文件也被它改过了。 后果 测试不再代表你的需求，“全部通过”毫无意义。 防法 在提示里明确禁止。用 git diff -- test_wordfreq.py 检查。或者把测试放在它不该碰的位置。练习 4 的技能里，也写了这条护栏。 考点（答案写在注释里） python -m pytest -q test_wordfreq.py # 先用参考实现验尺：5 passed，说明测试本身没写错 git diff -- test_wordfreq.py # 应该是空的：测试被改过，“全部通过”就不算数 git log -p # 改动全部来自智能体，才算一行没亲手写 printf 'The cat and the hat.\\nTHE end\\n' | python wordfreq.py -n 3 # 第一行是 3 the：不分大小写（ex03-b）"}, {"u": "labs/lab07.html#ex04", "c": "练习 7 · 智能体编程", "t": "练习 4 · 三种配置的区别：何时进上下文、进多少", "x": "格式与体积 Git Bash 实测 在智能体中测试未实测 原题 ：为你选的编码智能体，创建并测试三样东西。一是 AGENTS.md ，或者对应的文件，比如 CLAUDE.md 。二是一个技能，比如 Claude Code 的 skill 或 Codex 的 skill 。三是一个子智能体，比如 Claude Code 的 subagent 。想想什么时候该用哪一个。你的智能体可能不支持其中某些功能。可以跳过，或者换一个支持的智能体。 AGENTS.md 每次启动全文加载。技能和子智能体启动时只加载描述。子智能体还在独立的上下文里跑。 K 先回顾 AGENTS.md 与技能，见 第 7 讲第 16 节 。子智能体见 第 17 节 。 {} 写（以 Claude Code 的目录约定为例） ▶ 跑：检查格式，估算各自占多少上下文 输出怎么读。AGENTS.md 每次启动都整个进上下文，515 字节。技能和子智能体启动时只放描述，分别是 158 和 215 字节。正文 322 和 442 字节，用到时才读。字节数只是估算，真实系统按 token 计。 ▶ 跑：在智能体里测试（需要账号） 验收标准有四条。① 新开会话，直接问“改完 Python 代码后要做什么”。它能复述 AGENTS.md 里的两条规矩。② 说“跑一下测试”。它会打开 run-tests 技能，按里面的格式汇报。也就是只列失败测试和第一行断言。③ 改一个 .py 文件后，说 use the code-checker subagent 。主对话里只出现子智能体的结论，没有几百行检查输出。④ 删掉 AGENTS.md 里的某条规矩，再问一遍。回答跟着变，说明它真的来自文件。不是模型自己的习惯。 AGENTS.md / CLAUDE.md 技能 skill 子智能体 subagent 何时进上下文 每次启动，全文 启动时只有描述。用到时读正文 启动时只有描述。被调用时，在 独立 的上下文里运行 适合放 每次都需要的规矩：怎么跑测试、代码风格、目录约定 偶尔才用的长流程：发布步骤、评审清单 读得多、结论短的子任务：检查、调研、评审 代价 越长越占上下文 描述写得不好，就不会被想起 多一次启动。看不到主对话的历史，提示要给足 打个比方 AGENTS.md 像员工手册，入职第一天全读。技能像工具柜里的说明书，用哪台机器才翻哪本。子智能体像外包，你只看他交来的报告。 ! 为什么会在这里踩坑：描述只写“是什么” 误解 子智能体的 description，写成“一个 Python 检查工具”就够了。 实际 主智能体启动时只看得到描述。它靠描述决定什么时候委派。描述里没写“何时用”，它往往不会被自动调用。 正确写法 像本题的 SKILL.md 那样，把使用时机写进描述。比如“在修改 Python 代码之后使用”。讲义也说，可以显式调用它。也可以让主智能体在改完 Python 文件后自动调用。 考点（答案写在注释里） AGENTS.md # 每次启动全文进上下文，515 字节：只放每次都需要的规矩 SKILL.md 的头部 # 启动时只加载 name 和 description，158 字节。正文用到才读 code-checker.md # 子智能体：独立上下文干活，只把结论交回主对话 CLAUDE.md 里写 @AGENTS.md # Claude Code 读 CLAUDE.md，这一行让两种工具共用一份说明 # 两份正文要是写进 AGENTS.md，每次启动要多占 764 字节（ex04-a）"}, {"u": "labs/lab07.html#ex05", "c": "练习 7 · 智能体编程", "t": "练习 5 · 让智能体写一条 sed，别让它逐行编辑", "x": "命令行做法 Git Bash 实测 智能体部分未实测 原题 ：第 9 讲（代码质量）有一道 Markdown 列表正则练习。用编码智能体完成它。把讲义文件里作为列表标记的 - 换成 * 。注意不是所有的 - 都是列表标记。它是不是直接编辑文件完成的？让智能体直接改文件来做这种事，有什么缺点和局限？想办法让它不通过直接编辑文件来完成。提示：让它用第 1 讲里的某个命令行工具。 列表标记只在行首，后面跟空格，而且不在代码块里。让智能体写一条 sed 或 awk 命令。规则一眼看清，换个文件还能再用。 K 先回顾 第 1 讲的 sed 和 awk。第 9 讲的正则。本讲的上下文与审查，见 第 7 讲第 14 节 和 第 18 节 。 ? 原理：直接编辑的缺点 耗上下文 ：要把整个文件读进上下文。每一处修改，还要生成一段 diff。文件越大，越慢、越贵，还可能撑满窗口。 难复现、难审查 ：28 处修改，分散在一堆编辑操作里。你只能逐处检查。一条 sed 或 awk 命令，规则一眼看懂，换个文件还能再用。 容易漏改或误改 ：模型是概率性的。长文件里逐行手改，可能漏掉几处。也可能把破折号 --- 也改了。以上是根据讲座内容的推理，你做练习时可以验证。 {} 写：命令行做法，以及给智能体的两种提示 ▶ 跑：天真的全局替换会误伤多少 输出怎么读。 sed 's/-/*/g' 改动了 68 行，真正的列表项只有 28 行。front matter 的 --- 变成了 *** 。日期变成了 2026*01*23 ， high-quality 变成了 high*quality 。实测用的是课程仓库本地副本里的 code-quality.md。 ▶ 跑：只换列表标记 恰好 28 行被改，替换后不再有“- ”开头的列表项。结果和一行 sed -E 's/^([[:space:]]*)- /\\1* /' 逐字节相同。因为这个文件的代码块里，恰好没有“- ”开头的行。awk 版本多做了一层保险。 下面的演示逐行扫描，看 awk 怎么只换该换的那几处。 ▶ 跑：在智能体里比较两种提示（需要账号） 验收标准有三条。① 用提示 A 时，记录它是否直接编辑。还有它调了几次编辑工具。再看 git diff --stat 改了多少行，应为 28 行，多了就是误改。② 用提示 B 时，它应该给出一条 sed 或 awk 命令并运行。 git diff --stat 同样是 28 行。③ 用 cmp 把两种方式的结果和本页 bullets.sh 的结果比一比。看谁做对了。 打个比方 让智能体逐行改，像请人在书里一处处描改符号。让它写 sed，像请他刻一枚印章。印章对不对，你看一眼就知道，还能反复用。 ! 为什么会在这里踩坑：awk 里写成了 gsub bash · 本机实测（输入是第 101 行那段文字） $ cat line101.txt - `abc` --- matches the literal \"abc\". $ awk '{ sub(/- /, \"* \") } 1' line101.txt # sub 只换第一处 * `abc` --- matches the literal \"abc\". $ awk '{ gsub(/- /, \"* \") } 1' line101.txt # gsub 全换，破折号被改坏 * `abc` --* matches the literal \"abc\". 错误写法 gsub(/- /, \"* \") 后果 gsub 会把一行里所有的“- ”都换掉。第 101 行的破折号 --- 后面正好有空格。于是它变成了 --* 。 正确写法 用 sub 。它只替换一行里的第一处匹配，也就是行首的列表标记。 考点（答案写在注释里） sed 's/-/*/g' code-quality.md # 错：68 行被改，第 1 行的 --- 变成 ***，front matter 坏了 awk '!code && /^[[:space:]]*- / { sub(/- /, \"* \") }' # 对：只换行首的“- ”，正好 28 行 /^[[:space:]]*```/ { code = !code; print; next } # 遇到代码块围栏就翻转标志，块里的行一律不动 diff a.md a.md.new | grep -c '^>' # 数改动行数，再和智能体的 git diff --stat 对照"}, {"u": "labs/lab07.html#ex06", "c": "练习 7 · 智能体编程", "t": "练习 6 · yolo 模式关进容器，最坏也只毁掉容器", "x": "配置静态检查 Git Bash 实测 Docker 未实测 原题 ：多数编码智能体都有某种“yolo 模式”，例如 Claude Code 的 --dangerously-skip-permissions 。直接这样用不安全。但放进虚拟机或容器这类隔离环境，可能就可以接受。在你的机器上把这套环境搭起来。这些文档可能有用： Claude Code devcontainers 、 Docker Sandboxes / Claude Code 。做法不止一种。 在容器里跳过所有确认。智能体能碰到的，只有容器和挂载进去的项目目录。破坏了就删掉重建，项目里的改动靠 Git 审查。 K 先回顾 容器与 Dockerfile，见 第 6 讲第 12 到 15 节 。本讲的工具审批见 第 7 讲第 1 节 ，隐私见 第 6 节 。 ? 原理 隔离的意义：最坏情况只发生在容器和这个目录里。API 密钥仍要传进容器，智能体也读得到（devcontainer.json 第 7 行） 注意网络。容器默认能访问外网。智能体仍可能把数据发出去，或者下载东西。官方文档的参考 devcontainer 还配置了出站网络限制。这一点以文档为准，本页未实测。本页的最小配置没有这一层。 {} 写 ▶ 跑：本机能做的检查 输出怎么读。devcontainer.json 是合法的 JSON。Dockerfile 第 2 行用 node:22-slim，第 7 行切到非 root 用户 node。第 9 行的默认命令，跳过了所有权限确认。 ▶ 跑：构建并启动（需要 Docker 和账号） 验收标准有四条。① 在容器里 whoami 输出 node，而不是 root。② ls /workspace 只看到项目文件。 ls ~ 看不到你宿主机家目录的内容。③ 让智能体做破坏性操作，比如删掉 /workspace 之外的某个文件。影响只留在容器里，重建容器就能恢复。④ /workspace 里的改动，用 git diff 全部看得见、撤得回。 打个比方 像让小朋友在沙坑里随便玩。沙坑弄乱了，铲平就行。可你借给他的那本书带进了沙坑，弄坏了还是你的。 ! 为什么会在这里踩坑：以为进了容器就万事大吉 误解 智能体在容器里，项目目录也就安全了。 实际 项目目录是挂载进去的。智能体对它的改动，会直接写回宿主机。隔离保护的，只是目录之外的东西。 正确做法 目录之内的改动，照样要靠 Git 审查和撤销。这也是讲师自己的做法。密钥别写进 devcontainer.json，用环境变量传。 考点（答案写在注释里） USER node # 容器里也不给 root（Dockerfile 第 7 行） -v \"$PWD\":/workspace # 唯一和宿主机共享的目录：改动直接写回宿主机，靠 Git 审查 -e ANTHROPIC_API_KEY # 密钥从环境变量传进去，但容器里的智能体也读得到 claude --dangerously-skip-permissions # yolo 模式：只在这种隔离环境里考虑 # 容器默认能上外网：本页的最小配置没有限制出站网络"}, {"u": "labs/lab07.html#selfcheck", "c": "练习 7 · 智能体编程", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。练习 1 的类型检查，要先在 venv 里装好 mypy。 考点速查（注释里写着答案） python mini_harness.py \"检查 dl.py 能否编译\" # 不加 --approve：run 的结果是“（用户拒绝了这次工具调用）”，39 字节（extra-b） dl_cli.py 第 12 行去掉 data: bytes = # 测试照样过，mypy --strict 报 no-any-return，和原版 dl.py 一样（练习 1） ctx.append({\"role\": \"tool\", ...}) # 每次工具结果都追加进上下文：模型没有记忆，只看得到输入（第 7 讲第 5 节） sed 's/-/*/g' code-quality.md # 第 1 行 --- 变成 ***，front matter 坏了（ex05-a） 技能只预先加载描述 # 免得对话还没开始，上下文就被占满。两份正文省下 764 字节（ex04-a）"}, {"u": "labs/lab08.html", "c": "练习 8 · 代码之外", "t": "开头", "x": "LAB 08 · 对应 第 8 讲 · 代码之外 练习可视化笔记 · 代码之外 讲义第 8 讲一共 7 道练习，这里逐题讲。每题先亮结论，再给真跑的代码和输出。接着打个比方，最后指出坑在哪。考点都写在代码注释里。这些练习大多要你去真实的开源社区“看”。读源码注释，翻提交历史，比较 README。再评估 issue 和 PR，看 Stack Overflow。本页把 能在本机复现的部分 做成了能真跑的脚本和示例。所有输出都由脚本在本机真跑后自动收集。生成时间是 … 。要去真实社区的部分，给出了步骤、模板和验收标准。这些都标明了“需你本人完成”。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 需要联网或需你本人完成，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab08.html#env", "c": "练习 8 · 代码之外", "t": "环境检查：只在本机真跑，不对外发任何东西", "x": "本页命令都在 Windows 的 Git Bash 里真跑。要联网或要你本人去社区做的部分，标成了未实测。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本页的边界与替代做法 不做任何对外动作 ：不在真实项目里发 issue、评论或 PR。也不点赞。练习 4、6、7 要去真实项目找例子。这部分标成 需你本人完成 ，给出操作步骤和判断标准。 不批量联网 ：练习 1 原题建议看 Redis 或 curl 的源码。本页改用 本机已装的 CPython 标准库源码 ，版本是 Python 3.13.5。它同样是知名开源项目。练习 3 的 README，取自本机已装的 requests、rich 和 flask 包。它们在 GitHub 上都远超 1000 星，元数据里自带 README，不用下载。 示例仓库可复现 ：练习 2 的仓库由 make_repo.sh 现场生成。作者、邮箱和提交时间都固定了。邮箱用的是 example.com 示例身份。脚本还用 GIT_CONFIG_GLOBAL=/dev/null 隔离了你的 git 配置。所以谁跑出来的哈希，都和本页一致。 检查脚本是启发式 ：练习 4、6、7 各有一个 *_check.py 。它们把讲义的清单写成了正则。它们只能查“有没有”，判断不了“好不好”。这是用来练眼光的，不是自动评分器。"}, {"u": "labs/lab08.html#ex01", "c": "练习 8 · 代码之外", "t": "练习 1 · 好注释删掉了，后人就得重踩一遍坑", "x": "Git Bash 实测 改用 CPython 源码 原题 ：浏览一个知名项目的源码，比如 Redis 或 curl 。找出讲座提到的几类注释。比如有用的 TODO，对外部文档的引用。还有讲“为什么不用显而易见做法”的注释。以及来之不易的教训。如果这条注释不在了，会失去什么？ 好注释交代的，是代码里看不出的东西。比如现状、原因、出处，以及和原文的差异。删掉它，后来者要么把对的改错，要么重做一遍实验。 K 先回顾 七类值得写的注释，见 第 8 讲第 2 节 。 grep -n -A/-B 显示行号和上下文，见第 1 讲。 ? 原理：怎么找 注释有固定的“记号”，可以 grep。 TODO 、 XXX 、 FIXME 最常见。引用常带 Reference 、 RFC 、 See ，或者作者名、论文名。教训常带 issue 编号，CPython 里是 bpo- 和 GH- 。why-not 常出现 instead of 、 avoid 、 don't ，或者 could … but 。先 grep 出候选，再带上下文读。 ▶ 跑：带上下文的 TODO（smtplib.py） 输出怎么读。TODO 之前的 5 行解释了 现状和原因 。有多个 Resent 块时，没法确定哪个最新。所以宁可抛 ValueError，也不去猜。TODO 本身说了 要做什么 ：加启发式，让用户选择开启。还说了 为什么值得做 ：几乎总能猜对。 删掉它，后来者可能把 ValueError 当成 bug“修”掉。或者重新论证一遍能不能猜。 ▶ 跑：引用外部文献，并注明和原文的差异（random.py） 第 540 行给出完整的论文出处。读者可以对照原文验证算法。第 863 行更值钱： 原论文漏了一个 log(v) 。这正是讲义说的“注明和参考资料的差异”。 没有它，下一个对照论文的人会以为代码写错了。他会把正确的代码，“改”成论文里的错误版本。 ▶ 跑：why-not 与 issue 编号（heapq.py、_pyio.py） heapq 这段是教科书式的 why-not。它说我们 本可以 提前跳出循环。但事实证明这不是好主意，尽管很多书都这样写。接着给了原因。弹出时被筛进来的元素通常很大，提前比较往往不划算。最后给了出处：Knuth 卷 3。 GH-95782 则把一行看似多余的 max(…, 0) ，和一个 issue 关联起来。这是“来之不易的教训”的常见写法。删掉注释，有人会觉得 max 多此一举。 {} 写：给一条“只说不要”的注释补上原因 base64.py 第 179 行写着 s = s + … # Don't use += ! ，却没说为什么。下面的小实验把“为什么”找了回来： ▶ 跑 输出怎么读。调用者传进来的，可能是可变的 bytearray 。 s = s + … 会生成新对象，调用者的数据不变。 s += … 对 bytearray 是 就地追加 ，会悄悄改掉调用者的缓冲区。真正的 b32encode 处理完，缓冲区仍是 abc 。 这就是那行注释的原因吗？这是笔记作者根据实验做的推断。CPython 源码里没写。这条注释防住了“看起来更短”的改法。可惜没留下原因，后人只能像这样重做实验。这正是练习要你体会的“会失去什么”。 打个比方 好注释像山路边的警示牌：“此处塌方，请绕行”。拆了牌子，路面看着挺平，下一个人照样开下去。 ▶ 跑：原题的 curl 做法（未实测） 需你本人完成：在 Redis 或 curl 里找 在浏览器里打开仓库，用 GitHub 的代码搜索。也可以克隆后 grep -rn 。搜 TODO 、 XXX 、 RFC 和 workaround 。 每类挑一条，记下文件、行号和永久链接。在 GitHub 上按 y ，链接会换成带提交哈希的永久链接。 每条写一句“如果没有它，后来者会……”。 验收标准 ：至少 4 条，覆盖 TODO、引用、why-not 和教训四类。每条都能说出具体的损失，不能只说“会更难懂”。 考点（答案写在注释里） # TODO: optimize # 坏：没说优化什么，为什么现在不做，到什么程度才要做 # TODO implement heuristics ... # 好：smtplib 这条交代了现状、原因、要做的事和预期效果 # 任何人看完都能接着做。讲义的反例和正例，差的就是这些"}, {"u": "labs/lab08.html#ex02", "c": "练习 8 · 代码之外", "t": "练习 2 · 提交信息事后补很难，要在提交时写好", "x": "Git Bash 实测（示例仓库） 真实项目需你本人完成 原题 ：挑一个你感兴趣的开源项目。看它最近的提交历史（ git log ）。找一条解释了 为什么 的好提交信息。再找一条只描述 改了什么 的弱信息。对弱的那条，看它的 diff（ git show <hash> ）。按 Problem → Solution → Implications 结构，重写一条更好的信息。注意事后重建上下文要花多少功夫！ 用 awk 'NF <= 2' 能快速筛出只有一个词的提交信息。可要补写“为什么”，diff 帮不上忙。只能去翻 PR、issue，或者去问人。 K 先回顾 提交信息的四个问题，以及 P、S、I 结构。见 第 8 讲第 4 节 。git blame 和 log -S 也在那一节。Git 基础见第 5 讲。 {} 写：造一个可复现的示例仓库 ▶ 跑：看历史 输出怎么读。5 次提交里，ff12122 和 0e606e9 解释了为什么。7809933 fix 和 4140218 update 什么都没说。 ▶ 跑：自动筛出弱信息，再看 diff awk 'NF <= 2' 只留“哈希加一个词”的行。这个筛子粗糙，但好用。真实项目里，还可以筛 wip 、 fix 、 update 、 misc 这类词。 git show HEAD 告诉我们改了什么：64 变成 16。可为什么是 16？diff 里没有任何线索。 {} 写：按 Problem → Solution → Implications 重写 诚实地说 这条信息里写了“网关固件只缓存 16 个包”。能写出来，是因为示例场景是笔记作者编的。真实项目里的弱提交，你通常只能去翻资料。比如对应的 PR、issue 和邮件列表。或者直接去问作者。这正是练习想让你体会的成本。找不到依据的地方，在信息里如实写“推测”，不要编。 ▶ 跑：用 --amend 改写最后一次提交的信息 哈希从 4140218 变成了 ed8824e。amend 不是“修改”提交。它造了一个新提交，替换掉分支末端。为了让新哈希也能复现，准备步骤里固定了 GIT_COMMITTER_DATE 。 ▶ 跑：好信息与坏信息对 blame 的差别 第 3 到 5 行追到 ff12122，信息完整解释了 1464 的由来。第 6 行追到 7809933，只有一个 fix 。下面的演示把筛选和改写的过程画了出来。 打个比方 事后补提交信息，像隔了半年再补旅行日记。照片都在，可当时为什么改道，你已经想不起来了。 ! 为什么会在这里踩坑：隔离了配置就没有身份 现象 Committer identity unknown … fatal: no email was given and auto-detection is disabled ，退出码 128。 原因 为了不碰你的真实配置，这里让 git 不读全局配置。于是它不知道“你是谁”。amend 会保留原作者，但 提交者 换成了当前用户。提交者必须有名字和邮箱。 user.useConfigOnly=true 让 git 不去猜身份。 补充 不加这个选项会怎样？git 会用“系统用户名@主机名”拼一个邮箱。本机拼出来的不合法，所以同样报错。在主机名完整的系统上，它可能“成功”。你的主机名就被悄悄写进了提交。 正确写法 先在 这个仓库 里设身份： git config user.name … 和 git config user.email … 。不加 --global ，就只影响当前仓库。见上面的 ex02-amend。 误区 想用 --amend 去改 7809933 那条 fix 。 实际 amend 只能改分支最末端的提交。改更早的要用交互式 rebase，这是补充。而且它会重写之后所有提交的哈希。已经推送、别人在用的历史，不该这样改。所以提交信息要在提交时就写好。 ▶ 跑：在真实项目上（未实测） 需你本人完成：在真实项目上做一遍 克隆一个你用过的项目，用 git log --format='%h %s' -n 200 浏览标题。再用上面的 awk 筛一遍。 挑一条弱信息，运行 git show <hash> 。再去 GitHub 上找它对应的 PR 和 issue，收集“为什么”。提交页面通常会显示关联的 PR。 按 P、S、I 写一条新信息。拿不准的地方写“推测”。 验收标准 ：新信息的正文能回答两件事。什么问题逼着改动？有什么取舍或影响？再记下你花了多少分钟重建上下文，查了哪些地方。 考点（答案写在注释里） git log --format='%h %s' | awk 'NF <= 2' # 只留“哈希加一个词”的行 # 为什么写 NF <= 2，不写 NF == 2？ # 标题为空的提交（--allow-empty-message）只剩哈希，NF = 1 # 那是最差的提交信息，也该被筛出来 git commit --amend # 只能改最末端的提交，而且哈希会变"}, {"u": "labs/lab08.html#ex03", "c": "练习 8 · 代码之外", "t": "练习 3 · 千星项目的 README 也有好有坏，先用法后安装", "x": "Git Bash 实测 原题 ：比较 GitHub 上三个 1000 星以上项目的 README。它们都一样有用吗？找出那些你看来主要是噪声的东西。把它们当成你以后写 README 的教训。 三个千星项目的 README 差别很大。requests 第 5 行就给代码，rich 先讲安装，flask 干脆不提安装。哪些是噪声，要你站在读者的角度判断。 K 先回顾 README 漏斗：是什么，为什么关心，怎么用，怎么装。见 第 8 讲第 3 节 。 ? 原理：不联网也能拿到 README Python 包发布到 PyPI 时，通常把 README 当“长描述”写进元数据。装好后，它就在 site-packages/<包>-<版本>.dist-info/METADATA 里。用 importlib.metadata 就能读出来。本机装有 requests、rich 和 flask，它们在 GitHub 上都远超 1000 星。 {} 写 ▶ 跑 输出怎么读。数字对应本机这几个版本的 README： 项目 是什么 用法和安装谁先 可能的噪声 requests 2.32.5 第 3 行一句话。元数据里是 “Python HTTP for Humans.” 第 5 行就是代码示例，第 28 行才讲安装。 先用法 下载量、徽章。“Cloning the repository” 更像是给贡献者看的 rich 14.3.2 第 30 行才有一句话介绍 第 46 行 “Installing” 在前。第 60 行起才是用法 开头 28 行是徽章和 18 种语言的 README 链接。第 34 行有张功能演示图。这正是讲义推荐的可视化演示 flask 3.1.2 第 5 到 9 行一段介绍 第 20 行是 “A Simple Example”。整份 README 不提安装 很短。Donate 和 Contributing 各占一节 脚本只能给出位置和顺序。哪些是噪声，要你以读者的身份判断。同一段徽章，对想看项目活不活跃的人，可能就有用。 打个比方 比 README 像比三家店的门面。一家橱窗里摆着样品，一家门口贴满了奖状。还有一家只挂了块招牌。路人几秒钟就决定进不进。 ! 为什么会在这里踩坑：把代码块里的注释当成标题 现象 第一版脚本把 flask README 代码块里的 # save this as app.py ，也当成了 Markdown 标题。 原因 Markdown 标题和 Python、shell 的注释，都以 # 开头。 正确写法 先标记每行在不在 ``` 代码块里，见第 18 到 21 行。只在块外找标题。拿正则“半解析”结构化文本，这种边界情况到处都是。第 9 讲会讲正则的局限。 需你本人完成：看 GitHub 上渲染后的页面 METADATA 里的 README，可能和 GitHub 主页上的最新版略有不同。图片和徽章，也只有在浏览器里才看得到效果。打开三个项目的 GitHub 主页，计时。看你多少秒内能回答“这是什么、我该不该关心”。 验收标准 ：每个项目写一条“我会删掉或挪走的内容”。再写一条“值得学的做法”。 考点（答案写在注释里） first code/usage: L5 first 'install': L28 -> usage first # requests：先用法后安装，符合讲义 first code/usage: L50 first 'install': L46 -> install first # rich：读者还没决定用不用，就得先看安装 # 为什么讲义主张先用法、后安装？ # 读者还没决定要不要用，安装步骤对他没意义。先让他看到效果，再决定值不值得装"}, {"u": "labs/lab08.html#ex04", "c": "练习 8 · 代码之外", "t": "练习 4 · issue 每缺一项，维护者就要多追问一轮", "x": "Git Bash 实测（样本） 真实 issue 需你本人完成 原题 ：在你用的项目里，找一个 open 的 issue。有 “good first issue” 或 “help wanted” 标签的优先。按讲座的标准评估它。它尊重维护者的时间吗？调试要的信息都给全了吗？还是说，维护者得和提交者来回好几轮，才找得到根因？ 把讲义的清单写成 7 条正则，就能粗查一份 issue 缺了什么。坏样本 0/7，至少要追问 7 轮。好样本 7/7，第一次读就能复现。 K 先回顾 bug 报告清单、最小复现和搜重复，见 第 8 讲第 10 节 。正则的 re.I 和 re.M 见第 9 讲。 {} 写：把清单变成脚本 两份样本是示意，围绕练习 5 的真实 bug 写成： ▶ 跑 坏的那份 0/7。维护者至少要问 7 次，才能开始调试。每一轮往返，可能就是几天。好的那份 7/7，第一次读就能复现。下面的演示逐条画出了正则的匹配。 打个比方 issue 像一张报修单。写着“空调坏了”的，师傅得打电话问三遍。另一张写着“302 不出冷风，滤网洗过了”。师傅带对工具直接上门。 需你本人完成：评估一个真实的 issue 在你常用的项目的 Issues 页，按标签筛 good first issue 或 help wanted 。挑一个 open 的 bug 类 issue。 把正文复制到本地文件，只用于自己分析。运行 python ex04/issue_check.py 你的文件.txt 。再人工逐项核对：脚本说“有”的项，内容真的够用吗？ 读下面的评论。维护者追问了什么？和你预测的缺失项一致吗？ 验收标准 ：写出缺哪几项、预计几轮往返。再和评论区的实际往返对比。 不要 为了练习去评论或 +1。那正是讲座说的噪声。 考点（答案写在注释里） Expected: `analytics` # 为什么要写期望？光写实际发生了什么不行吗 # 你看到的可能正是设计如此。那就不是代码 bug，而是文档没说清 # 写出期望和实际的差值，维护者才能判断是哪一种（视频 23:21）"}, {"u": "labs/lab08.html#ex05", "c": "练习 8 · 代码之外", "t": "练习 5 · 最小复现：删一块跑一次，bug 还在才算数", "x": "Git Bash 实测 原题 ：想一个你在软件里遇到过的 bug，或在 issue 跟踪器里找一个。练习做最小可复现示例。剥掉一切和 bug 无关的东西。直到剩下的用例最小，又仍能展示问题。写下你删了什么，为什么删。 缩减的套路是删一块、跑一次，bug 还在才接受。脚本能把 31 行自动缩到 17 行。剩下的要人工看懂 bug 再收尾，最后一行就能复现。 K 先回顾 最小可复现示例见 第 8 讲第 10 节 。subprocess 和正则的先行断言 (?!…) 见第 9 讲。 {} 写：一个带 bug 的程序 ▶ 跑：看到症状 analytics.csv 的标题成了 Analyti 。仔细看，Sale 和 Cost 也都少了字母，只是不那么显眼。 {} 写：自动缩减器 ▶ 跑 缩减器一共运行了 50 次候选程序。块大小 15、7、3 全部失败，逐行删时成功了 14 次。31 行缩到了 17 行。下面的演示逐步画出了这个循环。 {} 写：人工收尾 ▶ 跑 删了什么 为什么能删 谁删的 文档字符串、注释、9 个空行、 return 0 不影响运行结果 reduce.py sales.csv、costs.csv 两份数据 bug 只要一个文件名就能出现 reduce.py csv 和 io 的导入、 total() 、数字列、 main() 循环、 sys.exit 和 bug 无关，但它们互相调用，单删一行就报错。得先看懂 bug 在 title_for 里，再整体拿掉 人工 title_for 函数本身、 .title() 把 rstrip(\".csv\") 直接用在字符串上，症状不变 人工 打个比方 最小复现像拆一团乱线找断头。一根根剪下来，每剪一根就通一次电。灯还亮，说明这根和故障无关，扔掉。 ! 为什么会在这里踩坑：rstrip 换成 strip 也修不好 错误写法 name.strip(\".csv\") 实际 csv_export.csv 变成了 _export 。strip 从 两端 删掉字符集合 {. c s v} 里的字符。开头的 csv 也被删了。 正确写法 用 name.removesuffix(\".csv\") ，要 Python 3.9 以上。也可以用 os.path.splitext(name)[0] ，这条是补充。有了最小复现，修法对不对，一行就能验证。 考点（答案写在注释里） SYMPTOM = re.compile(r\"analyti(?!cs)\", re.IGNORECASE) # reduce.py 第 9 行：analyti 后面不能跟 cs # 只写 analyti 会怎样？正确的输出 analytics 也包含 analyti # 判定永远为真，修好的程序也会被当成“有 bug” # 甚至可能删出一个碰巧打印 analytics 的程序。判定越精确，缩出来的才越是同一个 bug"}, {"u": "labs/lab08.html#ex06", "c": "练习 8 · 代码之外", "t": "练习 6 · 好评审意见：针对代码、给替代方案、讲原因", "x": "Git Bash 实测（样本） 真实 PR 需你本人完成 原题 ：在你熟悉的项目里，找一个已合并的 PR。它的评审意见要有实质内容，不只是 “LGTM”。通读评审。所有评论都同样有建设性吗？如果你是 PR 作者，收到这些评论会是什么感受？ 给每条评论贴标签。看它针对人还是代码，是提问还是命令。再看讲没讲原因，给没给替代方案。一个标签都贴不上的，就该改写。 K 先回顾 代码评审的建议，见 第 8 讲第 14 节 。 {} 写：评论样本与打标签脚本 前 8 条是讲义里成对出现的坏、好示例。其中第 4 条按视频补上了原因。最后两条 nit 和肯定是示意。 ▶ 跑 输出怎么读。“You wrote…” 被标成针对人。“Don't use globals here.” 和 “Handle the null case.” 没有标签。脚本提示改写。 注意 “This function is confusing.” 也被要求改写。它已经从针对人改成了针对代码，这是讲义的正例。但它还是没说 哪里 不好懂，希望怎么改。启发式脚本在这里，反而帮你多想了一步。 打个比方 评审意见像导航语音。“你走错了”没用。“前方 200 米掉头，这条路在修”，才让人知道怎么办。 需你本人完成：读一个真实的评审 在 GitHub 的 Pull requests 页筛 is:pr is:merged ，按评论数排序。挑一个评论多、讨论具体的。 给每条评审意见归类。针对代码还是人？能不能直接动手？是提问还是命令？讲原因了吗？是阻塞还是 nit？有没有肯定？ 以作者的身份写一句感受。再把最差的一条改写成好的版本。 验收标准 ：一张归类表，一条改写。再写一句：评论减半的话，哪些该留下。只读，不评论。 考点（答案写在注释里） # 一个 PR 里有 20 处命名不合约定，评审者该怎么写？ # 只在第一处评一次：“本仓库的命名约定是……，请全局统一” # 别留 20 条重复评论（视频 48:36）。必要时标成 nit，让作者先改阻塞问题 This function is confusing. # 针对代码了，但没说哪里难懂、想怎么改"}, {"u": "labs/lab08.html#ex07", "c": "练习 8 · 代码之外", "t": "练习 7 · 具体的是非题，十行实验就能自己回答", "x": "Git Bash 实测（样本） 真实帖子需你本人完成 原题 ：去 Stack Overflow，在你熟悉的技术里找一个答案得票很高的问题。再找一个被关闭或被大量踩的问题。用讲座的建议对比它们。哪个问题能得到更好的回答，能事先预测吗？ 好问题说出了自己的理解，做过功课，问得具体。像“LEFT JOIN 会保留右表没匹配的行吗”这种是非题。十行 SQLite 就能自己验证。 K 先回顾 提问的建议，见 第 8 讲第 15 节 。 {} 写 Q1 和 Q2 是讲义原句，一个太泛，一个具体。Q3 是示意。 ▶ 跑：检查三种问法 {} 写：用实验回答是非题 ▶ 跑 Q2 的答案是“是”。LEFT JOIN 里，ben 带着 None 出现，None 就是 SQL 的 NULL。条件恒为假时，三个人都在，右边全是 None。Q3 也就有了答案。 这就是讲义说的“先做点功课”。很多具体的是非题，十行实验就能自己验证。问人时，就能带着结果去问更深一层的问题。 打个比方 提问像问路。“火车站怎么走”只能换来一大段描述。“前面路口左转是火车站吗”，对方点个头你就走了。 ! 为什么会在这里踩坑：多追问一步就能发现 错误写法 … LEFT JOIN labs l ON s.id = l.student_id WHERE l.lab = 'lab01' 现象 看上面 ex07-b 最后一行。ben 又消失了，结果和普通 JOIN 一样。 原因 WHERE 在连接 之后 才过滤。ben 那行的 l.lab 是 NULL。 NULL = 'lab01' 不为真，于是被滤掉了。这条是补充的 SQL 语义。 正确写法 把对右表的条件写进 ON： ON s.id = l.student_id AND l.lab = 'lab01' 。这就是“别接受不完整的答案”的价值。多问一个是非题，就多学到一个坑。 需你本人完成：在 Stack Overflow 上对比 在你熟悉的标签下按 Votes 排序，打开一个高分问题。再用搜索语法 [标签] closed:yes 找，或者按分数升序找。目标是一个被关闭或被踩的问题。 把两个问题的标题和正文，分别存成一行。用 question_check.py 跑一遍。再人工核对：有没有最小代码？有没有说试过什么？是不是一个能回答的具体问题？ 读关闭理由，比如 “Needs details or clarity”。看它对应清单里的哪一项。 验收标准 ：说出两个问题在清单上的差异。再判断哪个能得到更好的回答，能不能事先预测。只读，不投票，不评论。 考点（答案写在注释里） How do SQL joins work? # 太泛：对方只能从头讲起 # 为什么一串是非题比一个开放问题更快弄懂？ # 每个是非题都有明确的是或否，你马上知道哪部分理解对了、哪部分错了 # 开放问题容易引来长篇大论，很多你已经知道，或者并不相关（视频 55:22）"}, {"u": "labs/lab08.html#selfcheck", "c": "练习 8 · 代码之外", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。 示例仓库固定了身份和时间，哈希是确定的。用练习 2 的 make_repo.sh 重建后， git log --oneline 应当和本页逐字相同。 考点速查（注释里写着答案） export GIT_CONFIG_GLOBAL=/dev/null # 删掉 make_repo.sh 第 4 行，哈希多半不变：第 8 到 13 行已固定作者和时间 # 但你的 autocrlf、提交模板、钩子可能改掉内容或行为，结果就不可靠了（练习 2） lines = trial # reduce.py 接受删除后 i 不前进：后面的行前移，位置 i 上是新的一块（练习 5） re.search(pat, text, re.I | re.M) # 去掉 re.M：^ 只匹配全文开头，编号步骤和代码围栏都找不到，好 issue 被误判缺 2 项（练习 4） git log -S'MAX_IN_FLIGHT = 16' --format='%h %s' # 输出 4140218 update：找得到提交，找不回为什么（练习 2） # 本页为什么不直接去真实项目发 issue 或评论？对外发言会给维护者和订阅者制造噪声 # 那正是讲座批评的 “+1”。练习的目的是学会读和判断，参不参与、怎么参与由你本人决定"}, {"u": "labs/lab09.html", "c": "练习 9 · 代码质量", "t": "开头", "x": "LAB 09 · 对应 第 9 讲 · 代码质量 练习可视化笔记 · 代码质量 讲义第 9 讲一共 6 道练习。第 6 题还带 6.1 和 6.2 两个小问。前三题要用“你正在做的项目”。本页统一换成按视频重建的示例库 Minilib 。每题先亮结论，再给真跑的代码和输出。接着打个比方讲原理，最后指出坑在哪。考点都写在代码注释里。 所有输出都由脚本在本机真跑后自动收集 。生成时间是 … 。有些部分要用你本人的账号或 AI 智能体。这些只给步骤和验收标准。 定位到第一道未完成的题 Git Bash 5.3 · Windows 本机 真跑 未实测 需要你本人的账号或对外动作，写明原因 L3 注释层（不可选中，复制不会带上）"}, {"u": "labs/lab09.html#env", "c": "练习 9 · 代码质量", "t": "环境检查：工具装在临时沙箱里，不碰全局", "x": "本页命令都在 Windows 的 Git Bash 里真跑。ruff、pre-commit 和 semgrep 是临时装进沙箱的。 动手前先确认工具链。下面是生成本页时，在本机真跑的检查命令和输出： 本机限制与处理办法 不全局安装 ：本机没有 ruff、pre-commit 和 semgrep。用到它们时，“准备”步骤会用 uv 建一个 venv 装好。venv 建在 本次运行的临时沙箱 里。版本固定为 ruff 0.17.3、pre-commit 4.7.0、semgrep 1.182.1。运行结束，连同下载缓存一起删除。所以每次重新生成本页，都要联网下载这几个包。semgrep 比较大，约需半分钟。 不碰你的家目录 ：semgrep 和 pre-commit 默认会往家目录写设置和缓存。所以准备步骤把 USERPROFILE 、 UV_CACHE_DIR 、 PRE_COMMIT_HOME 都指向沙箱。git 配置也用 GIT_CONFIG_GLOBAL=/dev/null 隔离开。 pytest、coverage、PyYAML 用本机已有的。 hatch、just、make、shellcheck 没装，本页也用不到。 不推送到 GitHub ：练习 3 的工作流文件写好了。但推送到 GitHub Actions 看结果是对外动作，标成未实测。本页用 ci_local.sh 在本机执行同样的检查命令。 AI 智能体 ：练习 1 和 2 里，有些步骤要靠智能体。比如循环修 lint、补测试。这要用你本人的智能体账号。本页只给提示词和验收标准。 示例项目 Minilib 讲师在一个叫 Minilib 的单文件小库上演示。视频没有完整展示它的源码。 minilib/ 是按视频描述重建的版本。 utils.py 里故意留着视频提到的格式问题和 lint 问题。还有两个 bug：fizzbuzz 的分支顺序，left_pad 的截断。下面每题都在它的一份 新拷贝 上运行，互不影响。"}, {"u": "labs/lab09.html#ex01", "c": "练习 9 · 代码质量", "t": "练习 1 · 能自动修的交给工具，剩下的才轮到人", "x": "Git Bash 实测 AI 智能体部分需你本人完成 原题 ：为你正在做的项目配置格式化器、linter 和 pre-commit 钩子。报错很多也不怕。格式问题交给自动格式化。lint 错误试着让 AI 智能体 去修。要确保智能体能运行 linter，并看到结果。这样它能循环修复，直到全部解决。仔细检查结果，确保 AI 没有弄坏你的代码！ 先跑 ruff format 和 ruff check --fix ，让工具修完它能安全修的。剩下的照规则文档人工改，最后用钩子守住每次提交。 K 先回顾 格式化器见 第 9 讲第 2 节 。linter 与 noqa 见 第 9 讲第 3 节 。pre-commit 钩子见 第 9 讲第 8 节 。 ? 原理 先让工具做完它能安全完成的部分。剩下的才需要人或智能体来判断 {} 写：配置（pyproject.toml 里的 ruff 部分见上方 Minilib） ▶ 跑：格式化 输出怎么读： --check --diff 给出 unified diff， - 是原行， + 是格式化后。这时退出码非 0。去掉 --check 才真正写回。最后一次检查通过了。灰字的准备步骤，是在沙箱里装 ruff。 ▶ 跑：lint 与自动修复 6 个问题里，3 个带 [*] ，能安全自动修。 --fix 之后，报告说 8 个里修了 5 个。因为修掉一个 RET505 以后，后面的 elif 又成了新的 RET505。ruff 会循环修，修到不动为止。剩下的 F403、EM101、S602 要人来处理。 ▶ 跑：让 linter 教你 {} 写：人工修完的版本（绿色是手工改的行） 对照的基准，是 ruff 自动修复后的文件。 ▶ 跑：全部通过 import * 是有意保留的，视频里讲师也这样做。所以用 sed 在那一行末尾加了 # noqa: F403 。 ▶ 跑：pre-commit 钩子拦下格式不对的提交 输出怎么读：第一次 git commit 时， ruff format --check 失败了。git 没有创建提交，commit exit=1。 ruff format 修好后再提交，两个钩子都 Passed。 git log 里多了 4d26b19。 打个比方 像先把碗丢进洗碗机，再手洗它洗不掉的锅底。钩子是柜子前的检查员，碗不干净不许放进去。 ! 为什么会在这里踩坑：钩子能被绕过 现象 带着两个 lint 错误，E402 和 F401， git commit --no-verify 照样提交成功。 原因 钩子只装在每个人自己的 .git/hooks/ 里。没执行过 pre-commit install 的人不受约束。用 --no-verify 的人也一样（视频 41:45）。 对策 把同样的检查也放进 CI，见练习 3。服务器上的检查，谁也绕不过去。 需你本人完成：让 AI 智能体循环修 lint 在你自己的项目上，可以这样指挥编码智能体（示意）： “运行 ruff check . ，逐个修复报告的问题。每改一轮，都重新运行 ruff 和测试。直到 ruff 没有输出，测试也全部通过。不要用 noqa 掩盖问题，除非你在回复里说明理由。” 验收标准 有三条。第一， ruff check 和 ruff format --check 的退出码都是 0。第二，测试全部通过。第三，你逐个看过它的 diff。尤其是“不安全修复”和新加的 # noqa ，确认没有改变行为。讲义也说，要仔细检查，确保 AI 没弄坏代码。 考点（答案写在注释里） entry: ruff format --check # 钩子只检查，不修改 # 提交途中偷偷改文件，提交进去的就不是你暂存、看过的内容 # 所以让钩子失败，你跑完格式化、看过 diff 再提交 # pre-commit 也有“改了文件就判失败”的钩子，效果类似（补充） ruff check --fix # 修完会再查一轮，修掉一个 RET505 可能冒出新的 RET505"}, {"u": "labs/lab09.html#ex02", "c": "练习 9 · 代码质量", "t": "练习 2 · 覆盖率 100% 不等于测对了", "x": "Git Bash 实测 AI 智能体部分需你本人完成 原题 ：选一门你熟悉的语言，学它的测试库。为你的项目写一个单元测试。运行覆盖率工具，生成 HTML 格式的报告，观察结果。你能找出被覆盖的行吗？覆盖率多半很低。手工补一些测试提高它。再让 AI 智能体来提高覆盖率。要确保它能跑带覆盖率的测试，还能生成逐行报告。这样它才知道该把精力放在哪里。AI 生成的测试真的好吗？ 覆盖率只说明哪些行跑过，不说明结果对不对。高覆盖率加上有意义的 assert，测试才真有用。 K 先回顾 测试见 第 9 讲第 5 节 。覆盖率和手推公式见 第 9 讲第 6 节 。 {} 写：第一个测试文件 ! 为什么会在这里踩坑：测试本身也有 bug 现象 NameError: name 'fizzbuzz' is not defined 。失败的不是被测代码，而是测试本身。 正确写法 先写 from minilib import fizzbuzz 。看到失败时，先分清是哪种。 AssertionError 是被测代码的结果不对。别的异常，多半是测试或环境有问题。讲师在视频 25:09 现场踩过。 ▶ 跑：测试发现 bug ▶ 跑：覆盖率 手推：(22 − 11) / 22 = 50%。注意 Missing 里的 12 到 13 行。明明有 fizzbuzz(30) 的测试， return \"fizzbuzz\" 却没被执行。它是永远走不到的死代码，bug 正在这里。 {} 写：修 bug（补丁） ▶ 跑 {} 写：手工补测试 ▶ 跑：覆盖率与 HTML 报告 手推：(22 − 1) / 22 = 95.45%，显示为 95%。只剩 cat() 的第 33 行没跑到。 coverage html 会生成 htmlcov/index.html 。在浏览器里打开，就能逐行查看。绿色是执行过的，红色是没执行的。本页从 HTML 里 grep 出了总覆盖率。 打个比方 覆盖率像点名册，只记谁来过教室。来过不代表听懂了。assert 才是那场考试。 ! 为什么会在这里踩坑：覆盖率 100% 不等于测对了 现象 覆盖率 100%，测试全部通过。可 left_pad('00', 1) 返回 '0' ，截断 bug 一直在。 原因 覆盖率只统计执行到了没有，不管结果对不对。没有 assert 的测试，也能把每一行都执行一遍。讲师见过 AI 生成的这种测试。覆盖率 100%，却几乎毫无用处（视频 31:05）。 对策 审查测试有没有在检查 行为 。每个测试至少一个有意义的 assert。边界情况要专门测，这里是 len(s) > i 。也可以用性质测试，见第 9 讲第 7 节。 需你本人完成：让 AI 智能体提高覆盖率 给智能体的指令（示意）： “用 coverage run -m pytest 跑测试。再用 coverage report -m 看哪些行没覆盖。也可以用 coverage xml ，它更紧凑，适合你读。为没覆盖的行补测试。每个测试都要 assert 一个看得见的行为。不要修改被测代码。如果你认为发现了 bug，就写一个会失败的测试。然后告诉我。” 验收标准 ：覆盖率提高了。然后逐个读它写的测试。有没有像 test_useless.py 那样，只调用不检查的？有没有把错误的现有行为写成期望值？那样 bug 反而被测试“保护”起来了。 视频问答里讲师的经验是，一开始给的测试很有用。越往后越容易生成没用的。这时需要你引导（视频 1:07:19）。 考点（答案写在注释里） python -m coverage report -m # __init__.py 是 100%，utils.py 的 def 行也都算执行过 # 因为导入模块时，顶层语句会执行一遍，import 和 def 都在其中 # def 只是创建函数对象。函数体要等调用时才执行，没调用的函数体就是红的 assert fizzbuzz(95) == \"buzz\" # 补这一条，buzz 分支才算覆盖（视频 28:28）"}, {"u": "labs/lab09.html#ex03", "c": "练习 9 · 代码质量", "t": "练习 3 · CI 只能抓到你写了检查的东西", "x": "Git Bash 实测（本地等价检查） 推送到 GitHub 需你本人完成 原题 ：为你的项目配置持续集成，每次 push 时运行。让 CI 跑格式检查、lint 和测试。故意弄坏代码，例如引入一个 lint 违规。确认 CI 能抓住它。 工作流在 push、PR 和每周定时触发。故意加一行 import os ，lint 作业就变红。可没写测试的 bug，CI 照样是绿的。 K 先回顾 CI 的触发、作业、步骤与矩阵，见 第 9 讲第 9 节 。还会用到第 1 讲的退出码和 shell 函数。 {} 写：工作流 一共三类作业：format、lint 和 test。test 是 3 个系统乘 2 个 Python 版本的矩阵。任何一项失败，整次运行就变红。 ! 为什么会在这里踩坑：on 在 YAML 里会变成 True 现象 用 PyYAML 读这个工作流，顶层的键是 ['name', True, 'jobs'] 。 on 变成了布尔值 True。 原因 YAML 1.1 把 on、off、yes、no 都当成布尔值（补充）。GitHub Actions 自己的解析器能正确处理，工作流本身没问题。可你要是写脚本去检查或生成工作流，就得用 d[True] 来取。或者把键写成 \"on\": 。 {} 写：在本机执行同样的检查 基线代码是练习 1 修完 lint，再加上练习 2 修好的 fizzbuzz： ▶ 跑：全部通过 ▶ 跑：故意引入 lint 违规 输出怎么读：在第 3 行后插入 import os 。lint 作业失败，报 I001 import 顺序和 F401 没用到。test 照样跑了，而且通过，最后退出码是 1。注意 left_pad 的截断 bug 没让 CI 变红。CI 只能检查你写了检查的东西。 打个比方 CI 像机场安检。它只查清单上写了的违禁品。清单上没有的东西，带上飞机它也不拦。 ! 为什么会在这里踩坑：以为没开 set -e 才能接着跑 误解 ci_local.sh 能在 lint 失败后接着跑 test，是因为没开 set -e 。 实测 给它开上 -e，三个作业照样都跑完，exit=1。而逐行直接运行命令的 naive.sh，在 ruff 失败处就退出了。lint ok 和测试都没出现。 原因 命令失败时，有几种情况 不会 触发 -e。一是它在 if 、 while 的条件里，二是它在 && 、 || 的左边。这条是补充，见 Bash 手册的 The Set Builtin。ci_local.sh 第 9 行把每个检查放进了 if 条件。所以开不开 -e，都会接着跑。 ▶ 跑：推送到 GitHub（未实测） 需你本人完成：在 GitHub 上看它真的变红 在 GitHub 新建仓库。把 minilib/ 推上去，连同 .github/workflows/ci.yml 。 打开 Actions 标签页。应该看到 format、lint 和 6 个 test 作业，全部变绿。 新建分支，加一行 import os 。推送并开一个 PR，PR 页面上应显示 lint 检查失败。 可选：在 README 里加上状态徽章。讲义链接了 GitHub 文档。 验收标准 ：截图或链接显示主分支是绿的。破坏后的 PR 是红的，失败的正是 lint 作业。 考点（答案写在注释里） - run: ruff check . # 同一作业里这一步失败，后面的步骤默认不再执行 # 除非给后面的步骤加上 if: always() 之类的条件 # 不同作业互不影响，照样运行，除非用 needs 声明了依赖 # ci_local.sh 模仿的就是“作业之间互不影响”（补充，未在 GitHub 上实测）"}, {"u": "labs/lab09.html#ex04", "c": "练习 9 · 代码质量", "t": "练习 4 · grep 漏掉拆行和别名，semgrep 漏掉字典传参", "x": "Git Bash 实测 原题 ：写一个正则，用 grep 在你的代码里找出 subprocess.Popen(..., shell=True) 。然后试着“打破”这个正则。那些让 grep 失手的危险代码，semgrep 还能匹配上吗？ 字符级搜索会漏报，也会误报。semgrep 按语法树匹配，准得多，但也有盲区。 K 先回顾 semgrep 见 第 9 讲第 4 节 。正则里的转义 \\. 和 \\( ，见 第 9 讲第 13 节 。 {} 写：9 种写法的样本 ▶ 跑：两版 grep 第一版命中 5 行，其中只有 1、2 是真调用。文档字符串、注释 8、字符串 9 都是误报。3 跨行、4 有空格、5 是别名、6 藏在字典里，全漏了。 第二版放宽了 = 两边的空格，还排除了 # 开头的行。它多找到了 4，去掉了 8。可 3、5、6 照样漏，文档字符串和 9 照样误报。 注意正则里的 \\( 。讲师在视频里一开始没转义括号。结果 ( 被当成了分组（视频 18:11）。 ▶ 跑：semgrep semgrep 找到了 1 到 5。跨行调用、多余参数、空格都认得出来。连 from subprocess import Popen as P 这种别名也认得。注释、字符串和 shell=False 都没有误报。它漏掉了 6。 shell=True 藏在字典里，语法树上看不到这个关键字参数。完整对比见 第 9 讲的演示 。 打个比方 grep 像只认长相的保安，换件衣服就认不出。semgrep 像查身份证的保安。可人要是躲进箱子里，他也看不见。 考点（答案写在注释里） grep -nE 'subprocess\\.Popen\\(.*shell=True' # \\. 和 \\( 要转义，不然 . 是任意字符，( 是分组 semgrep -l python -e 'subprocess.Popen(..., **$KW)' # 补 6 号的一种办法：凡是 ** 传参都拿出来人工审 # 也可以靠 ruff 的 S602、S604 这类规则，再加代码评审 # 或者约定“禁止把 **kwargs 传给 subprocess” # 没有一种静态分析是完美的，几层叠加更可靠（补充，未实测）"}, {"u": "labs/lab09.html#ex05", "c": "练习 9 · 代码质量", "t": "练习 5 · 只换行首的项目符号，用 ^ 把位置锚住", "x": "Git Bash 实测（sed + Vim） 原题 ：在你的 IDE 或编辑器里练习正则搜索替换。把 这份讲义 里的 - Markdown 项目符号 换成 * 。注意，直接替换所有 “-” 是错的。文件里很多 “-” 并不是项目符号。 模式写成 ^( *)- ，只认行首、缩进之后的那个 - 加空格。正好 28 行被改，和项目符号的行数一致。 K 先回顾 ^ 行首、捕获组与 \\1 ，见 第 9 讲第 14 节 。还会用到第 1 讲的 sed、diff 和 grep -c。 实测改动 实测没有联网下载。用的是 讲义源文件 code-quality.md 的本地副本。它正是题目链接的那个文件。准备步骤把它复制进沙箱。这份副本在生成笔记后已删除。 ▶ 跑：先数一数 ! 为什么会在这里踩坑：把所有 - 都换掉 现象 68 行被改。YAML 头的 --- 变成了 *** ，日期变成 2026*01*23。high-quality、regular-expressions 这样的连字符和锚点，也全坏了。上面列出的，是非项目符号的受害行。 ▶ 跑：只换行首的项目符号 模式 ^( *)- 拆开看。行首，可选的缩进，一个 - ，一个空格。缩进被捕获为 \\1 ，替换时原样放回。正好 28 行被改，和项目符号的行数一致。 ▶ 跑：在编辑器里做同样的事（Vim） Vim 方言里，分组要写成 \\( 和 \\) ， \\s 是空白字符。 -Es 让 Vim 以无界面的 Ex 模式执行命令。结果和 sed 逐字节相同，用 cmp 验证过。 在 VS Code 里也能做。打开查找替换，点亮 .* 按钮。查找 ^(\\s*)- ，替换为 $1* 。 打个比方 像只把每段开头的小圆点换成星号。正文里的连字符，一个都不碰。 ^ 就是告诉工具，只看行首。 考点（答案写在注释里） sed -E 's/^( *)- /\\1* /' # 对：缩进捕获下来，替换时原样放回 sed 's/^- /* /' # 缩进的子列表项，它的 - 不在行首，会漏掉 sed 's/^\\s*- /* /' # 缩进被一起吃掉又没放回，子列表被“拍平”到第一层 # 这份讲义恰好没有缩进的 - 项目符号，所以三种写法都改 28 行（推理，未实测） # 可练习 6 的子题前面带缩进，说明文件里确实有嵌套列表。捕获缩进更稳妥"}, {"u": "labs/lab09.html#ex06", "c": "练习 9 · 代码质量", "t": "练习 6 · 正则取名字会吃过头，JSON 还是交给解析器", "x": "Git Bash 实测 原题 ：写一个正则，从形如 {\"name\": \"Alyssa P. Hacker\", \"college\": \"MIT\"} 的 JSON 里捕获名字。本例是 Alyssa P. Hacker 。提示：第一次尝试可能会得到 Alyssa P. Hacker\", \"college\": \"MIT 。读 Python 正则文档里讲贪婪量词的部分，来修正它。 6.1 让模式在名字含有 \" 时也能工作。JSON 里双引号转义成 \\\" 。 6.2 实践中 不 推荐用正则做复杂解析。用你的语言自带的 JSON 解析器，写一个命令行程序。它从 stdin 读这种 JSON，把名字输出到 stdout。Python 里除了 import json ，只需一行。 (.*) 贪婪，会一直吃到最后一个引号。换成 [^\"]* 就停在下一个引号。要处理转义，就让 \\\\. 成对吃。真遇到复杂 JSON，交给解析器。 K 先回顾 量词与回溯、贪婪与非贪婪，见 第 9 讲第 13 节 。捕获组见 第 9 讲第 14 节 。正则的局限见 第 9 讲第 15 节 。 {} 写：四个正则加两条样本 ▶ 跑 第 1 行：贪婪版吃过头，正是题目提示的那个错误结果。其余三种都对。第 2 行：非贪婪版和非引号版，都停在 \\\" 的引号上。它们只拿到 Ben \\ 。只有“转义感知”的版本拿到了完整名字。不过转义符仍原样留着。 打个比方 贪婪的 .* 像吃自助，先把盘子堆满。吃不下了，再一样样放回去。非贪婪是一样样拿，够了就停。 ▶ 跑：在 shell 里用 grep -P \\K 是 PCRE 的写法，意思是丢掉之前已匹配的部分。于是 -o 只输出名字（补充）。第三条命令是同一个模式的另一种写法 [^\"\\\\] 。在本机的 GNU grep 3.0 上，它报错 missing terminating ] for character class（本机实测）。改用十六进制转义 \\x5c 表示反斜杠，就正常了。不同工具、不同版本，对反斜杠的处理并不一致。这正是讲师说的方言差异。 {} 写：6.2 用 JSON 解析器 ▶ 跑 解析器把 \\\" 还原成了真正的引号： Ben \"Bitdiddle\" B. 。 ! 为什么会在这里踩坑：JSON 换个写法，正则就失灵 现象 键的顺序换了，冒号后面没有空格。这都是合法 JSON，grep 却一个都没匹配到，退出码 1。 原因 正则依赖表面写法。 \"name\": \" 里那个空格就是硬性要求。JSON 的语法有嵌套、转义和任意空白。这些超出了正则擅长的范围。 正确写法 用解析器。 name.py 照样输出 Alyssa P. Hacker。讲义也说，不推荐用正则解决复杂的解析问题。 考点（答案写在注释里） \"name\": \"((?:[^\"\\\\]|\\\\.)*)\" # 转义感知：每步吃一个普通字符，或者吃“反斜杠加任意字符”这一对 # 为什么要写 [^\"\\\\]，不能只写 [^\"] # [^\"] 允许单独吃掉反斜杠。遇到 \\\" 时，它可能先吃掉 \\ # 下一步再把 \" 当成结束引号，又回到被截断的结果 # 把反斜杠排除在外，它只能走 \\\\. 这条分支，和后面的字符成对被吃掉"}, {"u": "labs/lab09.html#selfcheck", "c": "练习 9 · 代码质量", "t": "自查：自己重跑一遍", "x": "本页的代码和输出，都是生成笔记时在本机真跑收集的。想验证，就把题解复制到空目录，在 Git Bash 里重跑。 生成脚本和题解源文件都已删除， 代码以本页为准 。代码块的“复制”按钮，拿到的是原文件的原始字节。生成时间见页头。 ruff、pre-commit、semgrep 本机没有全局安装。实测时，它们装在临时 venv 里。你重跑前要先装好它们，这需要联网。 考点速查（注释里写着答案） python -m coverage report -m # 原版只跑 test_fizzbuzz.py，Missing 里有第 13 行（练习 2） # 因为 return \"fizzbuzz\" 永远走不到 set -euo pipefail # 写进 ci_local.sh 第 4 行，test 照样会跑（练习 3） # 检查都在 if 条件里，不触发 -e。naive.sh 那样直接跑才会停 repo: local # 配 language: system，直接用 PATH 里的 ruff（练习 1） # 不用去 GitHub 克隆钩子仓库，离线能跑。代价是每人自己装 ruff \"name\": \"(.+)\" # 和 (.*) 一样贪婪（练习 6） # 得到 Alyssa P. Hacker\", \"college\": \"MIT s/^- /* / # 对这份讲义也是 28 行（练习 5） # 遇到缩进的子列表就漏掉，它的 - 不在行首"}];
